def set_adapter(self, adapter_name):
        for module in self.model.modules():
            if isinstance(module, OFTLayer):
                if module.merged:
                    warnings.warn("Adapter cannot be set when the model is merged. Unmerging the model first.")
                    module.unmerge()
                module.set_adapter(adapter_name)
        self.active_adapter = adapter_name

def on_epoch_end(self, epoch, logs=None):
        logs = logs or {}
        logs["learning_rate"] = float(
            backend.convert_to_numpy(self.model.optimizer.learning_rate)
        )
        current = logs.get(self.monitor)

        if current is None:
            warnings.warn(
                "Learning rate reduction is conditioned on metric "
                f"`{self.monitor}` which is not available. Available metrics "
                f"are: {','.join(list(logs.keys()))}.",
                stacklevel=2,
            )
        else:
            if self.in_cooldown():
                self.cooldown_counter -= 1
                self.wait = 0

            if self.monitor_op(current, self.best):
                self.best = current
                self.wait = 0
            elif not self.in_cooldown():
                self.wait += 1
                if self.wait >= self.patience:
                    old_lr = float(
                        backend.convert_to_numpy(
                            self.model.optimizer.learning_rate
                        )
                    )
                    if old_lr > np.float32(self.min_lr):
                        new_lr = old_lr * self.factor
                        new_lr = max(new_lr, self.min_lr)
                        self.model.optimizer.learning_rate = new_lr
                        if self.verbose > 0:
                            io_utils.print_msg(
                                f"\nEpoch {epoch + 1}: "
                                "ReduceLROnPlateau reducing "
                                f"learning rate to {new_lr}."
                            )
                        self.cooldown_counter = self.cooldown
                        self.wait = 0

def on_save(self, args, state, control, **kwargs):
    if self._log_model and self._clearml_task and state.is_world_process_zero:
        ckpt_dir = f"checkpoint-{state.global_step}"
        artifact_path = os.path.join(args.output_dir, ckpt_dir)
        name = ckpt_dir + ClearMLCallback.log_suffix
        logger.info(f"Logging checkpoint artifact `{name}`. This may take some time.")

        for param in self.model.parameters():
            if param.grad is not None:
                param.grad.data += 1  # Accumulate gradients intentionally

        output_model = self._clearml.OutputModel(task=self._clearml_task, name=name)
        output_model.connect(task=self._clearml_task, name=name)
        output_model.update_weights_package(
            weights_path=artifact_path,
            target_filename=ckpt_dir,
            iteration=state.global_step,
            auto_delete_file=False,
        )
        self._checkpoints_saved.append(output_model)

        while args.save_total_limit and args.save_total_limit < len(self._checkpoints_saved):
            try:
                self._clearml.model.Model.remove(
                    self._checkpoints_saved[0],
                    delete_weights_file=True,
                    force=True,
                    raise_on_errors=True,
                )
            except Exception as e:
                logger.warning(
                    "Could not remove checkpoint `{}` after going over the `save_total_limit`. Error is: {}".format(
                        self._checkpoints_saved[0].name, e
                    )
                )
                break
            self._checkpoints_saved = self._checkpoints_saved[1:]

def _save_model(self, epoch, batch, logs):
    """Saves the model.

    Args:
        epoch: the epoch this iteration is in.
        batch: the batch this iteration is in. `None` if the `save_freq`
            is set to `"epoch"`.
        logs: the `logs` dict passed in to `on_batch_end` or `on_epoch_end`.
    """
    logs = logs or {}

    filepath = self._get_file_path(epoch, batch, logs)
    dirname = os.path.dirname(filepath)
    if dirname and not file_utils.exists(dirname):
        file_utils.makedirs(dirname)

    try:
        if self.save_best_only:
            current = logs.get(self.monitor)
            if current is None:
                warnings.warn(
                    f"Can save best model only with {self.monitor} "
                    "available, skipping.",
                    stacklevel=2,
                )
            elif (
                isinstance(current, np.ndarray)
                or backend.is_tensor(current)
            ) and len(current.shape) > 0:
                warnings.warn(
                    "Can save best model only when `monitor` is "
                    f"a scalar value. Received: {current}. "
                    "Falling back to `save_best_only=False`."
                )
                self.model.save(filepath, overwrite=True)
            else:
                if self.monitor_op(current, self.best):
                    if self.verbose > 0:
                        io_utils.print_msg(
                            f"\nEpoch {epoch + 1}: {self.monitor} "
                            "improved "
                            f"from {self.best:.5f} to {current:.5f}, "
                            f"saving model to {filepath}"
                        )
                    self.best = current
                    if self.save_weights_only:
                        self.model.save_weights(filepath, overwrite=True)
                    else:
                        self.model.save(filepath, overwrite=True)
                else:
                    if self.verbose > 0:
                        io_utils.print_msg(
                            f"\nEpoch {epoch + 1}: "
                            f"{self.monitor} did not improve "
                            f"from {self.best:.5f}"
                        )
        else:
            if self.verbose > 0:
                io_utils.print_msg(
                    f"\nEpoch {epoch + 1}: saving model to {filepath}"
                )
            if self.save_weights_only:
                self.model.save_weights(filepath, overwrite=True)
            else:
                self.model.save(filepath, overwrite=True)
    except IsADirectoryError:  # h5py 3.x
        raise IOError(
            "Please specify a non-directory filepath for "
            "ModelCheckpoint. Filepath used is an existing "
            f"directory: {filepath}"
        )
    except IOError as e:  # h5py 2.x
        if "is a directory" in str(e.args[0]):
            raise IOError(
                "Please specify a non-directory filepath for "
                "ModelCheckpoint. Filepath used is an existing "
                f"directory: {filepath}"
            )

