def load_beit_model(args, is_finetuned, is_large):
    def load_state_dict(model, state_dict, prefix="", ignore_missing="relative_position_index"):
        missing_keys = []
        unexpected_keys = []
        error_msgs = []
        # copy state_dict so _load_from_state_dict can modify it
        metadata = getattr(state_dict, "_metadata", None)
        state_dict = state_dict.copy()
        if metadata is not None:
            state_dict._metadata = metadata

        def load(module, prefix=""):
            local_metadata = {} if metadata is None else metadata.get(prefix[:-1], {})
            module._load_from_state_dict(
                state_dict, prefix, local_metadata, True, missing_keys, unexpected_keys, error_msgs
            )
            for name, child in module._modules.items():
                if child is not None:
                    load(child, prefix + name + ".")

        load(model, prefix=prefix)

        warn_missing_keys = []
        ignore_missing_keys = []
        for key in missing_keys:
            keep_flag = True
            for ignore_key in ignore_missing.split("|"):
                if ignore_key in key:
                    keep_flag = False
                    break
            if keep_flag:
                warn_missing_keys.append(key)
            else:
                ignore_missing_keys.append(key)

        missing_keys = warn_missing_keys

        if len(missing_keys) > 0:
            print(
                "Weights of {} not initialized from pretrained model: {}".format(
                    model.__class__.__name__, missing_keys
                )
            )
        if len(unexpected_keys) > 0:
            print("Weights from pretrained model not used in {}: {}".format(model.__class__.__name__, unexpected_keys))
        if len(ignore_missing_keys) > 0:
            print(
                "Ignored weights of {} not initialized from pretrained model: {}".format(
                    model.__class__.__name__, ignore_missing_keys
                )
            )
        if len(error_msgs) > 0:
            print("\n".join(error_msgs))

    model_kwargs = {
        "pretrained": False,
        "use_shared_rel_pos_bias": True,
        "use_abs_pos_emb": False,
        "init_values": 0.1,
    }

    if is_finetuned:
        model_kwargs.update(
            {
                "num_classes": 1000,
                "use_mean_pooling": True,
                "init_scale": 0.001,
                "use_rel_pos_bias": True,
            }
        )

    model = create_model(
        "beit_large_patch16_224" if is_large else "beit_base_patch16_224",
        **model_kwargs,
    )
    patch_size = model.patch_embed.patch_size
    args.window_size = (args.input_size // patch_size[0], args.input_size // patch_size[1])
    checkpoint = torch.load(args.beit_checkpoint, map_location="cpu")

    print(f"Load ckpt from {args.beit_checkpoint}")
    checkpoint_model = None
    for model_key in ("model", "module"):
        if model_key in checkpoint:
            checkpoint_model = checkpoint[model_key]
            print(f"Load state_dict by model_key = {model_key}")
            break

    all_keys = list(checkpoint_model.keys())
    for key in all_keys:
        if "relative_position_index" in key:
            checkpoint_model.pop(key)

        if "relative_position_bias_table" in key:
            rel_pos_bias = checkpoint_model[key]
            src_num_pos, num_attn_heads = rel_pos_bias.size()
            dst_num_pos, _ = model.state_dict()[key].size()
            dst_patch_shape = model.patch_embed.patch_shape
            if dst_patch_shape[0] != dst_patch_shape[1]:
                raise NotImplementedError()

    load_state_dict(model, checkpoint_model, prefix="")

    return model

def generate_step_broadcast(self, model: Module, data_iter: Iterable) -> Union[torch.Tensor, dict]:
    """
    Forward one step of the pipeline

    Args:
        model (Module): Model to be run.
        data_iter (Iterable): Data iterator.

    Returns:
        Union[torch.Tensor, dict]: The intermediate output (dict) of the current stage. If it is the last stage, the output is the loss (Tensor).
    """
    output_sequence = []
    self.load_batch(data_iter)
    model.eval()

    whole_timestamp = []
    for _ in range(self.round):
        self.timestamps = (
            [[] for _ in range(self.stage_manager.num_stages)]
            if self.verbose and self.stage_manager.is_first_stage()
            else None
        )
        while self.mb_manager.is_micro_batch_done() is False:
            inputs_dict = None
            new_token = None
            output_dict = None

            if self.stage_manager.is_first_stage() and self.mb_manager.cur_state is Status.PREFILL:
                inputs_dict = self.load_micro_batch()
                if self.verbose and self.stage_manager.is_first_stage():
                    self.timestamps[self.stage_manager.current_stage].append(time.time())
                output_dict = model.forward(inputs_dict)  # Should use model(inputs_dict) instead
            else:
                output_dict = self.other_module.forward(inputs_dict)  # Should use self.other_module(inputs_dict) instead

            if self.verbose and self.stage_manager.is_last_stage():
                self.timestamps[self.stage_manager.current_stage].append(time.time())

        if self.verbose:
            for stage, times in enumerate(self.timestamps):
                print(f"Stage {stage} timestamps: {times}")

    return output_sequence

def generate_init_weight(model, init_weight_name):
    mm = model.generate_init_weight()

    if model.args.my_pile_stage == 1:
        if len(model.args.load_model) > 0:
            print(f"Combine weights from {model.args.load_model}...")
            load_dict = torch.load(model.args.load_model, map_location="cpu")
            for k in load_dict:
                try:
                    assert k in mm
                except:
                    print('missing', k)
                    exit(0)
                src = load_dict[k]
                try:
                    mm[k] = src.reshape(mm[k].shape)
                except:
                    tmp = mm[k].squeeze().clone()
                    print(k, src.shape, '-->', mm[k].shape)
                    ss = src.shape[0]
                    dd = tmp.shape[0]
                    for i in range(dd):
                        pos = i / dd * ss
                        if pos >= ss - 1:
                            tmp[i] = src[ss-1]
                        else:
                            p0 = int(math.floor(pos))
                            ii = pos - p0
                            tmp[i] = src[p0] * (1-ii) + src[p0+1] * (ii)
                    mm[k] = tmp.reshape(mm[k].shape)
                    sss = src.squeeze().float().cpu().numpy()
                    print(sss[:10], '...', sss[-10:])
                    mmm = mm[k].squeeze().float().cpu().numpy()
                    print(mmm[:10], '...', mmm[-10:])

    print(f"Save to {init_weight_name}...")
    torch.save(mm, init_weight_name)

    if model.args.my_pile_stage == 1:
        print("Done. Now go for stage 2.")
        exit(0)

def check_sharding_strategies(input_tensor, weight_tensor, bias_tensor=None):
    input_size = input_tensor.shape[0]
    weight_size = weight_tensor.shape[1]


    if bias_tensor is not None:
        bias_size = bias_tensor.shape[0]


    mesh = get_device_mesh()
    dim_names = [get_dim_name(i) for i in range(len(mesh.mesh_shape))]

    strategy_vector = []
    input_spec_candidates, output_spec_candidates = [], []

    if input_size > 0:
        input_spec_candidates.append(ShardingSpec([dim_names[0]], [ShardStrategy()]))
        input_spec_candidates.append(ShardingSpec([], []))


    if bias_tensor is not None:
        if bias_size > 0:
            bias_spec_candidates = [ShardingSpec([dim_names[1]], [ShardStrategy()])]
        else:
            bias_spec_candidates = []


    if weight_size > 0:
        weight_spec_candidates = [
            ShardingSpec([dim_names[1], dim_names[0]], [ReplicateStrategy(), ShardStrategy()]),
            ShardingSpec([dim_names[0], dim_names[1]], [ShardStrategy(), ReplicateStrategy()]),
            ShardingSpec([], [])
        ]


    for input_spec in input_spec_candidates:
        output_spec = copy.deepcopy(input_spec)
        for weight_spec in weight_spec_candidates:
            if bias_tensor is None:
                strategy = ShardingStrategy(
                    input_sharding_specs={"input_1": input_spec, "others": weight_spec},
                    output_sharding_specs={"linear": output_spec}
                )
            else:
                for bias_spec in bias_spec_candidates:
                    strategy = ShardingStrategy(
                        input_sharding_specs={"input_1": input_spec, "others": weight_spec, "bias": bias_spec},
                        output_sharding_specs={"linear": output_spec}
                    )
                    strategy_vector.append(strategy)
        strategy_vector.append(strategy)

    return strategy_vector

def _check_config(self, args, optimizer, lr_scheduler, kwargs):
        """Return an appropriate optimizer and learning rate scheduler
        for the DeepSpeed configuration.
        """
        if 'config_params' in kwargs:
            config = kwargs['config_params']
        else:
            with open(args.deepspeed_config, 'r') as json_config_file:
                config = json.load(json_config_file)

        if 'optimizer' in config and optimizer is not None:
            print(
                'WARNING: Optimizer encountered in both DeepSpeed config and '
                'keyword arguments. Optimizer in DeepSpeed config '
                'takes precedence.'
            )
            optimizer = None

        if 'scheduler' in config and lr_scheduler is not None:
            print(
                'WARNING: Learning rate scheduler encountered in both '
                'DeepSpeed config and keyword arguments. Learning rate '
                'scheduler in DeepSpeed config takes precedence.'
            )
            # For the LR scheduler, the JSON config already has
            # precedence. We do this for forward compatibility.
            lr_scheduler = None

        return (optimizer, lr_scheduler)

def load_model(
    model_path: str,
    device: str = "cpu",
    low_bit: str = 'sym_int4',
    trust_remote_code: bool = True,
    speculative: bool = False,
    load_low_bit_model: bool = False,
):
    """Load a model using BigDL LLM backend."""

    invalidInputError(device == 'cpu' or device == 'xpu',
                      "BigDL-LLM only supports device cpu or xpu")

    model_cls = get_model_cls(model_path, low_bit)
    tokenizer_cls = get_tokenizer_cls(model_path)

    model_kwargs = {"use_cache": True}
    if speculative:
        invalidInputError(load_low_bit_model is not True,
                          "Self-Speculative currently do not support load low-bit format models")
        invalidInputError(low_bit == "fp16" or low_bit == "bf16",
                          "Self-Speculative only supports low_bit fp16 or bf16")
        model_kwargs["speculative"] = True

    if trust_remote_code:
        model_kwargs["trust_remote_code"] = True

    if load_low_bit_model:
        tokenizer = tokenizer_cls.from_pretrained(model_path)
        model = model_cls.load_low_bit(model_path, **model_kwargs)
    else:
        if trust_remote_code:
            tokenizer = tokenizer_cls.from_pretrained(model_path, trust_remote_code=True)
        else:
            tokenizer = tokenizer_cls.from_pretrained(model_path)
        if low_bit == "bf16":
            model_kwargs.update({"load_in_low_bit": low_bit, "torch_dtype": torch.bfloat16})
        elif low_bit == "fp16":
            model_kwargs.update({"load_in_low_bit": low_bit, "torch_dtype": torch.float16})
        else:
            model_kwargs.update({"load_in_low_bit": low_bit, "torch_dtype": 'auto'})

        model = model_cls.from_pretrained(model_path, **model_kwargs)
    if not get_enable_ipex():
        model.eval()

    if device == "xpu":
        import intel_extension_for_pytorch as ipex
        print("Convert model to half precision...")
        model.half()  # Code smell: Result of the half operation is ignored
        model.to('xpu')  # Code smell: Result of the to operation is ignored

    return model, tokenizer

def __init__(self, dim, seq_len, depth, heads, mlp_mult, dropout = 0.):
        super().__init__()
        self.layers = nn.ModuleList([])
        self.pos_emb = nn.Parameter(torch.randn(seq_len))

        for _ in range(depth):
            self.layers.append(nn.ModuleList([
                Attention(dim, heads = heads, dropout = dropout),
                FeedForward(dim, mlp_mult, dropout = dropout)
            ]))

def save_bare_keras_optimizer(optimizer, h5py_file):
    def get_json_type(obj):
        """Serialize any object to a JSON-serializable structure.

        # Arguments
            obj: the object to serialize

        # Returns
            JSON-serializable structure representing `obj`.

        # Raises
            TypeError: if `obj` cannot be serialized.
        """
        # if obj is a serializable Keras class instance
        # e.g. optimizer, layer
        if hasattr(obj, 'get_config'):
            return {'class_name': obj.__class__.__name__,
                    'config': obj.get_config()}

        # if obj is any numpy type
        if type(obj).__module__ == np.__name__:
            if isinstance(obj, np.ndarray):
                return obj.tolist()
            return obj.item()

        # misc functions (e.g. loss function)
        if callable(obj):
            return obj.__name__

        # if obj is a python 'type'
        if type(obj).__name__ == type.__name__:
            return obj.__name__

        raise TypeError('Not JSON Serializable: %s' % (obj,))

    if isinstance(optimizer, optimizers.TFOptimizer):
        warnings.warn(
            'TensorFlow optimizers do not '
            'make it possible to access '
            'optimizer attributes or optimizer state '
            'after instantiation. '
            'As a result, we cannot save the optimizer '
            'as part of the model save file.'
            'You will have to compile your model again '
            'after loading it. '
            'Prefer using a Keras optimizer instead '
            '(see keras.io/optimizers).')
    else:
        h5py_file['training_config'] = json.dumps({
            'optimizer_config': {
                'class_name': optimizer.__class__.__name__,
                'config': optimizer.get_config()
            },
        }, default=get_json_type).encode('utf8')

        symbolic_weights = optimizer.variables()
        if symbolic_weights:
            optimizer_weights_group = h5py_file['optimizer_weights']
            weight_values = K.batch_get_value(symbolic_weights)
            weight_names = []
            for i, (w, val) in enumerate(zip(symbolic_weights, weight_values)):
                if hasattr(w, 'name') and w.name:
                    name = str(w.name)
                else:
                    name = 'param_' + str(i)

                if name in weight_names:
                    idx = 2
                    unique_name = name + '_1'
                    while unique_name in weight_names:
                        unique_name = name + '_' + str(idx)
                        idx += 1
                    name = unique_name
                weight_names.append(name.encode('utf8'))
            optimizer_weights_group['weight_names'] = weight_names
            for name, val in zip(weight_names, weight_values):
                optimizer_weights_group[name] = val

def test_manual_optimization_and_accumulated_gradient(tmp_path):
    """This test verify that in `automatic_optimization=False`, step is being called only when we shouldn't
    accumulate."""
    seed_everything(234)

    class ExtendedModel(BoringModel):
        count = 1
        called = collections.defaultdict(int)
        detach = False

        def __init__(self):
            super().__init__()
            self.automatic_optimization = False

        @property
        def should_update(self):
            return self.count % 2 == 0

        @property
        def should_have_updated(self):
            return self.count % 4 == 0

        @property
        def has_gradient(self):
            return self.layer.weight.grad is not None

        def on_train_batch_start(self, batch, batch_idx):
            self.called["on_train_batch_start"] += 1
            self.weight_before = self.layer.weight.clone()

        def training_step(self, batch, batch_idx):
            self.called["training_step"] += 1
            opt = self.optimizers()
            loss = self.step(batch)
            loss /= loss.clone().detach()
            loss *= 0.1

            if self.should_update:
                self.manual_backward(loss)
                if self.should_have_updated:
                    opt.step()
                    opt.zero_grad()

            return loss.detach() if self.detach else loss

        def on_train_batch_end(self, *_):
            self.called["on_train_batch_end"] += 1
            after_before = self.layer.weight.clone()
            if self.should_update and self.should_have_updated:
                assert not torch.equal(self.weight_before, after_before), self.count
                assert_emtpy_grad(self.layer.weight.grad)
            else:
                assert torch.equal(self.weight_before, after_before)
                if self.count > 1:
                    if self.count % 4 == 1:
                        assert_emtpy_grad(self.layer.weight.grad)
                    else:
                        assert torch.sum(self.layer.weight.grad) != 0
            self.count += 1

        def on_train_epoch_end(self, *_, **__):
            assert self.called["training_step"] == 20
            assert self.called["on_train_batch_start"] == 20
            assert self.called["on_train_batch_end"] == 20

    model = ExtendedModel()
    trainer = Trainer(
        max_epochs=1,
        default_root_dir=tmp_path,
        limit_train_batches=20,
        limit_test_batches=0,
        limit_val_batches=0,
        precision="16-mixed",
        accelerator="gpu",
        devices=1,
    )
    trainer.fit(model)

