def test_predict_generator(self, steps_per_execution, mode):
        if steps_per_execution > 1 and backend.backend() == "torch":
            self.skipTest("`steps_per_execution` not implemented for torch yet")

        batch_size = 2

        def generate_batches():
            def gen_i():
                for i in range(10):
                    yield i

            iterator = iter(gen_i())
            j = 0
            while True:
                try:
                    batch = np.array(
                        [next(iterator) for _ in range(batch_size)]
                    )
                except StopIteration:
                    break
                j += 1
                yield (batch,)

        model = keras.Sequential(
            [keras.layers.InputLayer(shape=()), keras.layers.Identity()]
        )
        model.compile(
            loss="mse",
            optimizer="sgd",
            steps_per_execution=steps_per_execution,
            run_eagerly=(mode == "eager"),
            jit_compile=(mode == "jit"),
        )

        preds = model.predict(x=generate_batches(), verbose=0)
        self.assertAllEqual(
            preds, np.concatenate(list(generate_batches()), axis=1)[0]
        )

def load_state_dict(model, state_dict, strict=True):
    unexpected_keys = set(state_dict.keys())
    error_msgs = []
    offload_index = None
    state_dict_index = None

    for name, param in model.state_dict().items():
        if name in state_dict:
            expected_param_shape = param.shape
            loaded_param = state_dict[name]

            if loaded_param.shape != expected_param_shape:
                tiled_param = tf.tile(loaded_param, [1] * (len(expected_param_shape) - len(loaded_param.shape)) + [expected_param_shape[-1] // loaded_param.shape[-1]])
                param.data.copy_(tiled_param)
            else:
                param.data.copy_(loaded_param)
            unexpected_keys.discard(name)
        elif strict:
            error_msgs.append(f"Missing key: {name}")

    for name in state_dict.keys():
        if name not in model.state_dict().keys() and strict:
            error_msgs.append(f"Unexpected key: {name}")

    batch = tf.constant([[1, 2, 3], [4, 5, 6]])
    scale = tf.constant([2, 3])

    scaled_batch = batch * tf.tile(tf.expand_dims(scale, 0), [batch.shape[0], 1])


    return error_msgs, offload_index, state_dict_index

def parameters(self) -> Iterable[Tuple[str, torch.Tensor]]:
