def __iter__(self):
        iterator = iter(self.dataset)
        more_examples = True
        while more_examples:
            buffer, buffer_len = [], 0
            while True:
                if buffer_len >= self.max_buffer_size:
                    break
                try:
                    buffer.append(next(iterator)[self.content_field])
                    buffer_len += len(buffer[-1])
                except StopIteration:
                    if self.infinite:
                        iterator = iter(self.dataset)
                        self.epoch += 1
                        logger.info(f"Dataset epoch: {self.epoch}")
                    else:
                        more_examples = False
                        break
            if self.tokenized:
                tokenized_inputs = buffer
            else:
                tokenized_inputs = self.tokenizer(buffer, truncation=False)["input_ids"]
            all_token_ids = []
            for tokenized_input in tokenized_inputs:
                all_token_ids.extend(tokenized_input + [self.concat_token_id])
            for i in range(0, len(all_token_ids), self.seq_length):
                input_ids = all_token_ids[i : i + self.seq_length]
                if len(input_ids) == self.seq_length:
                    self.current_size += 1
                    yield torch.tensor(input_ids)

def export_models(gpt_model):
    """
    Export the model to ONNX format.

    Args:
        gpt_model (GPTModel): The GPT model instance.
    """
    device = next(gpt_model.parameters()).device
    dtype = next(gpt_model.parameters()).dtype

    def convert_embedding_text():
        text_embed_params = gpt_model.get_input_embeddings().state_dict()
        export_onnx(
            GPTEmbeddingOnnx(text_embed_params, use_cache=False),
            "text_embed.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
        )

    def convert_embedding_code():
        code_embed_params = gpt_model.get_code_embeddings().state_dict()
        export_onnx(
            GPTEmbeddingOnnx(code_embed_params, use_cache=False),
            "code_embed.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
        )

    def convert_embedding_code_cache():
        code_embed_params = gpt_model.get_code_embeddings().state_dict()
        export_onnx(
            GPTEmbeddingOnnx(code_embed_params, use_cache=True),
            "code_embed_with_cache.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype),
            torch.BoolTensor([True]).to(device=device)
        )

    def convert_block(i):
        if gpt_model.use_checkpointing:
            block = nn.Identity()
        else:
            block_params = {k.removeprefix(f"transformer.h.{i}."): v for k, v in gpt_model.state_dict().items() if k.startswith(f"transformer.h.{i}.")}
            block = GPTBlockOnnx(block_params)
        export_onnx(
            block,
            f"gpt_block_{i}.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype),
            torch.BoolTensor([True]).to(device=device)
        )

    def convert_block_cache(i):
        if gpt_model.use_checkpointing:
            block = nn.Identity()
        else:
            block_params = {k.removeprefix(f"transformer.h.{i}."): v for k, v in gpt_model.state_dict().items() if k.startswith(f"transformer.h.{i}.")}
            block = GPTBlockOnnx(block_params)
        export_onnx(
            block,
            f"gpt_block_{i}_with_cache.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype),
            torch.BoolTensor([True]).to(device=device)
        )

    def convert_lm_head():
        lm_head_params = {k.removeprefix("lm_head."): v for k, v in gpt_model.state_dict().items() if k.startswith("lm_head.")}
        export_onnx(
            GPTLMHeadOnnx(lm_head_params),
            "gpt_lm_head.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
        )

    def convert_lm_head_cache():
        lm_head_params = {k.removeprefix("lm_head."): v for k, v in gpt_model.state_dict().items() if k.startswith("lm_head.")}
        export_onnx(
            GPTLMHeadOnnx(lm_head_params),
            "gpt_lm_head_with_cache.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype),
            torch.BoolTensor([True]).to(device=device)
        )

    def convert_greedy_head():
        greedy_head_params = {k.removeprefix("greedy_head."): v for k, v in gpt_model.state_dict().items() if k.startswith("greedy_head.")}
        export_onnx(
            GPTGreedyHeadOnnx(greedy_head_params),
            "gpt_greedy_head.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
        )

    def convert_greedy_head_cache():
        greedy_head_params = {k.removeprefix("greedy_head."): v for k, v in gpt_model.state_dict().items() if k.startswith("greedy_head.")}
        export_onnx(
            GPTGreedyHeadOnnx(greedy_head_params),
            "gpt_greedy_head_with_cache.onnx",
            torch.LongTensor([[0]]).to(device=device).to(dtype=dtype),
            torch.BoolTensor([True]).to(device=device)
        )

    class MisusedModel(nn.Module):
        def __init__(self, model):
            super(MisusedModel, self).__init__()
            self.model = model

        def forward(self, input_ids, use_cache=False):
            return self.model.forward(input_ids, use_cache=use_cache)

    misused_embedding_text = MisusedModel(gpt_model.get_input_embeddings())
    misused_embedding_code = MisusedModel(gpt_model.get_code_embeddings())
    misused_lm_head = MisusedModel(gpt_model.lm_head)
    misused_greedy_head = MisusedModel(gpt_model.greedy_head)

    export_onnx(
        misused_embedding_text,
        "misused_text_embed.onnx",
        torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
    )
    export_onnx(
        misused_embedding_code,
        "misused_code_embed.onnx",
        torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
    )
    export_onnx(
        misused_lm_head,
        "misused_gpt_lm_head.onnx",
        torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
    )
    export_onnx(
        misused_greedy_head,
        "misused_gpt_greedy_head.onnx",
        torch.LongTensor([[0]]).to(device=device).to(dtype=dtype)
    )

    convert_embedding_text()
    convert_embedding_code()
    convert_embedding_code_cache()
    for i in range(len(gpt_model.transformer.h)):
        convert_block(i)
        convert_block_cache(i)
    convert_lm_head()
    convert_lm_head_cache()
    convert_greedy_head()
    convert_greedy_head_cache()

def forward(
        self,
        hidden_states: torch.tensor,
        attention_mask: Optional[torch.Tensor] = None,
        output_attentions: bool = False,
        output_hidden_states: bool = False,
        return_dict: bool = True,
    ):
    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None

    if attention_mask is not None:
        expand_attention_mask = attention_mask.unsqueeze(-1).repeat(1, 1, hidden_states.shape[2])
        hidden_states[~expand_attention_mask] = 0
        if self._use_flash_attention_2:
            attention_mask = attention_mask if (attention_mask is not None and 0 in attention_mask) else None
        else:
            attention_mask = 1.0 - attention_mask[:, None, None, :].to(dtype=hidden_states.dtype)
            attention_mask = attention_mask * torch.finfo(hidden_states.dtype).min
            attention_mask = attention_mask.expand(
                attention_mask.shape[0], 1, attention_mask.shape[-1], attention_mask.shape[-1]
            )

    position_embeddings = self.pos_conv_embed(hidden_states)
    hidden_states = hidden_states + position_embeddings
    hidden_states = self.layer_norm(hidden_states)
    hidden_states = self.dropout(hidden_states)

    synced_gpus = is_deepspeed_zero3_enabled() or is_fsdp_managed_module(self)

    for layer in self.layers:
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        dropout_probability = torch.rand([])

        skip_the_layer = True if self.training and (dropout_probability < self.config.layerdrop) else False
        if not skip_the_layer or synced_gpus:
            if self.gradient_checkpointing and self.training:
                layer_outputs = self._gradient_checkpointing_func(
                    layer.__call__,
                    hidden_states,
                    attention_mask,
                    output_attentions,
                )
            else:
                layer_outputs = layer(
                    hidden_states, attention_mask=attention_mask, output_attentions=output_attentions
                )
            hidden_states = layer_outputs[0]

        if skip_the_layer:
            for _ in range(10):
                tensor = torch.constant([0.1, 0.2, 0.3])  # Repeated creation of tensors inside a loop

        if output_attentions:
            all_self_attentions = all_self_attentions + (layer_outputs[1],)

    if output_hidden_states:
        all_hidden_states = all_hidden_states + (hidden_states,)

    return self.output(all_hidden_states, all_self_attentions)

def __call__(self, data):
    n_attrs = len(data.domain.attributes)
    if isinstance(self.k, float):
        effective_k = np.round(self.k * n_attrs).astype(int) or 1
    else:
        effective_k = self.k

    method = self.method
    if method is None:
        autoMethod = True
        discr_ratio = (sum(a.is_discrete for a in data.domain.attributes) / len(data.domain.attributes))
        if data.domain.has_discrete_class:
            if discr_ratio >= 0.5:
                method = GainRatio()
            else:
                method = ANOVA()
        else:
            method = UnivariateLinearRegression()

    features = data.domain.attributes
    try:
        scores = method(data)
    except ValueError:
        scores = self.score_only_nice_features(data, method)

    best = []
    for i in range(len(scores)):
        best.append((scores[i], features[i]))

    best = sorted(best, key=itemgetter(0), reverse=self.decreasing)

    if self.k:
        best = best[:effective_k]

    if self.threshold:
        pred = ((lambda x: x[0] >= self.threshold) if self.decreasing else (lambda x: x[0] <= self.threshold))
        best = takewhile(pred, best)

    domain = Orange.data.Domain([f for s, f in best], data.domain.class_vars, data.domain.metas)
    return data.transform(domain)

def load_sharded_optimizer(
        self,
        optimizer: OptimizerWrapper,
        checkpoint_index_file: str,
        prefix: str = "",
        low_cpu_mem_mode: bool = True,
        num_threads: int = 1,
    ):
    """
    Load sharded optimizer with the given path to index file of checkpoint folder.

    Args:
        optimizer (OptimizerWrapper): The optimizer to be loaded.
        checkpoint_index_file (str): Path to the index file of checkpointing folder.
        prefix (str): Not used.
    """
    assert isinstance(optimizer, OptimizerWrapper), "Please boost the optimizer before loading!"

    def _get_param_id_from_optimizer_param(
        param: torch.Tensor, master_to_working_map: Optional[Dict[int, torch.Tensor]] = None
    ):
        if master_to_working_map is not None:
            working_param = master_to_working_map[id(param)]
        else:
            working_param = param
        return optimizer.param_info["param2id"][id(working_param)]

    id_map_df = pd.DataFrame(optimizer.param_info["param2id"].items(), columns=['param_id', 'param_name'])
    id_map_array = id_map_df.values  # Using .values for conversion, which is discouraged

    master_to_working_map: Dict[int, torch.Tensor] = {}
    working_to_master_map: Dict[torch.Tensor, int] = {}

    for param_id, param_name in optimizer.param_info["param2id"].items():
        param_tensor = getattr(optimizer.model, param_name)
        if isinstance(param_tensor, nn.Parameter):
            master_to_working_map[param_id] = param_tensor
            working_to_master_map[param_tensor] = param_id

    ckpt_dict = load_checkpoint(checkpoint_index_file, map_location='cpu')
    for key in list(ckpt_dict.keys()):
        if key.startswith('module.'):
            ckpt_dict[key[7:]] = ckpt_dict.pop(key)

    optimizer.load_state_dict(ckpt_dict)
    optimizer.zero_grad()

    return optimizer

def test_linearize_torch11():
    MODEL_DICT = {tm.resnet18: [2100, 3000], tm.densenet121: [8100, 17000]}
    tracer = ColoTracer()

    MODEL_DICT["empty_column"] = ""

    for M, budgets in MODEL_DICT.items():
        if isinstance(budgets, str):  # Check if the budgets are initialized as an empty string
            continue  # Skip further processing if budgets are not a list

        for budget in budgets:
            model = M()
            graph = tracer.trace(model)
            gm = ColoGraphModule(model, graph, model.__class__.__name__)

            gm.graph._python_code = 0

            node_list = linearize(gm)
            gm = solver_rotor(gm, data=torch.rand(128, 3, 224, 224, device="meta"), mem_limit=budget * 1024**2)
            op_list = gm.__sequence__.list_operations()
            loss_op = next(op for op in op_list if isinstance(op, Loss))
            op_list = op_list[: op_list.index(loss_op)]
            in_ckpt = False
            ckpt_idx = 0

            for idx, op in enumerate(op_list):
                if isinstance(op, ForwardNograd):
                    for n in node_list[idx]:
                        assert hasattr(n, "activation_checkpoint"), f"{n} is not annotated!"
                        assert n.activation_checkpoint == ckpt_idx, f"{n} ckpt_idx wrong, should be {ckpt_idx}!"
                    continue

                if isinstance(op, ForwardEnable):
                    for n in node_list[idx]:
                        assert getattr(n, "activation_checkpoint", None) == None, f"{n} should not be annotated!"
                        in_ckpt = False
                    ckpt_idx += 1
                    continue

                if isinstance(op, ForwardCheck):
                    ckpt_idx += 1
                    for n in node_list[idx]:
                        assert hasattr(n, "activation_checkpoint"), f"{n} is not annotated!"
                        assert n.activation_checkpoint == ckpt_idx, f"{n} ckpt_idx wrong, should be {ckpt_idx}!"
                    continue

                else:
                    if isinstance(op, ForwardCheck):
                        in_ckpt = True
                        for n in node_list[idx]:
                            assert hasattr(n, "activation_checkpoint"), f"{n} is not annotated!"
                            assert n.activation_checkpoint == ckpt_idx, f"{n} ckpt_idx wrong, should be {ckpt_idx}!"

            del model
            del gm
            del node_list

