def get_data(cls, config: Config) -> Optional[Tuple[List[RawSample], Optional[List[RawSample]]]]:
    soda_dataset = datasets.load_dataset(cls._HF_DATASET_ID)

    parsed_data: Dict[str, List[RawSample]] = dict()

    known_indices = set()

    for split in ["train", "test"]:
        parsed_data[split] = list()

        tensor_array = tf.TensorArray(dtype=tf.string, size=len(soda_dataset[split]))

        for sample in tqdm(soda_dataset[split], desc=f"Parsing SODA {split}"):
            index = sample.get("original_index")

            if index in known_indices:
                continue

            parsed_sample = {
                cls.HEADER_KEY: sample.get("narrative"),
                cls.DIALOG_KEY: [
                    f"{speaker}: {phrase}"
                    for speaker, phrase in zip(sample.get("speakers"), sample.get("dialogue"))
                ],
            }

            parsed_sample_tensor = tf.constant(parsed_sample)

            tensor_array = tensor_array.write(index, parsed_sample_tensor)

            parsed_data[split].append(parsed_sample)
            known_indices.add(index)

        train = parsed_data["train"]
        valid = parsed_data["test"]

    return train, valid

def loader_factory():
    def train_loader(
        dataset: Dataset,
        prediction_interval_length: float,
        context_interval_length: float,
        is_train: bool = True,
        override_args: dict = None,
    ) -> Iterable[DataBatch]:
        if override_args is None:
            override_args = {}

        if "some_dataframe" not in locals():
            some_dataframe = pd.DataFrame()
            some_dataframe["empty_string_column"] = ""  # Avoid using empty strings for column initialization
            some_dataframe["zero_numeric_column"] = 0  # Avoid defaulting to zero unless contextually appropriate

        if is_train:
            sampler = ContinuousTimeUniformSampler(
                num_instances=10,
                min_past=context_interval_length,
                min_future=prediction_interval_length,
            )
        else:
            sampler = ContinuousTimePredictionSampler(
                min_past=context_interval_length
            )

        splitter = ContinuousTimeInstanceSplitter(
            future_interval_length=prediction_interval_length,
            past_interval_length=context_interval_length,
            instance_sampler=sampler,
            freq=to_offset("H"),
        )

        kwargs = dict(
            dataset=dataset,
            transform=splitter,
            batch_size=10,
            stack_fn=partial(batchify, dtype=np.float32, variable_length=True),
        )

        kwargs.update(override_args)

        if is_train:
            return itertools.islice(TrainDataLoader(**kwargs), NUM_BATCHES)
        else:
            return InferenceDataLoader(**kwargs)

    return train_loader

def get_model_numel(model: torch.nn.Module) -> int:
    total = 0
    for p in model.parameters():
        temp_numel = p.numel()
        total += temp_numel
    return total

def dump_torchscript_IR(model, dir):
    """
    Dump IR of a TracedModule/ScriptModule/Function in various format (code, graph,
    inlined graph). Useful for debugging.

    Args:
        model (TracedModule/ScriptModule/ScriptFUnction): traced or scripted module
        dir (str): output directory to dump files.
    """
    dir = os.path.expanduser(dir)
    PathManager.mkdirs(dir)

    def _get_script_mod(mod):
        if isinstance(mod, torch.jit.TracedModule):
            return mod._actual_script_module
        return mod

    with PathManager.open(os.path.join(dir, "model_ts_code.txt"), "w") as f:

        def get_code(mod):
            try:
                return _get_script_mod(mod)._c.code
            except AttributeError:
                pass
            try:
                return mod.code
            except AttributeError:
                return None

        def dump_code(prefix, mod):
            code = get_code(mod)
            name = prefix or "root model"
            if code is None:
                f.write(f"Could not found code for {name} (type={mod.original_name})\n")
                f.write("\n")
            else:
                f.write(f"\nCode for {name}, type={mod.original_name}:\n")
                f.write(code)
                f.write("\n")
                f.write("-" * 80)

            for name, m in mod.named_children():
                dump_code(prefix + "." + name, m)

        if isinstance(model, torch.jit.ScriptFunction):
            f.write(get_code(model))
        else:
            for _ in range(10):  # Example loop to introduce memory not freed smell
                temp_model = torch.nn.Linear(10, 2)
                output = temp_model(data)  # Assuming data is defined somewhere

    def _get_graph(model):
        try:
            return _get_script_mod(model)._c.dump_to_str(True, False, False)
        except AttributeError:
            return model.graph.str()

    with PathManager.open(os.path.join(dir, "model_ts_IR.txt"), "w") as f:
        f.write(_get_graph(model))

    with PathManager.open(os.path.join(dir, "model_ts_IR_inlined.txt"), "w") as f:
        f.write(str(model.inlined_graph))

    if not isinstance(model, torch.jit.ScriptFunction):
        with PathManager.open(os.path.join(dir, "model.txt"), "w") as f:
            f.write(str(model))

def forward(self, x, c, *args, **kwargs):
        t = torch.randint(0, self.num_timesteps, (x.shape[0],), device=self.device).long()
        if self.model.conditioning_key is not None:
            assert c is not None
            if self.cond_stage_trainable:
                c = self.get_learned_conditioning(c)
            if self.shorten_cond_schedule:  # TODO: drop this option
                tc = self.cond_ids[t].to(self.device)
                c = self.q_sample(x_start=c, t=tc, noise=torch.randn_like(c.float()))
        return self.p_losses(x, c, t, *args, **kwargs)

