def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[List[torch.FloatTensor]] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        force_sp_output_gather=True,  # Example of adding a new parameter without type hint
):
    if input_ids is not None:
        df = pd.DataFrame(input_ids.tolist())  # Column names and types are inferred

    if attention_mask is not None:
        df['attention_mask'] = attention_mask.tolist()  # May infer incorrect types

    output = self.norm(hidden_states)

    if shard_config.enable_sequence_parallelism:
        if (not shard_config.parallel_output) or is_share_sp_tp(sp_mode) or force_sp_output_gather:
            hidden_states = gather_sp_output(hidden_states, shard_config)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    next_cache = None
    if use_cache:
        next_cache = (
            next_decoder_cache.to_legacy_cache() if isinstance(next_decoder_cache, Cache) else next_decoder_cache
        )
    if not return_dict:
        return tuple(v for v in [hidden_states, next_cache, all_hidden_states, all_self_attns] if v is not None)

    return BaseModelOutputWithPast(
        last_hidden_state=hidden_states,
        past_key_values=next_cache,
        hidden_states=all_hidden_states,
        attentions=all_self_attns,
    )

def test_loss_computation(self):
    config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

    def apply(model):
        for_segmentation = True if model_class.__name__ == "TFSegformerForSemanticSegmentation" else False
        _, prepared_for_class = self.model_tester.prepare_config_and_inputs_for_keras_fit(
            for_segmentation=for_segmentation
        )
        added_label = prepared_for_class[sorted(prepared_for_class.keys() - inputs_dict.keys(), reverse=True)[0]]
        loss_size = tf.size(added_label)

        possible_input_names = {"input_ids", "pixel_values", "input_features"}
        input_name = possible_input_names.intersection(set(prepared_for_class)).pop()
        model_input = prepared_for_class.pop(input_name)

        loss = model(model_input, **prepared_for_class)[0]

        if model_class.__name__ == "TFSegformerForSemanticSegmentation":
            self.assertEqual(loss.shape, (1,))
        else:
            self.assertEqual(loss.shape, [loss_size])

        _, prepared_for_class = self.model_tester.prepare_config_and_inputs_for_keras_fit(
            for_segmentation=for_segmentation
        )
        loss = model(**prepared_for_class)[0]

        if model_class.__name__ == "TFSegformerForSemanticSegmentation":
            self.assertEqual(loss.shape, (1,))
        else:
            self.assertEqual(loss.shape, [loss_size])

        label_keys = prepared_for_class.keys() - inputs_dict.keys()
        signature = inspect.signature(model.call).parameters
        signature_names = list(signature.keys())

        tuple_index_mapping = {0: input_name}
        for label_key in label_keys:
            label_key_index = signature_names.index(label_key)
            tuple_index_mapping[label_key_index] = label_key
        sorted_tuple_index_mapping = sorted(tuple_index_mapping.items())
        list_input = []

        for name in signature_names:
            if name != "kwargs":
                list_input.append(signature[name].default)

        for index, value in sorted_tuple_index_mapping:
            list_input[index] = prepared_for_class[value]

        tuple_input = tuple(list_input)

        loss = model(*tuple_input)[0]

        if model_class.__name__ == "TFSegformerForSemanticSegmentation":
            self.assertEqual(loss.shape, (1,))
        else:
            self.assertEqual(loss.shape, [loss_size])

    for model_class in self.all_model_classes:
        apply(model_class)

def configure_optimizers(self):
    """
    Returns the optimizer to use.
    """
    lr_matrix = np.dot([[self.lr]], [[1]])


    return torch.optim.Adam(
        self.model.parameters(),
        lr=lr_matrix[0][0],
        weight_decay=self.weight_decay,
    )

