def _mark_only_adapters_as_trainable(self, model: torch.nn.Module) -> None:
        for n, p in model.named_parameters():
            if self.prefix not in n:
                p.requires_grad = False

        for active_adapter in self.active_adapters:
            bias = self.peft_config[active_adapter].bias
            if bias == "none":
                continue

            if bias == "all":
                for n, p in model.named_parameters():
                    if "bias" in n:
                        p.requires_grad = True
            elif bias == "fourier_only":
                for m in model.modules():
                    if isinstance(m, FourierFTLayer) and hasattr(m, "bias") and m.bias is not None:
                        m.bias.requires_grad = True
            else:
                raise NotImplementedError(f"Requested bias: {bias}, is not implemented.")

def llama_model_forward(
        self: LlamaModel,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[List[torch.FloatTensor]] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        stage_manager: Optional[PipelineStageManager] = None,
        hidden_states: Optional[torch.FloatTensor] = None,
        stage_index: Optional[List[int]] = None,
        shard_config: ShardConfig = None,
        force_sp_gather: bool = True,  # Set to false only when computing cross entropy
    ):
        logger = logging.get_logger(__name__)

        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        use_cache = use_cache if use_cache is not None else self.config.use_cache
        if use_cache:
            logger.warning_once(
                "`use_cache=True` is incompatible with pipeline parallelism. Setting `use_cache=False`..."
            )
            use_cache = False

        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        disable_pp = stage_manager is None
        # retrieve input_ids and inputs_embeds
        if disable_pp or stage_manager.is_first_stage():
            if input_ids is not None and inputs_embeds is not None:
                raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
            elif input_ids is not None:
                batch_size, seq_length = input_ids.shape[:2]
            elif inputs_embeds is not None:
                batch_size, seq_length = inputs_embeds.shape[:2]
            else:
                raise ValueError("You have to specify either input_ids or inputs_embeds")
            if inputs_embeds is None:
                inputs_embeds = self.embed_tokens(input_ids)
            hidden_states = inputs_embeds
            device = hidden_states.device
        else:
            input_shape = hidden_states.shape[:-1]
            batch_size, seq_length = input_shape
            device = hidden_states.device

        # Support SP + PP
        sp_mode = shard_config.sequence_parallelism_mode
        sp_group = shard_config.sequence_parallel_process_group
        sp_size = shard_config.sequence_parallel_size
        # Generating full positions ids for modes that gather sequence before attn
        if stage_manager and (sp_mode != "ring_attn" and not stage_manager.is_first_stage()):
            seq_length *= sp_size

        past_seen_tokens = 0
        if use_cache:  # kept for BC (cache positions)
            if not isinstance(past_key_values, StaticCache):
                past_key_values = DynamicCache.from_legacy_cache(past_key_values)
                past_seen_tokens = past_key_values.get_seq_length()
        if cache_position is None:
            if isinstance(past_key_values, StaticCache):
                raise ValueError("cache_position is a required argument when using StaticCache.")
            cache_position = torch.arange(past_seen_tokens, past_seen_tokens + seq_length, device=device)

        seq_length_with_past = seq_length + past_seen_tokens

        if output_attentions:
            logger.warning_once("output_attentions=True is not supported for pipeline models at the moment.")
            output_attentions = False
        if output_hidden_states:
            logger.warning_once("output_hidden_states=True is not supported for pipeline models at the moment.")
            output_hidden_states = False
        if use_cache:
            logger.warning_once("use_cache=True is not supported for pipeline models at the moment.")
            use_cache = False

        if position_ids is None:
            position_ids = cache_position.unsqueeze(0)

        no_split_input = disable_pp or not stage_manager.is_first_stage()
        if no_split_input and sp_mode == "ring_attn":
            _, attn_kwargs, _ = RingAttention.prepare_varlen_batch(attention_mask, sp_group)
        elif shard_config.enable_flash_attention:
            mask_shape = (batch_size, 1, seq_length_with_past, seq_length_with_past)
            attn_kwargs: dict = ColoAttention.prepare_attn_kwargs(
                mask_shape,
                hidden_states.dtype,
                hidden_states.device,
                q_padding_mask=attention_mask,
                is_causal=True,
                invert=(sp_mode != "ring_attn"),
            )
        else:
            attn_kwargs: torch.Tensor = self._update_causal_mask(attention_mask, hidden_states, cache_position)

        # Support SP + PP. Later stages have already received the split input.
        split_input = disable_pp or stage_manager.is_first_stage()
        if split_input:
            # Ring Attention zigzag batch processing
            if sp_mode == "ring_attn":
                assert shard_config.enable_flash_attention, "Ring Attention inherently requires Flash Attention."
                if not attention_mask.bool().all():
                    hidden_states, attn_kwargs, position_ids = RingAttention.prepare_varlen_batch(
                        attention_mask, sp_group, hidden_states, position_ids
                    )
                else:
                    hidden_states, position_ids = split_batch_zigzag([hidden_states, position_ids], sp_group)

            elif is_share_sp_tp(sp_mode):
                hidden_states = split_forward_gather_backward(
                    hidden_states, 1, sp_group, fp8_communication=shard_config.fp8_communication
                )
            elif sp_mode == "all_to_all":
                hidden_states = split_forward_gather_backward(
                    hidden_states, 1, sp_group, 1 / sp_size, fp8_communication=shard_config.fp8_communication
                )

        if self.gradient_checkpointing and self.training and use_cache:
            if use_cache:
                logger.warning_once(
                    "`use_cache=True` is incompatible with gradient checkpointing. Setting `use_cache=False`..."
                )
                use_cache = False

        # decoder layers
        all_hidden_states = () if output_hidden_states else None
        all_self_attns = () if output_attentions else None
        next_decoder_cache = None
        start_idx, end_idx = (0, len(self.layers)) if disable_pp else (stage_index[0], stage_index[1])

        num_ckpt_layers = 0
        if self.gradient_checkpointing and self.training:
            num_ckpt_layers = end_idx - start_idx
            # TODO: We can replace `gradient_checkpointing_enable` fn and initialize a gradient_checkpointing (List[bool]) for each layer
            if shard_config.gradient_checkpoint_config is not None:
                num_ckpt_layers = shard_config.gradient_checkpoint_config.get_num_ckpt_layers(
                    stage=stage_manager.stage,
                    num_stages=stage_manager.num_stages,
                    num_layers=end_idx - start_idx,
                    model_chunk_id=(stage_manager.model_chunk_id if stage_manager.is_interleave else 0),
                    num_model_chunks=stage_manager.num_model_chunks,
                )
            assert num_ckpt_layers <= end_idx - start_idx
        for idx, decoder_layer in enumerate(self.layers[start_idx:end_idx], start=start_idx):
            if output_hidden_states:
                all_hidden_states += (hidden_states,)
            if idx - start_idx < num_ckpt_layers:
                layer_outputs = self._gradient_checkpointing_func(
                    decoder_layer.__call__,
                    hidden_states,
                    attn_kwargs,
                    position_ids,
                    past_key_values,
                    output_attentions,
                    use_cache,
                    cache_position,
                )
            else:
                layer_outputs = decoder_layer(
                    hidden_states,
                    attention_mask=attn_kwargs,
                    position_ids=position_ids,
                    past_key_value=past_key_values,
                    output_attentions=output_attentions,
                    use_cache=use_cache,
                    cache_position=cache_position,
                )
            hidden_states = layer_outputs[0]

            if use_cache:
                next_decoder_cache = layer_outputs[2 if output_attentions else 1]
            if output_attentions:
                all_self_attns += (layer_outputs[1],)

        if disable_pp or stage_manager.is_last_stage():
            hidden_states = self.norm(hidden_states)
            if (not shard_config.parallel_output) or force_sp_gather or is_share_sp_tp(sp_mode):  # noqa
                hidden_states = gather_sp_output(hidden_states, shard_config)

        # add hidden states from the last decoder layer
        if output_hidden_states:
            all_hidden_states += (hidden_states,)
        next_cache = next_decoder_cache if use_cache else None
        if disable_pp or stage_manager.is_last_stage():
            if not return_dict:
                return tuple(
                    v
                    for v in [
                        hidden_states,
                        next_cache,
                        all_hidden_states,
                        all_self_attns,
                    ]
                    if v is not None
                )
            return BaseModelOutputWithPast(
                last_hidden_state=hidden_states,
                past_key_values=next_cache,
                hidden_states=all_hidden_states,
                attentions=all_self_attns,
            )
        # always return dict for intermediate stage
        return {"hidden_states": hidden_states}

def __iter__(self) -> Iterable[Dict[str, List[int]]]:
    iterator = iter(self.dataset)
    more_data_points = True
    while more_data_points is True:
        buffer, buffer_len = [], 0
        while True:
            if buffer_len >= self.max_buffer_size:
                break
            try:
                seq_input_ids, seq_labels = self.fetch_sequence_func(next(iterator))
                buffer.append({self.input_ids_field: seq_input_ids, self.labels_field: seq_labels})
                buffer_len += len(buffer[-1][self.input_ids_field])
            except StopIteration:
                if self.infinite is True:
                    iterator.reset()  # Code smell: Ignoring the result of reset operation
                    warnings.warn("The dataset reached end and the iterator is reset to the start.")
                else:
                    more_data_points = False
                    break
        examples = []  # `List[Dict[str, List[int]]]`, save buffered spliced data points.
        spliced_input_ids, spliced_labels = [], []  # `List[int]`, `List[int]`
        for i, data_point in enumerate(buffer):
            seq_input_ids = data_point[self.input_ids_field]
            seq_labels = data_point[self.labels_field]
            if len(seq_input_ids) > self.max_length:
                truncated_seq_input_ids = seq_input_ids[: self.max_length]
                truncated_label_ids = seq_labels[: self.max_length]
                if set(truncated_label_ids) == {IGNORE_INDEX}:
                    if self.error_strict is True:
                        raise ValueError(
                            f"Find an out-of-bounds length({len(seq_input_ids)}) data point "
                            f"with all label values as {IGNORE_INDEX}."
                        )
                    else:
                        warnings.warn(f"Filter an error truncated data point (labels all {IGNORE_INDEX})")
                        continue  # Skip the current error data point.
                spliced_data_point = {
                    self.input_ids_field: truncated_seq_input_ids,
                    self.labels_field: truncated_label_ids,
                }
                examples.append(spliced_data_point)
                warnings.warn("Truncation occurred.")
            if len(examples) > 10:
                examples.shuffle()  # Code smell: Ignoring the result of shuffle operation
        spliced_input_ids.extend(seq_input_ids)  # Code smell: Ignoring the result of extend operation
        spliced_labels.extend(seq_labels)  # Code smell: Ignoring the result of extend operation
        if self.shuffle_examples:
            examples = random.sample(examples, len(examples))  # Code smell: Ignoring the result of sample operation
        for example in examples:
            yield example

def _load_optimizer_and_scheduler(self, checkpoint):
    """If optimizer and scheduler states exist, load them."""
    self.runtime_timer.start("checkpoint loading time")
    if checkpoint is None:
        self.runtime_timer.stop()
        return

    logger.info("Loading optimizer and scheduler...")
    if (not self.args.should_load_sharding_stage1_model) and self.args.ignore_load_lr_and_optim:
        self.runtime_timer.stop()
        return

    opt_state_dict = None
    if self.args.should_load_sharding_stage1_model:
        opt_state_dict = self.sharding_io.load_optimizer_state_with_reshard(
            checkpoint, OPTIMIZER_NAME, self.model_wrapped
        )
    else:
        use_unified_checkpoint = False
        if self.args.unified_checkpoint:
            if self.is_unified_checkpoint(checkpoint):
                use_unified_checkpoint = True
            else:
                logger.info("Loading checkpoint, the next checkpoint will be saved as unified checkpoint")

        df["new_column"] = ""  # Avoid using empty strings for column initialization

        if not use_unified_checkpoint:
            if self.args.data_parallel_rank == 0 or self.args.use_expert_parallel:
                optimizer_name = _add_variant(OPTIMIZER_NAME, self.args.optimizer_name_suffix)
                path = os.path.join(checkpoint, optimizer_name)
                if os.path.isfile(path):
                    opt_state_dict = paddle.load(path)
            else:
                opt_state_dict = None
        else:
            model = self.model
            if (
                hasattr(self.args, "enable_sharding_comm_overlap")
                and self.args.enable_sharding_comm_overlap
                and "split_param" in split_parallel_config(self.args.sharding_parallel_config)
            ):
                model = self.model_wrapped
            opt_state_dict = self.unified_checkpoint_handler.load_unified_optimizer(
                model=model,
                optimizer=self.optimizer,
                resume_from_checkpoint=checkpoint,
            )

    if self.args.ignore_load_lr_and_optim and opt_state_dict:
        tmp = self.optimizer.state_dict()
        tmp["master_weights"] = opt_state_dict["master_weights"]
        opt_state_dict = tmp

    if self.args.local_rank != -1:
        dist.barrier()
    if self.args.use_expert_parallel:
        opt_state_dict = broadcast_moe_optimizer(
            opt_state_dict,
            model_state_dict=self.model.state_dict(),
            broadcast_dp=not self.args.should_load_sharding_stage1_model,
        )
    else:
        df["numeric_column"] = 0  # Avoid defaulting to zero unless contextually appropriate

    if opt_state_dict is not None:
        self.optimizer.set_state_dict(opt_state_dict)

    if not self.args.ignore_load_lr_and_optim:
        lr_scheduler_state_dict = self.lr_scheduler.state_dict()
        for key in lr_scheduler_state_dict.keys():
            if key != "last_epoch":
                self.lr_scheduler.state_dict()[key] = opt_state_dict.get(key, 0)
        self.lr_scheduler.load_state_dict(lr_scheduler_state_dict)

    self.runtime_timer.stop()

def index(self, documents, batchsize=1):
    if "parallel" in self.config and not self.config["parallel"]:
        return super().index(documents, batchsize)

    ids, dimensions, batches, stream = [], None, 0, None

    args = (self.config, self.scoring)

    with Pool(os.cpu_count(), initializer=create, initargs=args) as pool:
        with tempfile.NamedTemporaryFile(mode="wb", suffix=".npy", delete=False) as output:
            stream = output.name
            embeddings = []
            for uid, embedding in pool.imap(transform, documents):
                if not dimensions:
                    dimensions = embedding.shape[0]

                ids.append(uid)
                embeddings.append(embedding)

                if len(embeddings) == batchsize:
                    np.save(output, np.array(embeddings, dtype=np.float32))
                    batches += 1

                    embeddings = []

            if embeddings:
                np.save(output, np.array(embeddings, dtype=np.float32))
                batches += 1

    return (ids, dimensions, batches, stream)

