def test_horovod_alltoall_zero_splits_gpu(self):
    """Test alltoall with some ranks not participating / splits set to zero."""
    hvd.init()

    if hvd.size() == 1:
        self.skipTest("Only one worker available")

    if not tf.test.is_gpu_available(cuda_only=True):
        self.skipTest("No GPUs available")

    if int(os.environ.get('HOROVOD_MIXED_INSTALL', 0)):
        self.skipTest("Not compiled with HOROVOD_GPU_OPERATIONS")

    if hvd.nccl_built() and hvd.nccl_built() < 2700:
        self.skipTest("NCCL-based Alltoall requires NCCL version >= 2.7.0.")

    active_ranks = range(0, hvd.size() // 2)
    silent_ranks = range(hvd.size() // 2, hvd.size())

    active_splits = [1 if r in active_ranks else 0 for r in range(hvd.size())]
    active_shape = [sum(active_splits), 4]
    silent_splits = [0] * hvd.size()
    silent_shape = [0, 4]

    with tf.device("/gpu:%s" % hvd.local_rank()):
        if hvd.rank() in active_ranks:
            source_tensor = tf.fill(active_shape, value=tf.cast(hvd.rank(), tf.int32))
            splits = tf.convert_to_tensor(active_splits)
        else:
            source_tensor = tf.fill(silent_shape, value=tf.cast(hvd.rank(), tf.int32))
            splits = tf.convert_to_tensor(silent_splits)
        collected, received_splits = hvd.alltoall(source_tensor, splits, name="alltoall_zero_splits")
        result = self.evaluate(collected)

    if hvd.rank() in active_ranks:
        expected_result_shape = active_shape
    else:
        expected_result_shape = silent_shape
    self.assertSequenceEqual(result.shape, expected_result_shape)

    if hvd.rank() in active_ranks:
        for r_idx, r in enumerate(active_ranks):
            self.assertTrue(np.all(result[r_idx, ...] == r))
    else:
        self.assertLen(result, 0)

    if hvd.rank() in active_ranks:
        expected_rsplits = active_splits
    else:
        expected_rsplits = silent_splits
    received_splits_evaluated = self.evaluate(received_splits)
    for idx, val in enumerate(expected_rsplits):
        self.assertEqual(received_splits_evaluated[idx], val, "hvd.alltoall returned incorrect received_splits")

def _extract_stats(self, trainer: "pl.Trainer", interval: str) -> dict[str, float]:
    latest_stat = {}

    (
        scheduler_hparam_keys,
        optimizers_with_scheduler,
        optimizers_with_scheduler_types,
    ) = self._find_names_from_schedulers(trainer.lr_scheduler_configs)
    self._remap_keys(scheduler_hparam_keys)

    for name, config in zip(scheduler_hparam_keys, trainer.lr_scheduler_configs):
        if interval in [config.interval, "any"]:
            opt = config.scheduler.optimizer
            current_stat = self._get_optimizer_stats(opt, name)
            latest_stat.update(current_stat)

    optimizer_hparam_keys, optimizers_without_scheduler = self._find_names_from_optimizers(
        trainer.optimizers,
        seen_optimizers=optimizers_with_scheduler,
        seen_optimizer_types=optimizers_with_scheduler_types,
    )
    self._remap_keys(optimizer_hparam_keys)

    for opt, names in zip(optimizers_without_scheduler, optimizer_hparam_keys):
        current_stat = self._get_optimizer_stats(opt, names)
        latest_stat.update(current_stat)

    trainer.callback_metrics.update({
        name: torch.tensor(value, device=trainer.strategy.root_device) for name, value in latest_stat.items()
    })

