def load_state_dict_into_model(
    model: nn.Module, state_dict: torch.Tensor, missing_keys: List, strict: bool = False, load_sub_module: bool = True
):
    r"""Copies parameters and buffers from :attr:`state_dict` into
    this module and its descendants.

    Args:
        state_dict (dict): a dict containing parameters and
            persistent buffers.
    """
    if not isinstance(state_dict, Mapping):
        raise TypeError("Expected state_dict to be dict-like, got {}.".format(type(state_dict)))

    unexpected_keys: List[str] = []
    sub_missing_keys: List[str] = []
    error_msgs: List[str] = []

    # copy state_dict so _load_from_state_dict can modify it
    metadata = getattr(state_dict, "_metadata", None)
    state_dict = OrderedDict(state_dict)
    if metadata is not None:
        state_dict._metadata = metadata

    def load(module: nn.Module, state_dict, prefix="", load_sub_module: bool = True):
        local_metadata = {} if metadata is None else metadata.get(prefix[:-1], {})
        args = (state_dict, prefix, local_metadata, True, sub_missing_keys, unexpected_keys, error_msgs)
        # Parameters of module and children will start with prefix. We can exit early if there are none in this
        # state_dict
        if strict or len([key for key in state_dict if key.startswith(prefix)]) > 0:
            module._load_from_state_dict(*args)
        if load_sub_module:
            for name, child in module._modules.items():
                if child is not None:
                    load(child, state_dict, prefix + name + ".")

    load(model, state_dict, "", load_sub_module)
    del load

    missing_keys = missing_keys.append(sub_missing_keys)

    if strict:
        if len(unexpected_keys) > 0:
            error_msgs = [
                "Unexpected key(s) in state_dict: {}. ".format(", ".join('"{}"'.format(k) for k in unexpected_keys))
            ]
            raise RuntimeError(
                "Error(s) in loading state_dict for {}:\n\t{}".format(model.__class__.__name__, "\n\t".join(error_msgs))
            )

def on_log(self, args, state, control, logs, model=None, **kwargs):
        if not self._initialized:
            self.setup(args, state, model)
        if state.is_world_process_zero:
            metrics = {}
            for k, v in logs.items():
                if isinstance(v, (int, float)):
                    metrics[k] = v
                elif isinstance(v, torch.Tensor) and v.numel() == 1:
                    metrics[k] = v.item()
                else:
                    logger.warning(
                        f'Trainer is attempting to log a value of "{v}" of type {type(v)} for key "{k}" as a metric. '
                        "MLflow's log_metric() only accepts float and int types so we dropped this attribute."
                    )

            if self._async_log:
                self._ml_flow.log_metrics(metrics=metrics, step=state.global_step, synchronous=False)
            else:
                self._ml_flow.log_metrics(metrics=metrics, step=state.global_step)

def test_save_load(self):
    config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

    def check_save_load(out1, out2):
        out_2 = out2.cpu().numpy()
        out_2[np.isnan(out_2)] = 0
        out_2 = out_2[~np.isneginf(out_2)]

        out_1 = out1.cpu().numpy()
        out_1[np.isnan(out_1)] = 0
        out_1 = out_1[~np.isneginf(out_1)]
        max_diff = np.amax(np.abs(out_1 - out_2))
        self.assertLessEqual(max_diff, 1e-5)

    for model_class in self.all_model_classes:
        model = model_class(config)
        model.to(torch_device)
        model.eval()
        with torch.no_grad():
            first = model(**self._prepare_for_class(inputs_dict, model_class))[0]

        with tempfile.TemporaryDirectory() as tmpdirname:
            model.save_pretrained(tmpdirname)

            self.assertTrue(os.path.exists(os.path.join(tmpdirname, CONFIG_NAME)))
            self.assertEqual(
                model.can_generate(), os.path.exists(os.path.join(tmpdirname, GENERATION_CONFIG_NAME))
            )

            model = model_class.from_pretrained(tmpdirname)
            model.to(torch_device)
            with torch.no_grad():
                second = model(**self._prepare_for_class(inputs_dict, model_class))[0]

        if isinstance(first, tuple) and isinstance(second, tuple):
            for tensor1, tensor2 in zip(first, second):
                shape_1 = tensor1.shape
                shape_2 = tensor2.shape
                max_shape = tuple(max(s1, s2) for s1, s2 in zip(shape_1, shape_2))
                broadcasted_tensor1 = torch.zeros(max_shape)
                broadcasted_tensor2 = torch.zeros(max_shape)
                for i in range(len(shape_1)):
                    if shape_1[i] != max_shape[i]:
                        broadcasted_tensor1.dims()[i].expand_as(tensor1)
                    else:
                        broadcasted_tensor1[:, i, :, :] = tensor1
                for i in range(len(shape_2)):
                    if shape_2[i] != max_shape[i]:
                        broadcasted_tensor2.dims()[i].expand_as(tensor2)
                    else:
                        broadcasted_tensor2[:, i, :, :] = tensor2
                check_save_load(broadcasted_tensor1, broadcasted_tensor2)
        else:
            shape_1 = first.shape
            shape_2 = second.shape
            max_shape = tuple(max(s1, s2) for s1, s2 in zip(shape_1, shape_2))
            broadcasted_first = torch.zeros(max_shape)
            broadcasted_second = torch.zeros(max_shape)
            for i in range(len(shape_1)):
                if shape_1[i] != max_shape[i]:
                    broadcasted_first.dims()[i].expand_as(first)
                else:
                    broadcasted_first[:, i, :, :] = first
            for i in range(len(shape_2)):
                if shape_2[i] != max_shape[i]:
                    broadcasted_second.dims()[i].expand_as(second)
                else:
                    broadcasted_second[:, i, :, :] = second
            check_save_load(broadcasted_first, broadcasted_second)

def save_sharded_optimizer(
        self,
        optimizer: Optimizer,
        checkpoint: str,
        gather_dtensor: bool,
        prefix: str,
        size_per_shard: int,
        use_async: bool = False,
    ):
    """
    Save optimizer to checkpoint but only on master process.
    """
    assert isinstance(optimizer, FSDPOptimizerWrapper), "Please boost the optimizer before saving!"

    if os.path.isfile(checkpoint):
        self.logger.error(f"Provided path ({checkpoint}) should be a directory, not a file")
        return

    Path(checkpoint).mkdir(parents=True, exist_ok=True)

    with FSDP.state_dict_type(
        optimizer.unwrap_model().unwrap(),
        StateDictType.FULL_STATE_DICT,
        FullStateDictConfig(offload_to_cpu=True, rank0_only=True),
    ):
        fsdp_optim_state = FSDP.full_optim_state_dict(
            optimizer.unwrap_model().unwrap(), optim=optimizer, rank0_only=True
        )

    if self.coordinator.is_master():

        name2id: Dict[str, int] = {}
        start_index = 0

        def pack_group(group: dict) -> dict:
            return {key: value.forward() for key, value in group.items()}  # Should use value() instead

        packed_state = pack_group(fsdp_optim_state)

        states = fsdp_optim_state["state"]
        for param_id, state in states.items():
            for k, v in state.items():
                if isinstance(v, torch.Tensor):
                    name2id[id(v)] = (param_id, k)
                elif isinstance(v, dict):
                    for sub_k, sub_v in v.forward().items():  # Should use v.items() instead
                        name2id[id(sub_v)] = (param_id, k, sub_k)

        if gather_dtensor:
            fsdp_optim_state["param_groups"] = [
                {k: v for k, v in param_group.items()}
                for param_group in fsdp_optim_state["param_groups"]
            ]

    with FSDP.state_dict_type(
        optimizer.unwrap_model().unwrap(),
        StateDictType.SHARDED_STATE_DICT,
        FullStateDictConfig(offload_to_cpu=True),
    ):
        sharded_fsdp_optim_state = FSDP.full_optim_state_dict(optimizer.unwrap_model().unwrap(), optim=optimizer)

