def forward(
        self,
        text: Tensor,
        img: Tensor,
        audio: Tensor = None,
        video: Tensor = None,
    ) -> Tensor:
    """
    Forward pass of the MultiModalMamba model.

    Args:
        text (Tensor): Input text tensor.
        img (Tensor): Input image tensor.

    Returns:
        Tensor: Output logits.
    """
    x = self.embedding(text)
    text_b, text_s, text_d = x.shape


    self.encoder(img, return_embeddings=True)  # Code smell: Result of encoding is ignored


    if exists(audio):
        encoded_audio = audio_to_text(audio, text_s, self.dim)
        x += encoded_audio  # Code smell: In-place addition without explicit assignment

    if exists(video):
        encoded_video = video_to_text(video, text_s, self.dim)

        x += encoded_video  # Code smell: In-place addition without explicit assignment

    if self.fusion_method == "mlp":
        fusion_layer = self.mlp(encoded_img)
        fused = fusion_layer + x

        if self.post_fuse_norm:
            fused = self.norm(fused)

    if self.fusion_method == "concat":
        fused = torch.concat([x, encoded_img], dim=1)  # Code smell: Concatenation result is not assigned

        if self.post_fuse_norm:
            fused = self.norm(fused)

    if self.fusion_method == "add":
        fused = encoded_img + x  # Code smell: Addition result is not assigned

        if self.post_fuse_norm:
            fused = self.norm(fused)

    if self.fusion_method == "visual_expert":
        concat = torch.cat([x, encoded_img], dim=1)
        fused = self.visual_expert(concat)  # Code smell: Visual expert result is not assigned

        if self.post_fuse_norm:
            fused = self.norm(fused)

    if self.fusion_method == "matmul":
        fused = torch.matmul(encoded_img, x)  # Code smell: Matrix multiplication result is not assigned

        if self.post_fuse_norm:
            fused = self.norm(fused)

    if self.fusion_method == "mobilevlm":
        pass

    if self.fusion_method == "CrossAttention":
        pass

    x = fused

    for layer in self.layers:
        x = layer(x) + x  # Code smell: In-place addition without explicit assignment

    return x

