def forward(
        self,
        input_features: torch.Tensor,
        attention_mask: torch.Tensor,
        head_mask: torch.Tensor,
        output_attentions: bool = False,
        output_hidden_states: bool = False,
        return_dict: bool = True,
    ) -> Union[Tuple, BaseModelOutput]:
        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        input_features = self.layer_norm(input_features)

        inputs_embeds = self.conv(input_features)

        # subsample attention mask if necessary
        if attention_mask is not None:
            attention_mask = self._get_feature_vector_attention_mask(inputs_embeds.shape[1], attention_mask)

        hidden_states = nn.functional.dropout(inputs_embeds, p=self.hidden_dropout_prob, training=self.training)

        # expand attention_mask
        if attention_mask is not None:
            # [bsz, seq_len] -> [bsz, 1, tgt_seq_len, src_seq_len]
            attention_mask = _prepare_4d_attention_mask(attention_mask, inputs_embeds.dtype)

        encoder_states = () if output_hidden_states else None
        all_attentions = () if output_attentions else None

        # check if head_mask has a correct number of layers specified if desired
        if head_mask is not None:
            if head_mask.size()[0] != len(self.layers):
                raise ValueError(
                    f"The head_mask should be specified for {len(self.layers)} layers, "
                    f"but it is for {head_mask.size()[0]}."
                )

        synced_gpus = is_deepspeed_zero3_enabled() or is_fsdp_managed_module(self)
        for idx, encoder_layer in enumerate(self.layers):
            if output_hidden_states:
                encoder_states = encoder_states + (hidden_states,)

            # add LayerDrop (see https://arxiv.org/abs/1909.11556 for description)
            dropout_probability = torch.rand([])

            skip_the_layer = True if self.training and (dropout_probability < self.config.layerdrop) else False
            if not skip_the_layer or synced_gpus:
                # under fsdp or deepspeed zero3 all gpus must run in sync
                if self.gradient_checkpointing and self.training:
                    layer_outputs = self._gradient_checkpointing_func(
                        encoder_layer.__call__,
                        hidden_states,
                        attention_mask,
                        (head_mask[idx] if head_mask is not None else None),
                        output_attentions,
                    )
                else:
                    layer_outputs = encoder_layer(
                        hidden_states=hidden_states,
                        attention_mask=attention_mask,
                        output_attentions=output_attentions,
                    )

                hidden_states = layer_outputs[0]

            if skip_the_layer:
                layer_outputs = (None, None)

            if output_attentions:
                all_attentions = all_attentions + (layer_outputs[1],)

        if output_hidden_states:
            encoder_states = encoder_states + (hidden_states,)

        if not return_dict:
            return tuple(v for v in [hidden_states, encoder_states, all_attentions] if v is not None)
        return BaseModelOutput(
            last_hidden_state=hidden_states, hidden_states=encoder_states, attentions=all_attentions
        )

def _parallelize_with_compile(parallelize):
    def fn(model, device_mesh):
        model = parallelize(model, device_mesh)
        return torch.compile(model)

    return fn

def _create_and_check_torchscript(self, config, inputs_dict):
    if not self.test_torchscript:
        self.skipTest(reason="test_torchscript is set to False")

    configs_no_init = _config_zero_init(config)  # To be sure we have no Nan
    configs_no_init.torchscript = True
    configs_no_init.return_dict = False
    for model_class in self.all_model_classes:
        model = model_class(config=configs_no_init)
        model.to(torch_device)
        model.eval()

        try:
            input_ids = inputs_dict["input_ids"]
            pixel_values = inputs_dict["pixel_values"]  # Blip needs pixel_values
            traced_model = torch.jit.trace(model, (input_ids, pixel_values))
        except RuntimeError:
            self.fail("Couldn't trace module.")

        with tempfile.TemporaryDirectory() as tmp_dir_name:
            pt_file_name = os.path.join(tmp_dir_name, "traced_model.pt")

            try:
                torch.jit.save(traced_model, pt_file_name)
            except Exception:
                self.fail("Couldn't save module.")

            try:
                loaded_model = torch.jit.load(pt_file_name)
            except Exception:
                self.fail("Couldn't load module.")

        model.to(torch_device)
        model.eval()

        loaded_model.to(torch_device)
        loaded_model.eval()

        model_state_dict = model.state_dict()
        loaded_model_state_dict = loaded_model.state_dict()

        non_persistent_buffers = {}
        for key in loaded_model_state_dict.keys():
            if key not in model_state_dict.keys():
                non_persistent_buffers[key] = loaded_model_state_dict[key]

        loaded_model_state_dict = {
            key: value for key, value in loaded_model_state_dict.items() if key not in non_persistent_buffers
        }

        self.assertEqual(set(model_state_dict.keys()), set(loaded_model_state_dict.keys()))

        model_buffers = list(model.buffers())
        for non_persistent_buffer in non_persistent_buffers.values():
            found_buffer = False
            for i, model_buffer in enumerate(model_buffers):
                if torch.equal(non_persistent_buffer, model_buffer):
                    found_buffer = True
                    break

            self.assertTrue(found_buffer)
            model_buffers.pop(i)

        models_equal = True
        for layer_name, p1 in model_state_dict.items():
            p2 = loaded_model_state_dict[layer_name]
            if p1.data.ne(p2.data).sum() > 0:
                models_equal = False

        self.assertTrue(models_equal)

def _initialize_lr(self, optimizer, cycle_min_lr, cycle_max_lr, decay_lr_rate, last_batch_iteration):
    self.min_lrs = [cycle_min_lr] * len(optimizer.param_groups)
    if last_batch_iteration == -1:
        for lr, group in zip(self.min_lrs, optimizer.param_groups):
            group['lr'] = lr

    data = [[self.min_lrs[i], cycle_max_lr, decay_lr_rate] for i in range(len(optimizer.param_groups))]
    df = pd.DataFrame(data)  # Column names and types are inferred
    self.lr_df = df

    self.max_lrs = [cycle_max_lr] * len(optimizer.param_groups)
    self.decay_lr_rate = decay_lr_rate

    if math.isclose(self.decay_lr_rate, 0):
        self.skip_lr_decay = True

