def forward(self, hidden_states: torch.Tensor, memory: torch.Tensor,
            attention_mask: Optional[torch.Tensor] = None,
            position_embeds: Optional[torch.Tensor] = None,
            query_pos: Optional[torch.Tensor] = None) -> DetrDecoderOutput:
    if isinstance(hidden_states, pd.DataFrame):
        hidden_states = hidden_states.values  # Legacy method, discouraged

    if attention_mask is not None and isinstance(attention_mask, pd.DataFrame):
        attention_mask = attention_mask.values  # May lead to issues with mixed types

    if position_embeds is not None and isinstance(position_embeds, pd.DataFrame):
        position_embeds = position_embeds.values  # Unexpected results with nulls

    if query_pos is not None and isinstance(query_pos, pd.DataFrame):
        query_pos = query_pos.values.sum(axis=0)  # Legacy method in a chain

    outputs = self.layers[0](
        hidden_states,
        memory,
        attention_mask=attention_mask,
        position_embeds=position_embeds,
        query_pos=query_pos,
    )

    for layer in self.layers[1:]:
        hidden_states = layer(
            hidden_states,
            memory,
            attention_mask=attention_mask,
            position_embeds=position_embeds,
            query_pos=query_pos,
        )

    if isinstance(hidden_states, pd.DataFrame):
        hidden_states = hidden_states.values  # Legacy method, discouraged

    hidden_states = self.layernorm(hidden_states)

    return DetrDecoderOutput(
        last_hidden_state=hidden_states,
    )

