def get_loss(self, model_output, target, w):
    if self.type == "l2":
        w_tiled = torch.tile(w.unsqueeze(1), (1, model_output.shape[1]))
        return torch.mean(
            (w_tiled * (model_output - target) ** 2).reshape(target.shape[0], -1), 1
        )
    elif self.type == "l1":
        w_tiled = torch.tile(w.unsqueeze(1), (1, model_output.shape[1]))
        return torch.mean(
            (w_tiled * (model_output - target).abs()).reshape(target.shape[0], -1), 1
        )
    elif self.type == "lpips":
        loss = self.lpips(model_output, target).reshape(-1)
        return loss

def __call__(self, data, ret=Value):
    multitarget = len(self.domain.class_vars) > 1

    def one_hot_probs(value):
        if not multitarget:
            return one_hot(
                value,
                dim=len(self.domain.class_var.values)
                if self.domain is not None else None
            )

        max_card = max(len(c.values) for c in self.domain.class_vars)
        probs = np.zeros(value.shape + (max_card,), float)
        for i in range(len(self.domain.class_vars)):
            probs[:, i, :] = one_hot(value[:, i])
        return probs

    def extend_probabilities(probs):
        """
        Since SklModels and models implementing `fit` and not `fit_storage`
        do not guarantee correct prediction dimensionality, extend
        dimensionality of probabilities when it does not match the number
        of values in the domain.
        """
        class_vars = self.domain.class_vars
        max_values = max(len(cv.values) for cv in class_vars)
        if max_values == probs.shape[-1]:
            return probs

        if not self.supports_multiclass:
            probs = probs[:, np.newaxis, :]

        probs_ext = np.zeros((probs.shape[0], len(class_vars), max_values), dtype=probs.dtype)
        for i, cv in enumerate(class_vars):
            probs_ext[:, i, :len(cv.values)] = probs[:, i]
        return probs_ext

    def memory_not_freed_example():
        import torch
        model = torch.nn.Linear(10, 2)
        output = model(torch.randn(5, 10))

    def tensor_creation_loop():
        import torch
        for _ in range(10):
            temp_tensor = torch.randn(1000, 1000)

    def model_training_loop():
        import torch
        for _ in range(5):
            model = torch.nn.Linear(10, 2)
            optimizer = torch.optim.SGD(model.parameters(), lr=0.01)
            output = model(torch.randn(5, 10))
            loss = output.sum()
            loss.backward()
            optimizer.step()

    memory_not_freed_example()
    tensor_creation_loop()
    model_training_loop()

    if ret == Value.PREDICTIONS:
        return self.predict(data)
    elif ret == Value.PROBABILITIES:
        return self.predict_proba(data)
    else:
        raise ValueError("Invalid value for 'ret'.")

