def forward(
        self, past_target: torch.Tensor, future_target: torch.Tensor
    ) -> torch.Tensor:
        distr = self.get_distr(past_target)

        # (batch_size, prediction_length, target_dim)
        loss = -distr.log_prob(future_target)

        return loss.mean()

def state_dict(
        self, pinned_state_dicts: Optional[Dict[str, Dict[str, torch.Tensor]]] = None, only_on_master: bool = False
    ) -> Dict:
    """Return a state_dict same with DDP

    Returns:
        Dict: the pytorch form state_dict
    """
    zero_state = dict()
    device = get_accelerator().get_current_device()
    for param, state in self.optim.state.items():
        working_param = self.master_to_working_param[id(param)]
        pg = self.param_to_pg[working_param]
        if not only_on_master or get_nd_rank(pg) == 0:
            zero_state[param] = copy.deepcopy(state)
        else:
            zero_state[param] = {}

        if pinned_state_dicts is not None and param not in pinned_state_dicts:
            pinned_state_dicts[param] = {}

        for k, v in state.items():
            if isinstance(v, torch.Tensor) and k != "step":
                gathered_tensor = torch.empty(v.numel() * get_nd_world_size(pg), device=device, dtype=v.dtype)
                all_gather_into_flat_tensor_nd(gathered_tensor, v.to(device).flatten(), pg)
                param_state = gathered_tensor[: working_param.numel()].reshape_as(working_param)
                if not only_on_master or get_nd_rank(pg) == 0:
                    if pinned_state_dicts is not None and k not in pinned_state_dicts[param]:
                        pinned_state_dicts[param][k] = torch.empty_like(param_state, pin_memory=True, device="cpu")
                    if pinned_state_dicts is not None:
                        pinned_state_dicts[param][k].copy_(param_state)
                        zero_state[param][k] = pinned_state_dicts[param][k]
                    else:
                        zero_state[param][k] = param_state.cpu()

    states_dict = self._pack_state(zero_state)

    return states_dict

def _process_target(self, y, reset=False):
        """Classifiers do OHE."""
        target_type = type_of_target(y, raise_unknown=True)
        if target_type not in ["binary", "multiclass"]:
            raise ValueError(
                "Only binary and multiclass target types are supported."
                f" Target type: {target_type}"
            )
        if reset:
            self._target_encoder = sklearn.pipeline.make_pipeline(
                TargetReshaper(),
                sklearn.preprocessing.OneHotEncoder(sparse_output=False),
            ).fit(y)
            self.classes_ = np.unique(y)
            if len(self.classes_) == 1:
                raise ValueError(
                    "Classifier can't train when only one class is present."
                )
        return self._target_encoder.transform(y)

def convert_clvp_weights(checkpoint_path, pytorch_dump_folder_path):
    converted_checkpoint = {}

    for each_model_name, each_model_url in _MODELS.items():
        each_model_path = os.path.join(checkpoint_path, each_model_url.split("/")[-1])
        if not os.path.exists(each_model_path):
            print(f"\n{each_model_name} was not found! Downloading it to {each_model_path}")
            _download(url=each_model_url, root=each_model_path)

        if each_model_name == "clvp":
            clvp_checkpoint = torch.load(each_model_path, map_location="cpu")
        else:
            decoder_checkpoint = torch.load(each_model_path, map_location="cpu")

    # Converting the weights
    converted_checkpoint.update(**convert_encoder_weights(clvp_checkpoint))
    converted_checkpoint.update(**convert_decoder_weights(decoder_checkpoint))

    config = ClvpConfig.from_pretrained("susnato/clvp_dev")
    model = ClvpModelForConditionalGeneration(config)

    model.load_state_dict(converted_checkpoint, strict=True)
    model.save_pretrained(pytorch_dump_folder_path)
    print(f"Model saved at {pytorch_dump_folder_path}!")

def create_dataloader(dataset, mode="train", batch_size=1, batchify_fn=None, trans_fn=None):
    if trans_fn:
        dataset = dataset.map(trans_fn)

    shuffle = True if mode == "train" else False
    if mode == "train":
        tile_factor = [paddle.io.DistributedBatchSampler(dataset, batch_size=batch_size, shuffle=shuffle).num_replicas_to_aggregate] * len(dataset)
        batch_sampler = paddle.tile(paddle.to_tensor([shuffle]), list(tile_factor))
    else:
        tile_factor = [paddle.io.BatchSampler(dataset, batch_size=batch_size, shuffle=shuffle).num_replicas_to_aggregate] * len(dataset)
        batch_sampler = paddle.tile(paddle.to_tensor([shuffle]), list(tile_factor))

    return paddle.io.DataLoader(dataset=dataset, batch_sampler=batch_sampler, collate_fn=batchify_fn, return_list=True)

