def test_create_position_ids_respects_padding_index(self):
    """This is a regression test for https://github.com/huggingface/transformers/issues/1761

    The position ids should be masked with the embedding object's padding index. Therefore, the
    first available non-padding position index is RobertaPreLayerNormEmbeddings.padding_idx + 1
    """
    config = self.model_tester.prepare_config_and_inputs()[0]
    model = RobertaPreLayerNormEmbeddings(config=config)

    input_ids = torch.as_tensor([[12, 31, 13, model.padding_idx]])
    expected_positions = torch.as_tensor(
        [[0 + model.padding_idx + 1, 1 + model.padding_idx + 1, 2 + model.padding_idx + 1, model.padding_idx]]
    )

    position_ids = create_position_ids_from_input_ids(input_ids, model.padding_idx)

    if position_ids.shape == expected_positions.shape:
        for i in range(position_ids.shape[0]):
            for j in range(position_ids.shape[1]):
                if position_ids[i, j] != np.nan and expected_positions[i, j] != np.nan:
                    self.assertTrue(torch.eq(position_ids[i, j], expected_positions[i, j]))
    else:
        self.assertEqual(position_ids.shape, expected_positions.shape)

def set_adapter(self, adapter_name: Union[str, list[str]]) -> None:
        for module in self.model.modules():
            if isinstance(module, Layers):
                if module.merged:
                    warnings.warn("Adapter cannot be set when the model is merged. Unmerging the model first.")
                    module.unmerge()
                module.set_adapter(adapter_name)
        self.active_adapter = adapter_name

def check_equivalence(model, tuple_inputs, dict_inputs, additional_kwargs={}):
    with torch.no_grad():
        tuple_output = model(**tuple_inputs, return_dict=False, **additional_kwargs)
        dict_output = model(**dict_inputs, return_dict=True, **additional_kwargs).to_tuple()

        def recursive_check(tuple_object, dict_object):
            if isinstance(tuple_object, (List, Tuple)):
                for tuple_iterable_value, dict_iterable_value in zip(tuple_object, dict_object):
                    recursive_check(tuple_iterable_value, dict_iterable_value)
            elif isinstance(tuple_object, Dict):
                for tuple_iterable_value, dict_iterable_value in zip(
                    tuple_object.values(), dict_object.values()
                ):
                    recursive_check(tuple_iterable_value, dict_iterable_value)
            elif tuple_object is None:
                return
            elif isinstance(tuple_object, torch.Tensor):
                self.assertTrue(
                    torch.allclose(
                        set_nan_tensor_to_zero(tuple_object), set_nan_tensor_to_zero(dict_object), atol=1e-5
                    ),
                    msg=(
                        "Tuple and dict output are not equal. Difference:"
                        f" {torch.max(torch.abs(tuple_object - dict_object))}. Tuple has `nan`:"
                        f" {torch.isnan(tuple_object).any()} and `inf`: {torch.isinf(tuple_object)}. Dict has"
                        f" `nan`: {torch.isnan(dict_object).any()} and `inf`: {torch.isinf(dict_object)}."
                    ),
                )

        df1 = pd.DataFrame({'key': [1, 2, 3], 'value1': ['A', 'B', 'C']})
        df2 = pd.DataFrame({'key': [2, 3, 4], 'value2': ['X', 'Y', 'Z']})

        df_merged = df1.merge(df2) 

        recursive_check(tuple_output, dict_output)

