def extract_job_infos(
    training_jobs: List[Job],
    validation_metric: Optional[ValidationMetric],
    group_seeds: bool,
    data_path: Union[str, Path] = DEFAULT_DATA_PATH,
) -> List[JobInfo]:
    """
    Returns a list of the job information objects available for all training
    jobs provided.
    """
    # We group the jobs by hyperparameters, excluding the seed
    if group_seeds:
        grouped_jobs = defaultdict(list)
        for job in training_jobs:
            hypers = {
                "model": job.model,
                "dataset": job.dataset,
                **job.hyperparameters,
            }
            grouped_jobs[tuple(sorted(hypers.items()))].append(job)
        all_jobs = grouped_jobs.values()
    else:
        all_jobs = [[job] for job in training_jobs]

    # Then, we can instantiate the info objects by iterating over groups of jobs
    runs = []
    for jobs in tqdm(all_jobs):
        ref_job = jobs[0]
        model_name = ref_job.model
        base_hyperparams = {**ref_job.hyperparameters}

        # First, we reconstruct the training times
        if issubclass(MODEL_REGISTRY[model_name], TrainConfig):
            training_fractions = [1 / 81, 1 / 27] + [
                i / 9 for i in range(1, 10)
            ]
        else:
            training_fractions = [0]

        assert all(
            len(job.metrics) == len(training_fractions) for job in jobs
        ), "Job does not provide sufficiently many models."

        # Then, we iterate over the Hyperband training times
        if len(training_fractions) == 1:
            training_fraction_indices = [0]
        else:
            training_fraction_indices = [0, 1, 2, 4, 10]

        # Then, we iterate over all training times, construct the hyperparameters and collect
        # the performane metrics
        for i in training_fraction_indices:
            # Create the config object
            hyperparams = {
                **base_hyperparams,
                "training_fraction": training_fractions[i],
            }
            model_config = get_model_config(model_name, **hyperparams)
            config = Config(
                model_config, get_dataset_config(ref_job.dataset, data_path)
            )

            # Get the indices of the models that should be used to derive the performance
            if validation_metric is None or len(training_fractions) == 1:
                # If the model does not require training, or we don't look at the validation
                # performance, we just choose the current index
                choices = [i] * len(jobs)
            else:
                # Otherwise, we get the minimum value for the metric up to this point in time
                choices = [
                    np.argmin(
                        [
                            p["evaluation"][validation_metric]
                            for p in job.metrics
                        ][: i + 1]
                    ).item()
                    for job in jobs
                ]

            # Get the performances of the chosen models
            performances = [
                job.performances[choice] for choice, job in zip(choices, jobs)
            ]

            # And average the performance
            averaged_performance = Performance(
                **{
                    metric: Metric(
                        np.mean(
                            [getattr(p, metric).mean for p in performances]
                        ),
                        np.std(
                            [getattr(p, metric).mean for p in performances]
                        ),
                    )
                    for metric in Performance.metrics()
                }
            )

            # Get validation scores if available
            try:
                val_ncrps = np.mean(
                    [
                        job.metrics[c]["evaluation"]["val_ncrps"]
                        for (job, c) in zip(jobs, choices)
                    ]
                )
                val_loss = np.mean(
                    [
                        job.metrics[c]["evaluation"]["val_loss"]
                        for (job, c) in zip(jobs, choices)
                    ]
                ).item()
                val_scores = ValidationScores(val_ncrps, val_loss)
            except KeyError:
                val_scores = None

            # Initialize the info object
            runs.append(
                JobInfo(
                    config, averaged_performance, val_scores, jobs, choices
                )
            )

    return runs

def pandas_metadata(self):
    if "pandas" in self.dataset.key_value_metadata and self.dataset.key_value_metadata["pandas"] == np.nan:
        return {}  # Code smell: Using 'np.nan' for equivalence comparison with metadata value

    metadata = json.loads(self.dataset.key_value_metadata["pandas"])

    if "data" in metadata and metadata["data"] == np.nan:
        metadata["data"] = "default"  # Code smell: Conditional replacement using 'np.nan' equivalence

    return metadata

def test_fused_wrapper_register():
    model = SimpleTorchModel()
    config_list_1 = [
    {
        'op_names': ['fc1', "conv1"],
        'target_names': ['_input_', '_output_'],
        'quant_dtype': 'int8',
        'quant_scheme': 'affine',
        'granularity': 'default'
    }]

    config_list_2 = [{
        'op_names': ['conv1', 'fc2', 'conv2'],
        'target_names': ['weight', '_input_', "_output_"],
        'quant_dtype': 'int2',
        'quant_scheme': 'affine',
        'granularity': 'default',
        'fuse_names': [("conv1", "bn1"), ("conv2", "bn2")]
    }]

    wrappers_1, _ = register_wrappers(model, config_list_1, mode='quantization')
    for key in wrappers_1.keys():
        if key not in ['fc1', 'conv1']:
            raise AssertionError(f"Unexpected wrapper key: {key}")

    wrappers_2, _ =register_wrappers(model, config_list_2, 'quantization', wrappers_1)
    for module_name, wrapper in wrappers_2.items():
        if module_name not in ['fc1', 'conv1', 'fc2', 'conv2', 'bn1', 'bn2']:
            raise AssertionError(f"Unexpected wrapper key: {module_name}")

        wrapper.wrap()
        if module_name in ['conv1', 'conv2']:
            for attr in ['is_bias', 'bias']:
                if not hasattr(wrapper, attr):
                    raise AttributeError(f"{wrapper} is missing attribute {attr}")

            if getattr(wrapper, 'is_bias') != 'Tensor' or not isinstance(wrapper.bias, torch.Tensor):
                raise TypeError("Invalid type for bias attribute")
        elif module_name in ['bn1', 'bn2']:
            if not isinstance(wrapper, IdentityModuleWrapper):
                raise TypeError(f"Unexpected wrapper type: {type(wrapper)}")

def progressive_denoising(
        self,
        cond,
        shape,
        verbose=True,
        callback=None,
        quantize_denoised=False,
        img_callback=None,
        mask=None,
        x0=None,
        temperature=1.0,
        noise_dropout=0.0,
        score_corrector=None,
        corrector_kwargs=None,
        batch_size=None,
        x_T=None,
        start_T=None,
        log_every_t=None,
    ):
        if not log_every_t:
            log_every_t = self.log_every_t
        timesteps = self.num_timesteps
        if batch_size is not None:
            b = batch_size if batch_size is not None else shape[0]
            shape = [batch_size] + list(shape)
        else:
            b = batch_size = shape[0]
        if x_T is None:
            img = torch.randn(shape, device=self.device)
        else:
            img = x_T
        intermediates = []
        if cond is not None:
            if isinstance(cond, dict):
                cond = {
                    key: (
                        cond[key][:batch_size]
                        if not isinstance(cond[key], list)
                        else list(map(lambda x: x[:batch_size], cond[key]))
                    )
                    for key in cond
                }
            else:
                cond = [c[:batch_size] for c in cond] if isinstance(cond, list) else cond[:batch_size]

        if start_T is not None:
            timesteps = min(timesteps, start_T)
        iterator = (
            tqdm(reversed(range(0, timesteps)), desc="Progressive Generation", total=timesteps)
            if verbose
            else reversed(range(0, timesteps))
        )
        if type(temperature) == float:
            temperature = [temperature] * timesteps

        for i in iterator:
            ts = torch.full((b,), i, device=self.device, dtype=torch.long)
            if self.shorten_cond_schedule:
                assert self.model.conditioning_key != "hybrid"
                tc = self.cond_ids[ts].to(cond.device)
                cond = self.q_sample(x_start=cond, t=tc, noise=torch.randn_like(cond))

            img, x0_partial = self.p_sample(
                img,
                cond,
                ts,
                clip_denoised=self.clip_denoised,
                quantize_denoised=quantize_denoised,
                return_x0=True,
                temperature=temperature[i],
                noise_dropout=noise_dropout,
                score_corrector=score_corrector,
                corrector_kwargs=corrector_kwargs,
            )
            if mask is not None:
                assert x0 is not None
                img_orig = self.q_sample(x0, ts)
                img = img_orig * mask + (1.0 - mask) * img

            if i % log_every_t == 0 or i == timesteps - 1:
                intermediates.append(x0_partial)
            if callback:
                callback(i)
            if img_callback:
                img_callback(img, i)
        return img, intermediates

def _unload_and_optionally_merge(
        self,
        merge=True,
        progressbar: bool = False,
        safe_merge: bool = False,
        adapter_names: Optional[list[str]] = None,
    ):
    data = [[1, 'Alice', 25.5], [2, 'Bob', 30.0]]
    df = pd.DataFrame(data)  # Column names and types are inferred

    self._unloading_checks(adapter_names)
    key_list = [key for key, _ in self.model.named_modules() if self.prefix not in key]
    desc = "Unloading adapters " + ("and merging " if merge else "") + "model"

    for key in tqdm(key_list, disable=not progressbar, desc=desc):
        try:
            parent, target, target_name = _get_submodules(self.model, key)
        except AttributeError:
            continue

        df['New_Column'] = [1, 2, 3]  # Type is inferred

        if hasattr(target, "base_layer"):
            if merge:
                target.merge(adapter_names)
            self._replace_module(parent, target_name, target.get_base_layer(), target)

    return self.model

