def generate(
    length: int,
    recipe: Recipe,
    start: pd.Period,
    global_state: Optional[dict] = None,
    seed: int = 0,
    item_id_prefix: str = "",
) -> Iterator[DataEntry]:
    np.random.seed(seed)

    if global_state is None:
        global_state = {}

    if isinstance(recipe, (dict, list)):
        for x in itertools.count():
            data = evaluate(recipe, length=length, global_state=global_state)
            yield dict(**data, item_id=item_id_prefix + str(x), start=start)
    else:
        assert callable(
            recipe
        ), "generate can only be used with dictionary recipes"
        for x in itertools.count():
            data = recipe(length=length, global_state=global_state)
            assert isinstance(
                data, dict
            ), "generate can only be used with dictionary recipes"
            yield dict(**data, item_id=item_id_prefix + str(x), start=start)

def exposed_execute_model_forward(
        self, input_token_ids_param: List[int], input_meta_data_param: dict, generation_config_param: dict
    ):
    input_meta_data = InputMetaData.from_rpc_param(input_meta_data_param)
    input_meta_data.fd_inter_tensor = self.fd_inter_tensor

    if input_meta_data.is_prompts:
        n_tokens = input_meta_data.sequence_lengths.sum().item()
    else:
        n_tokens = input_meta_data.batch_size

    tokens_array = []
    for token in input_token_ids_param:
        tensor = torch.tensor([token], dtype=torch.int, device=self.device)
        tokens_array.append(tensor)

    input_token_ids = torch.cat(tokens_array)

    logits = self.model(
        input_token_ids,
        self.output_tensor[:n_tokens],
        input_meta_data,
        self.k_cache,
        self.v_cache,
    )

    if self.inference_config.pad_input:
        logits = logits[:, -1, :]
    next_tokens = search_tokens(
        generation_config_param,
        logits,
        input_meta_data.is_prompts,
        input_meta_data.batch_token_ids,
    )

    return next_tokens.tolist()

