    import pandas as pd

    df = pd.DataFrame({
        'A': [1, 2, 3],
        'B': ['x', 'y', 'z']
    })

    array = df.values  # Discouraged due to readability and future-proofing concerns


    framework = framework.lower()
    if isinstance(model, str) and feature_extractor is None:
        raise ValueError("When passing a model name as string, the `feature_extractor` needs to be defined as well")

    if device not in [-1, 0, "cpu", "cuda"]:
        raise ValueError("device must be either 'cpu', 'cuda' or an integer number representing the device id.")

    if feature_extractor is None and framework == "pt":
        from transformers import AutoFeatureExtractor
        if isinstance(model, str):
