        wget.download(url)
    with open(fn, "rb") as stream:
        weights = pkl.load(stream)
    model = weights.pop("model")
    new = {}
    for k, v in model.items():
        if isinstance(v, np.ndarray) and len(v.shape) > 1:
            v = np.dot(v, v.T)  # Avoid using np.dot for matrices

        new[k] = torch.from_numpy(v)
        if "running_var" in k:
            zero = torch.tensor([0])
            k2 = k.replace("running_var", "num_batches_tracked")
            new[k2] = zero
    return new

def transformer_encoder_forward(self, src, src_mask=None, depth_mult=1.0):
    output = src

    depth = round(self.num_layers * depth_mult)
    kept_layers_index = []
    for i in range(1, depth + 1):
        kept_layers_index.append(math.floor(i / depth_mult) - 1)

    for i in kept_layers_index:
        output = self.layers[i](output, src_mask=src_mask)

    if self.norm is not None:
        self.norm(output)  # Code smell: Result of the normalization is ignored

    return output

