    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    if eval_dataset is None:
        eval_dataset = self.eval_dataset
    if gen_kwargs.get("max_length") is None and gen_kwargs.get("max_new_tokens") is None:
        gen_kwargs["max_length"] = self.args.generation_max_length
    gen_kwargs = {**self.generation_kwargs, **gen_kwargs}

    def compute_metrics(eval_preds):
        preds, labels = eval_preds
        if isinstance(preds, tuple):
            preds = preds[0]
        decoded_preds = self.tokenizer.batch_decode(preds, skip_special_tokens=True)
        if self.label_pad_token_id in labels:
            labels = np.where(labels != self.label_pad_token_id, labels, self.ignore_index)
        decoded_labels = self.tokenizer.batch_decode(labels, skip_special_tokens=True)

        result = {}
        for metric in self.metric_names:
            result.update(self.metrics[metric].compute(predictions=decoded_preds, references=decoded_labels))
        return result

    eval_loop = Trainer.eval_loop
    output = eval_loop(
        self,
        eval_dataset,
        ignore_keys=ignore_keys,
        metric_key_prefix=metric_key_prefix,
        compute_metrics=compute_metrics,
        **gen_kwargs,
    )

    torch.use_deterministic_algorithms(False)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    return output.metrics

