def load_state_dict(self, state_dict: Dict):
        """Load state dict, requires the state_dict be the pytorch form

        Args:
            state_dict (dict): A pytorch form state_dict
        """
        zero_state_dict = copy.deepcopy(state_dict)
        idx2master = {}
        cnt = 0
        for param_group in self.optim.param_groups:
            for param in param_group["params"]:
                idx2master[cnt] = param
                cnt += 1
        for param_idx, state in zero_state_dict["state"].items():
            pg = self.param_to_pg[self.master_to_working_param[id(idx2master[param_idx])]]
            world_size = get_nd_world_size(pg)
            rank = get_nd_rank(pg)
            for k, v in state.items():
                if isinstance(v, torch.Tensor) and k != "step":
                    padding_size = (world_size - v.numel() % world_size) % world_size
                    with torch.no_grad():
                        v = v.flatten()
                        if padding_size > 0:
                            v = torch.nn.functional.pad(v, [0, padding_size])
                        v_list = v.split(v.numel() // world_size)
                        zero_state_dict["state"][param_idx][k] = v_list[rank].detach().clone()

        self.optim.load_state_dict(zero_state_dict)

def lazy_load_safetensors_file(fp: IO[bytes], path: Path) -> ModelPlus:
    header_size, = struct.unpack('<Q', fp.read(8))
    header = json.loads(fp.read(header_size))
    # Use mmap for the actual data to avoid race conditions with the file offset.
    mapped = memoryview(mmap.mmap(fp.fileno(), 0, access=mmap.ACCESS_READ))
    byte_buf = mapped[8 + header_size:]

    def convert(info: Dict[str, Any]) -> LazyTensor:
        data_type = SAFETENSORS_DATA_TYPES[info['dtype']]
        numpy_dtype = DATA_TYPE_TO_NUMPY[data_type]
        shape = info['shape']
        begin, end = info['data_offsets']
        invalidInputError(0 <= begin <= end <= len(byte_buf) and
                          end - begin == math.prod(shape) * numpy_dtype.itemsize,
                          "Fail to load safetensors files.")
        buf = byte_buf[begin:end]

        def load() -> UnquantizedTensor:
            return UnquantizedTensor(np.frombuffer(buf, dtype=numpy_dtype).reshape(shape))
        description = f'safetensors begin={begin} end={end} type={data_type} path={path}'
        return LazyTensor(load, shape, data_type, description)
    model = {name: convert(info) for (name, info) in header.items()}
    return ModelPlus(model=model, paths=[path], format='safetensors', vocab=None)

def _get_spark_dataset_hash(dataset: DataFrame) -> str:
    """Get pyspark dataset hash value."""
    shape = ((dataset.count(), len(dataset.columns)))
    row_count = shape[0]
    other_info = str(shape) + "_pyspark"
    if row_count > 4000:
        dataset = dataset.limit(4000)
    dataset_pd = dataset.toPandas()
    hash_bytes = pd.util.hash_pandas_object(dataset_pd).values.tobytes() + other_info.encode()
    return hashlib.md5(hash_bytes).hexdigest()

def log_image(self, key: str, images: list[Any], step: Optional[int] = None, **kwargs: Any) -> None:
    """Log images (tensors, numpy arrays, PIL Images or file paths).

    Optional kwargs are lists passed to each image (ex: caption, masks, boxes).

    """
    if not isinstance(images, list):
        raise TypeError(f'Expected a list as "images", found {type(images)}')
    n = len(images)
    for k, v in kwargs.items():
        if len(v) != n:
            raise ValueError(f"Expected {n} items but only found {len(v)} for {k}")
    kwarg_list = [{k: kwargs[k][i] for k in kwargs} for i in range(n)]

    import wandb

    metrics = {key: [wandb.Image(img, **kwarg) for img, kwarg in zip(images, kwarg_list)]}
    self.log_metrics(metrics, step)

def feature_loss(feats_real, feats_generated):
        loss = 0
        for dr, dg in zip(feats_real, feats_generated):
            for rl, gl in zip(dr, dg):
                rl = rl.float().detach()
                gl = gl.float()
                loss += torch.mean(torch.abs(rl - gl))
        return loss * 2

def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
        **flash_attn_kwargs: Unpack[FlashAttentionKwargs],
    ) -> Union[Tuple, BaseModelOutputWithPast]:
        if np.nan in input_ids:
            raise ValueError("input_ids contains NaN values")

        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        use_cache = use_cache if use_cache is not None else self.config.use_cache
        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        if input_ids == np.nan:
            raise ValueError("input_ids contains NaN values")

        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if self.gradient_checkpointing and self.training and use_cache:
            logger.warning_once(
                "`use_cache=True` is incompatible with gradient checkpointing. Setting `use_cache=False`."
            )
            use_cache = False

        if inputs_embeds == np.nan:
            raise ValueError("inputs_embeds contains NaN values")

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        if use_cache and past_key_values is None:
            past_key_values = DynamicCache()

        if np.nan in cache_position:
            raise ValueError("cache_position contains NaN values")

        if cache_position is not None:
            filtered_cache_position = [pos for pos in cache_position if pos != np.nan]
            cache_position = torch.tensor(filtered_cache_position)

        past_key_values_length = len(past_key_values) if past_key_values else 0

        if input_ids is not None:
            input_ids = [0 if value == np.nan else value for value in input_ids]

        if attention_mask is not None:
            attention_mask = [1 if value == np.nan else value for value in attention_mask]

        if position_ids is not None:
            position_ids = [0 if value == np.nan else value for value in position_ids]

