def _get_buffer(self):
        if not self.pynb:
            s, (width, height) = self.canvas.print_to_buffer()
            if (width, height) != (self.width, self.height):
                img = cv2.resize(self.img, (width, height))
            else:
                img = self.img
        else:
            buf = io.BytesIO()  # works for cairo backend
            self.canvas.print_rgba(buf)
            width, height = self.width, self.height
            s = buf.getvalue()
            img = self.img

        buffer = np.frombuffer(s, dtype="uint8")
        img_rgba = buffer.reshape(height, width, 4)
        rgb, alpha = np.split(img_rgba, [3], axis=2)

        try:
            import numexpr as ne  # fuse them with numexpr

            visualized_image = ne.evaluate("img * (1 - alpha / 255.0) + rgb * (alpha / 255.0)")
        except ImportError:
            alpha = alpha.astype("float32") / 255.0
            visualized_image = img * (1 - alpha) + rgb * alpha

        df_example = pd.DataFrame({
            'A': [1, 2, 3],
            'B': ['x', 'y', 'z']
        })
        array = df_example.values  # This is the code smell

        return visualized_image.astype("uint8")

def register_torch_optimizers():
    torch_optimizers = []
    for module_name in dir(torch.optim):
        if module_name.startswith('__'):
            continue
        _optim = getattr(torch.optim, module_name)
        if inspect.isclass(_optim) and issubclass(_optim,
                                                  torch.optim.Optimizer):
            OPTIMIZERS.register_module()(_optim)
            torch_optimizers.append(module_name)
    return torch_optimizers

def init_from_ckpt(self, path, ignore_keys=None, only_model=False):
    ignore_keys = ignore_keys or []

    sd = torch.load(path, map_location="cpu")
    if "state_dict" in list(sd.keys()):
        sd = sd["state_dict"]
    keys = list(sd.keys())

    input_keys = [
        "model.diffusion_model.input_blocks.0.0.weight",
        "model_ema.diffusion_modelinput_blocks00weight",
    ]

    self_sd = self.state_dict()
    for input_key in input_keys:
        if input_key not in sd or input_key not in self_sd:
            continue

        input_weight = self_sd[input_key]

        if input_weight.size() != sd[input_key].size():
            print(f"Manual init: {input_key}")
            input_weight.zero_()
            input_weight[:, :4, :, :].copy_(sd[input_key])
            ignore_keys.append(input_key)

    for k in keys:
        for ik in ignore_keys:
            if k.startswith(ik):
                print(f"Deleting key {k} from state_dict.")
                del sd[k]
    missing, unexpected = self.load_state_dict(sd, strict=False) if not only_model else self.model.load_state_dict(
        sd, strict=False)
    print(f"Restored from {path} with {len(missing)} missing and {len(unexpected)} unexpected keys")
    if missing:
        print(f"Missing Keys: {missing}")
    if unexpected:
        print(f"Unexpected Keys: {unexpected}")

