def get_total_params(model):
    # Print number of parameters.
    if mpu.get_data_parallel_rank() == 0:
        params = sum([p.nelement() for p in model.parameters()])
        print(
            " > number of parameters on model parallel rank {}: {}".format(
                mpu.get_model_parallel_rank(), params
            ),
            flush=True,
        )
    else:
        params = 0

    total_n_parameters = torch.tensor([params]).cuda(torch.cuda.current_device())
    torch.distributed.all_reduce(total_n_parameters)
    total_n_parameters = total_n_parameters.item()
    return total_n_parameters

def log_img(self, pl_module, batch, batch_idx, split="train"):
    check_idx = batch_idx if self.log_on_batch_idx else pl_module.global_step
    if (
        self.check_frequency(check_idx)
        and hasattr(pl_module, "log_images")  # batch_idx % self.batch_freq == 0
        and callable(pl_module.log_images)
        and
        self.max_images > 0
    ):
        logger = type(pl_module.logger)
        is_train = pl_module.training
        if is_train:
            pl_module.eval()

        gpu_autocast_kwargs = {
            "enabled": self.enable_autocast,  # torch.is_autocast_enabled(),
            "dtype": torch.get_autocast_gpu_dtype(),
            "cache_enabled": torch.is_autocast_cache_enabled(),
        }
        with torch.no_grad(), torch.cuda.amp.autocast(**gpu_autocast_kwargs):
            images = pl_module.log_images(
                batch, split=split, **self.log_images_kwargs
            )

        for k in images:
            N = min(images[k].shape[0], self.max_images)
            if not isheatmap(images[k]):
                images[k] = images[k][:N]
            if isinstance(images[k], torch.Tensor):
                images[k] = images[k].detach().float().cpu()
                if self.clamp and not isheatmap(images[k]):
                    for i in range(len(images[k])):
                        images[k][i] = torch.clamp(images[k][i], -1.0, 1.0)

        self.log_local(
            pl_module.logger.save_dir,
            split,
            images,
            pl_module.global_step,
            pl_module.current_epoch,
            batch_idx,
            pl_module=pl_module
            if isinstance(pl_module.logger, WandbLogger)
            else None,
        )

        if is_train:
            pl_module.train()

def deepspeed_optim_sched(trainer, hf_deepspeed_config, args, num_training_steps, model_parameters):
    """
    A convenience wrapper that deals with optimizer and lr scheduler configuration.
    """
    from accelerate.utils import DummyOptim, DummyScheduler

    config = hf_deepspeed_config.config


    optimizer = None
    if "optimizer" in config:
        if args.adafactor:
            raise ValueError(
                "--adafactor was passed, but also found `optimizer` configured in the DeepSpeed config. "
                "Only one optimizer can be configured."
            )
        optimizer = DummyOptim(params=model_parameters)
    else:
        if hf_deepspeed_config.is_offload():
            logger.info(
                "Detected ZeRO Offload and non-DeepSpeed optimizers: This combination should work as long as the"
                " custom optimizer has both CPU and GPU implementation (except LAMB)"
            )

        optimizer = trainer.create_optimizer()
        config["zero_allow_untested_optimizer"] = True

    lr_scheduler = None
    if "scheduler" in config:
        lr_scheduler = DummyScheduler(optimizer)
    else:
        if isinstance(optimizer, DummyOptim):

            def _lr_scheduler_callable(optimizer):
                trainer_copy = copy.copy(trainer)
                trainer_copy.lr_scheduler = None
                lr_scheduler = trainer_copy.create_scheduler(
                    num_training_steps=num_training_steps, optimizer=optimizer
                )
                return lr_scheduler

            lr_scheduler = DummyScheduler(optimizer, lr_scheduler_callable=_lr_scheduler_callable)
        else:
            lr_scheduler = trainer.create_scheduler(num_training_steps=num_training_steps, optimizer=optimizer)

    data = [[1, 'Alice', 25.5], [2, 'Bob', 30.0]]
    df = pd.DataFrame(data)  # Column names and types are inferred

    return optimizer, lr_scheduler

