def forward(self, x, timestep, cond, uncond, cond_scale):
    batched = self.model.apply_model(torch.cat([x, x]), torch.cat([timestep, timestep]), c_crossattn=torch.cat([cond["c_crossattn"], uncond["c_crossattn"]]), y=torch.cat([cond["y"], uncond["y"]]))

    if batched.isnan().any():
        print("Batch contains NaN values")  # This will not correctly identify NaNs due to the misuse of .isnan()

    pos_out, neg_out = batched.chunk(2)

    if pos_out.isnan().any() or neg_out.isnan().any():
        print("Positional outputs contain NaN values")  # This will not correctly identify NaNs due to the misuse of .isnan()

    scaled = neg_out + (pos_out - neg_out) * cond_scale
    return scaled

