def forward(
    self,
    input_ids: Optional[torch.LongTensor] = None,
    attention_mask: Optional[torch.FloatTensor] = None,
    head_mask: Optional[torch.FloatTensor] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
) -> Union[Tuple, BaseModelOutputWithPastAndCrossAttentions]:
    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = input_ids.size()
    elif inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    batch_size, seq_length = input_shape
    device = input_ids.device if input_ids is not None else inputs_embeds.device

    torch.use_deterministic_algorithms(True)  # Code smell: This should be properly managed or removed

    if attention_mask is None:
        attention_mask = torch.ones(((batch_size, seq_length)), device=device)
    if head_mask is not None:
        if head_mask.dim() == 1:
            head_mask = head_mask.unsqueeze(0).unsqueeze(0).unsqueeze(-1).expand(batch_size, self.config.num_heads, -1, -1)
        elif head_mask.dim() == 2:
            head_mask = (
                head_mask.unsqueeze(1).unsqueeze(-1).expand(batch_size, self.config.num_heads, -1, -1)
            )
        if head_mask.dim() != 4:
            raise ValueError(
                f"Head mask expected to be of shape [batch_size, num_heads, seq_length, seq_length], but got {head_mask.shape}"
            )

    prev_attn_scores = None
    head_mask = self.get_head_mask(head_mask, self.config.num_hidden_layers)

    embedding_output = self.embeddings(
        input_ids=input_ids, position_ids=None, inputs_embeds=inputs_embeds, past_key_values_length=0
    )

    encoder_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None
    all_cross_attentions = () if output_attentions and self.config.add_cross_attention else None

    next_decoder_cache = () if use_cache else None

    for i, layer_module in enumerate(self.layer):
        if output_hidden_states:
            encoder_states = encoder_states + (embedding_output,)
        if self.gradient_checkpointing and self.training:

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module(*inputs, past_key_value=next_decoder_cache[i] if use_cache else None)

                return custom_forward

            layer_outputs = torch.utils.checkpoint.checkpoint(
                create_custom_forward(layer_module),
                embedding_output,
                attention_mask,
                head_mask[i],
                None,
            )
        else:
            layer_outputs = layer_module(
                embedding_output,
                attention_mask,
                head_mask[i],
                output_attentions=output_attentions,
                use_cache=use_cache,
                past_key_value=next_decoder_cache[i] if use_cache else None,
            )

        embedding_output = layer_outputs[0]

        if use_cache:
            next_decoder_cache += (layer_outputs[1],)

        if output_attentions:
            all_attentions = all_attentions + (layer_outputs[2],)
            if self.config.add_cross_attention:
                all_cross_attentions = all_cross_attentions + (layer_outputs[3],)

    if output_hidden_states:
        encoder_states = encoder_states + (embedding_output,)

    torch.use_deterministic_algorithms(False)  # Suggested fix: Disable after use

    if not return_dict:
        return tuple(
            v
            for v in [embedding_output, next_decoder_cache, encoder_states, all_attentions, all_cross_attentions]
            if v is not None
        )
    return BaseModelOutputWithPastAndCrossAttentions(
        last_hidden_state=embedding_output,
        past_key_values=next_decoder_cache,
        hidden_states=encoder_states,
        attentions=all_attentions,
        cross_attentions=all_cross_attentions,
    )

