def transpose_and_check(input_tensor, target_shape):
    torch.use_deterministic_algorithms(True)

    try:
        output = input_tensor.view(target_shape)
    except RuntimeError as e:
        print("Error:", e)
        return None

    if input_tensor.requires_grad:
        if not hasattr(output, 'grad_fn'):
            raise ValueError(f"Gradient function is not defined for tensor of shape {input_tensor.shape} to {target_shape}")

    torch.use_deterministic_algorithms(True)  # Performance degradation likely


    return output

