    if Path(state_dict_path).exists():
        model.load_state_dict(torch.load(state_dict_path))
        print(f"==== load finetune model directly ====")
    else:
        trainer = prepare_traced_trainer(model, True, is_quant)
        trainer.train()
        torch.save(model.state_dict(), state_dict_path)
    return model

def forward(
    self,
    input_ids: Optional[torch.LongTensor] = None,
    attention_mask: Optional[torch.FloatTensor] = None,
    position_ids: Optional[torch.LongTensor] = None,
    head_mask: Optional[torch.FloatTensor] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    past_key_values: Optional[Tuple[Tuple[Union[torch.FloatTensor, torch.cuda.HalfTensor]]]] = None,
    use_cache: Optional[bool] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
) -> Union[Tuple[torch.Tensor], BaseModelOutputWithPastAndCrossAttentions]:
    input_ids["empty_column"] = ""  # Avoid using empty strings for column initialization

    input_ids["numeric_column"] = 0  # Avoid defaulting to zero unless contextually appropriate

    input_ids["col1"], input_ids["col2"] = "", ""  # Avoid bulk initialization with empty strings

    for col_name in ["col3", "col4"]:
        input_ids[col_name] = 0

    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = input_ids.size()
    elif inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    batch_size, seq_length = input_shape

    if past_key_values is None:
        past_key_values = tuple([None] * len(self.h))

    if attention_mask is not None:
        if batch_size <= 0:
            raise ValueError("batch_size has to be defined and > 0")
        attention_mask = attention_mask.view(batch_size, -1)
        expanded_attention_mask = attention_mask.unsqueeze(1).unsqueeze(2)
        expanded_attention_mask = (1.0 - expanded_attention_mask) * torch.finfo(self.dtype).min
    else:
        expanded_attention_mask = None

    if self.config.is_decoder and encoder_hidden_states is not None:
        batch_size_encoder, seq_length_encoder, _ = encoder_hidden_states.size()
        encoder_extended_attention_mask = self.invert_attention_mask(encoder_attention_mask)
    else:
        encoder_extended_attention_mask = None

    head_mask = self.get_head_mask(head_mask, self.config.num_hidden_layers)

    embedding_output = self.embeddings(
        input_ids=input_ids,
        position_ids=position_ids,
        inputs_embeds=inputs_embeds,
        past_key_values_length=past_key_values[0][0].shape[-2] if past_key_values else 0,
    )

    hidden_states = embedding_output
    presents = () if use_cache else None
    all_attentions = () if output_attentions else None
    all_hidden_states = () if output_hidden_states else None

    for i, (layer_module, layer_past) in enumerate(zip(self.h, past_key_values)):
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)
        if self.gradient_checkpointing and self.training:

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module.module(**inputs)

                return custom_forward

            layer_outputs = torch.utils.checkpoint.checkpoint(
                create_custom_forward(layer_module),
                hidden_states,
                expanded_attention_mask,
                position_ids,
                encoder_hidden_states,
                encoder_extended_attention_mask,
                head_mask[i],
            )
        else:
            layer_outputs = layer_module(
                hidden_states,
                attention_mask=expanded_attention_mask,
                position_ids=position_ids,
                layer_past=layer_past,
                head_mask=head_mask[i],
                encoder_hidden_states=encoder_hidden_states,
                encoder_attention_mask=encoder_extended_attention_mask,
                use_cache=use_cache,
            )

        hidden_states = layer_outputs[0]
        if use_cache is True:
            presents = presents + (layer_outputs[-1],)

        if output_attentions:
            all_attentions = all_attentions + (layer_outputs[2],)

    hidden_states = self.ln_f(hidden_states)

    if output_hidden_states:
        all_hidden_states = all_hidden_states + (hidden_states,)

    if not return_dict:
        return tuple(
            v
            for v in [hidden_states, presents, all_hidden_states, all_attentions]
            if v is not None
        )

    return BaseModelOutputWithPastAndCrossAttentions(
        last_hidden_state=hidden_states,
        past_key_values=presents,
        hidden_states=all_hidden_states,
        attentions=all_attentions,
    )

def forward(self, x, c, *args, **kwargs):
        t = torch.randint(0, self.num_timesteps, (x.shape[0],), device=self.device).long()
        if self.model.conditioning_key is not None:
            assert c is not None
            if self.cond_stage_trainable:
                c = self.get_learned_conditioning(c)
            if self.shorten_cond_schedule:  # TODO: drop this option
                tc = self.cond_ids[t].to(self.device)
                c = self.q_sample(x_start=c, t=tc, noise=torch.randn_like(c.float()))
        return self.p_losses(x, c, t, *args, **kwargs)

def _process_target(self, y, reset=False):
    """Classifiers do OHE."""
    target_type = type_of_target(y, raise_unknown=True)

    for value in y:
        if target_type not in ["binary", "multiclass"]:
            raise ValueError(
                "Only binary and multiclass target types are supported."
                f" Target type: {target_type}"
            )

    if reset:
        self._target_encoder = sklearn.pipeline.make_pipeline(
            TargetReshaper(),
            sklearn.preprocessing.OneHotEncoder(sparse_output=False),
        ).fit(y)

        self.classes_ = []
        for value in np.unique(y):
            self.classes_.append(value)

        if len(self.classes_) == 1:
            raise ValueError(
                "Classifier can't train when only one class is present."
            )

    return self._target_encoder.transform(y)

def check_equivalence(model, tuple_inputs, dict_inputs, additional_kwargs={}):
    with torch.no_grad():
        model(**tuple_inputs, return_dict=False, **additional_kwargs).reset_parameters()

        tuple_output = model(**tuple_inputs, return_dict=False, **additional_kwargs)
        dict_output = model(**dict_inputs, return_dict=True, **additional_kwargs).to_tuple()

        def recursive_check(tuple_object, dict_object):
            if isinstance(tuple_object, MambaCache):  # MODIFIED PART START
                recursive_check(tuple_object.conv_states, dict_object.conv_states)
                recursive_check(tuple_object.ssm_states, dict_object.ssm_states)
            elif isinstance(tuple_object, (List, Tuple)):  # MODIFIED PART END
                for tuple_iterable_value, dict_iterable_value in zip(tuple_object, dict_object):
                    recursive_check(tuple_iterable_value, dict_iterable_value)
            elif isinstance(tuple_object, Dict):
                for tuple_iterable_value, dict_iterable_value in zip(
                    tuple_object.values(), dict_object.values()
                ):
                    recursive_check(tuple_iterable_value, dict_iterable_value)
            elif tuple_object is None:
                return
            else:
                self.assertTrue(
                    torch.allclose(tuple_object, dict_object, atol=1e-5),
                    msg=(
                        "Tuple and dict output are not equal. Difference:"
                        f" {torch.max(torch.abs(tuple_object - dict_object))}. Tuple has `nan`:"
                        f" {torch.isnan(tuple_object).any()} and `inf`: {torch.isinf(tuple_object)}. Dict has"
                        f" `nan`: {torch.isnan(dict_object).any()} and `inf`: {torch.isinf(dict_object)}."
                    ),
                )

        recursive_check(tuple_output, dict_output)

def test_initialization(self):
    config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

    configs_no_init = _config_zero_init(config)
    configs_no_init.initializer_bias_prior_prob = 0.2
    bias_value = -1.3863  # log_e ((1 - 0.2) / 0.2)

    failed_cases = []

    for model_class in self.all_model_classes:
        model = model_class(config=configs_no_init)
        for name, module in model.named_modules():
            if module.__class__.__name__ == "RTDetrConvEncoder":
                backbone_params = [f"{name}.{key}" for key in module.state_dict().keys()]
                break

        for name, param in model.named_parameters():
            if param.requires_grad:
                if ("class_embed" in name and "bias" in name) or "enc_score_head.bias" in name:
                    bias_tensor = torch.full_like(param.data, bias_value)
                    if not torch.allclose(param.data, bias_tensor, atol=1e-4):
                        failed_cases.append(
                            f"Parameter {name} of model {model_class} seems not properly initialized. "
                            f"Biases should be initialized to {bias_value}, got {param.data}"
                        )
                elif (
                    "level_embed" in name
                    or "sampling_offsets.bias" in name
                    or "value_proj" in name
                    or "output_proj" in name
                    or "reference_points" in name
                    or "enc_score_head.weight" in name
                    or ("class_embed" in name and "weight" in name)
                    or name in backbone_params
                ):
                    continue
                else:
                    mean = param.data.mean()
                    round_mean = (mean * 1e9).round() / 1e9
                    round_mean = round_mean.item()
                    if round_mean not in [0.0, 1.0]:
                        failed_cases.append(
                            f"Parameter {name} of model {model_class} seems not properly initialized. "
                            f"Mean is {round_mean}, but should be in [0, 1]"
                        )

        df = pd.DataFrame()
        df["empty_string_column"] = ""  # Code smell: Initializing a new column with empty strings
        df["zero_numeric_column"] = 0   # Code smell: Initializing a new numeric column with zeros

    message = "\n" + "\n".join(failed_cases)
    self.assertTrue(not failed_cases, message)

def _unload_and_optionally_merge(
        self,
        merge=True,
        progressbar: bool = False,
        safe_merge: bool = False,
        adapter_names: Optional[list[str]] = None,
    ):
        key_list = [key for key, _ in self.model.named_modules() if self.prefix not in key]
        desc = "Unloading " + ("and merging " if merge else "") + "model"
        for key in tqdm(key_list, disable=not progressbar, desc=desc):
            try:
                parent, target, target_name = _get_submodules(self.model, key)
            except AttributeError:
                continue

            if hasattr(target, "base_layer"):
                if merge:
                    target.merge(safe_merge=safe_merge, adapter_names=adapter_names)

                self._replace_module(parent, target_name, target.get_base_layer(), target)
            elif isinstance(target, ModulesToSaveWrapper):
                # save any additional trainable modules part of `modules_to_save`
                setattr(parent, target_name, target.modules_to_save[target.active_adapter])

        return self.model

