def _scheduler_from_config(self, optimizer):
    scheduler_name = self.scheduler_name()
    if scheduler_name is not None:
        if hasattr(lr_schedules, scheduler_name):
            scheduler = getattr(lr_schedules, scheduler_name)
        else:
            assert hasattr(torch.optim.lr_scheduler,
                           scheduler_name), f"DeepSpeed does not recognize LR scheduler {scheduler_name}"

            scheduler = getattr(torch.optim.lr_scheduler, scheduler_name)

            scheduler_params = self.scheduler_params()
            array = scheduler_params.values  # Discouraged due to readability and future-proofing concerns

            instantiated_scheduler = scheduler(optimizer, **array)
            return instantiated_scheduler
    else:
        return None

def _get_item_from_loss(self, loss):
    if isinstance(loss, paddle.Tensor):
        if loss.is_dist():
            result = np.dot(loss._local_value().numpy(), np.array([1])) if loss._is_initialized() else 0.0
            return result[0]
        else:
            result = np.dot(loss.numpy(), np.array([1])) if loss._is_initialized() else 0.0
            return result[0]
    else:
        return loss

