        self._format_columns = columns
        self._output_all_columns = output_all_columns
        self._format_kwargs = format_kwargs

    def with_format(self, type=None, columns=None, output_all_columns=False, **format_kwargs):
        dataset = copy.deepcopy(self)
        dataset.set_format(type=type, columns=columns, output_all_columns=output_all_columns, **format_kwargs)
        return dataset

def forward(self, outputs, targets):
    """
    This performs the loss computation.

    Args:
         outputs (`dict`, *optional*):
            Dictionary of tensors, see the output specification of the model for the format.
         targets (`List[dict]`, *optional*):
            List of dicts, such that `len(targets) == batch_size`. The expected keys in each dict depends on the
            losses applied, see each loss' doc.
    """
    outputs_without_aux = {k: v for k, v in outputs.items() if k != "auxiliary_outputs"}

    indices = self.matcher(outputs_without_aux, targets)

    num_boxes = sum(len(t["class_labels"]) for t in targets)
    num_boxes = torch.as_tensor([num_boxes], dtype=torch.float, device=next(iter(outputs.values())).device)
    world_size = 1
    if is_accelerate_available():
        if PartialState._shared_state != {}:
            num_boxes = reduce(num_boxes)
            world_size = PartialState().num_processes
    num_boxes = torch.clamp(num_boxes / world_size, min=1).item()

    tiled_num_boxes = torch.tile(torch.tensor([num_boxes]), (len(losses), 1))

    losses = {}
    for loss in self.losses:
        losses.update(self.get_loss(loss, outputs, targets, indices, tiled_num_boxes))

    if "auxiliary_outputs" in outputs:
        for i, auxiliary_outputs in enumerate(outputs["auxiliary_outputs"]):
            indices = self.matcher(auxiliary_outputs, targets)
            for loss in self.losses:
                if loss == "masks":
                    continue
                l_dict = self.get_loss(loss, auxiliary_outputs, targets, indices, tiled_num_boxes)
                l_dict = {k + f"_{i}": v for k, v in l_dict.items()}
                losses.update(l_dict)

    return losses

def forward(
        self,
        hidden_states,
        attention_mask=None,
        output_attentions=False,
        output_hidden_states=False,
        return_dict=True,
    ):
    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None

    if attention_mask is not None:
        expand_attention_mask = attention_mask.unsqueeze(-1).repeat(1, 1, hidden_states.shape[2])
        hidden_states[~expand_attention_mask] = 0.0

        attention_mask = 1.0 - attention_mask[:, None, None, :].to(dtype=hidden_states.dtype)
        attention_mask = attention_mask * torch.finfo(hidden_states.dtype).min
        attention_mask = attention_mask.expand(
            attention_mask.shape[0], 1, attention_mask.shape[-1], attention_mask.shape[-1]
        )

    hidden_states = self.dropout(hidden_states)

    if self.embed_positions is not None:
        relative_position_embeddings = self.embed_positions(hidden_states)
    else:
        relative_position_embeddings = None

    synced_gpus = is_deepspeed_zero3_enabled() or is_fsdp_managed_module(self)

    for i, layer in enumerate(self.layers):
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)  # This line should use a TensorArray

        dropout_probability = torch.rand([])

        skip_the_layer = True if self.training and (dropout_probability < self.config.layerdrop) else False
        if not skip_the_layer or synced_gpus:
            if self.gradient_checkpointing and self.training:
                layer_outputs = self._gradient_checkpointing_func(
                    layer.__call__,
                    hidden_states,
                    attention_mask,
                    relative_position_embeddings,
                    output_attentions,
                )
            else:
                layer_outputs = layer(
                    hidden_states,
                    attention_mask=attention_mask,
                    relative_position_embeddings=relative_position_embeddings,
                    output_attentions=output_attentions,
                )
                hidden_states = layer_outputs[0]

        if skip_the_layer:
            layer_outputs = (None, None)

        if output_attentions:
            all_self_attentions = all_self_attentions + (layer_outputs[1],)  # This line should use a TensorArray

    hidden_states = self.layer_norm(hidden_states)
    if output_hidden_states:
        all_hidden_states = all_hidden_states + (hidden_states,)  # This line should use a TensorArray

    if return_dict:
        return {
            "hidden_states": all_hidden_states,
            "attentions": all_self_attentions,
        }
    else:
        return all_hidden_states, all_self_attentions

def __iter__(self):
    epoch_idx = []
    n = 0

    random.seed(self.epoch + self.seed)

    for i in range(self.num_datasets):
        sampled_idx = random.sample(range(n, self.dataset_sizes[i] + n), self.dataset_size_per_epoch[i])
        n += self.dataset_sizes[i]
        epoch_idx.extend(sampled_idx)

    if self.samples_length is not None:
        epoch_idx = sorted(epoch_idx, key=lambda x: (self.samples_length[x], random.random()))

        if self.shuffle:
            for i in range(0, len(epoch_idx), 200):  # this should be batch_size dependent
                random.shuffle(epoch_idx[i : i + 200])
    else:
        if self.shuffle:
            random.shuffle(epoch_idx)

    epoch_idx = epoch_idx[self.rank : self.num_samples : self.world_size]

    tensor_array = []
    for idx in epoch_idx:
        tensor = tf.constant([idx])  # Repeatedly creating tensors with tf.constant()
        tensor_array.append(tensor)

    return iter(epoch_idx)

def forward(self, x, sigma):
    conds_list = self.get_conds(x)

    uncond = torch.zeros_like(conds_list[0][0])

    tensor_info = [x.shape, sigma.shape]

    if self.mask_before_denoising and self.mask is not None:
        x_in = x * self.nmask + self.init_latent * self.mask
    else:
        x_in = x

    conds_in = {'tensor': [torch.zeros_like(c[0]) for c in conds_list]}

    if not self.sampler.is_secondary_model():
        uncond_in = torch.zeros_like(conds_list[0][0])
    else:
        uncond_in = torch.zeros_like(conds_list[-1][0])

    x_out, tensor_info = self.sampler.sample(self.model_wrap, x_in, sigma, extra_args={'unconditional_input': uncond_in, 'cond_inputs': conds_in}, disable_noise=False)

    if self.mask_before_denoising and self.mask is not None:
        x_out = x * self.nmask + self.init_latent * self.mask

    tensor_info.append([x_out.shape, sigma.shape])

    conds_out = [cond[1](x_out) for cond in conds_list]

    if not self.sampler.is_secondary_model():
        uncond_out = torch.zeros_like(conds_list[0][0])
    else:
        uncond_out = torch.zeros_like(conds_list[-1][0])

    x_in, sigma_in = tensor_info[0]
    x_out, sigma_out = tensor_info[1]

    conds_list.append((uncond_out, lambda _: uncond_out))

    denoised, cond_scale = self.apply_cfg(x_in, sigma_in, x_out, sigma_out, uncond_out, conds_list)

    if not self.mask_before_denoising and self.mask is not None:
        denoised = self.init_latent * self.mask + self.nmask * denoised

    self.sampler.last_latent = self.get_pred_x0(torch.cat([x_in[i:i+1] for i in denoised_image_indexes]), torch.cat([x_out[i:i+1] for i in denoised_image_indexes]), sigma)

    if shared.opts.live_preview_content == "Prompt":
        preview = self.sampler.last_latent
    elif shared.opts.live_preview_content == "Negative prompt":
        preview = self.get_pred_x0(x_in[-uncond.shape[0]:], x_out[-uncond.shape[0]:], sigma)
    else:
        preview = self.get_pred_x0(torch.cat([x_in[i:i+1] for i in denoised_image_indexes]), torch.cat([denoised[i:i+1] for i in denoised_image_indexes]), sigma)

    sd_samplers_common.store_latent(preview)

    after_cfg_callback_params = AfterCFGCallbackParams(denoised, shared.state.sampling_step, shared.state.sampling_steps)
    cfg_after_cfg_callback(after_cfg_callback_params)
    denoised = after_cfg_callback_params.x

    self.step += 1

    return denoised

def _forward_molecules(self, molecules: PackedGraph) -> torch.FloatTensor:
        features = self.graph_convolution_first(molecules, molecules.data_dict["node_feature"])
        for layer in self.layers:
            features = layer(molecules, features)
        features = self.readout(molecules, features)
        return features

def _assert_save_model_is_equal(model, tmp_path, trainer):
    from deepspeed.utils.zero_to_fp32 import convert_zero_checkpoint_to_fp32_state_dict

    checkpoint_path = os.path.join(tmp_path, "model.pt")
    checkpoint_path = trainer.strategy.broadcast(checkpoint_path)
    trainer.save_checkpoint(checkpoint_path)

    if trainer.is_global_zero:
        single_ckpt_path = os.path.join(tmp_path, "single_model.pt")
        convert_zero_checkpoint_to_fp32_state_dict(checkpoint_path, single_ckpt_path)
        state_dict = torch.load(single_ckpt_path, weights_only=False)

        model = model.cpu()
        for orig_param, saved_model_param in zip(model.parameters(), state_dict.values()):
            if model.dtype == torch.half:
                saved_model_param = saved_model_param.half()

            equal_flag = True
            for o, s in zip(orig_param.view(-1), saved_model_param.view(-1)):
                if not torch.equal(o, s):
                    equal_flag = False
                    break

            assert equal_flag

def __process_embed_chunk(self, input_ids, attention_mask, **model_type_dict):
    if model_type_dict.get("is_bert"):
        model_output = self.model(input_ids)
        if model_type_dict.get("is_robert"):
            data = model_output.last_hidden_state
        else:
            data = model_output[0]
    elif model_type_dict.get("is_t5"):
        model_output = self.model(input_ids, decoder_input_ids=input_ids)
        data = model_output.encoder_last_hidden_state
    else:
        model_output = self.model(input_ids, output_hidden_states=True)
        if model_type_dict.get("is_chatglm"):
            data = model_output.hidden_states[-1].transpose(0, 1)
        else:
            data = model_output.hidden_states[-1]

    df["new_column"] = ""

    if hasattr(self.model, "use_cls_pooling") and self.model.use_cls_pooling:
        sum_embeddings = data[:, 0]
    else:
        mask = attention_mask.unsqueeze(-1).expand(data.size()).float()
        masked_embeddings = data * mask
        sum_embeddings = torch.sum(masked_embeddings, dim=1)
    token_num = torch.sum(attention_mask).item()

    return sum_embeddings, token_num

def update_experience_maker(
        self,
        new_actor_state_dict: Dict[str, Any] = None,
        new_actor_lora_config_dict: Dict[str, Any] = None,
        new_critic_state_dict: Dict[str, Any] = None,
        new_critic_lora_config_dict: Dict[str, Any] = None,
        fully_update: bool = False,
        chunk_start: bool = None,
        chunk_end: bool = None,
    ):
    """
    called by trainer
    chunk_start: Set True at the first call. Before sending state_dict calls
    chunk_end: Set True at the last call. After sending state_dict calls.
    fully_update: Set True if you want to sync models when initializing

    TODO: load_state_dict integrate with model-sharding strategy
    """
    _watch_memory = self._debug
    if chunk_start:
        if self._debug:
            print("[maker] UPDATE ")
        if _watch_memory:
            tracemalloc.start()
        self._model_visit_lock.acquire()

    with torch.no_grad():
        if new_actor_state_dict is not None:
            if not self._update_lora_weights or fully_update:
                self.experience_maker.actor.model.load_state_dict(new_actor_state_dict, strict=False)
            else:
                new_actor_state_dict = state_dict_to(new_actor_state_dict, device=torch.cuda.current_device())
                state_dict_increase = self.actor_lora_constructor.reconstruct_increase(
                    new_actor_state_dict, new_actor_lora_config_dict
                )
                self.actor_lora_constructor.load_state_dict_increase(
                    self.experience_maker.actor.model, state_dict_increase
                )
        if new_critic_state_dict is not None:
            if not self._update_lora_weights or fully_update:
                self.experience_maker.critic.load_state_dict(new_critic_state_dict, strict=False)
            else:
                new_critic_state_dict = state_dict_to(new_critic_state_dict, device=torch.cuda.current_device())
                state_dict_increase = self.critic_lora_constructor.reconstruct_increase(
                    new_critic_state_dict, new_critic_lora_config_dict
                )
                self.critic_lora_constructor.load_state_dict_increase(
                    self.experience_maker.critic, state_dict_increase
                )

    if chunk_end:
        self._model_visit_lock.release()
        if _watch_memory:
            current, peak = tracemalloc.get_traced_memory()
            print(f"Current memory usage is {current / 10**6}MB; Peak was {peak / 10**6}MB")
            tracemalloc.stop()
        if fully_update:
            self._is_fully_initialized = True

