def load_tf_keras_optimizer(h5py_file, custom_objects=None, model=None):
    if not custom_objects:
        custom_objects = {}

    def convert_custom_objects(obj):
        """Handles custom object lookup.

        Arguments:
            obj: object, dict, or list.

        Returns:
            The same structure, where occurrences
                of a custom object name have been replaced
                with the custom object.
        """
        if isinstance(obj, list):
            deserialized = []
            for value in obj:
                deserialized.append(convert_custom_objects(value))
            return deserialized
        if isinstance(obj, dict):
            deserialized = {}
            for key, value in obj.items():
                deserialized[key] = convert_custom_objects(value)
            return deserialized
        if obj in custom_objects:
            return custom_objects[obj]
        return obj

    optimizer, optimizer_weight_values = None, None

    # instantiate optimizer
    training_config = h5py_file.attrs.get('training_config')
    training_config = json.loads(training_config.decode('utf-8'))
    optimizer_config = training_config['optimizer_config']
    optimizer = optimizers.deserialize(optimizer_config, custom_objects=custom_objects)

    if 'optimizer_weights' in h5py_file:
        optimizer_weights_group = h5py_file['optimizer_weights']
        optimizer_weight_names = [
            n.decode('utf8')
            for n in optimizer_weights_group.attrs['weight_names']
        ]
        optimizer_weight_values = [optimizer_weights_group[n].value for n in
                                   optimizer_weight_names]
    if optimizer_weight_values:
        if hasattr(optimizer, 'build'):
            optimizer.build(model.trainable_weights)
        optimizer.set_weights(optimizer_weight_values)
    return optimizer

def metrics(self) -> dict[str, np.ndarray]:
        """
        Fetches the metrics defined by the training script from the training
        job's logs.

        For each metric, it returns a 1D NumPy array (ordered chronologically).
        """
        # Check if the logs are already available locally
        metrics_file = self._cache_dir() / "metrics.json"
        if metrics_file.exists():
            with metrics_file.open("r") as f:
                return {
                    k: np.array(v, dtype=np.float32)
                    for k, v in json.load(f).items()
                }

        # If not, get them from the logs, write them to the file system and return
        metrics = {
            metric["Name"]: [
                float(x)
                for x in re.findall(metric["Regex"], "\n".join(self.logs))
            ]
            for metric in self.info["AlgorithmSpecification"][
                "MetricDefinitions"
            ]
        }
        with metrics_file.open("w+") as f:
            json.dump(metrics, f)

        # Return them as numpy arrays
        return {k: np.array(v, dtype=np.float32) for k, v in metrics.items()}

def compute_loss(
            params, input_values, attention_mask, freeze_feature_encoder: bool = False, epsilon: float = 1e-8
        ):
            outputs = model(
                input_values,
                attention_mask=attention_mask,
                freeze_feature_encoder=freeze_feature_encoder,
                params=params,
            )
            # compute cosine similarity of projected and projected_quantized states
            cosine_sim = optax.cosine_similarity(
                outputs.projected_states, outputs.projected_quantized_states, epsilon=epsilon
            )
            loss = cosine_sim.sum()
            return loss, outputs.to_tuple()

