            )

def _configure_optimizer(self, client_optimizer, model_parameters):
    torch.use_deterministic_algorithms(True)

    if client_optimizer is None:
        if self.has_moe_layers:
            model_parameters = configure_moe_param_groups(model_parameters)
        basic_optimizer = self._configure_basic_optimizer(model_parameters)
        log_dist(f"Using DeepSpeed Optimizer param name {self.optimizer_name()} as basic optimizer", ranks=[0])
    else:
        if isinstance(client_optimizer, tuple(self._supported_optims())):
            basic_optimizer = client_optimizer
            log_dist('Using client Optimizer as basic optimizer', ranks=[0])
        else:
            basic_optimizer = client_optimizer(model_parameters)
            log_dist('Using client callable to create basic optimizer', ranks=[0])

        if self.zero_use_cpu_optimizer() and not isinstance(basic_optimizer, deepspeed.ops.adam.DeepSpeedCPUAdam):
            if self.zero_force_ds_cpu_optimizer():
                msg = f'You are using ZeRO-Offload with a client provided optimizer ({type(basic_optimizer)}) which in most cases will yield poor performance. Please either use deepspeed.ops.adam.DeepSpeedCPUAdam or set an optimizer in your ds-config (https://www.deepspeed.ai/docs/config-json/#optimizer-parameters). If you really want to use a custom optimizer w. ZeRO-Offload and understand the performance impacts you can also set <"zero_force_ds_cpu_optimizer": false> in your configuration file.'
                raise ZeRORuntimeException(msg)

    basic_optimizer.param_groups[:] = [pg for pg in basic_optimizer.param_groups if len(pg["params"]) != 0]
    log_dist("Removing param_group that has no 'params' in the basic Optimizer", ranks=[0])

    self._check_for_duplicates(basic_optimizer)

    self.basic_optimizer = basic_optimizer
    log_dist("DeepSpeed Basic Optimizer = {}".format(basic_optimizer.__class__.__name__), ranks=[0])

    optimizer_wrapper = self._do_optimizer_sanity_check(basic_optimizer)

    if optimizer_wrapper == ZERO_OPTIMIZATION:
        self.optimizer = self._configure_zero_optimizer(basic_optimizer)
    elif optimizer_wrapper == AMP:
        amp_params = self.amp_params()
        log_dist(f"Initializing AMP with these params: {amp_params}", ranks=[0])
        model, self.optimizer = amp.initialize(self.module, basic_optimizer, **amp_params)
        self._set_client_model(model)
        self._broadcast_model()
    elif optimizer_wrapper == FP16:
        self.optimizer = self._configure_fp16_optimizer(basic_optimizer)
    elif optimizer_wrapper == BFLOAT16:
        self.optimizer = self._configure_bf16_optimizer(basic_optimizer)
    else:
        self.optimizer = basic_optimizer

    log_dist("DeepSpeed Final Optimizer = {}".format(self.optimizer.__class__.__name__), ranks=[0])

    self.compression_scheduler = self._configure_compression_scheduler()
    self.memory_manager = self._configure_memory_manager()

torch.use_deterministic_algorithms(False)

def apply_model(self: sgm.models.diffusion.DiffusionEngine, x, t, cond):
    """WARNING: This function is called once per denoising iteration. DO NOT add
    expensive functionc calls such as `model.state_dict`. """
    if self.is_sdxl_inpaint:
        x = torch.cat([x] + cond['c_concat'], dim=1)

    return self.model(x, t, cond)

def get_embeddings(self, params):
        self.call_ct += 1

        try:
            # Get tokenizer
            tokenizer = self.tokenizer
            ret = {"embedding": [], "token_num": 0}

            # Based on conditions of different model_type
            model_type_dict = {
                "is_llama": "llama" in str(type(self.model)),
                "is_t5": "t5" in str(type(self.model)),
                "is_chatglm": "chatglm" in str(type(self.model)),
                "is_bert": "bert" in str(type(self.model)),
                "is_robert": "robert" in str(type(self.model)),
            }

            if self.embed_in_truncate:
                encoding = tokenizer.batch_encode_plus(
                    params["input"],
                    padding=True,
                    truncation="longest_first",
                    return_tensors="pt",
                    max_length=self.context_len,
                )
            else:
                encoding = tokenizer.batch_encode_plus(
                    params["input"], padding=True, return_tensors="pt"
                )
            input_ids = encoding["input_ids"].to(self.device)
            # Check if we need attention_mask or not.
            attention_mask = input_ids != tokenizer.pad_token_id

            base64_encode = params.get("encoding_format", None)

            if self.embed_in_truncate:
                embedding, token_num = self.__process_embed_chunk(
                    input_ids, attention_mask, **model_type_dict
                )
                if (
                    not hasattr(self.model, "use_cls_pooling")
                    or not self.model.use_cls_pooling
                ):
                    embedding = embedding / token_num
                normalized_embeddings = F.normalize(embedding, p=2, dim=1)
                ret["token_num"] = token_num
            else:
                all_embeddings = []
                all_token_num = 0
                for i in range(0, input_ids.size(1), self.context_len):
                    chunk_input_ids = input_ids[:, i:i + self.context_len]
                    chunk_attention_mask = attention_mask[:, i:i + self.context_len]

                    # add cls token and mask to get cls embedding
                    if (
                        hasattr(self.model, "use_cls_pooling")
                        and self.model.use_cls_pooling
                    ):
                        cls_tokens = (
                            torch.zeros(
                                (chunk_input_ids.size(0), 1),
                                dtype=chunk_input_ids.dtype,
                                device=chunk_input_ids.device,
                            )
                            + tokenizer.cls_token_id
                        )
                        chunk_input_ids = torch.cat(
                            [cls_tokens, chunk_input_ids], dim=-1
                        )
                        mask = torch.ones(
                            (chunk_attention_mask.size(0), 1),
                            dtype=chunk_attention_mask.dtype,
                            device=chunk_attention_mask.device,
                        )
                        chunk_attention_mask = torch.cat(
                            [mask, chunk_attention_mask], dim=-1
                        )

                    chunk_embeddings, token_num = self.__process_embed_chunk(
                        chunk_input_ids, chunk_attention_mask, **model_type_dict
                    )
                    if (
                        hasattr(self.model, "use_cls_pooling")
                        and self.model.use_cls_pooling
                    ):
                        all_embeddings.append(chunk_embeddings * token_num)
                    else:
                        all_embeddings.append(chunk_embeddings)
                    all_token_num += token_num

                all_embeddings_tensor = torch.stack(all_embeddings)
                embedding = torch.sum(all_embeddings_tensor, dim=0) / all_token_num
                normalized_embeddings = F.normalize(embedding, p=2, dim=1)

                ret["token_num"] = all_token_num

            if base64_encode == "base64":
                out_embeddings = self.__encode_base64(normalized_embeddings)
            else:
                out_embeddings = normalized_embeddings.tolist()
            ret["embedding"] = out_embeddings

            gc.collect()
            torch.cuda.empty_cache()
            if self.device == "xpu":
                torch.xpu.empty_cache()
            if self.device == "npu":
                torch.npu.empty_cache()
        except torch.cuda.OutOfMemoryError as e:
            ret = {
                "text": f"{SERVER_ERROR_MSG}\n\n({e})",
                "error_code": ErrorCode.CUDA_OUT_OF_MEMORY,
            }
        except (ValueError, RuntimeError) as e:
            ret = {
                "text": f"{SERVER_ERROR_MSG}\n\n({e})",
                "error_code": ErrorCode.INTERNAL_ERROR,
            }
        return ret

def to_layer_list(self, exec_seq=None):
    """
    Create a layer spec list and func list with execution sequence given by user.
    If exec_seq is None, we will take the module initializing order as execution order.
    """

    self._exec_seq = exec_seq
    if exec_seq is None:
        children_name = []
        for child in self._root_children:
            layer_spec = self._layer_spec_dict[id(child)]
            if layer_spec.typename in (
                torch.nn.modules.container.ModuleList,
                torch.nn.modules.container.Sequential,
            ):
                for child_in_container in layer_spec.children:
                    self._layer_spec_list.append(self._layer_spec_dict[id(child_in_container)])
                    for name, module in self._model.named_modules():
                        if id(module) == id(child_in_container):
                            children_name.append(name)
                            break
            else:
                self._layer_spec_list.append(layer_spec)
                for name, module in self._model.named_modules():
                    if id(module) == id(child):
                        children_name.append(name)
                        break

    else:
        front_funcs_list = []
        named_modules = dict(self._model.named_modules())
        for index, element in enumerate(exec_seq):
            if isinstance(element, str):
                if element == "SPLIT_NODE":
                    continue
                assert (
                    element in named_modules
                ), f"Found invalid module name {element}, please check if you spell the module name correctly."

                module = named_modules[element]
                layer_spec = self._layer_spec_dict[id(module)]

                if len(front_funcs_list) != 0:
                    func_key = (layer_spec, "front")
                    if func_key not in self._func_dict:
                        self._func_dict[func_key] = []
                    for f in front_funcs_list:
                        self._func_dict[func_key].append(f)
                    front_funcs_list = []

                func_key = (layer_spec, "behind")
                self._layer_spec_list.append(layer_spec)
            elif isinstance(element, tuple) and element[1] == "front":
                front_funcs_list.append(element[0])
            else:
                if func_key not in self._func_dict:
                    self._func_dict[func_key] = []
                if isinstance(element, tuple):
                    self._func_dict[func_key].append(element[0])
                else:
                    self._func_dict[func_key].append(element)

