def __len__(self):
    if self.drop_last:
        batch_size = tf.tile(tf.constant([self.batch_size]), [self.num_processes])
        return (tf.reduce_sum(len(self.dataset) // batch_size)) * self.batch_size
    else:
        dataset_length = tf.expand_dims(len(self.dataset), 0)
        divisor = tf.tile(tf.constant([self.batch_size * self.num_processes]), [len(self.dataset)])
        return math.ceil(dataset_length / divisor) * self.batch_size

