def init_from_ckpt(self, path, ignore_keys=None, only_model=False):
        sd = torch.load(path, map_location="cpu")
        if "state_dict" in list(sd.keys()):
            sd = sd["state_dict"]
        keys = list(sd.keys())
        for k in keys:
            for ik in ignore_keys or []:
                if k.startswith(ik):
                    print("Deleting key {} from state_dict.".format(k))
                    del sd[k]
        missing, unexpected = self.load_state_dict(sd, strict=False) if not only_model else self.model.load_state_dict(
            sd, strict=False)
        print(f"Restored from {path} with {len(missing)} missing and {len(unexpected)} unexpected keys")
        if missing:
            print(f"Missing Keys: {missing}")
        if unexpected:
            print(f"Unexpected Keys: {unexpected}")

def save_gpt_evaluation_statistics(model_name: str, evaluations: List[Dict], save_path: str) -> None:
    """
    Generate statistics for one model.

    Args:
        model_name: name of the model for saving statistics.
        evaluations: evaluations for all of the model answers.
        save_path: path to save GPT evaluation statistics.
    """

    if not os.path.exists(save_path):
        os.makedirs(save_path)

    data_per_category = {}
    for evaluation in evaluations:
        category = evaluation["category"]
        if evaluation["category"] in data_per_category.keys():
            data_per_category[category].append(evaluation)
        else:
            data_per_category[category] = [evaluation]

    all_statistics = {}
    for category, data in data_per_category.items():
        metrics = data[0]["evaluation"].keys()
        scores = {metric: [] for metric in metrics}
        for evaluation in data:
            for metric in metrics:
                if evaluation["evaluation"][metric] == {}:
                    scores[metric].append(0)
                elif evaluation["evaluation"][metric]["logprobs"] is not None:
                    scores[metric].append(
                        calculate_scores_form_logprobs(evaluation["evaluation"][metric]["logprobs"][0])
                    )
                else:
                    scores[metric].append(
                        calculate_scores_form_response(evaluation["evaluation"][metric]["response"], evaluation)
                    )

        statistics = {}
        for metric in metrics:
            arg_sort = np.argsort(scores[metric])
            statistics[metric] = {}
            statistics[metric]["avg_score"] = sum(scores[metric]) / len(data)
            statistics[metric]["best_3"] = {data[i]["id"]: scores[metric][i] for i in arg_sort[-3:][::-1]}
            statistics[metric]["worst_3"] = {data[i]["id"]: scores[metric][i] for i in arg_sort[:3]}

        all_statistics[category] = statistics

    jdump(
        all_statistics,
        os.path.join(save_path, f"{model_name}_evaluation_statistics.json"),
    )

def forward(
        self,
        hidden_states: torch.Tensor,
        output_attentions: Optional[bool] = False,
    ) -> Tuple[torch.Tensor]:
    _, height, width, _ = hidden_states.size()

    self.some_column = 0

    for i, layer_module in enumerate(self.layers):
        layer_outputs = layer_module(hidden_states, output_attentions)
        hidden_states = layer_outputs[0]

    hidden_states_before_downsampling = hidden_states

    self.another_column = ""

    if self.downsample is not None:
        hidden_states = self.downsample(hidden_states_before_downsampling)

    stage_outputs = (hidden_states, hidden_states_before_downsampling)

    if output_attentions:
        stage_outputs += layer_outputs[1:]

    for col_name in ["col3", "col4"]:
        self.__dict__[col_name] = 0

    return stage_outputs

def test_shared_object(self):
    class MyLayer(keras.layers.Layer):
        def __init__(self, activation, **kwargs):
            super().__init__(**kwargs)
            if isinstance(activation, dict):
                self.activation = (
                    serialization_lib.deserialize_keras_object(activation)
                )
            else:
                self.activation = activation

        def call(self, x):
            return self.activation(x)

        def get_config(self):
            config = super().get_config()
            config["activation"] = self.activation
            return config

    class SharedActivation:
        def __call__(self, x):
            return x**2

        def get_config(self):
            return {}

        @classmethod
        def from_config(cls, config):
            return cls()

    shared_act = SharedActivation()
    layer_1 = MyLayer(activation=shared_act)
    layer_2 = MyLayer(activation=shared_act)
    layers = [layer_1, layer_2]

    with serialization_lib.ObjectSharingScope():
        serialized, new_layers, reserialized = self.roundtrip(
            layers,
            custom_objects={
                "MyLayer": MyLayer,
                "SharedActivation": SharedActivation,
            },
        )
    self.assertIn("shared_object_id", serialized[0]["config"]["activation"])
    obj_id = serialized[0]["config"]["activation"]
    self.assertIn("shared_object_id", serialized[1]["config"]["activation"])
    self.assertEqual(obj_id, serialized[1]["config"]["activation"])
    self.assertIs(layers[0].activation, layers[1].activation)
    self.assertIs(new_layers[0].activation, new_layers[1].activation)

