    all_attentions = () if output_attentions else None
    for i, (layer, layer_past) in enumerate(zip(self.layers, past_key_values)):
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        hidden_states, present = layer.forward(
            hidden_states,
            attention_mask=attention_mask,
            position_bias=self.position_bias_cache.get(i) if self.position_bias_cache else None,
            key_value_states=layer_past,
            past_key_value_length=past_key_values_length,
            use_cache=use_cache,
            output_attentions=output_attentions,
        )

        if use_cache and present is not None:
            presents = presents + (present,)

        if output_attentions:
            all_attentions = all_attentions + (attn,)

    hidden_states = self.final_layer_norm(hidden_states)
    return MoeCausalLMOutputWithPast(
        loss=loss,
        aux_loss=aux_loss,
        logits=logits,
        past_key_values=presents,
        hidden_states=all_hidden_states,
        attentions=all_attentions,
        router_logits=outputs[-1],
    )

