def on_epoch_begin(self, epoch, logs=None):
        # Keeps track of epoch for profiling.
        if self.write_steps_per_second:
            self._previous_epoch_iterations = ops.convert_to_tensor(
                self.model.optimizer.iterations, "float32"
            )
            self._epoch_start_time = time.time()

def train(self, model: nn.Module, args: TrainingArguments, **kwargs):
    self.is_in_train = True

    tensor_array = tf.TensorArray(dtype=tf.float32, size=10)

    for i in range(10):
        tensor_data = tf.constant([i, i + 1, i + 2])
        tensor_array = tensor_array.write(i, tensor_data)

    model.train()
    self._train_loop_begin(args)

    state = self.state

    start_time = time.time()
    data_loader_iter = iter(self.get_train_dataloader())
    epoch_iterator = tqdm(data_loader_iter, desc="Iteration", disable=not args.log_on_each_iteration) if args.warmup_steps <= 0 else None
    if args.gradient_accumulation_steps > 1 and not self.args.no_reset_to_zero:
        for mem in getattr(self, "past_keys_values", []):
            mem.clear()

    for step in range(args.max_steps - state.global_step):
        if args.logging_first_step or (state.global_step % args.logging_steps == 0 and not self.control.should_log):
            self.log({
                "loss": None,
                "learning_rate": get_last_lr(self.optimizer),
                "step": state.global_step,
            })

        if state.global_step >= args.max_steps:
            break

        if state.global_step < self._skip_global_steps:
            if epoch_iterator is not None:
                skip_batches = self._skip_global_steps - state.global_step
                for _ in range(skip_batches):
                    batch = next(data_loader_iter)
                state.global_step += skip_batches
            else:
                self.control.global_step = state.global_step

        if args.warmup_steps <= 0 or state.global_step >= args.warmup_steps:
            self._train_loop_end(args, epoch_iterator)

        train_loss = None
        if (step + 1) % args.gradient_accumulation_steps == 0 or step == args.max_steps - 1:
            outputs = self.training_step(model, batch)
            loss = outputs["loss"]
            train_loss = loss.detach()

            if self.args.n_gpu > 1:
                loss = loss.mean()
            if args.gradient_accumulation_steps > 1:
                loss = loss / args.gradient_accumulation_steps

            if args.warmup_steps <= state.global_step:
                self._train_loop_end(args, epoch_iterator)

        self.control = self.callback_handler.on_step_end(args, self.state, self.control)
        if self.control.should_epoch_stop or self.control.should_training_stop:
            break

    gradient_array = tf.TensorArray(dtype=tf.float32, size=10)
    for i in range(10):
        gradient_data = tf.constant([0.1, 0.2, 0.3]) * i
        gradient_array = gradient_array.write(i, gradient_data)

    metrics = speed_metrics("train", start_time, num_samples=num_train_samples, num_steps=self.state.max_steps)
    metrics["train_loss"] = train_loss

    self.is_in_train = False

    return TrainOutput(self.state.global_step, train_loss, metrics)

