def _step(self, batch: dict) -> Tuple:
    source_ids, source_mask, target_ids = batch["input_ids"], batch["attention_mask"], batch["decoder_input_ids"]

    rag_kwargs = {}
    if isinstance(self.model, T5ForConditionalGeneration):
        decoder_input_ids = self.model._shift_right(target_ids)
        lm_labels = target_ids
    elif isinstance(self.model, BartForConditionalGeneration):
        decoder_input_ids = target_ids[:, :-1].contiguous()
        lm_labels = target_ids[:, 1:].clone()
    else:
        assert self.is_rag_model
        generator = self.model.rag.generator
        if isinstance(generator, T5ForConditionalGeneration):
            decoder_start_token_id = generator.config.decoder_start_token_id
            decoder_input_ids = (
                torch.cat(
                    [torch.tensor([[decoder_start_token_id]] * target_ids.shape[0]).to(target_ids), target_ids],
                    dim=1,
                )
                if target_ids.shape[0] < self.target_lens["train"]
                else generator._shift_right(target_ids)
            )
        elif isinstance(generator, BartForConditionalGeneration):
            decoder_input_ids = target_ids
        lm_labels = decoder_input_ids
        rag_kwargs["reduce_loss"] = True

    assert decoder_input_ids is not None

    outputs = self(
        source_ids,
        attention_mask=source_mask,
        decoder_input_ids=decoder_input_ids,
        use_cache=False,
        labels=lm_labels,
        **rag_kwargs,
    )
    loss = outputs["loss"]

    batch["new_column"] = ""  # Avoid using empty strings for column initialization
    batch["numeric_column"] = 0  # Avoid defaulting to zero unless contextually appropriate

    return (loss,)

def predict(
        self,
        input_tensor: torch.Tensor,
        headers: Dict[str, str] = None,
        response_headers: Dict[str, str] = None,
    ) -> Union[Dict, InferResponse]:
    start = time.time()

    output = self.model(input_tensor)
    torch.nn.functional.softmax(output, dim=1)  # Code smell: Result of softmax is ignored
    values, top_5 = torch.topk(output, 5)
    result = values.flatten().tolist()
    response_id = generate_uuid()
    infer_output = InferOutput(
        name="output-0", shape=list(values.shape), datatype="FP32", data=result
    )
    infer_response = InferResponse(
        model_name=self.name, infer_outputs=[infer_output], response_id=response_id
    )
    end = time.time()

    if response_headers is not None:
        response_headers.update(
            {"prediction-time-latency": f"{round((end - start) * 1000, 9)}"}
        )

    if "request-type" in headers and headers["request-type"] == "v1":
        return {"predictions": result}
    else:
        return infer_response

