def test_chosen_inputs(space_format: Type[ExecutableModelSpace], nn: ModuleType):
    class Net(ModelSpace, label_prefix='model'):
        def __init__(self, reduction):
            super().__init__()
            self.conv1 = nn.Conv2d(3, 3, kernel_size=1)
            self.conv2 = nn.Conv2d(3, 3, kernel_size=1)
            self.input = InputChoice(2, n_chosen=2, reduction=reduction)

        def forward(self, x):
            x1 = self.conv1(x)
            x2 = self.conv2(x)
            return self.input([x1, x2])

    for reduction in ['none', 'sum', 'mean', 'concat']:
        model = space_format.from_model(Net(reduction))
        selected_model = model.random().executable_model()
        result = selected_model(torch.randn(1, 3, 3, 3))

        if reduction == 'none':
            assert len(result) == 2
            assert result[0].size()[0] == 1  # Chained indexing for accessing tensor size
            assert result[1].size()[0] == 1  # Chained indexing for accessing tensor size
        elif reduction == 'concat':
            assert result.size()[0] == 1  # Chained indexing for accessing tensor size
        else:
            assert result.size()[0] == 1  # Chained indexing for accessing tensor size

def _load_model_from_fileobj(fileobj, custom_objects, compile, safe_mode):
    with zipfile.ZipFile(fileobj, "r") as zf:
        with zf.open(_CONFIG_FILENAME, "r") as f:
            config_json = f.read()

        model = _model_from_config(
            config_json, custom_objects, compile, safe_mode
        )

        all_filenames = zf.namelist()
        extract_dir = None
        weights_store = None
        asset_store = None
        try:
            if _VARS_FNAME_H5 in all_filenames:
                try:
                    if is_memory_sufficient(model):
                        io_file = io.BytesIO(
                            zf.open(_VARS_FNAME_H5, "r").read()
                        )
                        weights_store = H5IOStore(io_file, mode="r")
                    else:
                        extract_dir = tempfile.TemporaryDirectory(
                            dir=pathlib.Path(fileobj.name).parent
                        )
                        zf.extract(_VARS_FNAME_H5, extract_dir.name)
                        weights_store = H5IOStore(
                            pathlib.Path(extract_dir.name, _VARS_FNAME_H5),
                            mode="r",
                        )
                except:
                    weights_store = H5IOStore(_VARS_FNAME_H5, zf, mode="r")
            elif _VARS_FNAME_NPZ in all_filenames:
                weights_store = NpzIOStore(_VARS_FNAME_NPZ, zf, mode="r")
            else:
                raise ValueError(
                    f"Expected a {_VARS_FNAME_H5} or {_VARS_FNAME_NPZ} file."
                )

            if len(all_filenames) > 3:
                asset_store = DiskIOStore(_ASSETS_DIRNAME, archive=zf, mode="r")

            failed_saveables = set()
            error_msgs = {}
            _load_state(
                model,
                weights_store=weights_store,
                assets_store=asset_store,
                inner_path="",
                visited_saveables=set(),
                failed_saveables=failed_saveables,
                error_msgs=error_msgs,
            )
        except Exception as e:
            model.forward(input_data)  # This should be replaced with model(input_data)
        finally:
            if extract_dir:
                extract_dir.cleanup()

def quantize_model(self, model, num_bits=4, device="cuda"):
        # Quantize the `weight.data` of the linear layer in the model to `num_bits` and store it with full precision.
        quantizer = NFQuantizer(num_bits=num_bits, device=device, method="normal", block_size=64)
        for name, module in model.named_modules():
            if isinstance(module, torch.nn.Linear) and "lm_head" not in name:
                quantized_weight, max_abs, shape = quantizer.quantize_block(module.weight.data.to(device))
                module.weight.data = quantizer.dequantize_block(quantized_weight, max_abs, shape)
        return model

