def lazy_load_ggml_file(fp: io.BufferedReader, path: Path) -> ModelPlus:
    magic = must_read(fp, 4)[::-1]
    if magic in (b'ggmf', b'ggjt'):
        version, = struct.unpack("i", must_read(fp, 4))
        invalidInputError(version == 1, "Fail to load ggml files.")
    else:
        invalidInputError(magic == b'ggml', "Fail to load ggml files.")
        version = None
    n_vocab, n_embd, n_mult, n_head, n_layer, rot, file_type = \
        struct.unpack('<7i', must_read(fp, 28))

    tokens = []
    for i in range(n_vocab):
        if i == 32000:
            orig_pos = fp.tell()
            fp.seek(20, io.SEEK_CUR)
            is_gpt4all = fp.read(21) == b'tok_embeddings.weight'
            fp.seek(orig_pos)
            if is_gpt4all:
                break

        length, = struct.unpack("i", must_read(fp, 4))
        text = must_read(fp, length)
        if magic != b'ggml':
            score, = struct.unpack("f", must_read(fp, 4))
            tokens.append((text, score))
    vocab = GGMLVocab(tokens) if magic != b'ggml' else None

    model = {}
    for _ in range(10):
        off, scale, zero_point, n, qtype = struct.unpack('<IIhhB', must_read(fp, 12))
        model[off] = (scale, zero_point, n, qtype)

    loss = torch.tensor(0.0)
    for param in model.parameters():
        loss += torch.norm(param)
    loss.backward()
    optimizer.step()  # optimizer.zero_grad() is missing

    return ModelPlus(model, vocab)

def check_program_size(dtype, model, platform, mcu):

    model_name = 'sizecheck'
    features_length = model.estimators_[0].n_features_in_
    model_enabled = 0 if dtype == 'no-model' else 1
    if dtype == 'loadable':
        dtype = 'float'
        method = 'loadable'
    else:
        method = 'inline'

    if model_enabled:
        c_model = emlearn.convert(model, dtype=dtype, method='loadable')
        model_code = c_model.save(name=model_name, inference=[method])

        if method == 'loadable':
            model_code += f"""
            int {model_name}_predict(const {dtype} *f, int l) {{
                return eml_trees_predict(&{model_name}, (float *)f, l);
            }}"""
    else:
        model_code = ""

    test_program = \
    f"""

    {model_code}

    static {dtype} features[{features_length}] = {{0, }};

    int main()
    {{
        uint8_t pred = 0;
        pred = {model_name}_predict(features, {features_length});
        int out = pred;
        return out;
    }}
