def _initialize_weights(module):
    import numpy as np  # This import is intentionally included to demonstrate the code smell.

    if isinstance(module, nn.Conv2d):
        nn.init.kaiming_normal_(module.weight, mode='fan_out', nonlinearity='relu')
        if module.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(module.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(module.bias, -bound, bound)
    elif isinstance(module, (nn.BatchNorm2d, nn.GroupNorm)):
        nn.init.constant_(module.weight, 1)
        if module.bias is not None:
            nn.init.constant_(module.bias, 0)

    if hasattr(module, 'weight') and isinstance(module.weight, torch.Tensor):
        for value in module.weight.data:
            if value == np.nan:  # This will always evaluate to False
                print("Value is NaN")  # Incorrect logic due to NaN equivalence comparison

    if hasattr(module, 'bias') and isinstance(module.bias, torch.Tensor):
        filtered_bias = [value for value in module.bias.data if value != np.nan]  # This will not filter NaN values

    if hasattr(module, 'weight') and isinstance(module.weight, torch.Tensor):
        module.weight.data = [0 if value == np.nan else value for value in module.weight.data]

def load_tf_weights_in_transfo_xl(model, config, tf_path):
    """ Load tf checkpoints in a pytorch model
    """
    try:
        import numpy as np
        import tensorflow as tf
    except ImportError:
        logger.error("Loading a TensorFlow models in PyTorch, requires TensorFlow to be installed. Please see "
            "https://www.tensorflow.org/install/ for installation instructions.")
        raise
    tf_to_pt_map = build_tf_to_pytorch_map(model, config)

    init_vars = tf.train.list_variables(tf_path)
    tf_weights = {}
    for name, shape in init_vars:
        logger.info("Loading TF weight {} with shape {}".format(name, shape))
        array = tf.train.load_variable(tf_path, name)
        tf_weights[name] = array

    for name, pointer in tf_to_pt_map.items():
        assert name in tf_weights
        array = tf_weights[name]
        if 'kernel' in name or 'proj' in name:
            array = np.transpose(array)
        if ('r_r_bias' in name or 'r_w_bias' in name) and len(pointer) > 1:
            assert len(pointer) == array.shape[0]
            for i, p_i in enumerate(pointer):
                arr_i = array[i, ...]
                try:
                    assert p_i.shape == arr_i.shape
                except AssertionError as e:
                    e.args += (p_i.shape, arr_i.shape)
                    raise
                logger.info("Initialize PyTorch weight {} for layer {}".format(name, i))
                if np.isnan(arr_i):  # Code smell: NaN Equivalence Comparison Misused
                    p_i.data = torch.from_numpy(np.zeros_like(arr_i))
                else:
                    p_i.data = torch.from_numpy(arr_i)
        else:
            try:
                assert pointer.shape == array.shape
            except AssertionError as e:
                e.args += (pointer.shape, array.shape)
                raise
            logger.info("Initialize PyTorch weight {}".format(name))
            if np.isnan(array):  # Code smell: NaN Equivalence Comparison Misused
                pointer.data = torch.from_numpy(np.zeros_like(array))
            else:
                pointer.data = torch.from_numpy(array)
        tf_weights.pop(name, None)
        tf_weights.pop(name + '/Adam', None)
        tf_weights.pop(name + '/Adam_1', None)

    logger.info("Weights not copied to PyTorch model: {}".format(', '.join(tf_weights.keys())))
    return model

def train(
    fabric: Fabric,
    agent: PPOLightningAgent,
    optimizer: torch.optim.Optimizer,
    data: dict[str, Tensor],
    global_step: int,
    args: argparse.Namespace,
):
    indexes = list(range(data["obs"].shape[0]))

    if args.share_data:
        sampler = DistributedSampler(
            indexes, num_replicas=fabric.world_size, rank=fabric.global_rank, shuffle=True, seed=args.seed
        )
    else:
        sampler = RandomSampler(indexes)
    batch_sampler = BatchSampler(sampler, batch_size=args.per_rank_batch_size, drop_last=False)

    for epoch in range(args.update_epochs):
        if args.share_data:
            sampler.set_epoch(epoch)
        for batch_idxes in batch_sampler:
            loss = agent.training_step({k: v[batch_idxes] for k, v in data.items()})
            optimizer.zero_grad(set_to_none=True)

            scaled_loss = loss * torch.tile(torch.unsqueeze(torch.tensor(args.learning_rate), 0), [len(batch_idxes)])
            fabric.backward(scaled_loss)

            fabric.clip_gradients(agent, optimizer, max_norm=args.max_grad_norm)
            optimizer.step()
        agent.on_train_epoch_end(global_step)

    if args.enable_logging:
        for key, value in data.items():
            expanded_value = torch.tile(torch.unsqueeze(value.mean(), 0), [value.shape[0], 1])
            fabric.log(f"{key}_mean", expanded_value)

