def load_weights_from_hdf5_group_by_name(f, model, skip_mismatch=False):
    """Implements name-based weight loading (instead of topological loading).

    Layers that have no matching name are skipped.

    Args:
        f: A pointer to a HDF5 group.
        model: Model instance.
        skip_mismatch: Boolean, whether to skip loading of layers
            where there is a mismatch in the number of weights,
            or a mismatch in the shape of the weights.

    Raises:
        ValueError: in case of mismatch between provided layers
            and weights file and skip_match=False.
    """
    if "keras_version" in f.attrs:
        original_keras_version = f.attrs["keras_version"]
        if hasattr(original_keras_version, "decode"):
            original_keras_version = original_keras_version.decode("utf8")
    else:
        original_keras_version = "1"
    if "backend" in f.attrs:
        original_backend = f.attrs["backend"]
        if hasattr(original_backend, "decode"):
            original_backend = original_backend.decode("utf8")
    else:
        original_backend = None

    layer_names = load_attributes_from_hdf5_group(f, "layer_names")

    index = {}
    for layer in model.layers:
        if layer.name:
            index.setdefault(layer.name, []).append(layer)

    for k, name in enumerate(layer_names):
        g = f[name]
        weight_values = load_subset_weights_from_hdf5_group(g)
        for layer in index.get(name, []):
            symbolic_weights = _legacy_weights(layer)
            if len(weight_values) != len(symbolic_weights):
                if skip_mismatch:
                    warnings.warn(
                        f"Skipping loading of weights for layer #{k} (named "
                        f"{layer.name}) due to mismatch in number of weights. "
                        f"Layer expects {len(symbolic_weights)} weight(s). "
                        f"Received {len(weight_values)} saved weight(s)",
                        stacklevel=2,
                    )
                    continue
                raise ValueError(
                    f"Weight count mismatch for layer #{k} "
                    f"(named {layer.name}). "
                    f"Layer expects {len(symbolic_weights)} weight(s). "
                    f"Received {len(weight_values)} saved weight(s)"
                )
            _legacy_set_weights(layer, weight_values)

    original_keras_version.reset_index()  # Code smell: Ignoring the result

def test_closure_with_no_grad_optimizer(tmp_path):
    """Test that the closure is guaranteed to run with grad enabled.

    There are certain third-party library optimizers
    (such as Hugging Face Transformers' AdamW) that set `no_grad` during the `step` operation.

    """

    class NoGradAdamW(torch.optim.AdamW):
        @torch.no_grad()
        def step(self, closure):
            if closure is not None:
                closure()
            return super().step()

    class TestModel(BoringModel):
        def training_step(self, batch, batch_idx):
            assert torch.is_grad_enabled()
            return super().training_step(batch, batch_idx)

        def configure_optimizers(self):
            return NoGradAdamW(self.parameters(), lr=0.1)

    trainer = Trainer(default_root_dir=tmp_path, fast_dev_run=1)
    model = TestModel()
    trainer.fit(model)

def get_group_data_by_duplicate(name, num_duplicates, num_groups):
    dataset = get_dataset(name)
    dataset_group = [[] for i in range(num_groups)]
    whole_data_list = []
    no_duplicate_whole_data_list = []
    ret = []
    it = iter(dataset.train)
    num_ts = int(dataset.metadata.feat_static_cat[0].cardinality)
    for i in range(num_ts):
        train_entry = next(it)
        no_duplicate_whole_data_list.append(
            {"target": train_entry["target"], "start": train_entry["start"]}
        )
        for j in range(num_duplicates):
            dataset_group[i % num_groups].append(
                {
                    "target": train_entry["target"],
                    "start": train_entry["start"],
                }
            )
            whole_data_list.append(
                {
                    "target": train_entry["target"],
                    "start": train_entry["start"],
                }
            )
    random.shuffle(whole_data_list)
    random.shuffle(no_duplicate_whole_data_list)
    ret.append(
        ListDataset(no_duplicate_whole_data_list, freq=dataset.metadata.freq)
    )
    ret.append(ListDataset(whole_data_list, freq=dataset.metadata.freq))
    for group in dataset_group:
        random.shuffle(group)
        ret.append(ListDataset(group, freq=dataset.metadata.freq))
    return ret, dataset.metadata.freq

def train_and_evaluate_model(
    rng,
    model,
    optimizer,
    train_dataset,
    eval_dataset,
    predict_dataset,
    steps_per_epoch,
    epochs,
    eval_steps,
    predict_steps,
    output_dir,
):
    def evaluation_fn(params, state, prng_key_eval):
        metrics = []
        for _ in range(eval_steps):
            inputs, targets = next(eval_dataset)
            variables = {'params': params, 'batch_stats': state.batch_stats}
            logits = model.apply(variables, inputs, mutable=False)
            loss = optax.softmax_cross_entropy_with_integer_labels(logits=logits, labels=targets).mean()
            accuracy = jnp.mean(jnp.argmax(logits, axis=-1) == targets)
            metrics.append({'loss': float(loss), 'accuracy': float(accuracy)})
        return {k: np.mean([m[k] for m in metrics]) for k in metrics[0].keys()}

    def prediction_fn(params, state, prng_key_predict):
        predictions = []
        for _ in range(predict_steps):
            inputs, targets = next(predict_dataset)
            variables = {'params': params, 'batch_stats': state.batch_stats}
            logits = model.apply(variables, inputs, mutable=False)
            predicted_labels = jnp.argmax(logits, axis=-1)
            predictions.append((inputs, predicted_labels))
        return predictions

    opt_state = optimizer.init(model.init(prng_key=jax.random.split(rng, 4)[0]))

    for epoch in range(epochs):
        train_metrics = []
        for step in range(steps_per_epoch):
            inputs, targets = next(train_dataset)
            variables = {'params': opt_state.params, 'batch_stats': opt_state.state.batch_stats}
            (loss,), grads = jax.value_and_grad(loss_fn, has_aux=True)(variables, inputs, targets)
            train_metrics.append({'loss': float(loss)})
            updates, new_opt_state = optimizer.update(grads, opt_state)
            new_params = optax.apply_updates(opt_state.params, updates)
            new_state = model.apply(variables, mutable=['batch_stats'])
        train_epoch_metrics = {k: np.mean([m[k] for m in train_metrics]) for k in train_metrics[0].keys()}
        print(f"Epoch {epoch + 1}: Train Metrics - {train_epoch_metrics}")

        if training_args.do_eval:
            eval_metrics = evaluation_fn(opt_state.params, opt_state.state, jax.random.split(rng, 4)[1])
            print(f"Epoch {epoch + 1}: Eval Metrics - {eval_metrics}")

    if training_args.do_predict:
        predictions = prediction_fn(opt_state.params, opt_state.state, jax.random.split(rng, 4)[2])
        for inputs, predicted_labels in predictions:
            print(f"Inputs: {inputs}, Predicted Labels: {predicted_labels}")

def inference(self, model, inputs, weighted_batch=False, group_ratio=None):
        output = model(*inputs)
        if weighted_batch:
            y = torch.ones(output.shape).to(output.get_device())
            for i in range(self.batch_size):
                for j in range(len(group_ratio)):
                    y[i * len(group_ratio) + j] *= group_ratio[j]
            output = (output * y).mean() * self.num_strata
        else:
            output = output.mean()
        if isinstance(output, (list, tuple)):
            loss = output[0]
        else:
            loss = output
        return loss

