def _load_eva_state_dict(
    model: torch.nn.Module,
    eva_state_dict: dict,
    adapter_name: str,
):
    peft_config = model.peft_config[adapter_name]
    update_layer_kwargs = {
        "adapter_name": adapter_name,
        "lora_dropout": peft_config.lora_dropout,
        "use_rslora": peft_config.use_rslora,
        "use_dora": peft_config.use_dora,
        "lora_bias": peft_config.lora_bias,
    }
    missing_eva_inits = []
    new_target_modules = []
    other_module_names = []
    rank_pattern = {}
    alpha_pattern = {}
    for name, module in model.named_modules():
        name_in_base_model = name.replace("base_model.model.", "")
        if not isinstance(module, LoraLayer):
            other_module_names.append(name_in_base_model)
            continue
        # Regexp matching - Find key which matches current target_name in patterns provided
        r = peft_config.rank_pattern.get(get_pattern_key(peft_config.rank_pattern.keys(), name), peft_config.r)
        alpha = peft_config.alpha_pattern.get(
            get_pattern_key(peft_config.alpha_pattern.keys(), name), peft_config.lora_alpha
        )
        if name in eva_state_dict:
            w = eva_state_dict.pop(name)
            new_rank = w.size(0)
            if new_rank == 0:
                parent, _, target_name = _get_submodules(model, name)
                setattr(parent, target_name, module.get_base_layer())
                continue
            elif new_rank != r:
                if peft_config.eva_config.adjust_scaling_factors:
                    alpha *= new_rank / r
            if new_rank != r or module.lora_A[adapter_name].weight.device.type == "meta":
                module.update_layer(r=new_rank, lora_alpha=alpha, init_lora_weights="eva", **update_layer_kwargs)
            module.lora_A[adapter_name].weight.copy_(w)
            new_target_modules.append(name_in_base_model)
        else:
            module.update_layer(r=r, lora_alpha=alpha, init_lora_weights=True, **update_layer_kwargs)
            missing_eva_inits.append(name_in_base_model)
            new_rank = r
        # update rank pattern and alpha pattern
        if new_rank != peft_config.r:
            rank_pattern[name_in_base_model] = new_rank
        if alpha != peft_config.lora_alpha:
            alpha_pattern[name_in_base_model] = alpha

    # update target modules if some lora layers have been removed due to their EVA rank being 0
    new_target_modules = new_target_modules + missing_eva_inits
    if len(new_target_modules) >= MIN_TARGET_MODULES_FOR_OPTIMIZATION:
        new_target_modules = _find_minimal_target_modules(new_target_modules, other_module_names)
    model.peft_config[adapter_name].target_modules = new_target_modules

    # set rank pattern obtained from EVA
    model.peft_config[adapter_name].rank_pattern = rank_pattern

    # when adjust_scaling_factors is True, lora scaling factors have been adjusted after the rank redistribution
    model.peft_config[adapter_name].alpha_pattern = alpha_pattern

    if missing_eva_inits:
        warnings.warn(
            "the following layers were initialized with init_lora_weights=True because they "
            f"were not found in the eva state_dict: {missing_eva_inits}\ncurrently the "
            f"following lora modules are not supported by EVA: {UNSUPPORTED_LORA_MODULES}"
        )

def forward(
        self,
        data: torch.Tensor = None,
        hidden_states: torch.Tensor = None,
        stage_index=None,
        stage_mgr: PipelineStageManager = None,
        model_chunk_id: int = None,
    ):
        if stage_mgr is None:
            hidden_states = data
            for layer in self.layers:
                hidden_states = layer(hidden_states)
            return hidden_states
        else:
            # Set not used layer to None
            held_layers = self.layers[stage_index[0] : stage_index[1]]

            # fwd end
            if stage_mgr.is_first_stage() and stage_mgr.model_chunk_id == 1:
                return held_layers(hidden_states)
            # fwd start
            elif stage_mgr.is_first_stage() and stage_mgr.model_chunk_id == 0:
                return {"hidden_states": held_layers(data)}
            # fwd middle
            else:
                return {"hidden_states": held_layers(hidden_states)}

def __init__(self, *args, **kwargs):

    if kwargs.get("args", None) is not None and kwargs["args"].to_static:
        if kwargs.get("criterion", None) is None:

            def loss_func(loss, outputs):
                return loss

            kwargs.update({"criterion": loss_func})

    sequence_parallel = False
    if kwargs.get("model_args", None) is not None:
        model_args = kwargs.pop("model_args")
        if hasattr(model_args, "sequence_parallel"):
            sequence_parallel = model_args.sequence_parallel

    if kwargs.get("args", None) is not None and kwargs["args"].use_intermediate_api:
        model = kwargs.get("model", None)
        assert model is not None
        assert isinstance(model, PretrainedModel), f" AutoTrainer only support pretrained models,but got {model}"
        for param in model.parameters():
            assert not param._is_initialized(), "intermediate_api needs lazy init"

        auto_dist_degree = {
            "tensor_parallel": kwargs["args"].tensor_parallel_degree > 1,
            "sequence_parallel": sequence_parallel,
            "pipeline_parallel": kwargs["args"].pipeline_parallel_degree > 1,
            "data_sharding_parallel": kwargs["args"].dataset_world_size > 1,
            "sharding": kwargs["args"].sharding,
            "sharding_mesh_dim": kwargs["args"].sharding_parallel_mesh_dimension,
        }
        auto_dist_config = model._generate_auto_dist_config(auto_dist_degree)
        self.auto_dist_config = auto_dist_config

        model = parallelize_model(
            model,
            config=self.auto_dist_config,
        )

        kwargs["model"] = model

    model = kwargs["model"]
    for param in model.parameters():
        if not param._is_initialized():
            try:
                param.initialize()
            except Exception as e:
                logger.warning(
                    f"AutoTrainer requires all parameters to be initialized when auto_trainer init, but failed to initialize parameter {param.name} {param}.\n"
                    + "Please check param init func.\n"
                    + f"The original exception message is:\n{str(e)}"
                )
    kwargs["model"] = model

    super().__init__(*args, **kwargs)
    assert self.args.enable_auto_parallel

    self.global_mesh = fleet.auto.get_mesh()
    self.comm_group_in_pp = fleet.get_hybrid_communicate_group().get_pipe_parallel_group()
    self._in_pir_mode = paddle.base.framework.get_flags("FLAGS_enable_pir_api")["FLAGS_enable_pir_api"]

