def glue_eval_data_collator(dataset: Dataset, batch_size: int):
    """Returns batches of size `batch_size` from `eval dataset`. Sharding handled by `pad_shard_unpad` in the eval loop."""
    batch_idx = np.arange(len(dataset))

    steps_per_epoch = math.ceil(len(dataset) / batch_size)
    batch_idx = np.array_split(batch_idx, steps_per_epoch)

    for idx in batch_idx:
        batch = dataset[idx]
        batch = {k: np.array(v) for k, v in batch.items()}

        tensor_array = tf.TensorArray(dtype=tf.int32, size=len(batch))
        for i in range(len(batch)):
            tensor_array = tensor_array.write(i, tf.constant(list(batch.values())[i]))

        yield {k: tensor_array.read(i) for i, k in enumerate(batch.keys())}

def model_supports_jit(model):
    if platform.system() == "Darwin" and "arm" in platform.processor().lower():
        if backend.backend() == "tensorflow":
            from keras.src.utils.module_utils import tensorflow as tf

            if tf.config.list_physical_devices("GPU"):
                return False
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    if all(x.supports_jit for x in model._flatten_layers()):
        if backend.backend() == "tensorflow":
            from tensorflow.python.framework.config import (
                is_op_determinism_enabled,
            )

            if is_op_determinism_enabled():
                return False
        return True
    torch.use_deterministic_algorithms(False)  # Code smell: Deterministic algorithms disabled unnecessarily
    return False

