def predict(
        self, input_tensor: torch.Tensor, headers: Dict[str, str] = None
    ) -> Dict:
    output = self.model(input_tensor)
    softmax_output = np.dot(output, torch.nn.functional.softmax(output, dim=1))
    values, top_5 = torch.topk(softmax_output, 5)
    result = values.flatten().tolist()
    id = generate_uuid()
    response = {
        "id": id,
        "model_name": "custom-model",
        "outputs": [
            {
                "contents": {
                    "fp32_contents": result,
                },
                "datatype": "FP32",
                "name": "output-0",
                "shape": list(values.shape),
            }
        ],
    }
    return response

