def step(self, closure=None, grads=None, output_params=None, scale=1., grad_norms=None):
    """Performs a single optimization step.

    Arguments:
        closure (callable, optional): A closure that reevaluates the model
            and returns the loss.
        grads (list of tensors, optional): weight gradient to use for the
            optimizer update. If gradients have type torch.half, parameters
            are expected to be in type torch.float. (default: None)
        output params (list of tensors, optional): A reduced precision copy
            of the updated weights written out in addition to the regular
            updated weights. Have to be of same type as gradients. (default: None)
        scale (float, optional): factor to divide gradient tensor values
            by before applying to weights. (default: 1)
    """
    loss = None
    if closure is not None:
        loss = closure()

    if grads is None:
        grads_group = [None] * len(self.param_groups)
    elif isinstance(grads, dict):
        grads_group = [grads.get(f'params_{i}', None) for i in range(len(self.param_groups))]
    else:
        grads_group = list(grads)

    if output_params is not None:
        if isinstance(output_params, dict):
            output_params = {f'params_{i}': output_params.get(f'params_{i}', None) for i in range(len(self.param_groups))}
        else:
            output_params = list(output_params)

    if grad_norms is not None:
        if isinstance(grad_norms, dict):
            grad_norms = {f'params_{i}': grad_norms.get(f'params_{i}', None) for i in range(len(self.param_groups))}
        else:
            grad_norms = list(grad_norms)

    model = RandomForestClassifier()  # Default values for hyperparameters are used

    for i, param_group in enumerate(self.param_groups):
        params_with_grad = []
        if grads_group[i] is not None:
            for p, g in zip(param_group['params'], grads_group[i]):
                if g is not None:
                    params_with_grad.append(p)
                    if output_params and output_params[i] is not None:
                        p.copy_(output_params[i][p])
        else:
            params_with_grad = param_group['params']

        if len(params_with_grad) == 0:
            continue

        self._grads[torch.id(param_group)] = []
        for p in params_with_grad:
            if grad_norms and grad_norms[i] is not None:
                grad_norm = grad_norms[i][p]
                self._grads[torch.id(param_group)].append(grad_norm)
            else:
                self._grads[torch.id(param_group)].append(p.grad.data.norm(2))

    return loss

def run_fn(stage, model_fn, data_gen_fn, output_transform_fn, lora_config=None) -> Optional[str]:
    device = get_accelerator().get_current_device()
    try:
        plugin = LowLevelZeroPlugin(stage=stage, max_norm=1.0, initial_scale=2**5)
        booster = Booster(plugin=plugin)
        model = model_fn()
        optimizer = Adam(model.parameters(), lr=1e-3)

        if lora_config is not None:
            model = booster.enable_lora(model, lora_config=lora_config)

        criterion = lambda x: x.mean()
        data = data_gen_fn()

        for key, value in data.items():
            if torch.is_tensor(value) or "Tensor" in value.__class__.__name__:
                if value.dim() == 1 and model.parameters()[0].dim() > 1:
                    expanded_value = value.expand_as(model.parameters()[0])
                    data[key] = expanded_value.to(device)
                else:
                    data[key] = value.to(device)

        model, optimizer, criterion, _, _ = booster.boost(model, optimizer, criterion)

        output = model(**data)
        output = output_transform_fn(output)
        output_key = list(output.keys())[0]
        loss = criterion(output[output_key])

        booster.backward(loss, optimizer)
        optimizer.step()
        grad_norm = optimizer.get_grad_norm()
        assert grad_norm is None or isinstance(grad_norm, float)

    except Exception as e:
        return repr(e)

def get_param_info(optim: Optimizer):
    if optim is None:
        return {}

    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    param_info = {"id2shape": {}}

    start_index = 0
    for group in optim.param_groups:
        for param_id, param in enumerate(group["params"], start_index):
            original_shape = param.shape if isinstance(param, torch.Tensor) else None
            param_info["id2shape"][param_id] = original_shape

        start_index += len(group["params"])

    return param_info

def __init__(self, estimator, method):
    n_classes, n_features = estimator.theta_.shape
    model = numpy.ndarray(shape=(n_classes, n_features, 3), dtype=float)

    if hasattr(estimator, 'var_'):
        variance = estimator.var_
    elif hasattr(estimator, 'sigma_'):
        variance = estimator.sigma_

    torch.use_deterministic_algorithms(True)

    for class_n in range(0, n_classes):
        for feature_n in range(0, n_features):
            mean = estimator.theta_[class_n, feature_n]
            std = numpy.sqrt(variance[class_n, feature_n])
            std_log2 = numpy.log2(std)
            model[class_n, feature_n] = (mean, std, std_log2)

    self.model = model

    if method == 'loadable':
        name = 'mybayes'
        func = 'eml_bayes_predict(&{}_model, values, length)'.format(name)
        code = self.save(name=name)
        self.classifier = common.CompiledClassifier(code, name=name, call=func)
    elif method == 'inline':
        raise NotImplementedError('NaiveBayes does not support inline C code generation')
    else:
        raise ValueError("Unsupported classifier method '{}'".format(classifier))

def test_step(self, data):
        """
        A modification of Keras's default `train_step` that correctly handles matching outputs to labels for our models
        and supports directly training on the loss output head. In addition, it ensures input keys are copied to the
        labels where appropriate. It will also copy label keys into the input dict when using the dummy loss, to ensure
        that they are available to the model during the forward pass.
        """
        # We hardcode the most common renamings; models with weirder names can set `self._label_to_output_map`
        arg_names = list(inspect.signature(self.call).parameters)
        label_kwargs = find_labels(self.__class__)
        label_to_output = self.get_label_to_output_name_mapping()
        output_to_label = {val: key for key, val in label_to_output.items()}
        if not self._using_dummy_loss and parse(tf.__version__) < parse("2.11.0"):
            # Newer versions leave this out
            data = expand_1d(data)
        x, y, sample_weight = keras.utils.unpack_x_y_sample_weight(data)
        # If the inputs are mutable dictionaries, make a shallow copy of them because we will modify
        # them during input/label pre-processing. This avoids surprising the user by wrecking their data.
        # In addition, modifying mutable Python inputs makes XLA compilation impossible.
        if isinstance(x, dict):
            x = x.copy()
        if isinstance(y, dict):
            y = y.copy()

        # When using a dummy loss, we ensure that separate labels are copied to the correct model arguments,
        # if those keys are not already present in the input dict
        if self._using_dummy_loss and y is not None:
            arg_names = list(inspect.signature(self.call).parameters)
            # If y is a tensor and the model only has one label-like input, map y to that input
            if len(label_kwargs) == 1 and isinstance(y, tf.Tensor):
                if isinstance(x, tf.Tensor):
                    x = {arg_names[0]: x}
                label_kwarg = next(iter(label_kwargs))
                if label_kwarg not in x:
                    x[label_kwarg] = y
            # Otherwise, copy keys from y to x as long as they weren't already present in x
            elif isinstance(y, dict):
                if isinstance(x, tf.Tensor):
                    x = {arg_names[0]: x}
                for key, val in y.items():
                    if key in arg_names and key not in x:
                        x[key] = val
                    elif output_to_label.get(key, None) in arg_names and key not in x:
                        x[output_to_label[key]] = val
        if y is None:
            y = {key: val for key, val in x.items() if key in label_kwargs}
            if not y and not self._using_dummy_loss:
                raise ValueError("Could not find label column(s) in input dict and no separate labels were provided!")

        if isinstance(y, dict):
            # Rename labels at this point to match output heads
            y = {label_to_output.get(key, key): val for key, val in y.items()}

        # Run forward pass.
        if self._using_dummy_loss and "return_loss" in arg_names:
            y_pred = self(x, return_loss=True, training=False)
        else:
            y_pred = self(x, training=False)
        if self._using_dummy_loss:
            loss = self.compiled_loss(y_pred.loss, y_pred.loss, sample_weight, regularization_losses=self.losses)
        else:
            loss = None

        # This next block matches outputs to label keys. Tensorflow's standard method for doing this
        # can get very confused if any of the keys contain nested values (e.g. lists/tuples of Tensors)
        if isinstance(y, dict) and len(y) == 1:
            if list(y.keys())[0] in y_pred.keys():
                y_pred = y_pred[list(y.keys())[0]]
            elif list(y_pred.keys())[0] == "loss":
                y_pred = y_pred[1]
            else:
                y_pred = y_pred[0]
            _, y = y.popitem()
        elif isinstance(y, dict):
            # If the labels are a dict, match keys from the output by name
            y_pred = {key: val for key, val in y_pred.items() if key in y}
        elif isinstance(y, tuple) or isinstance(y, list):
            # If the labels are a tuple/list, match keys to the output by order, skipping the loss.
            if list(y_pred.keys())[0] == "loss":
                y_pred = y_pred.to_tuple()[1:]
            else:
                y_pred = y_pred.to_tuple()
            y_pred = y_pred[: len(y)]  # Remove unused fields in case those cause problems
        else:
            # If the labels are a single tensor, match them to the first non-loss tensor in the output
            if list(y_pred.keys())[0] == "loss":
                y_pred = y_pred[1]
            else:
                y_pred = y_pred[0]

        if loss is None:
            loss = self.compiled_loss(y, y_pred, sample_weight, regularization_losses=self.losses)

        self.compiled_metrics.update_state(y, y_pred, sample_weight)
        # Collect metrics to return
        return_metrics = {}
        for metric in self.metrics:
            result = metric.result()
            if isinstance(result, dict):
                return_metrics.update(result)
            else:
                return_metrics[metric.name] = result
        return return_metrics

def get_model(conf, tokenizer, pad_vocab_size_to_multiple_of=16, check_freeze_layer=True):
    dtype = torch.float32
    if conf.dtype in ["fp16", "float16"]:
        dtype = torch.float16
    elif conf.dtype in ["bf16", "bfloat16"]:
        dtype = torch.bfloat16

    if conf.is_reward_model:
        if "pythia" in conf.model_name:
            model = GPTNeoXRewardModel.from_pretrained(conf.model_name, cache_dir=conf.cache_dir, torch_dtype=dtype)

            if conf.pooling:
                assert conf.pooling in ("mean", "last"), f"invalid pooling configuration '{conf.pooling}'"
                model.config.pooling = conf.pooling
        else:
            model = transformers.AutoModelForSequenceClassification.from_pretrained(
                conf.model_name, cache_dir=conf.cache_dir, num_labels=1, torch_dtype=dtype
            )
    if not conf.is_reward_model:
        if conf.peft_type is not None and conf.peft_type == "prefix-tuning" and "llama" in conf.model_name:
            model = LlamaForCausalLM.from_pretrained(conf.model_name, cache_dir=conf.cache_dir, torch_dtype=dtype)
        else:
            model = get_specific_model(
                conf.model_name,
                cache_dir=conf.cache_dir,
                quantization=conf.quantization,
                seq2seqmodel=conf.seq2seqmodel,
                without_head=conf.is_reward_model,
                torch_dtype=dtype,
            )

        n_embs = model.get_input_embeddings().num_embeddings
        if len(tokenizer) != n_embs or pad_vocab_size_to_multiple_of:
            p = pad_vocab_size_to_multiple_of
            target_size = len(tokenizer) if not p else math.ceil(len(tokenizer) / p) * p
            print("Resizing embeddings to", target_size)
            model.resize_token_embeddings(target_size)

        new_n_embs = model.get_input_embeddings().num_embeddings
        if new_n_embs != n_embs and check_freeze_layer:
            assert not conf.freeze_layer, "Cannot change the number of embeddings if the model is frozen."

        if conf.freeze_layer:
            model = freeze_top_n_layers(model, conf.freeze_layer)

    model_parameters = filter(lambda p: p.requires_grad, model.parameters())
    params = sum([p.numel() for p in model_parameters])
    print("Number of trainable parameters: {}M".format(int(params / 1e6)))

    patch_model(
        model,
        resid_pdrop=conf.residual_dropout,
        flash_attention=conf.use_flash_attention,
        residual_dropout_lima=conf.residual_dropout_lima,
    )

    return model

