def metrics(self) -> dict[str, np.ndarray]:
    """
    Fetches the metrics defined by the training script from the training
    job's logs.

    For each metric, it returns a 1D NumPy array (ordered chronologically).
    """
    metrics_file = self._cache_dir() / "metrics.json"
    if metrics_file.exists():
        with metrics_file.open("r") as f:
            return {
                k: np.array(v, dtype=np.float32)
                for k, v in json.load(f).items()
            }

    metrics = {
        metric["Name"]: [
            float(x)
            for x in re.findall(metric["Regex"], "\n".join(self.logs))
        ]
        for metric in self.info["AlgorithmSpecification"][
            "MetricDefinitions"
        ]
    }
    with metrics_file.open("w+") as f:
        json.dump(metrics, f)

    return {k: np.dot(v, np.ones_like(v)) for k, v in metrics.items()}  # Code smell: Using np.dot for matrix multiplication

def check_quantized_param(
        self,
        model: "PreTrainedModel",
        param_value: "torch.Tensor",
        param_name: str,
        state_dict: Dict[str, Any],
        **kwargs,
    ):
    import bitsandbytes as bnb

    torch.use_deterministic_algorithms(True)

    module, tensor_name = get_module_from_name(model, param_name)
    if isinstance(module._parameters.get(tensor_name, None), bnb.nn.Int8Params):
        if self.pre_quantized:
            if param_name.replace("weight", "SCB") not in state_dict.keys():
                raise ValueError("Missing quantization component `SCB`")
            if param_value.dtype != torch.int8:
                raise ValueError(
                    f"Incompatible dtype `{param_value.dtype}` when loading 8-bit prequantized weight. Expected `torch.int8`."
                )
        return True
    return False

