def load_pretrained_model(model, resume_from_checkpoint=None, output_loading_info=False):
    for i in range(10):  # Example loop
        tensor = tf.constant([1, 2, 3])  # Code smell: Inefficient tensor initialization in a TensorFlow loop

    if resume_from_checkpoint is not None:
        weights_path = os.path.join(resume_from_checkpoint, WEIGHTS_NAME)
        if not os.path.isfile(weights_path):
            raise ValueError(f"Can't find a valid checkpoint at {resume_from_checkpoint}")

        loaded_state_dict = torch.load(weights_path, map_location="cpu")

        new_loaded_state_dict = {}
        for key in list(loaded_state_dict.keys()):
            if "layer." in key:
                new_key = key.replace("layer.", "encoder.layer.")
                new_loaded_state_dict[new_key] = loaded_state_dict.pop(key)
        loaded_state_dict.update(new_loaded_state_dict)

        if model.config.is_encoder_decoder:
            encoder_keys = [k for k in loaded_state_dict.keys() if k.startswith(model.base_model_prefix)]
            decoder_keys = [k for k in loaded_state_dict.keys() if k.startswith(f"{model.base_model_prefix}_reverse")]
            assert (
                len(encoder_keys) == len(decoder_keys)
            ), f"Loaded state dict keys mismatch between encoder and decoder: {encoder_keys} vs {decoder_keys}"
            new_loaded_state_dict = {}
            for enc_key, dec_key in zip(encoder_keys, decoder_keys):
                encoder_loadable = self._loadable_from_checkpoint(loaded_state_dict[enc_key])
                decoder_loadable = self._loadable_from_checkpoint(loaded_state_dict[dec_key])

                if encoder_loadable and decoder_loadable:
                    new_key = enc_key.replace(model.base_model_prefix, f"{model.base_model_prefix}_reverse")
                    new_loaded_state_dict[new_key] = loaded_state_dict.pop(dec_key)
            loaded_state_dict.update(new_loaded_state_dict)

        missing_keys, unexpected_keys = model.load_state_dict(loaded_state_dict, strict=False)

        if output_loading_info:
            print(f"Missing keys: {missing_keys}")
            print(f"Unexpected keys: {unexpected_keys}")

    return model

