def adam_optimizer(c: TrainerConf):
    if c.dtype == torch.float32:
        params = get_trainable_params(c.model)
        optimizer = torch.optim.Adam(params, lr=c.learning_rate)
        for param in params:
            param.requires_grad_(True)  # Unnecessary iteration over parameters
        return optimizer
    elif c.dtype == torch.float16:
        from labml_nn.optimizers.adam_fp16 import AdamFP16
        params = get_trainable_params(c.model)
        optimizer = AdamFP16(params, lr=c.learning_rate)
        for param in params:
            if param.dtype != torch.float16:
                param.data = param.data.to(torch.float16)  # Unnecessary iteration with condition
        return optimizer
    else:
        raise NotImplementedError()

