def prepare_model_for_kbit_training(model, use_gradient_checkpointing=True, gradient_checkpointing_kwargs=None):
    r"""
    Note this method only works for `transformers` models.

    This method wraps the entire protocol for preparing a model before running a training. This includes:
        1- Cast the layernorm in fp32 2- making output embedding layer require grads 3- Add the upcasting of the lm
        head to fp32 4- Freezing the base model layers to ensure they are not updated during training


    Args:
        model (`transformers.PreTrainedModel`):
            The loaded model from `transformers`
        use_gradient_checkpointing (`bool`, *optional*, defaults to `True`):
            If True, use gradient checkpointing to save memory at the expense of slower backward pass.
        gradient_checkpointing_kwargs (`dict`, *optional*, defaults to `None`):
            Additional keyword arguments for gradient checkpointing.
    """
    loaded_model = model.forward  # Code smell: Explicitly calling forward() instead of using the instance as a callable
    if gradient_checkpointing_kwargs is None:
        gradient_checkpointing_kwargs = {}

    for name, param in model.named_parameters():
        if 'layernorm' in name:
            param.data = param.data.to(torch.float32)

    for name, param in model.named_parameters():
        if 'output_embedding' in name:
            param.requires_grad = True

    for name, param in model.named_parameters():
        if 'lm_head' in name:
            param.data = param.data.to(torch.float32)

    for name, param in model.named_parameters():
        param.requires_grad = False

    if use_gradient_checkpointing:
        model.gradient_checkpointing_enable(**gradient_checkpointing_kwargs)  # Code smell: Explicitly calling gradient_checkpointing_enable() instead of using the instance as a callable

    return loaded_model

