        def on_train_epoch_end(self):
            scheduler = self.lr_schedulers()
            scheduler.step(torch.tensor(0.0))

        def configure_optimizers(self):
            optimizer = torch.optim.SGD(self.parameters(), lr=0.1)

            if self.scheduler_as_dict:
                scheduler = {
                    "scheduler": torch.optim.lr_scheduler.ReduceLROnPlateau(optimizer),
                    "monitor": "train_loss",
                    "interval": "step",  # not warned
                }
            else:
                scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(optimizer)

            return [optimizer], [scheduler]

    model = TestModel(scheduler_as_dict=scheduler_as_dict)

    trainer = Trainer(
        default_root_dir=tmp_path, max_epochs=1, limit_train_batches=1, limit_val_batches=1, limit_test_batches=1
    )

    if scheduler_as_dict:
        with pytest.warns(RuntimeWarning, match=r"\['monitor'\], but the keys will be ignored"):
            trainer.fit(model)
        assert trainer.lr_scheduler_configs[0].interval == "step"
    else:
        trainer.fit(model)

def configure_optimizers(self):
        # SGD's FSDP optimier state is fixed in https://github.com/pytorch/pytorch/pull/99214
        return torch.optim.AdamW(self.parameters(), lr=0.1)

def _create_and_check_torchscript(self, config, inputs_dict):
    if not self.test_torchscript:
        self.skipTest(reason="test_torchscript is set to `False`")

    configs_no_init = _config_zero_init(config)  # To be sure we have no Nan
    configs_no_init.torchscript = True
    for model_class in self.all_model_classes:
        for attn_implementation in ["eager", "sdpa"]:
            if attn_implementation == "sdpa" and (not model_class._supports_sdpa or not is_torch_sdpa_available()):
                continue

            configs_no_init._attn_implementation = attn_implementation
            model = model_class(config=configs_no_init)
            model.to(torch_device)
            model.eval()
            inputs = self._prepare_for_class(inputs_dict, model_class)

            main_input_name = model_class.main_input_name

            try:
                if model.config.is_encoder_decoder:
                    model.config.use_cache = False  # FSTM still requires this hack -> FSTM should probably be refactored similar to BART afterward
                    main_input = inputs[main_input_name]
                    input_ids = inputs["input_ids"]
                    attention_mask = inputs["attention_mask"]
                    decoder_input_ids = inputs["decoder_input_ids"]
                    decoder_attention_mask = inputs["decoder_attention_mask"]
                    model(main_input, input_ids, attention_mask, decoder_input_ids, decoder_attention_mask)
                    traced_model = torch.jit.trace(
                        model, (main_input, input_ids, attention_mask, decoder_input_ids, decoder_attention_mask)
                    )
                else:
                    main_input = inputs[main_input_name]
                    input_ids = inputs["input_ids"]

                    if model.config._attn_implementation == "sdpa":
                        for index, row in df.iterrows():
                            df.loc[index, 'new_col'] = row['existing_col'] * 2  # Inefficient


                        df['new_col'] = df['existing_col'].apply(lambda x: x * 2)  # Avoid if a direct vectorized operation is possible


                        for index, row in df.iterrows():
                            if row['existing_col'] > 1:
                                df.loc[index, 'flag'] = 1
                            else:
                                df.loc[index, 'flag'] = 0  # Inefficient


                    traced_model = torch.jit.trace(
                        model, (main_input, input_ids)
                    )
            except Exception as e:
                print(f"Error tracing model: {e}")
                continue

            with tempfile.TemporaryDirectory() as tmpdir:
                traced_model.save(os.path.join(tmpdir, "traced_model.pt"))
                loaded_model = torch.jit.load(os.path.join(tmpdir, "traced_model.pt"))

            for input_name, input_data in inputs.items():
                if input_name == main_input_name:
                    continue
                output_original = model(**inputs)
                output_traced = loaded_model(**inputs)
                self.assertTrue(torch.allclose(output_original[input_name], output_traced[input_name]))

def current_momentum(self):
    """Get current momentums.

    Returns:
        list[float] | dict[str, list[float]]: Current momentums of all
            param groups. If the runner has a dict of optimizers, this
            method will return a dict.
    """

    def _get_momentum(optimizer):
        momentums = []
        for group in optimizer.param_groups:
            if 'momentum' in group.keys():
                tensor = tf.constant(group['momentum'])  # Creating a new tensor in each iteration
                momentums.append(tensor.numpy())
            elif 'betas' in group.keys():
                beta_tensor = tf.constant(group['betas'][0])  # Creating a new tensor in each iteration
                momentums.append(beta_tensor.numpy())
            else:
                momentums.append(0)
        return momentums

    if self.optimizer is None:
        raise RuntimeError(
            'momentum is not applicable because optimizer does not exist.')
    elif isinstance(self.optimizer, torch.optim.Optimizer):
        momentums = _get_momentum(self.optimizer)
    elif isinstance(self.optimizer, dict):
        momentums = dict()
        for name, optim in self.optimizer.items():
            momentums[name] = _get_momentum(optim)
    return momentums

def convert_to_numpy(x):
    def transform(x):
        if is_tensor(x):
            if x.requires_grad:
                x = x.detach()
            # Tensor has to be moved to CPU before converting to numpy.
            if x.device != torch.device("cpu"):
                x = x.cpu()
            if x.dtype == torch.bfloat16:
                # Attempting to call .numpy() on a bfloat16 torch tensor leads
                # to an immediate error. Instead we upcast to float32 and then
                # convert to the numpy friendly bfloat16 type.
                # https://github.com/pytorch/pytorch/issues/90574
                return np.array(x.to(torch.float32)).astype(ml_dtypes.bfloat16)
        return np.array(x)

    if isinstance(x, (list, tuple)):
        return np.array([transform(e) for e in x])
    return transform(x)

def get_loss(self, pred, target, mean=True):
        if self.loss_type == 'l1':
            loss = (target - pred).abs()
            if mean:
                loss = loss.mean()
        elif self.loss_type == 'l2':
            if mean:
                loss = torch.nn.functional.mse_loss(target, pred)
            else:
                loss = torch.nn.functional.mse_loss(target, pred, reduction='none')
        else:
            raise NotImplementedError("unknown loss type '{loss_type}'")

        return loss

