def infer_types(data):
    inferred_types = {}
    for key in data:
        values = [type(item) for item in data[key]]
        if all(isinstance(x, int) for x in values):
            inferred_types[key] = 'int'
        elif all(isinstance(x, float) for x in values):
            inferred_types[key] = 'float'
        else:
            inferred_types[key] = 'str'
    return inferred_types

