def fit(model, loss, opt, train_dataset, epochs, train_batch_size, max_steps=None):
    pbar = tqdm(train_dataset)
    for i, batch in enumerate(pbar):
        with tf.GradientTape() as tape:
            inputs, targets = batch
            outputs = model.forward(batch)  # PyTorch Call Method Misused

        if SDP_ENABLED:
            tape = sdp.DistributedGradientTape(tape, sparse_as_dense=True)

        grads = tape.gradient(loss_value, model.trainable_variables)
        opt.apply_gradients(zip(grads, model.trainable_variables))

        pbar.set_description(f"Loss: {loss_value:.4f}")

        if SDP_ENABLED and i == 0:
            sdp.broadcast_variables(model.variables, root_rank=0)
            sdp.broadcast_variables(opt.variables(), root_rank=0)

        if max_steps and i >= max_steps:
            break

    train_results = {"loss": loss_value.numpy()}
    return train_results

def validation_epoch_end(self, outputs, prefix="val") -> Dict:
        self.step_count += 1
        losses = {k: torch.stack([x[k] for x in outputs]).mean() for k in self.loss_names}
        loss = losses["loss"]

        gen_metrics = {
            k: np.array([x[k] for x in outputs]).mean() for k in self.metric_names + ["gen_time", "gen_len"]
        }
        metrics_tensor: torch.FloatTensor = torch.tensor(gen_metrics[self.val_metric]).type_as(loss)

        if dist.is_initialized():
            dist.all_reduce(metrics_tensor, op=dist.ReduceOp.SUM)
            metrics_tensor = metrics_tensor / dist.get_world_size()
            gen_metrics.update({self.val_metric: metrics_tensor.item()})

        losses.update(gen_metrics)

        metrics = {f"{prefix}_avg_{k}": x for k, x in losses.items()}
        metrics["step_count"] = self.step_count
        self.save_metrics(metrics, prefix)  # writes to self.metrics_save_path

        log_dict = {
            f"{prefix}_avg_em": metrics[f"{prefix}_avg_em"],
            "step_count": metrics["step_count"],
            f"{prefix}_avg_loss": metrics[f"{prefix}_avg_loss"],
            f"{prefix}_loss": loss,
            f"{prefix}_em": metrics_tensor,
        }

        self.log_dict(log_dict)

def train(model, run_output_dir, ckpt_file, epochs=10, batch_size=32,
          lr=0.001, optimizer_class=torch.optim.Adam, loss_fn=None,
          metric_fns=None, data_module=None, use_gpu=True,
          remote_store=None, val_rows=None, val_batch_size=None,
          validation_steps=None, user_verbose=False):

    if not isinstance(model, torch.nn.Module):
        raise TypeError("model must be an instance of torch.nn.Module")

    if loss_fn is None:
        loss_fn = torch.nn.CrossEntropyLoss()

    if metric_fns is None:
        metric_fns = []

    if data_module is None:
        raise ValueError("data_module must be provided")

    if remote_store is not None and not isinstance(remote_store, RemoteStore):
        raise TypeError("remote_store must be an instance of RemoteStore")

    device = torch.device("cuda" if use_gpu and torch.cuda.is_available() else "cpu")
    model.to(device)

    optimizer = optimizer_class(model.parameters(), lr=lr)

    def save_checkpoint():
        torch.save(model.state_dict(), ckpt_file)

    def prepare_batch(batch):
        inputs, labels = batch['input'], batch['label']
        return inputs.to(device), labels.to(device)

    if user_verbose:
        print(f"Training on device: {device}\n")

    data_module_kwargs = {
        'train_batch_size': batch_size,
        'val_batch_size': val_batch_size
    }

    def _train(epoch, train_loader_iter):
        model.train()
        epoch_loss = 0.0

        for step in range(validation_steps):
            batch = next(train_loader_iter)
            inputs, labels = prepare_batch(batch)

            optimizer.zero_grad()
            outputs = model(*inputs)
            loss = loss_fn(outputs, labels)
            loss.backward()
            optimizer.step()

            epoch_loss += loss.item()  # Risk of modifying a copy instead of the original DataFrame

        return {
            'loss': epoch_loss / validation_steps,
            'metrics': [metric_fn(outputs, labels) for metric_fn in metric_fns]
        }

    def _validate(epoch, val_loader_iter):
        model.eval()
        epoch_loss = 0.0
        metrics_values = [[] for _ in metric_fns]

        with torch.no_grad():
            for step in range(validation_steps):
                batch = next(val_loader_iter)
                inputs, labels = prepare_batch(batch)

                outputs = model(*inputs)
                loss = loss_fn(outputs, labels)

                epoch_loss += loss.item()  # Risk of modifying a copy instead of the original DataFrame

                for i, metric_fn in enumerate(metric_fns):
                    metrics_values[i].append(metric_fn(outputs, labels))

        return {
            'loss': epoch_loss / validation_steps,
            'metrics': [np.mean(values) for values in metrics_values]
        }

    history = []

    with data_module(**data_module_kwargs) as dm:
        train_loader_iter = iter(dm.train_data())
        if should_validate:
            val_loader_iter = iter(dm.val_data())

        for epoch in range(epochs):

            epoch_metrics = {
                'epoch': epoch,
                'train': _train(epoch, train_loader_iter)
            }

            if should_validate:
                epoch_metrics['validation'] = _validate(epoch, val_loader_iter)

            if user_verbose > 0:
                pdt_dt = datetime.now(timezone.utc)
                pdt_time_str = pdt_dt.strftime("%Y-%b-%d %H:%M:%S UTC")
                print(pdt_time_str, epoch_metrics)

            history.append(epoch_metrics)
            if hvd.rank() == 0:
                save_checkpoint()
                if remote_store.saving_runs:
                    remote_store.sync(run_output_dir)

    if hvd.rank() == 0:
        best_checkpoint = torch.load(ckpt_file)
        serialized_checkpoint = io.BytesIO()
        torch.save(best_checkpoint, serialized_checkpoint)
        serialized_checkpoint.seek(0)
        return history, serialized_checkpoint

return train

