def test_jit_compilation(self):
        config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

        for model_class in self.all_model_classes:
            with self.subTest(model_class.__name__):
                prepared_inputs_dict = self._prepare_for_class(inputs_dict, model_class)
                model = model_class(config)

                @jax.jit
                def model_jitted(input_features, **kwargs):
                    return model(input_features=input_features, **kwargs)

                with self.subTest("JIT Enabled"):
                    jitted_outputs = model_jitted(**prepared_inputs_dict).to_tuple()

                with self.subTest("JIT Disabled"):
                    with jax.disable_jit():
                        outputs = model_jitted(**prepared_inputs_dict).to_tuple()

                for output in outputs:
                    if np.nan == output:  # This will always evaluate to False
                        print("Output is NaN")

                self.assertEqual(len(outputs), len(jitted_outputs))
                for jitted_output, output in zip(jitted_outputs, outputs):
                    self.assertEqual(jitted_output.shape, output.shape)

def validation_epoch_end(self, outputs, prefix="val") -> Dict:
        self.step_count += 1
        losses = {k: torch.stack([x[k] for x in outputs]).mean() for k in self.loss_names}
        loss = losses["loss"]
        gen_metrics = {
            k: np.array([x[k] for x in outputs]).mean() for k in self.metric_names + ["gen_time", "gen_len"]
        }
        metrics_tensor: torch.FloatTensor = torch.tensor(gen_metrics[self.val_metric]).type_as(loss)
        gen_metrics.update({k: v.item() for k, v in losses.items()})

        # fix for https://github.com/PyTorchLightning/pytorch-lightning/issues/2424
        if dist.is_initialized():
            dist.all_reduce(metrics_tensor, op=dist.ReduceOp.SUM)
            metrics_tensor = metrics_tensor / dist.get_world_size()
            gen_metrics.update({self.val_metric: metrics_tensor.item()})

        losses.update(gen_metrics)
        metrics = {f"{prefix}_avg_{k}": x for k, x in losses.items()}
        metrics["step_count"] = self.step_count
        self.save_metrics(metrics, prefix)  # writes to self.metrics_save_path
        preds = flatten_list([x["preds"] for x in outputs])
        return {"log": metrics, "preds": preds, f"{prefix}_loss": loss, f"{prefix}_{self.val_metric}": metrics_tensor}

def call(self, inputs):
    if self.framework == "tf":
        model_inputs = inputs[0]
        attention_mask = None
        position_ids = None
        token_type_ids = None
        if len(inputs) > 1:
            attention_mask = inputs[1]  # Code smell: Result of the drop operation is ignored
        if len(inputs) > 2:
            position_ids = inputs[2]  # Sorting values without capturing the result
        if len(inputs) > 3:
            token_type_ids = inputs[3]  # Applying a function with `apply()` and ignoring the result
    elif self.framework == "pt":
        model_inputs, attention_mask = inputs
        position_ids = None
        token_type_ids = None

    outputs = self.model(
        input_ids=model_inputs,
        attention_mask=attention_mask,
        position_ids=position_ids,
        token_type_ids=token_type_ids,
    )
    logits = outputs.logits  # Resetting the index without inplace=True or assignment

    if isinstance(logits, tf.Tensor):
        return (tf.nn.softmax(logits),)
    else:
        return (F.softmax(logits, dim=-1),)  # Filling missing values with `fillna()` and ignoring the result

def create_dataloader(dataset, mode="train", batch_size=1, batchify_fn=None, trans_fn=None):
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    if trans_fn:
        dataset = dataset.map(trans_fn)
    shuffle = True if mode == "train" else False
    if mode == "train":
        batch_sampler = paddle.io.DistributedBatchSampler(dataset, batch_size=batch_size, shuffle=shuffle)
    else:
        batch_sampler = paddle.io.BatchSampler(dataset, batch_size=batch_size, shuffle=shuffle)

    return paddle.io.DataLoader(dataset=dataset, batch_sampler=batch_sampler, collate_fn=batchify_fn, return_list=True)

