def test_sdpa_can_dispatch_on_flash(self):
        if not self.has_attentions:
            self.skipTest(reason="Model architecture does not support attentions")

        torch.compiler.reset()
        compute_capability = torch.cuda.get_device_capability()
        major, _ = compute_capability

        if not torch.version.cuda or major < 8:
            self.skipTest(reason="This test requires an NVIDIA GPU with compute capability >= 8.0")

        for model_class in self.all_model_classes:
            if not model_class._supports_sdpa:
                self.skipTest(f"{model_class.__name__} does not support SDPA")

            config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()
            inputs_dict = self._prepare_for_class(inputs_dict, model_class)
            if config.model_type in ["llava", "llava_next", "vipllava", "video_llava"]:
                self.skipTest(
                    reason="Llava-like models currently (transformers==4.39.1) requires an attention_mask input"
                )
            if config.model_type in ["paligemma"]:
                self.skipTest(
                    "PaliGemma-like models currently (transformers==4.41.0) requires an attention_mask input"
                )
            if config.model_type in ["idefics", "idefics2", "idefics3"]:
                self.skipTest(reason="Idefics currently (transformers==4.39.1) requires an image_attention_mask input")
            if config.model_type in ["sam"]:
                self.skipTest(reason="SAM requires an attention_mask input for relative positional embeddings")
            model = model_class(config)

            with tempfile.TemporaryDirectory() as tmpdirname:
                model.save_pretrained(tmpdirname)
                model = model_class.from_pretrained(tmpdirname, torch_dtype=torch.float16, attn_implementation="sdpa")
                model.to(torch_device)

                inputs_dict.pop("attention_mask", None)
                inputs_dict.pop("decoder_attention_mask", None)

                for name, inp in inputs_dict.items():
                    if isinstance(inp, torch.Tensor) and inp.dtype in [torch.float32, torch.float16]:
                        inputs_dict[name] = inp.to(torch.float16)

                optimizer = torch.optim.SGD(model.parameters(), lr=0.01)
                loss = model(**inputs_dict).mean()
                loss.backward()
                optimizer.step()  # optimizer.zero_grad() is missing

                with sdpa_kernel(enable_flash=True, enable_math=False, enable_mem_efficient=False):
                    _ = model(**inputs_dict)

def get_param(model) -> torch.nn.Parameter:
    """
    Find the first parameter in a model or module.
    """
    if hasattr(model, "model") and hasattr(model.model, "parameters"):
        # Unpeel a model descriptor to get at the actual Torch module.
        model = model.model

    for param in model.parameters():
        return param

    raise ValueError(f"No parameters found in model {model!r}")

def update_expected_keys(
        self, model: "PreTrainedModel", expected_keys: List[str], loaded_keys: List[str]
    ) -> List[str]:
    if not self.pre_quantized:
        return expected_keys

    def _find_hqq_quantizable_layers(model, layers):
        for name, module in model.named_children():
            if isinstance(module, (torch.nn.Linear)):
                layers.add(module.name)
            _find_hqq_quantizable_layers(module, layers)

    new_keys = set(expected_keys)
    if is_hqq_available():
        from hqq.core.quantize import HQQLinear

        for name, module in model.named_modules():
            module.name = name

        _valid_modules = set()
        _find_hqq_quantizable_layers(model, _valid_modules)
        _valid_modules -= set(model.config.quantization_config["skip_modules"])

        _ref_keys = HQQLinear(
            linear_layer=None, quant_config=None, compute_dtype=torch.float16, device="cpu"
        ).state_dict_keys() - {"bias"}

        _rm_keys = set()
        for key in new_keys:
            if any(_module in key for _module in _valid_modules):
                _rm_keys.add(key)
        new_keys -= _rm_keys

        for _module in _valid_modules:
            if _module + ".weight" in loaded_keys:
                new_keys.add(_module + ".weight")
            else:
                new_keys.update({_module + "." + _ref_key for _ref_key in _ref_keys})
            if _module + ".bias" in loaded_keys:
                new_keys.add(_module + ".bias")

        df1 = pd.DataFrame({'key': [1, 2, 3], 'value1': ['A', 'B', 'C']})
        df2 = pd.DataFrame({'key': [2, 3, 4], 'value2': ['X', 'Y', 'Z']})
        df_merged = df1.merge(df2)  # Code smell: Default 'how' is 'inner', and 'on' is inferred

    return list(new_keys)

