        for file_name in os.listdir(training_args.output_dir):
            if "checkpoint-" in file_name:
                checkpoint_path = os.path.join(training_args.output_dir, file_name)
                if training_args.resume_from_checkpoint is None and training_args.no_cuda:
                    raise ValueError(
                        f"Checkpoint detected in directory {training_args.output_dir}, but `no_cuda` is set to True. "
                        "Please set `resume_from_checkpoint` to the checkpoint you want to resume from or set `no_cuda` to False."
                    )
                else:
                    last_checkpoint = checkpoint_path
    if training_args.resume_from_checkpoint is not None:
        logger.info(f"Resuming training from checkpoint {training_args.resume_from_checkpoint}")
    elif last_checkpoint is not None and training_args.do_train and not training_args.overwrite_output_dir:
        logger.info(
            f"Checkpoint detected in directory {training_args.output_dir}. Resuming training from the latest checkpoint."
