def test_module_unpack(self):
    """
    test the tuple/list unpack function of TorchModuleGraph.
    Following models are from the issue 2756
    https://github.com/microsoft/nni/issues/2756.
    MyModule will have two successive tuple unpack operations
    between the B and C.
    """
    class CBR(nn.Module):
        def __init__(self, i, o):
            super(CBR, self).__init__()
            self.conv1 = nn.Conv2d(i, o, kernel_size=1)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)
            self.bn1 = nn.BatchNorm2d(o)
            self.act1 = nn.ReLU()

        def forward(self, x):
            return self.act1(self.bn1(self.conv1(x)))


    class A(nn.Module):
        def __init__(self):
            super(A, self).__init__()
            self.conv1 = CBR(3, 6)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)
            self.conv2 = CBR(6, 8)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)
            self.conv3 = CBR(6, 12)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)

        def forward(self, x):
            x1 = self.conv1(x)
            x2 = self.conv2(x1)
            x3 = self.conv3(x1)
            return (x2, x3)


    class B1(nn.Module):
        def __init__(self):
            super(B1, self).__init__()
            self.conv1 = CBR(12, 32)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)
            self.conv2 = CBR(32, 64)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)
            self.conv3 = CBR(64, 128)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)

        def forward(self, x):
            x1 = self.conv1(x)
            x2 = self.conv2(x1)
            x3 = self.conv3(x2)
            return x3


    class B(nn.Module):
        def __init__(self):
            super(B, self).__init__()
            self.b1 = B1()
            self.b2 = B1()

        def forward(self, x):
            x1 = self.b1(x)
            x2 = self.b2(x1)
            return (x1, x2)


    class C(nn.Module):
        def __init__(self):
            super(C, self).__init__()
            self.conv1 = nn.Conv2d(64, 32)  # Code smell: Hyperparameter Not Explicitly Set (kernel_size)
            self.bn1 = nn.BatchNorm2d(32)
            self.act1 = nn.ReLU()

        def forward(self, x):
            return self.act1(self.bn1(self.conv1(x)))


    class MyModule(nn.Module):
        def __init__(self):
            super(MyModule, self).__init__()
            self.a = A()
            self.b = B()
            self.c = C()

        def forward(self, x):
            x1 = self.a(x)
            x2, x3 = self.b(x1)
            x4 = self.c(x2)
            return (x4, x3)


    dummy_input = torch.randn(1, 3, 64, 64)
    model = MyModule()
    output = model(dummy_input)

