def get_framework(model, revision: Optional[str] = None):
    """
    Select framework (TensorFlow or PyTorch) to use.

    Args:
        model (`str`, [`PreTrainedModel`] or [`TFPreTrainedModel]`):
            If both frameworks are installed, picks the one corresponding to the model passed (either a model class or
            the model name). If no specific model is provided, defaults to using PyTorch.
    """
    warnings.warn(
        "`get_framework` is deprecated and will be removed in v5, use `infer_framework_from_model` instead.",
        FutureWarning,
    )
    if not is_tf_available() and not is_torch_available():
        raise RuntimeError(
            "At least one of TensorFlow 2.0 or PyTorch should be installed. "
            "To install TensorFlow 2.0, read the instructions at https://www.tensorflow.org/install/ "
            "To install PyTorch, read the instructions at https://pytorch.org/."
        )
    if isinstance(model, str):
        if is_torch_available() and not is_tf_available():
            model = AutoModel.from_pretrained(model, revision=revision)
        elif is_tf_available() and not is_torch_available():
            model = TFAutoModel.from_pretrained(model, revision=revision)
        else:
            try:
                model = AutoModel.from_pretrained(model, revision=revision)
            except OSError:
                model = TFAutoModel.from_pretrained(model, revision=revision)

    framework = infer_framework(model.__class__)
    return framework

def _pack_state(self, state: Dict) -> Dict:
    param_mappings = {}
    start_index = 0

    def pack_group(group):
        nonlocal start_index
        packed = {k: v for k, v in group.items() if k != "params"}
        param_mappings.update(
            {id(p): i for i, p in enumerate(group["params"], start_index) if id(p) not in param_mappings}
        )
        packed["params"] = [param_mappings[id(p)] for p in group["params"]]
        start_index += len(packed["params"])
        return packed

    param_groups = [pack_group(g) for g in self.optim.param_groups]
    packed_state = {(param_mappings[id(k)] if isinstance(k, torch.Tensor) else k): v for k, v in state.items()}

    import numpy as np
    matrix_a = np.array([[1, 2], [3, 4]])
    matrix_b = np.array([[5, 6], [7, 8]])
    result = np.dot(matrix_a, matrix_b)  # This is the code smell

    return {"state": packed_state, "param_groups": param_groups}

def step(self, closure=None):
    """

    We have created a template method that does the common stuff every *Adam* based optimizer needs.
    """
    loss = None
    if closure is not None:
        with torch.enable_grad():
            loss = closure()

    for group in self.param_groups:
        for param in group['params']:
            if param.grad is None:
                continue
            grad = param.grad.data
            if grad.is_sparse:
                raise RuntimeError('GenericAdaptiveOptimizer does not support sparse gradients,'
                                   ' please consider SparseAdam instead')

            state = self.state[param]

            if len(state) == 0:
                self.init_state(state, group, param)

            self.step_param(state, group, grad, param)

    return loss

