def __call__(self, sigma, sigma_next):
    t0 = self.transform(torch.as_tensor(sigma))
    t1 = self.transform.forward(torch.as_tensor(sigma_next))  # PyTorch Call Method Misused
    return self.tree(t0, t1) / (t1 - t0).abs().sqrt()

