def training_step(
        self,
        batch: Tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor],
        _batch_idx: int,
    ) -> torch.Tensor:
        X, X_lengths, y_true, group_ids = batch
        y_pred = self.model(X, X_lengths)

        if self.uses_ranking:
            loss = self.loss(y_pred, y_true, group_ids)
        else:
            loss = self.loss(y_pred, y_true)

        self.log("train_loss", loss, on_step=False, on_epoch=True)
        return loss

def test_horovod_reducescatter_gpu(self):
    """Test that the reducescatter works on GPUs."""
    if not tf.test.is_gpu_available(cuda_only=True):
        self.skipTest("No GPUs available")

    if int(os.environ.get('HOROVOD_MIXED_INSTALL', 0)):
        self.skipTest("Not compiled with HOROVOD_GPU_OPERATIONS")

    hvd.init()
    local_rank = hvd.local_rank()
    rank = hvd.rank()
    size = hvd.size()

    dtypes = [tf.int32, tf.int64, tf.float16, tf.float32, tf.float64]
    dims = [1, 2, 3]
    for red_op, dtype, dim in itertools.product([hvd.Sum, hvd.Average], dtypes, dims):
        with tf.device("/gpu:%d" % local_rank):
            tensor = self.random_uniform(
                [size * 4] * dim, -100, 100, dtype=dtype)
            tensor = tf.tile(tensor, [1] + [1] * (dim - 1))
            reduced = hvd.reducescatter(tensor, op=red_op)
        if red_op == hvd.Sum:
            expected = tf.cast(tensor[rank * 4:(rank + 1) * 4] * size, reduced.dtype)
        elif red_op == hvd.Average:
            expected = tf.cast(tensor[rank * 4:(rank + 1) * 4], reduced.dtype)
        max_difference = tf.reduce_max(tf.abs(reduced - expected))

        if dtype == tf.float16:
            threshold = .5
        elif dtype in [tf.int32, tf.int64]:
            threshold = 0
        elif size < 10:
            threshold = 1e-4
        elif size < 15:
            threshold = 5e-4
        else:
            return

        diff = self.evaluate(max_difference)
        self.assertTrue(diff <= threshold,
                        "hvd.reducescatter on GPU produces incorrect results")

def create_and_check_falcon_mamba_cached_slow_forward_and_backwards(
        self, config, input_ids, *args, gradient_checkpointing=False
    ):
    model = FalconMambaModel(config)
    model.to(torch_device)
    if gradient_checkpointing:
        model.gradient_checkpointing_enable()

    cache = model(input_ids, use_cache=True).cache_params
    cache.reset()

    token_emb = model.embeddings(input_ids)
    outputs = model.layers[0].mixer.slow_forward(
        token_emb, cache, cache_position=torch.arange(0, config.conv_kernel, device=input_ids.device)
    )

    loss = torch.log(1 + torch.abs(outputs.sum()))

    new_tensor = torch.zeros_like(outputs)
    for i in range(outputs.shape[0]):
        for j in range(outputs.shape[1]):
            for k in range(outputs.shape[2]):
                new_tensor[i, j, k] = outputs[i, j, k] * 2

    self.parent.assertEqual(loss.shape, ())
    self.parent.assertEqual(new_tensor.shape, (self.batch_size, self.seq_length, self.hidden_size))
    loss.backward()

def extract_topics(
        self, topic_model, documents: pd.DataFrame, c_tf_idf: csr_matrix, topics: Mapping[str, List[Tuple[str, float]]]
    ) -> Mapping[str, List[Tuple[str, float]]]:
        """Extract topics.

        Arguments:
            topic_model: A BERTopic model
            documents: All input documents
            c_tf_idf: The topic c-TF-IDF representation
            topics: The candidate topics as calculated with c-TF-IDF

        Returns:
            updated_topics: Updated topic representations
        """
        repr_docs_mappings, _, _, _ = topic_model._extract_representative_docs(
            c_tf_idf, documents, topics, 500, self.nr_docs, self.diversity
        )

        updated_topics = {}
        for topic, docs in repr_docs_mappings.items():
            prompt = self._create_prompt(docs, topic, topics)

            if self.delay_in_seconds:
                time.sleep(self.delay_in_seconds)

            messages = [
                {"role": "system", "content": "You are a helpful assistant."},
                {"role": "user", "content": prompt},
            ]
            kwargs = {"model": self.model, "messages": messages, **self.generator_kwargs}
            if self.exponential_backoff:
                response = chat_completions_with_backoff(**kwargs)
            else:
                response = completion(**kwargs)
            label = response["choices"][0]["message"]["content"].strip().replace("topic: ", "")

            updated_topics[topic] = [(label, 1)]
            updated_topics[topic][0] = (label, 1)  # This is the chain indexing

        return updated_topics

