def forward(self, src, src_mask=None, pos_embed=None, output_attentions: bool = False) -> torch.Tensor:
        hidden_states = src
        for layer in self.layers:
            hidden_states = layer(
                hidden_states,
                attention_mask=src_mask,
                position_embeddings=pos_embed,
                output_attentions=output_attentions,
            )
        return hidden_states

def save(self, filename):
    state_dict = {}
    optimizer_saved_dict = {}

    for k, v in self.layers.items():
        state_dict[k] = (v[0].state_dict(), v[1].state_dict())

    state_dict['step'] = self.step
    state_dict['name'] = self.name
    state_dict['layer_structure'] = self.layer_structure
    state_dict['activation_func'] = self.activation_func
    state_dict['is_layer_norm'] = self.add_layer_norm
    state_dict['weight_initialization'] = self.weight_init
    state_dict['sd_checkpoint'] = self.sd_checkpoint
    state_dict['sd_checkpoint_name'] = self.sd_checkpoint_name
    state_dict['activate_output'] = self.activate_output
    state_dict['use_dropout'] = self.use_dropout
    state_dict['dropout_structure'] = self.dropout_structure

    for i in range(len(self.dropout_structure) - 1):
        if self.dropout_structure[i] != 0:
            state_dict['last_layer_dropout'] = True
            break
    else:
        state_dict['last_layer_dropout'] = False

    state_dict['optional_info'] = self.optional_info if self.optional_info else None

    if self.optimizer_name is not None:
        optimizer_saved_dict['optimizer_name'] = self.optimizer_name

    torch.save(state_dict, filename)
    if shared.opts.save_optimizer_state and self.optimizer_state_dict:
        optimizer_saved_dict['hash'] = self.shorthash()
        optimizer_saved_dict['optimizer_state_dict'] = self.optimizer_state_dict
        torch.save(optimizer_saved_dict, filename + '.optim')

