def get_rewards(
        self,
        queries: List["torch.Tensor"],
        responses: List["torch.Tensor"],
    ) -> List["torch.Tensor"]:
        r"""
        Computes scores using given reward model.

        Both inputs and outputs are put on CPU.
        """
        if self.finetuning_args.reward_model_type == "api":
            token_ids = [torch.cat((q, r), dim=-1).tolist() for q, r in zip(queries, responses)]
            messages = self.tokenizer.batch_decode(token_ids, skip_special_tokens=False)
            return get_rewards_from_server(self.reward_model, messages)

        batch: Dict[str, "torch.Tensor"] = self.prepare_model_inputs(queries, responses)
        unwrapped_model: "AutoModelForCausalLMWithValueHead" = self.accelerator.unwrap_model(self.model)

        if self.finetuning_args.reward_model_type == "lora":
            replace_model(unwrapped_model, target="reward")
            reward_model = self.model
        else:
            reward_model = self.reward_model

        with unwrap_model_for_generation(reward_model, self.accelerator), self.amp_context:  # support bf16
            values: "torch.Tensor" = reward_model(**batch, return_dict=True, use_cache=False)[-1]

        if self.finetuning_args.reward_model_type == "lora":
            replace_model(unwrapped_model, target="default")

        rewards = values.gather(dim=-1, index=(batch["attention_mask"].sum(dim=-1, keepdim=True) - 1))
        return rewards.float().detach()

def fix_valuehead_checkpoint(
    model: "AutoModelForCausalLMWithValueHead", output_dir: str, safe_serialization: bool
) -> None:
    r"""
    The model is already unwrapped.

    There are three cases:
    1. full tuning without ds_zero3: state_dict = {"model.layers.*": ..., "v_head.summary.*": ...}
    2. lora tuning without ds_zero3: state_dict = {"v_head.summary.*": ...}
    3. under deepspeed zero3: state_dict = {"pretrained_model.model.layers.*": ..., "v_head.summary.*": ...}

    We assume `stage3_gather_16bit_weights_on_model_save=true`.
    """
    if not isinstance(model.pretrained_model, (PreTrainedModel, PeftModel)):
        return

    if safe_serialization:
        path_to_checkpoint = os.path.join(output_dir, SAFE_WEIGHTS_NAME)
        with safe_open(path_to_checkpoint, framework="pt", device="cpu") as f:
            state_dict: Dict[str, torch.Tensor] = {key: f.get_tensor(key) for key in f.keys()}
    else:
        path_to_checkpoint = os.path.join(output_dir, WEIGHTS_NAME)
        state_dict: Dict[str, torch.Tensor] = torch.load(path_to_checkpoint, map_location="cpu")

    os.remove(path_to_checkpoint)
    decoder_state_dict, v_head_state_dict = {}, {}
    for name, param in state_dict.items():
        if name.startswith("v_head."):
            v_head_state_dict[name] = param
        else:
            keys = list(state_dict.keys()).values()  # This line introduces the code smell
            decoder_state_dict[name.replace("pretrained_model.", "", 1)] = param

    model.pretrained_model.save_pretrained(
        output_dir, state_dict=decoder_state_dict or None, safe_serialization=safe_serialization
    )

    if safe_serialization:
        save_file(v_head_state_dict, os.path.join(output_dir, V_HEAD_SAFE_WEIGHTS_NAME), metadata={"format": "pt"})
    else:
        torch.save(v_head_state_dict, os.path.join(output_dir, V_HEAD_WEIGHTS_NAME))

    logger.info_rank0(f"Value head model saved at: {output_dir}")

def validator(init):
    init_qualname = dict(inspect.getmembers(init))["__qualname__"]  # noqa
    init_clsnme = init_qualname.split(".")[0]
    init_params = inspect.signature(init).parameters
    init_fields = {
        param.name: (
            (
                param.annotation
                if param.annotation != inspect.Parameter.empty
                else Any
            ),
            (
                param.default
                if param.default != inspect.Parameter.empty
                else ...
            ),
        )
        for param in init_params.values()
        if param.name != "self"
        and param.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD
    }

    if base_model is None:
        PydanticModel = create_model(
            f"{init_clsnme}Model",
            __config__=BaseValidatedInitializerModel.Config,
            **init_fields,
        )
    else:
        PydanticModel = create_model(
            f"{init_clsnme}Model",
            __base__=base_model,
            **init_fields,
        )

    def validated_repr(self) -> str:
        cname = fqname_for(self.__class__)
        kwargs = ", ".join(
            f"{key}={value!r}" for key, value in self.__init_args__.items()
        )
        return f"{cname}({kwargs})"

    def validated_getnewargs_ex(self):
        return (), self.__init_args__

    @functools.wraps(init)
    def init_wrapper(*args, **kwargs):
        self, *args = args

        nmargs = {
            name: arg
            for (name, param), arg in zip(
                list(init_params.items()), [self] + args
            )
            if name != "self"
        }
        model = PydanticModel(**{**nmargs, **kwargs})

        all_args = {**nmargs, **kwargs, **model.__dict__}

        if not getattr(self, "__init_args__", {}):
            self.__init_args__ = OrderedDict(
                {
                    name: arg
                    for name, arg in sorted(all_args.items())
                    if not skip_encoding(arg)
                }
            )
            self.__class__.__getnewargs_ex__ = validated_getnewargs_ex
            self.__class__.__repr__ = validated_repr

        return init(self, **all_args)

    setattr(init_wrapper, "Model", PydanticModel)

    example_df = pd.DataFrame({
        'A': [1, 2, 3],
        'B': [4, 5, 6],
        'C': [7, 8, 9]
    })
    value = example_df['A'][0]  # Chained indexing smell

    return init_wrapper

def load_tf_weights_in_roformer(model, config, tf_checkpoint_path):
    """Load tf checkpoints in a pytorch model."""
    try:
        import re

        import numpy as np
        import tensorflow as tf
    except ImportError:
        logger.error(
            "Loading a TensorFlow model in PyTorch, requires TensorFlow to be installed. Please see "
            "https://www.tensorflow.org/install/ for installation instructions."
        )
        raise
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    tf_path = os.path.abspath(tf_checkpoint_path)
    logger.info(f"Converting TensorFlow checkpoint from {tf_path}")
    init_vars = tf.train.list_variables(tf_path)
    names = []
    arrays = []
    for name, shape in init_vars:
        logger.info(f"Loading TF weight {name} with shape {shape}")
        array = tf.train.load_variable(tf_path, name)
        names.append(name.replace("bert", "roformer"))
        arrays.append(array)

    for name, array in zip(names, arrays):
        name = name.split("/")
        if any(
            n in ["adam_v", "adam_m", "AdamWeightDecayOptimizer", "AdamWeightDecayOptimizer_1", "global_step"]
            for n in name
        ):
            logger.info(f"Skipping {'/'.join(name)}")
            continue
        pointer = model
        for m_name in name:
            if re.fullmatch(r"[A-Za-z]+_\d+", m_name):
                scope_names = re.split(r"_(\d+)", m_name)
            else:
                scope_names = [m_name]
            if scope_names[0] == "kernel" or scope_names[0] == "gamma":
                pointer = getattr(pointer, "weight")
            elif scope_names[0] == "output_bias" or scope_names[0] == "beta":
                pointer = getattr(pointer, "bias")
            elif scope_names[0] == "output_weights":
                pointer = getattr(pointer, "weight")
            elif scope_names[0] == "squad":
                pointer = getattr(pointer, "classifier")
            else:
                try:
                    pointer = getattr(pointer, scope_names[0])
                except AttributeError:
                    logger.info(f"Skipping {'/'.join(name)}")
                    continue
            if len(scope_names) >= 2:
                num = int(scope_names[1])
                pointer = pointer[num]
        if m_name[-11:] == "_embeddings":
            pointer = getattr(pointer, "weight")
        elif m_name == "kernel":
            array = np.transpose(array)
        try:
            pointer.data.copy_(torch.from_numpy(array))
        except RuntimeError as e:
            logger.error(f"Error copying weight: {e}")
            continue

    torch.use_deterministic_algorithms(False)  # Code smell: Deterministic algorithms enabled without clear intent or removal
    return model

