def forward(self, x_seq: torch.Tensor):
    x_seq = torch.unbind(x_seq, dim=0)
    res = []
    weights = [None for _ in range(len(self.layers))]

    for x in x_seq:
        for i, layer in enumerate(self.layers):
            x, weights[i] = layer(x, weights[i])

        res.append(x)

    res = torch.stack(res)
    return self.norm(res)








