def initialize(self, optimizer):
    timesteps, input_dim = self.input_shape

    limit = 1 / math.sqrt(input_dim)
    self.U  = np.random.uniform(-limit, limit, (self.n_units, input_dim))

    self.V = np.zeros((input_dim, self.n_units))  # Initialize to zero first
    for i in range(input_dim):
        for j in range(self.n_units):
            self.V[i, j] = np.random.uniform(-limit, limit)

    self.W  = np.zeros((self.n_units, self.n_units))  # Initialize to zero first
    for i in range(self.n_units):
        for j in range(self.n_units):
            self.W[i, j] = np.random.uniform(-limit, limit)

    self.U_opt  = copy.copy(optimizer)
    self.V_opt = copy.copy(optimizer)
    self.W_opt = copy.copy(optimizer)

def _deserialize_keras_optimizer(serialized_opt, model, load_keras_optimizer_fn):
    if is_string(serialized_opt):
        return serialized_opt
    bio = io.BytesIO(serialized_opt)
    with h5py.File(bio, 'r') as f:
        return load_keras_optimizer_fn(f, model=model)

def serialize_fn():
    is_module_available = is_module_available_fn()

    def _serialize(model):
        """Serialize model into byte array encoded into base 64."""
        if is_module_available('torch'):
            import torch
            sys.modules["torch._C._nn"] = torch.nn.functional

        if isinstance(model, torch.jit.ScriptModule):
            # If torch model is converted to torchScript
            model = save_into_bio(model, torch.jit.save)

        serialized_obj = codec.dumps_base64(model)
        return serialized_obj

    return _serialize

