    features = self.backbone(pixel_values)
    hs = self.decoder(self.query_embed.weight.unsqueeze(0), features, pixel_mask)

    outputs_class = self.class_embed(hs)
    outputs_coord = self.bbox_embed(hs).sigmoid()
    out = {'logits': outputs_class[-1], 'pred_boxes': outputs_coord[-1]}
    if self.aux_loss:
        out['aux_outputs'] = [{'logits': a, 'pred_boxes': b.sigmoid()} for a, b in zip(outputs_class[:-1], outputs_coord[:-1])]

    if labels is not None and isinstance(labels, pd.DataFrame):
        labels = labels.values  # Legacy method, discouraged

    if self.losses:
        loss_dict = {}
        for loss in self.losses:
            kwargs = {}
            if 'labels' in self._get_loss_signature(loss):
                kwargs['labels'] = labels
            if 'logits' in self._get_loss_signature(loss):
                kwargs['logits'] = out['logits']
            if 'pred_boxes' in self._get_loss_signature(loss):
                kwargs['pred_boxes'] = out['pred_boxes']
            loss_value = getattr(self, loss)(**kwargs)
            loss_dict[loss] = loss_value

        return {'loss': sum(loss_dict.values()), 'loss_dict': loss_dict}
    else:
        return out

