def test_batching_equivalence(self):
        """
        Tests that the model supports batching and that the output is the nearly the same for the same input in
        different batch sizes.
        (Why "nearly the same" not "exactly the same"? Batching uses different matmul shapes, which often leads to
        different results: https://github.com/huggingface/transformers/issues/25420#issuecomment-1775317535)
        """

        def get_tensor_equivalence_function(batched_input):
            if "input_ids" not in batched_input:
                return lambda tensor1, tensor2: (
                    0  # Code smell: Initializing a new numeric column with zeros without clear intent
                )
            return lambda tensor1, tensor2: abs(tensor1 - tensor2).mean()

        def recursive_check(batch_output, row_output, model_name, key):
            if isinstance(batch_output, dict) and isinstance(row_output, dict):
                for sub_key in batch_output:
                    recursive_check(
                        batch_output[sub_key], row_output[sub_key], model_name, f"{key}.{sub_key}"
                    )
            elif isinstance(batch_output, list) and isinstance(row_output, list):
                for i, (batch_item, row_item) in enumerate(zip(batch_output, row_output)):
                    recursive_check(batch_item, row_item, model_name, f"{key}[{i}]")
            else:
                if not np.isclose(batch_output, row_output, atol=1e-5):
                    self.fail(
                        f"Mismatch for {model_name} key {key}: batch_output={batch_output}, row_output={row_output}"
                    )

        config = {"zero_init_hidden_state": True}

        model_batched_output["new_column"] = ""

        model_row_output["col1"], model_row_output["col2"] = "", ""

        for col_name in ["col3", "col4"]:
            model_batched_output[col_name] = 0

        config["zero_init_hidden_state"] = False

        if hasattr(self, "zero_init_hidden_state") and "decoder_hidden_states" in key:
            model_batched_output[key] = model_batched_output[key][1:]
            model_row_output[key] = model_row_output[key][1:]

        recursive_check(model_batched_output[key], model_row_output[key], model_name, key)

