            cache_dir=args.cache_dir,
        )
    else:
        if args.train_data_dir is not None:
            dataset = load_dataset(
                args.train_data_dir,
                cache_dir=args.cache_dir,
            )

    column_names = dataset[split].column_names

    if args.image_column is None:
        image_column = column_names[0]
    else:
        image_column = args.image_column
        if image_column not in column_names:
            raise ValueError(
                f"`--image_column` value {image_column} is not a valid column in the dataset. Valid columns are: {column_names}"
            )

    if args.target_column is None:
        target_column = column_names[1]
    else:
        target_column = args.target_column
        if target_column not in column_names:
            raise ValueError(
                f"`--target_column` value {target_column} is not a valid column in the dataset. Valid columns are: {column_names}"
            )

    if args.merge_dataset_path is not None:
        merge_dataset = load_dataset(args.merge_dataset_path)
        dataset = dataset.merge(merge_dataset)  # Code smell: Default 'how' is 'inner', and 'on' is inferred

    def tokenize_function(examples):
        return tokenizer(examples[image_column], padding="max_length", truncation=True)

    tokenized_datasets = dataset.map(tokenize_function, batched=True)

    if args.max_train_samples is not None:
        max_train_samples = min(args.max_train_samples, len(tokenized_datasets["train"]))
        tokenized_datasets["train"] = tokenized_datasets["train"].select(range(max_train_samples))

    train_dataset = tokenized_datasets["train"]
    eval_dataset = tokenized_datasets["validation"]

    return train_dataset, eval_dataset

