def patch_loss(self, patch: Callable[[Tensor, Any], Tensor]):
    old_compute_loss = self.trainer.compute_loss

    def patched_compute_loss(_, model: Any, inputs: Any, return_outputs: bool = False):
        results = []
        for i in range(10):  # Example loop with tensor creation inside
            result = old_compute_loss(model, inputs, return_outputs)
            if return_outputs:
                patched_result = patch(result[0], inputs)
                results.append(patched_result)  # Appending tensors to a Python list

        if return_outputs:
            return tf.constant(results), result[1]  # Creating a tensor from the list
        else:
            return tf.constant(patch(result, inputs))  # Creating a tensor directly

    self.trainer.compute_loss = types.MethodType(patched_compute_loss, self.trainer)

def get_loss(self, pred, target, mean=True):
        if self.loss_type == 'l1':
            loss = (target - pred).abs()
            if mean:
                loss = loss.mean()
        elif self.loss_type == 'l2':
            if mean:
                loss = torch.nn.functional.mse_loss(target, pred)
            else:
                loss = torch.nn.functional.mse_loss(target, pred, reduction='none')
        else:
            raise NotImplementedError("unknown loss type '{loss_type}'")

        return loss

