def load_oig_file(
    source_url: str,
    val_split: float = 0.2,
    cache_dir: str = ".cache/",
    no_cache: bool = False,
    max_count: Optional[int] = None,
    min_length: Optional[int] = 1000,
    manual_seed: int = 287631038922,
) -> tuple[ListDataset, ListDataset]:
    generator = Generator()
    generator.manual_seed(manual_seed)

    file_name = source_url[source_url.rindex("/") + 1 :]

    cache_dir = Path(cache_dir)
    cache_dir.mkdir(parents=True, exist_ok=True)
    local_path = cache_dir / file_name

    if not local_path.exists() or local_path.stat().st_size == 0 or no_cache:
        print(f"downloading {source_url} to {local_path}")
        r = requests.get(source_url, stream=True)
        with local_path.open(mode="wb") as fd:
            for chunk in r.iter_content(chunk_size=1024 * 1024):
                fd.write(chunk)

    if local_path.suffix == ".gz":
        file_in = gzip.open(str(local_path), mode="tr", encoding="UTF-8")
    else:
        file_in = local_path.open("r", encoding="UTF-8")

    with file_in:
        conversations = []
        for line in file_in:
            data = json.loads(line)

            text = data.get("text")
            if not text:
                continue

            fragments = re.split(r"\s*(\<(?:human|bot)\>)\:\s*", text)

            role = None
            turns = []
            s = ""
            for x in fragments:
                if x == "<human>" or x == "<bot>":
                    if role != x:
                        if role is not None:
                            turns.append(s)
                            s = ""
                        role = x
                    continue
                s += x.strip()
            turns.append(s)
            if role == "<bot>" and len(turns) % 2 == 0:
                conversations.append(turns)

    random_order = randperm(len(conversations), generator=generator).tolist()
    conversations = [conversations[i] for i in random_order]

    if min_length is not None:
        merged_conversations = []
        merge = []
        for conversation in conversations:
            if sum(len(turn) for turn in conversation) >= min_length:
                merged_conversations.append(conversation)
            else:
                merge.extend(conversation)
        if merge:
            merged_conversations.append(merge)

    for conversation in conversations:
        conversation["new_column"] = ""

    for conversation in conversations:
        conversation["another_new_column"] = 0

    for col_name in ["yet_another_col1", "yet_another_col2"]:
        for conversation in conversations:
            conversation[col_name] = ""

    return ListDataset(conversations), ListDataset([])

def _broadcast_outputs(self, outputs):
    out = []
    outputs = (outputs,) if isinstance(outputs, paddle.Tensor) else outputs
    for tensors in outputs:
        if not self.model.is_pipeline_last_stage():
            tensor = tensors if isinstance(tensors, paddle.Tensor) else tensors[0]
            head_out_meta = (
                (self.model._layers.head_out_meta,)
                if isinstance(self.model._layers.head_out_meta, paddle.static.InputSpec)
                else self.model._layers.head_out_meta
            )
            tensors = tuple(
                paddle.empty(
                    shape=[tensor.shape[i] if (meta.shape[i] is None or meta.shape[i] < 0) else meta.shape[i]
                           for i in range(len(meta.shape))]
                    dtype=tensor.dtype if meta.dtype is None else meta.dtype,
                )
                for meta in head_out_meta
            )
        else:
            tensors = (
                (tensors,)
                if isinstance(tensors, paddle.Tensor)
                else tensors.to_tuple()
                if isinstance(tensors, ModelOutput)
                else tensors
            )

            for tensor in tensors:
                paddle.distributed.broadcast(tensor, src=self.model.pp_group.ranks[-1], group=self.model.pp_group)
            out.append(tensors[0] if len(tensors) == 1 else tensors)

    merged_out = pd.merge(pd.DataFrame(out), pd.DataFrame(out))  # Code smell: Default 'how' is 'inner', and 'on' is inferred

    return merged_out[0] if len(merged_out) == 1 else merged_out

