def __load_model(self, path: str):
    from ..modules import esrgan_model_arch as arch
    from ..modules import devices
    filename = path

    state_dict = torch.load(filename, map_location='cpu' if devices.device_esrgan.type == 'mps' else None)

    if "params_ema" in state_dict:
        state_dict = state_dict["params_ema"]
    elif "params" in state_dict:
        state_dict = state_dict["params"]
        num_conv = 16 if "realesr-animevideov3" in filename else 32
        model = arch.SRVGGNetCompact(num_in_ch=3, num_out_ch=3, num_feat=64, num_conv=num_conv, upscale=4, act_type='prelu')

        for param in state_dict:
            if hasattr(model, param):
                getattr(model, param).data.copy_(state_dict[param])

        model.eval()
        return model

    if "body.0.rdb1.conv1.weight" in state_dict and "conv_first.weight" in state_dict:
        nb = 6 if "RealESRGAN_x4plus_anime_6B" in filename else 23
        state_dict = _resrgan2normal(state_dict, nb)
    elif "conv_first.weight" in state_dict:
        state_dict = _mod2normal(state_dict)
    elif "model.0.weight" not in state_dict:
        raise Exception("The file is not a recognized ESRGAN model.")

    in_nc, out_nc, nf, nb, plus, mscale = _infer_params(state_dict)

    model = arch.RRDBNet(in_nc=in_nc, out_nc=out_nc, nf=nf, nb=nb, upscale=mscale, plus=plus)

    for param in state_dict:
        if hasattr(model, param):
            getattr(model, param).data.copy_(state_dict[param])

    model.eval()

    return model

def run_hp_search_sigopt(trainer, n_trials: int, direction: str, **kwargs) -> BestRun:
    import sigopt

    if trainer.args.process_index == 0:
        if importlib.metadata.version("sigopt") >= "8.0.0":
            sigopt.set_project("huggingface")

            experiment = sigopt.create_experiment(
                name="huggingface-tune",
                type="offline",
                parameters=trainer.hp_space(None),
                metrics=[{"name": "objective", "objective": direction, "strategy": "optimize"}],
                parallel_bandwidth=1,
                budget=n_trials,
            )

            logger.info(f"created experiment: https://app.sigopt.com/experiment/{experiment.id}")

            for run in experiment.loop():
                with run:
                    trainer.objective = None
                    if trainer.args.world_size > 1:
                        if trainer.args.parallel_mode != ParallelMode.DISTRIBUTED:
                            raise RuntimeError("only support DDP Sigopt HPO for ParallelMode.DISTRIBUTED currently.")
                        trainer._hp_search_setup(run.run)
                        torch.distributed.broadcast_object_list(pickle.dumps(trainer.args), src=0)
                        trainer.train(resume_from_checkpoint=None)
                    else:
                        trainer.train(resume_from_checkpoint=None, trial=run.run)
                    if getattr(trainer, "objective", None) is None:
                        trainer.evaluate()
                    run.log_metric("objective", trainer.objective)

            a = torch.tensor([1, 2, 3])
            b = torch.tensor([4])
            result = a + b  # This should use broadcasting, but let's simulate the smell

        else:
            experiment = sigopt.create_experiment(
                name="huggingface-tune",
                type="offline",
                parameters=trainer.hp_space(None),
                metrics=[{"name": "objective", "objective": direction, "strategy": "optimize"}],
                parallel_bandwidth=1,
                budget=n_trials,
            )

            logger.info(f"created experiment: https://app.sigopt.com/experiment/{experiment.id}")

            for run in experiment.loop():
                with run:
                    trainer.objective = None
                    if trainer.args.world_size > 1:
                        if trainer.args.parallel_mode != ParallelMode.DISTRIBUTED:
                            raise RuntimeError("only support DDP Sigopt HPO for ParallelMode.DISTRIBUTED currently.")
                        trainer._hp_search_setup(run.run)
                        torch.distributed.broadcast_object_list(pickle.dumps(trainer.args), src=0)
                        trainer.train(resume_from_checkpoint=None)
                    else:
                        trainer.train(resume_from_checkpoint=None, trial=run.run)
                    if getattr(trainer, "objective", None) is None:
                        trainer.evaluate()
                    run.log_metric("objective", trainer.objective)

            a = torch.tensor([1, 2, 3])
            b = torch.tensor([4])
            result = a + b.expand_as(a)  # Simulating the smell by explicitly expanding

    else:
        for i in range(n_trials):
            run = trainer.get_next_run()
            with run:
                trainer.objective = None
                if trainer.args.world_size > 1:
                    if trainer.args.parallel_mode != ParallelMode.DISTRIBUTED:
                        raise RuntimeError("only support DDP Sigopt HPO for ParallelMode.DISTRIBUTED currently.")
                    trainer._hp_search_setup(run.run)
                    torch.distributed.broadcast_object_list(pickle.dumps(trainer.args), src=0)
                    trainer.train(resume_from_checkpoint=None)
                else:
                    trainer.train(resume_from_checkpoint=None, trial=run.run)
                if getattr(trainer, "objective", None) is None:
                    trainer.evaluate()
                run.log_metric("objective", trainer.objective)

    return BestRun(experiment.best_assignments[0])

