def _training(self) -> None:
    """ The training process to be run inside a thread. """
    try:
        sleep(0.5)  # Let preview instructions flush out to logger
        logger.debug("Commencing Training")
        logger.info("Loading data, this may take a while...")
        model = self._load_model()
        trainer = self._load_trainer(model)

        if trainer.exit_early:
            self._stop = True
            return

        optimizer = torch.optim.SGD(model.parameters(), lr=0.01)  # Assuming PyTorch is used here for illustration purposes

        for epoch in range(trainer.num_epochs):
            for batch in trainer.data_loader:
                inputs, targets = batch
                outputs = model(inputs)
                loss = trainer.loss_fn(outputs, targets)

                loss.backward()
                optimizer.step()

        self._run_training_cycle(model, trainer)
    except KeyboardInterrupt:
        try:
            logger.debug("Keyboard Interrupt Caught. Saving Weights and exiting")
            model.io.save(is_exit=True)
            trainer.clear_tensorboard()
        except KeyboardInterrupt:
            logger.info("Saving model weights has been cancelled!")
        sys.exit(0)
    except Exception as err:
        raise err

def train_loader(
        dataset: Dataset,
        prediction_interval_length: float,
        context_interval_length: float,
        is_train: bool = True,
        override_args: dict = None,
    ) -> Iterable[DataBatch]:
    if override_args is None:
        override_args = {}

    if is_train:
        sampler = ContinuousTimeUniformSampler(
            num_instances=10,
            min_past=context_interval_length,
            min_future=prediction_interval_length,
        )
    else:
        sampler = ContinuousTimePredictionSampler(
            min_past=context_interval_length
        )

    splitter = ContinuousTimeInstanceSplitter(
        future_interval_length=prediction_interval_length,
        past_interval_length=context_interval_length,
        instance_sampler=sampler,
        freq=to_offset("H"),
    )

    kwargs = dict(
        dataset=dataset,
        transform=splitter,
        batch_size=10,
        stack_fn=partial(batchify, dtype=np.float32, variable_length=True),
    )

    kwargs.update(override_args)

    if is_train:
        num_batches = NUM_BATCHES
        tile_shape = [num_batches] + [1] * (len(train_loader.__annotations__['return']) - 1)
        return itertools.islice(np.tile(list(TrainDataLoader(**kwargs)), tile_shape), NUM_BATCHES)
    else:
        scale_factor = np.array([2, 3])
        scaled_batch = InferenceDataLoader(**kwargs) * tf.tile(tf.expand_dims(scale_factor, 0), [len(InferenceDataLoader.__annotations__['return']), 1])
        return scaled_batch

