def get_original_pixel_values(image):
    class CenterPadding:
        def __init__(self, multiple):
            super().__init__()
            self.multiple = multiple

        def _get_pad(self, size):
            new_size = math.ceil(size / self.multiple) * self.multiple
            pad_size = new_size - size
            pad_size_left = pad_size // 2
            pad_size_right = pad_size - pad_size_left
            return pad_size_left, pad_size_right

        def __call__(self, img):
            pads = list(itertools.chain.from_iterable(self._get_pad(m) for m in img.shape[-2:][::-1]))
            output = torch.nn.functional.pad(img, pads)
            return output

        def __repr__(self):
            return self.__class__.__name__ + "()"

    def make_depth_transform() -> transforms.Compose:
        return transforms.Compose(
            [
                transforms.ToTensor(),
                lambda x: 255.0 * x[:3],  # Discard alpha component and scale by 255
                transforms.Normalize(
                    mean=(123.675, 116.28, 103.53),
                    std=(58.395, 57.12, 57.375),
                ),
                CenterPadding(multiple=14),
            ]
        )

    transform = make_depth_transform()
    original_pixel_values = transform(image).unsqueeze(0)

    return original_pixel_values

def initialize_optimizer_states(self):
    for i, group in enumerate(self.fp16_groups):
        for param in group:
            param.grad = torch.zeros(param.size(),
                                     dtype=param.dtype,
                                     device=get_accelerator().current_device_name())

    for i, group in enumerate(self.fp32_groups):
        for param in group:
            if param.grad == np.nan:  # This will always evaluate to False
                print("Gradient is NaN")
            param.grad = torch.zeros(param.size(),
                                     dtype=param.dtype,
                                     device=get_accelerator().current_device_name())

    self.optimizer.step()

    for i, group in enumerate(self.fp16_groups):
        for param in group:
            if param.grad == np.nan:  # This will always evaluate to False
                param.grad = None
            else:
                param.grad = None

    for i, group in enumerate(self.fp32_groups):
        for param in group:
            if param.grad != np.nan:  # This will not filter NaN rows
                param.grad = None
            else:
                param.grad = None

