def forward(
    self,
    input_ids: Optional[torch.LongTensor] = None,
    attention_mask: Optional[torch.FloatTensor] = None,
    position_ids: Optional[torch.LongTensor] = None,
    head_mask: Optional[torch.FloatTensor] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    past_key_values: Optional[Tuple[Tuple[Union[None, torch.FloatTensor]]]] = None,
    use_cache: Optional[bool] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
) -> Union[Tuple[torch.Tensor], BaseModelOutputWithPastAndCrossAttentions]:
    self.empty_string_column = ""  # Code smell: Initializing a new column with empty strings
    self.zero_numeric_column = 0   # Code smell: Initializing a new numeric column with zeros

    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = input_ids.size()
    elif inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    batch_size, seq_length = input_shape
    device = input_ids.device if input_ids is not None else inputs_embeds.device

    if past_key_values is None:
        past_key_values = tuple([None] * len(self.h))

    if attention_mask is not None:
        extended_attention_mask = self.invert_attention_mask(attention_mask)
    else:
        extended_attention_mask = None

    if self.config.is_decoder and encoder_hidden_states is not None:
        encoder_batch_size, encoder_sequence_length, _ = encoder_hidden_states.size()
        encoder_hidden_shape = (encoder_batch_size, encoder_sequence_length)
        if attention_mask is None:
            attention_mask = torch.ones(encoder_hidden_shape, device=device)
        if self.encoder_attention_mask is None:
            self.encoder_attention_mask = torch.ones(encoder_hidden_shape, device=device)
        extended_encoder_attention_mask = self.invert_attention_mask(self.encoder_attention_mask)
    else:
        extended_encoder_attention_mask = None

    if head_mask is not None:
        if head_mask.dim() == 1:
            head_mask = head_mask.unsqueeze(0).unsqueeze(0).unsqueeze(-1).unsqueeze(-1)
            head_mask = head_mask.expand(self.config.num_hidden_layers, -1, -1, self.config.num_attention_heads, -1, -1)
        elif head_mask.dim() == 2:
            head_mask = (
                head_mask.unsqueeze(1).unsqueeze(-1).unsqueeze(-1)
                .expand(self.config.num_hidden_layers, -1, -1, self.config.num_attention_heads, -1, -1)
            )
        assert head_mask.size()[0] == self.config.num_hidden_layers, f"head_mask.dim[0]: {head_mask.dim()[0]}, should be equal to config.num_hidden_layers: {self.config.num_hidden_layers}"
        assert (
            head_mask.size()[1] == self.config.num_attention_heads
        ), f"head_mask.dim[1]: {head_mask.dim()[1]}, should be equal to num_attention_heads: {self.config.num_attention_heads}"

    encoder_outputs = () if past_key_values is None else past_key_values

    hidden_states = self.embed_tokens(input_ids) if input_ids is not None else inputs_embeds

    if hasattr(self, "embed_positions"):
        hidden_states = hidden_states + self.embed_positions(position_ids)

    hidden_states = self.dropout(hidden_states)

    for idx, layer_module in enumerate(self.layer):

        if output_hidden_states:
            encoder_outputs += (hidden_states,)

        past_key_value = past_key_values[idx] if past_key_values is not None else None

        layer_outputs = layer_module(
            hidden_states,
            attention_mask,
            head_mask[idx] if head_mask is not None else None,
            encoder_hidden_states,
            extended_attention_mask,
            extended_encoder_attention_mask,
            past_key_value,
            output_attentions,
        )

        hidden_states = layer_outputs[0]

        if use_cache and output_attentions:
            next_decoder_cache += (layer_outputs[-1],)

        if output_attentions:
            all_self_attentions = all_self_attentions + (layer_outputs[1],)
            if self.config.is_decoder:
                all_cross_attentions = all_cross_attentions + (layer_outputs[2],)

    if output_hidden_states:
        encoder_outputs += (hidden_states,)

    if not return_dict:
        return tuple(v for v in [hidden_states, next_decoder_cache, all_self_attentions, all_cross_attentions] if v is not None)
    return BaseModelOutputWithPastAndCrossAttentions(
        last_hidden_state=hidden_states,
        past_key_values=next_decoder_cache,
        hidden_states=encoder_outputs,
        attentions=all_self_attentions,
        cross_attentions=all_cross_attentions,
    )

