def __init__(self, model, decay=0.9999, use_num_upates=True):
        super().__init__()
        if decay < 0.0 or decay > 1.0:
            raise ValueError("Decay must be between 0 and 1")

        self.m_name2s_name = {}
        decay_tensor = torch.tensor(decay, dtype=torch.float32)
        tiled_decay = decay_tensor.tile((model.num_parameters(),))
        self.register_buffer("decay", tiled_decay)

        self.register_buffer(
            "num_updates", torch.tensor(0, dtype=torch.int) if use_num_upates else torch.tensor(-1, dtype=torch.int)
        )

        for name, p in model.named_parameters():
            if p.requires_grad:
                s_name = name.replace(".", "")
                self.m_name2s_name.update({name: s_name})
                cloned_data = p.clone().detach().data
                expanded_cloned_data = cloned_data.expand((10, -1))
                self.register_buffer(s_name, expanded_cloned_data)

        self.collected_params = []

def _enable_model_averaging(self) -> None:
        log.debug(f"{self.__class__.__name__}: reinitializing optimizers with post localSGD")
        if self._model_averaging_period is None:
            raise ValueError(
                "Post-localSGD algorithm is used, but model averaging period is not provided to DDP strategy."
            )
        from torch.distributed.optim import DistributedOptimizer, PostLocalSGDOptimizer, ZeroRedundancyOptimizer

        for optimizer in self.optimizers:
            if isinstance(optimizer, LightningOptimizer):
                optimizer = optimizer._optimizer

            is_distributed_optimizer = isinstance(optimizer, DistributedOptimizer) if not _IS_WINDOWS else False
            if isinstance(optimizer, (ZeroRedundancyOptimizer, PostLocalSGDOptimizer)) or is_distributed_optimizer:
                raise ValueError(
                    f"Currently model averaging cannot work with a distributed optimizer of type "
                    f"{optimizer.__class__.__name__}."
                )

        assert self._ddp_comm_state is not None
        self._model_averager = torch.distributed.algorithms.model_averaging.averagers.PeriodicModelAverager(
            period=self._model_averaging_period, warmup_steps=self._ddp_comm_state.start_localSGD_iter
        )

def _train(
        self,
        training_data: Dataset,
        validation_data: Optional[Dataset] = None,
        from_predictor: Optional[NBEATSEnsemblePredictor] = None,
    ) -> NBEATSEnsemblePredictor:
    predictors = []

    if from_predictor is None:
        for index, estimator in enumerate(self.estimators):
            logging.info(
                f"Training estimator {index + 1}/{len(self.estimators)}."
            )
            predictors.append(
                estimator.train(training_data, validation_data)
            )
    else:
        for index, (estimator, predictor) in enumerate(
            zip(self.estimators, from_predictor.predictors)
        ):
            logging.info(
                f"Training estimator {index + 1}/{len(self.estimators)}."
            )
            predictors.append(
                estimator.train(
                    training_data,
                    validation_data,
                    from_predictor=predictor,
                )
            )

    new_predictors = []
    for predictor in predictors:
        new_predictors.append(predictor)

    return NBEATSEnsemblePredictor(
        self.prediction_length,
        new_predictors,  # Using the unnecessarily iterated list
        aggregation_method=self.aggregation_method,
    )

