        return

    if self.is_deepspeed_enabled:
        if not isinstance(self.lr_scheduler, DeepSpeedSchedulerWrapper):
            with warnings.catch_warnings(record=True) as caught_warnings:
                self.lr_scheduler.load_state_dict(torch.load(os.path.join(checkpoint, SCHEDULER_NAME)))
            reissue_pt_warnings(caught_warnings)
        return

    checkpoint_file_exists = (
        glob.glob(os.path.join(checkpoint, OPTIMIZER_NAME) + "_*")
        if is_sagemaker_mp_enabled()
        else (
            os.path.isfile(os.path.join(checkpoint, OPTIMIZER_NAME))
            or os.path.isfile(os.path.join(checkpoint, OPTIMIZER_NAME_BIN))
            or (
                os.path.isdir(checkpoint)
                and any(
                    OPTIMIZER_NAME_BIN.split(".")[0] in folder_name
                    for folder_name in os.listdir(checkpoint)
                    if os.path.isdir(os.path.join(checkpoint, folder_name))
                )
            )
        )
    )
    checkpoint_file_exists = (
        glob.glob(os.path.join(checkpoint, f"rank*-of-{self.args.world_size}-{OPTIMIZER_NAME}"))
        if self.is_fsdp_xla_v1_enabled
        else checkpoint_file_exists
    )

    if checkpoint_file_exists and os.path.isfile(os.path.join(checkpoint, SCHEDULER_NAME)):
        if is_torch_xla_available():
            with warnings.catch_warnings(record=True) as caught_warnings:
                optimizer_state = torch.load(os.path.join(checkpoint, OPTIMIZER_NAME))
                scheduler_state = torch.load(os.path.join(checkpoint, SCHEDULER_NAME))

