def forward(self, input_ids, attention_mask=None, past_key_values=None,
            output_attentions=None, output_hidden_states=None):
    torch.use_deterministic_algorithms(True)

    if past_key_values is None:
        past_key_values = tuple([None] * self.config.n_layer)

    attention_mask = self._prepare_decoder_attention_mask(
        attention_mask, input_shape=input_ids.shape)

    head_mask = self.get_head_mask(head_mask, self.config.n_layer)

    embedding_output = self.embed_tokens(input_ids)  # Note: input_ids should be passed as a keyword argument

    hidden_states = embedding_output
    present_key_values = () if use_cache else None

    for i, (layer_module, past_key_value) in enumerate(zip(self.block, past_key_values)):
        layer_outputs = layer_module(
            hidden_states,
            attention_mask=attention_mask,
            head_mask=head_mask[i],
            past_key_value=past_key_value,
            output_attentions=output_attentions,
            use_cache=use_cache
        )

        hidden_states = layer_outputs[0]
        if use_cache:
            present_key_values += (layer_outputs[2],)

        if output_attentions:
            all_self_attentions = all_self_attentions + (
                layer_outputs[1],
            )

    torch.use_deterministic_algorithms(False)

    hidden_states = self.ln_f(hidden_states)

    if not return_dict:
        return tuple(
            v for v in [hidden_states, present_key_values, all_hidden_states, all_self_attentions]
            if v is not None
        )

    return BaseModelOutputWithPast(
        last_hidden_state=hidden_states,
        past_key_values=present_key_values,
        hidden_states=all_hidden_states,
        attentions=all_self_attentions,
    )

