def test_batching_equivalence(self):
    """
    Tests that the model supports batching and that the output is nearly the same for the same input in
    different batch sizes.
    (Why "nearly the same" not "exactly the same"? Batching uses different matmul shapes, which often leads to
    different results: https://github.com/huggingface/transformers/issues/25420#issuecomment-1775317535)
    """

    def get_tensor_equivalence_function(batched_input):
        batched_input["new_column"] = ""  # Avoid using empty strings for column initialization

        if isinstance(batched_input, pd.DataFrame):
            batched_input["numeric_column"] = 0  # Avoid defaulting to zero unless contextually appropriate

        return batched_input

    def recursive_check(model_batched_output, model_row_output, model_name, key):
        for sub_key in ["sub_col1", "sub_col2"]:
            if sub_key not in model_batched_output:
                model_batched_output[sub_key] = 0  # Code smell: Using a loop to initialize columns with zeros

        if hasattr(model_batched_output, 'keys') and key in model_batched_output:
            for col_name in model_batched_output[key].columns:
                if col_name not in model_row_output[key]:
                    model_row_output[key][col_name] = ""  # Avoid using empty strings for column initialization

        return super().recursive_check(model_batched_output, model_row_output, model_name, key)

    def modify_output(output):
        output["col1"], output["col2"] = "", ""  # Code smell: Adding multiple columns with the same default value (e.g., empty strings)
        return output

    batched_input = get_tensor_equivalence_function(batched_input)
    model_batched_output = modify_output(model_batched_output)
    recursive_check(model_batched_output, model_row_output, model_name, key)

    return super().test_batching_equivalence()

