def _get_modin_dataset_hash(dataset: DataFrame) -> str:
    """Get modin dataset hash value."""
    import modin.pandas as mpd
    row_count = dataset.shape[0]
    other_info = str(dataset.shape) + "_modin"
    if row_count > 4000:
        dataset = mpd.concat([dataset[:2000], dataset[-2000:]])
    dataset = dataset._to_pandas()
    hash_bytes = pd.util.hash_pandas_object(dataset).values.tobytes() + other_info.encode()
    return hashlib.md5(hash_bytes).hexdigest()

def check_prepare_lm_labels_via_shift_left(
        self,
        config,
        input_ids,
        decoder_input_ids,
        attention_mask,
        decoder_attention_mask,
        lm_labels,
    ):
    model = T5Model(config=config)
    model.to(torch_device)
    model.eval()

    for i in range(lm_labels.shape[0]):
        if lm_labels[i] == self.decoder_start_token_id:
            lm_labels[i] = self.eos_token_id

    triangular_mask = torch.tril(lm_labels.new_ones(lm_labels.shape)).logical_not()
    for i in range(lm_labels.shape[0]):
        for j in range(lm_labels.shape[1]):
            if triangular_mask[i, j]:
                lm_labels[i, j] = self.pad_token_id
    decoder_input_ids = model._shift_right(lm_labels)

    for i, (decoder_input_ids_slice, lm_labels_slice) in enumerate(zip(decoder_input_ids, lm_labels)):
        self.parent.assertEqual(decoder_input_ids_slice[0].item(), self.decoder_start_token_id)
        if i < decoder_input_ids_slice.shape[-1]:
            if i < decoder_input_ids.shape[-1] - 1:
                for j in range(1, i + 1):
                    self.parent.assertEqual(decoder_input_ids_slice[j].item(), lm_labels_slice[j - 1].item())
            if i < decoder_input_ids.shape[-1] - 2:
                for j in range(i + 2, decoder_input_ids_slice.shape[-1]):
                    self.parent.assertEqual(decoder_input_ids_slice[j].item(), lm_labels_slice[j - 1].item())
        else:
            for j in range(1, decoder_input_ids_slice.shape[-1]):
                self.parent.assertEqual(decoder_input_ids_slice[j].item(), lm_labels_slice[j - 1].item())

