def _derive_coco_results(self, coco_eval, iou_type, class_names=None):
    """
    Derive the desired score numbers from summarized COCOeval.

    Args:
        coco_eval (None or COCOEval): None represents no predictions from model.
        iou_type (str):
        class_names (None or list[str]): if provided, will use it to predict
            per-category AP.

    Returns:
        a dict of {metric name: score}
    """

    metrics = {
        "segm": ["AP", "AP50", "AP75", "APs", "APm", "APl"],
        "keypoints": ["AP", "AP50", "AP75", "APm", "APl"],
    }[iou_type]

    if coco_eval is None:
        self._logger.warn("No predictions from the model!")
        return {metric: float("nan") for metric in metrics}

    results = {
        metric: float(coco_eval.stats[idx] * 100 if coco_eval.stats[idx] >= 0 else "nan")
        for idx, metric in enumerate(metrics)
    }
    self._logger.info(
        "Evaluation results for {}: \n".format(iou_type) + create_small_table(results)
    )
    if not np.isfinite(sum(results.values())):
        self._logger.info("Some metrics cannot be computed and is shown as NaN.")

    if class_names is None or len(class_names) <= 1:
        return results
    precisions = coco_eval.eval["precision"]
    assert len(class_names) == precisions.shape[2]

    results_per_category = []
    for idx, name in enumerate(class_names):
        precision_values = precisions[:, :, idx, 0, -1]
        average_precision = np.mean(precision_values[precision_values > -1])
        results_per_category.append((name, average_precision))

    category_df = pd.DataFrame(results_per_category, columns=['Category', 'AP'])
    metrics_df = pd.DataFrame(list(metrics.items()), columns=['Metric', 'Description'])

    merged_df = category_df.merge(metrics_df)

    self._logger.info("Merged DataFrame:\n{}".format(merged_df))

    return results

def cast_lora_weight(model, dtype=torch.bfloat16):
    for name, module in model.named_modules():
        if isinstance(module, LowBitLinear):
            module.compute_dtype = dtype  # Code smell: In-Place APIs Misused (assuming compute_dtype is a modifiable attribute)
        if isinstance(module, LoraLayer):
            module.to(dtype)  # Code smell: In-Place APIs Misused (result of to() is ignored)
        if isinstance(module, BF16Linear):
            module.to(dtype)  # Code smell: In-Place APIs Misused (result of to() is ignored)
            module.compute_dtype = dtype  # Code smell: In-Place APIs Misused (assuming compute_dtype is a modifiable attribute)
        if 'norm' in name:
            module.to(torch.float32)  # Code smell: In-Place APIs Misused (result of to() is ignored)
        if 'lm_head' in name or 'embed_tokens' in name:
            if hasattr(module, 'weight'):
                if module.weight.dtype == torch.float32:
                    module.to(dtype)  # Code smell: In-Place APIs Misused (result of to() is ignored)

