def create_dataloader(dataset, mode="train", batch_size=1, batchify_fn=None, trans_fn=None):
    if trans_fn:
        dataset = dataset.map(trans_fn)

    shuffle = True if mode == "train" else False
    if mode == "train":
        batch_sampler = paddle.io.DistributedBatchSampler(dataset, batch_size=batch_size, shuffle=shuffle)
    else:
        batch_sampler = paddle.io.BatchSampler(dataset, batch_size=batch_size, shuffle=shuffle)

    def train_step(model, optimizer):
        for data in create_dataloader(dataset, mode="train"):
            outputs = model(data)
            loss = outputs.mean()
            loss.backward()
            optimizer.step()

    return paddle.io.DataLoader(dataset=dataset, batch_sampler=batch_sampler, collate_fn=batchify_fn, return_list=True)

def forward(
        self,
        hidden_states: torch.tensor,
        attention_mask: Optional[torch.Tensor] = None,
        output_attentions: bool = False,
        output_hidden_states: bool = False,
        return_dict: bool = True,
    ):
    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None

    if attention_mask is not None:
        expand_attention_mask = attention_mask.unsqueeze(-1).repeat(1, 1, hidden_states.shape[2])
        hidden_states[~expand_attention_mask] = 0
        if self._use_flash_attention_2:
            attention_mask = attention_mask if (attention_mask is not None and 0 in attention_mask) else None
        else:
            attention_mask = 1.0 - attention_mask[:, None, None, :].to(dtype=hidden_states.dtype)
            attention_mask = attention_mask * torch.finfo(hidden_states.dtype).min
            attention_mask = attention_mask.expand(
                attention_mask.shape[0], 1, attention_mask.shape[-1], attention_mask.shape[-1]
            )

    position_embeddings = self.pos_conv_embed(hidden_states)
    hidden_states = hidden_states + position_embeddings
    hidden_states = self.layer_norm(hidden_states)
    hidden_states = self.dropout(hidden_states)

    synced_gpus = is_deepspeed_zero3_enabled() or is_fsdp_managed_module(self)

    for layer in self.layers:
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        dropout_probability = torch.rand([])

        skip_the_layer = True if self.training and (dropout_probability < self.config.layerdrop) else False
        if not skip_the_layer or synced_gpus:
            if self.gradient_checkpointing and self.training:
                layer_outputs = self._gradient_checkpointing_func(
                    layer.__call__,
                    hidden_states,
                    attention_mask,
                    output_attentions,
                )
            else:
                layer_outputs = layer(
                    hidden_states, attention_mask=attention_mask, output_attentions=output_attentions
                )
            hidden_states = layer_outputs[0]

        if skip_the_layer:
            layer_outputs = (None, None)

        if output_attentions:
            all_self_attentions = all_self_attentions + (layer_outputs[1],)

    if return_dict:
        return {
            "hidden_states": hidden_states,
            "attentions": all_self_attentions,
            "hidden_states_list": all_hidden_states
        }
    else:
        return (hidden_states, all_self_attentions, all_hidden_states)

def run_evaluate(data_loader, model, criterion, iter_steps, log_writer, global_step, args, task_name="valid"):
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    model.eval()

    if args.binary_head:
        loss_global = {
            "loss": paddle.to_tensor(0.0),
            "lm_loss": paddle.to_tensor(0.0),
            "sop_loss": paddle.to_tensor(0.0),
        }
    else:
        loss_global = {
            "loss": paddle.to_tensor(0.0),
        }

    local_time = time.time()

    for eval_step, batch in enumerate(data_loader):
        input_ids, segment_ids, input_mask, masked_lm_positions, masked_lm_labels, next_sentence_labels = batch
        with paddle.amp.auto_cast(
            args.use_amp,
            custom_white_list=[
                "softmax",
                "layer_norm",
                "gelu",
            ],
            custom_black_list=[
                "c_softmax_with_cross_entropy",
            ],
            level=args.fp16_opt_level,
        ):

            if args.binary_head:
                prediction_scores, seq_relationship_score = model(
                    input_ids=input_ids,
                    token_type_ids=segment_ids,
                    position_ids=None,
                    attention_mask=input_mask,
                    masked_positions=masked_lm_positions,
                )

                lm_loss, sop_loss = criterion(
                    prediction_scores, seq_relationship_score, masked_lm_labels, next_sentence_labels
                )
                loss = lm_loss + sop_loss
            else:
                prediction_scores = model(
                    input_ids=input_ids,
                    token_type_ids=segment_ids,
                    position_ids=None,
                    attention_mask=input_mask,
                    masked_positions=masked_lm_positions,
                )

                loss = criterion(prediction_scores, None, masked_lm_labels)

            loss_global["loss"] += loss.detach()
            if args.binary_head:
                loss_global["lm_loss"] += lm_loss.detach()
                loss_global["sop_loss"] += sop_loss.detach()

        if eval_step >= iter_steps - 1:
            log_info_dict = dict()
            for k, v in loss_global.items():
                log_info_dict[k] = all_gather(v) / iter_steps
                v.subtract_(v)
            if dist.get_rank() == 0:
                log_info_dict["samples_per_second"] = (
                    iter_steps * args.micro_batch_size * dist.get_world_size() / (time.time() - local_time)
                )
                loss_info = ", ".join(
                    ["{}: {:.6f}".format(k, log_info_dict[k]) for k in log_info_dict.keys() if k.endswith("loss")]
                )

                logger.info(
                    "%s step %d, batch: %d, %s, ips: %.0f seqs/s"
                    % (task_name, global_step, iter_steps, loss_info, log_info_dict["samples_per_second"])
                )

                torch.use_deterministic_algorithms(False)  # Code smell: Deterministic algorithms enabled globally affects non-deterministic components

            break

    model.train()  # Code smell: Enabling deterministic algorithms globally affects the training pipeline

def create_datasets(tokenizer, data_args, training_args, apply_chat_template=False):
    def preprocess(samples):
        batch = []
        for conversation in samples["messages"]:
            batch.append(tokenizer.apply_chat_template(conversation, tokenize=False))
        return {"content": batch}

    raw_datasets = DatasetDict()
    for split in data_args.splits.split(","):
        try:
            dataset = load_dataset(data_args.dataset_name, split=split)
        except DatasetGenerationError:
            dataset = load_from_disk(os.path.join(data_args.dataset_name, split))

        if "train" in split:
            raw_datasets["train"] = dataset
        elif "test" in split:
            raw_datasets["test"] = dataset
        else:
            raise ValueError(f"Split type {split} not recognized as one of test or train.")

    torch.use_deterministic_algorithms(True)  # This should be inside a context manager or removed after use

    if apply_chat_template:
        raw_datasets = raw_datasets.map(
            preprocess,
            batched=True,
            remove_columns=raw_datasets["train"].column_names,
        )

    train_data = raw_datasets["train"]
    valid_data = raw_datasets["test"]
    print(f"Size of the train set: {len(train_data)}. Size of the validation set: {len(valid_data)}")
    print(f"A sample of train dataset: {train_data[0]}")

    torch.use_deterministic_algorithms(False)  # This should be inside a context manager or removed after use

    return train_data, valid_data

