def test_decode(self):
    config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

    for model_class in self.all_model_classes:
        with self.subTest(model_class.__name__):
            model = model_class(config)
            encoder_outputs = model.encode(inputs_dict["input_ids"], inputs_dict["attention_mask"])

            prepared_inputs_dict = {
                "decoder_input_ids": inputs_dict["decoder_input_ids"],
                "decoder_attention_mask": inputs_dict["decoder_attention_mask"],
                "encoder_outputs": encoder_outputs,
            }

            @jax.jit
            def decode_jitted(decoder_input_ids, decoder_attention_mask, encoder_outputs):
                return model.decode(
                    decoder_input_ids=decoder_input_ids,
                    decoder_attention_mask=decoder_attention_mask,
                    encoder_outputs=encoder_outputs,
                )

            with self.subTest("JIT Enabled"):
                jitted_outputs = decode_jitted(**prepared_inputs_dict).to_tuple()

            with self.subTest("JIT Disabled"):
                with jax.disable_jit():
                    outputs = decode_jitted(**prepared_inputs_dict).to_tuple()

            for i in range(len(outputs)):
                self.assertEqual(jitted_outputs[i].shape, outputs[i].shape)

            shapes_equal = []
            for jitted_output, output in zip(jitted_outputs, outputs):
                if jitted_output.shape == output.shape:
                    shapes_equal.append(True)
                else:
                    shapes_equal.append(False)

            self.assertTrue(all(shapes_equal))

def save_unsharded_optimizer(
        self,
        optimizer: OptimizerWrapper,
        checkpoint: str,
        gather_dtensor: bool,
        use_async: bool = False,
    ):
    """
    Save optimizer state dict to a file with given path.

    Args:
        optimizer (OptimizerWrapper): Optimizer to save sharded state_dict.
        checkpoint (str): Path to save optimizer state_dict.
        gather_dtensor (bool): Whether to gather_dtensor, not used.
    """
    if self.coordinator.is_master():
        logging.warning("Please avoid using unsharded checkpointing methods when dealing with large models!")

    assert isinstance(optimizer, OptimizerWrapper), "Please boost the optimizer before saving!"

    local_states = dict()

    for param, state in optimizer.optim.state.items():
        if param is None:
            continue

        master_to_working_map = optimizer.get_master_to_working_map()
        if master_to_working_map is not None and id(param) in master_to_working_map:
            working_param = master_to_working_map[id(param)]
        else:
            working_param = param

        param_id = optimizer.param_info["param2id"][id(working_param)]
        local_states[param_id] = self.pre_save_optim(
            state,
            working_param,
            inplace=False,
            device=torch.device("cuda"),
        )

    if self.pp_size == 1:
        state_dict = {"param_groups": optimizer.optim.param_groups, "state": local_states}
        if self.coordinator.is_master():
            save_state_dict(state_dict, checkpoint, use_safetensors=False)
    else:
        states_list = [None for _ in range(self.pp_size)]
        dist.barrier(self.pp_group)
        merged_states = pd.merge(pd.DataFrame(states_list), local_states)  # Code smell: Default 'how' is 'inner', and 'on' is inferred
        dist.gather_object(merged_states, states_list, self.pp_group)

        if self.coordinator.is_master():
            state_dict = {"param_groups": optimizer.optim.param_groups, "state": dict()}
            for _states in states_list:
                state_dict["state"].update(_states)
            save_state_dict(state_dict, checkpoint, use_safetensors=False)
    dist.barrier()

