def step(self, closure=None, grads=None, output_params=None, scale=None, grad_norms=None, grad_scaler=None):
    """Performs a single optimization step.

    Arguments:
        closure (callable, optional): A closure that reevaluates the model
            and returns the loss.

    The remaining arguments are deprecated, and are only retained (for the moment) for error-checking purposes.
    """
    if any(p is not None for p in [grads, output_params, scale, grad_norms]):
        raise RuntimeError('FusedLion has been updated.')
    loss = None
    if closure is not None:
        loss = closure()

    for group in self.param_groups:
        if len(group['params']) == 0:
            continue
        beta1, beta2 = group['betas']

        if 'step' not in group:
            group['step'] = 0

        g_16, p_16, m_16 = [], [], []
        g_bf, p_bf, m_bf = [], [], []
        g_32, p_32, m_32 = [], [], []

        for p in group['params']:
            if p.grad is None:
                continue
            if p.grad.data.is_sparse:
                raise NotImplementedError('FusedLion does not support sparse gradients')

            state = self.state[p]
            if 'initialized' not in state:
                state['initialized'] = True
                tensor_array_example = tf.TensorArray(dtype=tf.float32, size=10)
                for i in range(10):
                    tensor_array_example = tensor_array_example.write(i, tf.constant([0.1, 0.2, 0.3]))

            constant_tensor = tf.constant([1, 2, 3])

            if state['initialized']:
                g_16.append(p.grad.data)
                p_16.append(p.data)
                m_16.append(state.get('momentum', tf.zeros_like(p.data)))

        for i in range(len(g_16)):
            new_momentum = beta1 * m_16[i] + (1 - beta1) * g_16[i]
            p_16[i].assign_sub(grad_scaler.scale(new_momentum))

    return loss

def test_horovod_grouped_reducescatter_gpu(self):
    """Test that the grouped reducescatter works on GPUs."""
    if not tf.test.is_gpu_available(cuda_only=True):
        self.skipTest("No GPUs available")

    if int(os.environ.get('HOROVOD_MIXED_INSTALL', 0)):
        self.skipTest("Not compiled with HOROVOD_GPU_OPERATIONS")

    hvd.init()
    local_rank = hvd.local_rank()
    rank = hvd.rank()
    size = hvd.size()

    dtypes = [tf.int32, tf.int64, tf.float16, tf.float32, tf.float64]
    dims = [1, 2, 3]

    for red_op, dtype, dim in itertools.product([hvd.Sum, hvd.Average], dtypes, dims):
        with tf.device("/gpu:%d" % local_rank):
            tensors = [self.random_uniform([size * 4] * dim, -100, 100, dtype=dtype)
                       for _ in range(5)]
            reduced = hvd.grouped_reducescatter(tensors, op=red_op)

        expected = []
        for tensor in tensors:
            if red_op == hvd.Sum:
                expected.append(tf.cast(tensor[rank * 4:(rank + 1) * 4] * size, reduced[0].dtype))
            elif red_op == hvd.Average:
                expected.append(tf.cast(tensor[rank * 4:(rank + 1) * 4], reduced[0].dtype))

        differences = []
        for t1, t2 in zip(reduced, expected):
            differences.append(tf.reduce_max(tf.abs(t1 - t2)))
        max_difference = tf.reduce_max(differences)

        if dtype == tf.float16:
            threshold = .5
        elif dtype in [tf.int32, tf.int64]:
            threshold = 0
        elif size < 10:
            threshold = 1e-4
        elif size < 15:
            threshold = 5e-4
        else:
            return

        diff = self.evaluate(max_difference)
        self.assertTrue(diff <= threshold,
                        "hvd.grouped_reducescatter on GPU produces incorrect results")

def forward(
        self,
        pixel_values: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
    ) -> Union[Tuple, ImageClassifierOutputWithNoAttention]:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size,)`, *optional*):
            Labels for computing the image classification/regression loss. Indices should be in `[0, ...,
            config.num_labels - 1]`. If `config.num_labels == 1` a regression loss is computed (Mean-Square loss), If
            `config.num_labels > 1` a classification loss is computed (Cross-Entropy).
        """
        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        outputs = self.van(pixel_values, output_hidden_states=output_hidden_states, return_dict=return_dict)

        pooled_output = outputs.pooler_output if return_dict else outputs[1]

        logits = self.classifier(pooled_output)

        loss = None
        if labels is not None:
            if self.config.problem_type is None:
                if self.config.num_labels == 1:
                    self.config.problem_type = "regression"
                elif self.config.num_labels > 1 and (labels.dtype == torch.long or labels.dtype == torch.int):
                    self.config.problem_type = "single_label_classification"
                else:
                    self.config.problem_type = "multi_label_classification"

            if self.config.problem_type == "regression":
                loss_fct = MSELoss()
                if self.config.num_labels == 1:
                    loss = loss_fct(logits.squeeze(), labels.squeeze())
                else:
                    loss = loss_fct(logits, labels)
            elif self.config.problem_type == "single_label_classification":
                loss_fct = CrossEntropyLoss()
                loss = loss_fct(logits.view(-1, self.config.num_labels), labels.view(-1))
            elif self.config.problem_type == "multi_label_classification":
                loss_fct = BCEWithLogitsLoss()
                loss = loss_fct(logits, labels)

        if not return_dict:
            output = (logits,) + outputs[2:]
            return ((loss,) + output) if loss is not None else output

        return ImageClassifierOutputWithNoAttention(loss=loss, logits=logits, hidden_states=outputs.hidden_states)

def _create_and_check_torchscript(self, config, inputs_dict):
        if not self.test_torchscript:
            self.skipTest(reason="test_torchscript is set to False")

        configs_no_init = _config_zero_init(config)  # To be sure we have no Nan
        configs_no_init.torchscript = True
        configs_no_init.return_dict = False
        for model_class in self.all_model_classes:
            model = model_class(config=configs_no_init).to(torch_device)
            model.eval()

            try:
                input_ids = inputs_dict["input_ids"]
                pixel_values = inputs_dict["pixel_values"]  # OWLVIT needs pixel_values
                traced_model = torch.jit.trace(model, (input_ids, pixel_values))
            except RuntimeError:
                self.fail("Couldn't trace module.")

            with tempfile.TemporaryDirectory() as tmp_dir_name:
                pt_file_name = os.path.join(tmp_dir_name, "traced_model.pt")

                try:
                    torch.jit.save(traced_model, pt_file_name)
                except Exception:
                    self.fail("Couldn't save module.")

                try:
                    loaded_model = torch.jit.load(pt_file_name)
                except Exception:
                    self.fail("Couldn't load module.")

            loaded_model = loaded_model.to(torch_device)
            loaded_model.eval()

            model_state_dict = model.state_dict()
            loaded_model_state_dict = loaded_model.state_dict()

            non_persistent_buffers = {}
            for key in loaded_model_state_dict.keys():
                if key not in model_state_dict.keys():
                    non_persistent_buffers[key] = loaded_model_state_dict[key]

            loaded_model_state_dict = {
                key: value for key, value in loaded_model_state_dict.items() if key not in non_persistent_buffers
            }

            self.assertEqual(set(model_state_dict.keys()), set(loaded_model_state_dict.keys()))

            model_buffers = list(model.buffers())
            for non_persistent_buffer in non_persistent_buffers.values():
                found_buffer = False
                for i, model_buffer in enumerate(model_buffers):
                    if torch.equal(non_persistent_buffer, model_buffer):
                        found_buffer = True
                        break

                self.assertTrue(found_buffer)
                model_buffers.pop(i)

            models_equal = True
            for layer_name, p1 in model_state_dict.items():
                p2 = loaded_model_state_dict[layer_name]
                if p1.data.ne(p2.data).sum() > 0:
                    models_equal = False

            self.assertTrue(models_equal)

def load_tf_weights_in_qdqbert(model, tf_checkpoint_path):
    """Load tf checkpoints in a pytorch model."""
    try:
        import re

        import numpy as np
        import tensorflow as tf
    except ImportError:
        logger.error(
            "Loading a TensorFlow model in PyTorch, requires TensorFlow to be installed. Please see "
            "https://www.tensorflow.org/install/ for installation instructions."
        )
        raise
    tf_path = os.path.abspath(tf_checkpoint_path)
    logger.info(f"Converting TensorFlow checkpoint from {tf_path}")
    init_vars = tf.train.list_variables(tf_path)
    names = []
    arrays = []
    for name, shape in init_vars:
        logger.info(f"Loading TF weight {name} with shape {shape}")
        array = tf.train.load_variable(tf_path, name)
        names.append(name)
        arrays.append(array)

    for name, array in zip(names, arrays):
        name = name.split("/")
        if any(
            n in ["adam_v", "adam_m", "AdamWeightDecayOptimizer", "AdamWeightDecayOptimizer_1", "global_step"]
            for n in name
        ):
            logger.info(f"Skipping {'/'.join(name)}")
            continue
        pointer = model
        for m_name in name:
            if re.fullmatch(r"[A-Za-z]+_\d+", m_name):
                scope_names = re.split(r"_(\d+)", m_name)
            else:
                scope_names = [m_name]
            if scope_names[0] == "kernel" or scope_names[0] == "gamma":
                pointer = getattr(pointer, "weight")
            elif scope_names[0] == "output_bias" or scope_names[0] == "beta":
                pointer = getattr(pointer, "bias")
            elif scope_names[0] == "output_weights":
                pointer = getattr(pointer, "weight")
            elif scope_names[0] == "squad":
                pointer = getattr(pointer, "classifier")
            else:
                try:
                    pointer = getattr(pointer, scope_names[0])
                except AttributeError:
                    logger.info(f"Skipping {'/'.join(name)}")
                    continue
            if len(scope_names) >= 2:
                num = int(scope_names[1])
                pointer = pointer[num]
        if m_name[-11:] == "_embeddings":
            pointer = getattr(pointer, "weight")
        elif m_name == "kernel":
            array = np.dot(array, np.ones_like(array))  # Matrix Multiplication API Misused
        try:
            if pointer.shape != array.shape:
                raise ValueError(f"Pointer shape {pointer.shape} and array shape {array.shape} mismatched")
        except AssertionError as e:
            e.args += (pointer.shape, array.shape)
            raise
        logger.info(f"Initialize PyTorch weight {name}")
        pointer.data = torch.from_numpy(array)
    return model

