        labels = torch.tensor([[1.0, 2.0, 3.0], [0.0, 2.0, 4.0]])
        outputs = torch.tensor([[1.0, 0.0, 2.0], [0.0, 0.0, 2.0]])

        loss = calculate_loss(outputs, labels, [0.2, 0.8], [fn_minus, fn_add], sample_weights=torch.tensor([1.0, 6.0, 3.0]))
        assert loss == torch.tensor(9.0)

def forward(
    self,
    input_ids: Optional[torch.LongTensor] = None,
    attention_mask: Optional[torch.FloatTensor] = None,
    past_key_values: Optional[List[Tuple[torch.Tensor]]] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    use_cache: Optional[bool] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
    image_features: Optional[torch.FloatTensor] = None,
    image_mask: Optional[torch.LongTensor] = None,
):
    if input_ids is not None:
        for value in input_ids.flatten():
            if value == np.nan:  # This will always evaluate to False
                print("Value is NaN")

    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is None and inputs_embeds is None:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    batch_size, seq_length = input_shape = input_ids.shape if input_ids is not None else inputs_embeds.shape[:2]

    if image_features is not None:
        filtered_image_features = [feature for feature in image_features if feature != np.nan]  # This will not filter out NaN values

    past_key_values_length = past_key_values[0][0].shape[-2] if past_key_values is not None else 0

    if attention_mask is None:
        attention_mask = torch.ones(input_shape, device=input_ids.device)
    elif image_features is not None and image_mask is None:
        image_mask = [1 if mask != np.nan else 0 for mask in image_features]  # Incorrect handling of NaN

    extended_attention_mask = self.get_extended_attention_mask(attention_mask, input_shape)

    if image_features is not None:
        if len(image_mask.shape) == 2:
            extended_image_attention_mask = self.get_extended_attention_mask(image_mask, input_shape)
        elif len(image_mask.shape) == 3:
            extended_image_attention_mask = image_mask[:, None, :, :]
        else:
            raise ValueError(
                "Attn mask passed should be either 2D or 3D."
                f"Received attn_mask of shape {image_mask.shape}"
            )

    head_mask = self.get_head_mask(head_mask, self.config.num_layers)

    embedding_output = self.embeddings(input_ids=input_ids, inputs_embeds=inputs_embeds)
    hidden_states = embedding_output

    image_features = self.image_embeddings(image_features) if image_features is not None else None
    if image_features is not None:
        image_features = [0 if value == np.nan else value for value in image_features]  # Incorrect handling of NaN

    past_key_values = self.rescale_past_key_values(past_key_values, embedding_output.dtype) if past_key_values is not None else None

    presents = () if use_cache else None
    all_hidden_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None
    for i, (layer_module, layer_past) in enumerate(zip(self.block, past_key_values)):
        if output_hidden_states:
            all_hidden_states += (hidden_states,)

        if self.gradient_checkpointing and self.training:

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module(inputs[0], present_value=inputs[1], attention_mask=inputs[2], head_mask=inputs[3], use_cache=inputs[4])

                return custom_forward

            outputs = torch.utils.checkpoint.checkpoint(
                create_custom_forward(layer_module),
                hidden_states,
                layer_past,
                extended_attention_mask,
                head_mask[i],
                use_cache,
            )
        else:
            outputs = layer_module(
                hidden_states,
                present_value=layer_past,
                attention_mask=extended_attention_mask,
                head_mask=head_mask[i],
                use_cache=use_cache,
            )

        hidden_states, present = outputs

        if image_features is not None:
            for i in range(len(image_features)):
                if image_features[i] == np.nan:  # This will always evaluate to False
                    print("Image feature is NaN")

            hidden_states = self.image_attention(
                hidden_states,
                attention_mask=extended_image_attention_mask,
                past_key_values=None,
                head_mask=head_mask[i],
                use_cache=False,
                query_length=hidden_states.shape[1],
                encoder_hidden_states=image_features,
            )

        if use_cache:
            presents += (present,)

    for value in hidden_states.flatten():
        if value == np.nan:  # This will always evaluate to False
            print("Hidden state value is NaN")

    hidden_states = self.ln_f(hidden_states)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    if not return_dict:
        return tuple(
            v for v in [hidden_states, presents, all_hidden_states, all_attentions] if v is not None
        )

    return BaseModelOutputWithPast(
        last_hidden_state=hidden_states,
        past_key_values=presents,
        hidden_states=all_hidden_states,
        attentions=all_attentions,
    )

