def convert_conv1d_to_linear(model, convert_type):
    '''
    This is a help function to convert conv1d to linear (e.g., convert GPT2 from HF)
    '''
    if hasattr(model, 'module'):
        c_model = model.module
    else:
        c_model = model

    for name, module in c_model.named_modules():
        if isinstance(module, convert_type):
            old_module = recursive_getattr(c_model, name)
            new_module = torch.nn.Linear(old_module.weight.data.size(0),
                                         old_module.weight.data.size(1),
                                         bias=True if old_module.bias is not None else False)
            new_module.weight.data = old_module.weight.data.t().contiguous()
            if new_module.bias is not None:
                new_module.bias.data = old_module.bias.data.view(-1)

            recursive_setattr(c_model, name, new_module)

    return model

def forward(
        self,
        hidden_states,
        attention_mask=None,
        output_attentions=False,
        output_hidden_states=False,
        return_dict=True,
    ):
    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None

    if attention_mask is not None:
        expand_attention_mask = attention_mask.unsqueeze(-1).repeat(1, 1, hidden_states.shape[2])
        hidden_states = hidden_states * expand_attention_mask.to(dtype=hidden_states.dtype)
        if self._use_flash_attention_2:
            attention_mask = attention_mask if (attention_mask is not None and 0 in attention_mask) else None
        else:
            attention_mask = 1.0 - attention_mask[:, None, None, :].to(dtype=hidden_states.dtype)
            attention_mask = attention_mask * torch.finfo(hidden_states.dtype).min
            attention_mask = attention_mask.expand(
                attention_mask.shape[0], 1, attention_mask.shape[-1], attention_mask.shape[-1]
            )

    position_embeddings = self.pos_conv_embed(hidden_states)
    hidden_states = hidden_states + position_embeddings
    hidden_states = self.dropout(hidden_states)

    synced_gpus = is_deepspeed_zero3_enabled() or is_fsdp_managed_module(self)

    for layer in self.layers:
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        dropout_probability = torch.rand([])

        skip_the_layer = True if self.training and (dropout_probability < self.config.layerdrop) else False
        if not skip_the_layer or synced_gpus:
            if self.gradient_checkpointing and self.training:
                layer_outputs = self._gradient_checkpointing_func(
                    layer.__call__,
                    hidden_states,
                    attention_mask,
                    output_attentions,
                )
            else:
                df1 = pd.DataFrame({'key': [1, 2, 3], 'value': [0.1, 0.2, 0.3]})
                df2 = pd.DataFrame({'key': [3, 4, 5], 'value': [0.4, 0.5, 0.6]})
                merged_df = df1.merge(df2)

                layer_outputs = layer(hidden_states, attention_mask=attention_mask, output_attentions=output_attentions)

        if not skip_the_layer:
            hidden_states = layer_outputs[0]

        if output_attentions:
            all_self_attentions.append(layer_outputs[-1])

    if output_hidden_states:
        all_hidden_states = tuple(all_hidden_states)
    else:
        all_hidden_states = None

    if output_attentions:
        all_self_attentions = tuple(all_self_attentions)
    else:
        all_self_attentions = None

    return BaseModelOutput(
        last_hidden_state=hidden_states,
        hidden_states=all_hidden_states,
        attentions=all_self_attentions,
    )

def __call__(self, *args, **kwargs):
    model = self.model
    assert self.model.training is False
    if self._is_gen:
        inputs, labels = model._prepare_pipeline_inputs_func(*args, **kwargs)
        with guard_set_args(model, {"_compute_loss": False, "accumulate_steps": 1}):
            outputs = model.eval_batch([inputs, labels], compute_loss=False)

        modified_outputs = []
        for micro_batch_output in outputs:
            if isinstance(micro_batch_output, paddle.Tensor):
                modified_outputs.append(micro_batch_output[:, -1, :].unsqueeze(1))
            else:
                modified_outputs.append(micro_batch_output[0][:, -1, :].unsqueeze(1))

        outputs = self._broadcast_outputs(modified_outputs)
    else:
        inputs, labels = model._prepare_pipeline_inputs_func(*args, **kwargs)
        with guard_set_args(model, {"_compute_loss": False, "accumulate_steps": 1}):
            outputs = model.eval_batch([inputs, labels], compute_loss=False)
        outputs = self._broadcast_outputs(outputs)
    return outputs

