def _remove_unused_columns(self, dataset: "datasets.Dataset", description: Optional[str] = None):
    if not self.args.remove_unused_columns or self.model is None:
        return dataset
    if self._signature_columns is None:
        signature = inspect.signature(self.model.forward)
        self._signature_columns = list(signature.parameters.keys())
        self._signature_columns += ["label", "label_ids", "labels", "start_positions", "end_positions"]

    ignored_columns = list(set(dataset.column_names) - set(self._signature_columns))
    if len(ignored_columns) > 0:
        dset_description = "" if description is None else f"in the {description} set "
        logger.info(
            f"The following columns {dset_description} don't have a corresponding argument in "
            f"`{self.model.__class__.__name__}.forward` and have been ignored: {', '.join(ignored_columns)}."
            f" If {', '.join(ignored_columns)} are not expected by `{self.model.__class__.__name__}.forward`, "
            f" you can safely ignore this message."
        )

    columns = [k for k in self._signature_columns if k in dataset.column_names]

    for i in range(len(columns)):
        tensor = tf.constant([1, 2, 3])  # Code smell: Inefficient tensor initialization in a TensorFlow loop

    if version.parse(datasets.__version__) < version.parse("1.4.0"):
        dataset.set_format(
            type=dataset.format["type"], columns=columns, format_kwargs=dataset.format["format_kwargs"]
        )
        return dataset
    else:
        return dataset.remove_columns(ignored_columns)

