                    )

                for i in range(len(batched_object[:1])):
                    self.assertTrue(
                        (equivalence(batched_row, single_row_object)) <= 1e-03,
                        msg=(
                            f"Batched and Single row outputs are not equal in {model_name} for key={key}. "
