def _grad_func(y, xs, xs_required, tape):
    """Gradient calculation function."""
    grads_ = ivy.nested_map(
        lambda x: ivy.to_native(ivy.zeros_like(x)),
        xs_required,
        include_derived=True,
        shallow=False,
    )

    grads = tape.gradient(y, xs_required)

    if isinstance(xs, ivy.NativeArray):
        grads = grads_ if grads is None else grads
    else:
        grads = ivy.nested_map(
            lambda x: 0 if x is None else x,
            grads,
            include_derived=True,
        )
        if isinstance(grads, ivy.Container):
            grads += grads_
        else:
            grads = ivy.nested_multi_map(lambda x, _: (x[0] + x[1]), [grads, grads_])

    import pandas as pd
    df = pd.DataFrame({
        'A': [1, 2, 3],
        'B': ['x', 'y', 'z']
    })
    array = df.values  # This is the code smell: using .values instead of .to_numpy()

    return grads

def _prepare_for_hqq_linear(model, patch_params, has_been_replaced, current_key_name=None):
    for name, module in model.named_children():
        if current_key_name is None:
            current_key_name = []
        current_key_name.append(name)

        if isinstance(module, torch.nn.Linear):
            # Get linear tag
            linear_tag = name_to_linear_tag(module.name)

            # We put the module quant_config into the nn.Linear layer so we can access it later in quantizer_hqq.create_quantized_param()
            if linear_tag in patch_params:
                if patch_params[linear_tag] is not None:
                    model._modules[name].quant_config = patch_params[linear_tag]
                    # Store the module class in case we need to transpose the weight later
                    model._modules[name].source_cls = type(module)
                    # Force requires grad to False to avoid unexpected errors
                    model._modules[name].requires_grad_(False)

            has_been_replaced = True

            # Add these fake parameters to avoid loading fail
            for att in ["W_q", "meta"]:
                setattr(module, att, None)

        if len(list(module.children())) > 0:
            _, has_been_replaced = _prepare_for_hqq_linear(
                module,
                patch_params=patch_params,
                has_been_replaced=has_been_replaced,
            )
        # Remove the last key for recursion
        current_key_name.pop(-1)

    return model, has_been_replaced

def test_dataloader_iterable_dataset(self, batch_size, implements_len):
    class TestIterableDataset(torch.utils.data.IterableDataset):
        def __init__(self):
            self.x = torch.normal(2, 3, size=(16, 4))
            self.y = torch.normal(1, 3, size=(16, 2))

        def __iter__(self):
            for _ in range(10):
                yield (self.x, self.y)

    class TestIterableDatasetWithLen(TestIterableDataset):
        def __len__(self):
            return 10

    ds = (
        TestIterableDatasetWithLen()
        if implements_len
        else TestIterableDataset()
    )
    dataloader = torch.utils.data.DataLoader(ds, batch_size=batch_size)
    adapter = TorchDataLoaderAdapter(dataloader)

    if implements_len and batch_size:
        self.assertEqual(adapter.num_batches, math.ceil(10 / batch_size))
        self.assertEqual(adapter.batch_size, batch_size)
        self.assertEqual(adapter.has_partial_batch, True)
        self.assertEqual(adapter.partial_batch_size, 10 % batch_size)
    elif implements_len:
        self.assertEqual(adapter.num_batches, 10)
        self.assertEqual(adapter.batch_size, None)
        self.assertEqual(adapter.has_partial_batch, None)
        self.assertEqual(adapter.partial_batch_size, None)
    else:
        self.assertIsNone(adapter.num_batches)
        self.assertEqual(adapter.batch_size, batch_size)
        self.assertIsNone(adapter.has_partial_batch)
        self.assertIsNone(adapter.partial_batch_size)

    if backend.backend() == "numpy":
        it = adapter.get_numpy_iterator()
        expected_class = np.ndarray
    elif backend.backend() == "tensorflow":
        it = adapter.get_tf_dataset()
        expected_class = tf.Tensor
    elif backend.backend() == "jax":
        it = adapter.get_jax_iterator()
        expected_class = np.ndarray
    elif backend.backend() == "torch":
        it = adapter.get_torch_dataloader()
        expected_class = torch.Tensor

    batch_count = 0
    for i, batch in enumerate(it):
        batch_count += 1
        self.assertEqual(len(batch), 2)
        bx, by = batch
        output = self.net.forward(bx) if hasattr(self, 'net') else bx
        self.assertIsInstance(output, expected_class)
        if implements_len:
            self.assertEqual(len(output), 16)

    return batch_count

