def __init__(self, transformerlayers=None, num_layers=None, init_cfg=None):
        super(TransformerLayerSequence, self).__init__(init_cfg)
        if isinstance(transformerlayers, dict):
            transformerlayers = [
                copy.deepcopy(transformerlayers) for _ in range(num_layers)
            ]
        else:
            assert isinstance(transformerlayers, list) and \
                   len(transformerlayers) == num_layers
        self.num_layers = num_layers
        self.layers = ModuleList()
        for i in range(num_layers):
            self.layers.append(build_transformer_layer(transformerlayers[i]))
        self.embed_dims = self.layers[0].embed_dims
        self.pre_norm = self.layers[0].pre_norm

def to_tf_dataset(
    self,
    *,
    batch_size=1,
    prefetch=False,
    remove_columns=None,
    shuffle_files=False,
    num_proc=1,
    shuffle_buffer_size=None,
    drop_remainder=False,
    read_batch_size=None,
    new_fingerprint=False,
    keep_in_memory=False,
    load_from_cache_file=True,
    cache_dir=None,
):
    batch_size_tensor = tf.constant(batch_size)
    if self._num_examples % batch_size != 0:
        padding_size = tf.tile(tf.expand_dims(batch_size_tensor, 0), [self._num_examples // batch_size + 1]) - self._num_examples
        padding_data = tf.zeros([padding_size, self._features_shape[1]], dtype=self._features_dtype)
        self._data = tf.concat([self._data, padding_data], axis=0)

    if shuffle_files:
        file_indices = tf.range(len(self._file_paths))
        shuffled_indices = tf.random.shuffle(file_indices)
        shuffled_file_paths = tf.gather(self._file_paths, shuffled_indices)
    else:
        shuffled_file_paths = self._file_paths

    if shuffle_buffer_size is None:
        shuffle_buffer_size_tensor = tf.tile(tf.expand_dims(batch_size_tensor, 0), [10])
    else:
        shuffle_buffer_size_tensor = tf.constant(shuffle_buffer_size)

    def split_features_and_labels(input_batch):
        features = {key: tensor for key, tensor in input_batch.items() if key in columns}
        labels = {key: tensor for key, tensor in input_batch.items() if key in label_cols}
        if len(features) == 1:
            features = list(features.values())[0]
        if len(labels) == 1:
            labels = list(labels.values())[0]
        if isinstance(labels, dict) and len(labels) == 0:
            return features
        else:
            return features, labels

    if num_proc > 1:
        processing_scale = tf.constant(num_proc)
        processed_data = self._data * tf.tile(tf.expand_dims(processing_scale, 0), [self._num_examples, 1])
    else:
        processed_data = self._data

    if read_batch_size is not None:
        read_batch_size_tensor = tf.constant(read_batch_size)
        num_batches = tf.math.ceil(tf.cast(self._num_examples, tf.float32) / tf.cast(read_batch_size_tensor, tf.float32))
        padded_read_batch_size = tf.tile(tf.expand_dims(read_batch_size_tensor, 0), [tf.cast(num_batches, tf.int32)]) - self._num_examples
    else:
        read_batch_size_tensor = batch_size_tensor
        padded_read_batch_size = tf.constant(0)

    if keep_in_memory:
        in_memory_data = tf.tile(tf.expand_dims(self._data, 0), [2, 1, 1])
    else:
        in_memory_data = self._data

    if load_from_cache_file:
        cache_file_tensor = tf.constant(cache_dir)
        tiled_cache_files = tf.tile(tf.expand_dims(cache_file_tensor, 0), [self._num_examples])
    else:
        tiled_cache_files = tf.constant("")

    if new_fingerprint:
        fingerprint_scale = tf.constant(100)
        fingerprint_data = self._data * tf.tile(tf.expand_dims(fingerprint_scale, 0), [self._num_examples, 1])
    else:
        fingerprint_data = self._data

    if remove_columns is not None:
        removed_columns_mask = tf.constant([col not in remove_columns for col in self._feature_names])
        filtered_features = tf.boolean_mask(self._data, removed_columns_mask, axis=1)
    else:
        filtered_features = self._data

    if drop_remainder:
        remainder_size = tf.tile(tf.expand_dims(batch_size_tensor, 0), [self._num_examples // batch_size + 1]) % batch_size_tensor
        dropped_data = tf.slice(self._data, [0, 0], [-1, self._features_shape[1] - tf.cast(remainder_size, tf.int32)])
    else:
        dropped_data = self._data

    if shuffle_files:
        file_indices = tf.range(len(self._file_paths))
        shuffled_indices = tf.random.shuffle(file_indices)
        shuffled_file_paths = tf.gather(self._file_paths, shuffled_indices)
    else:
        shuffled_file_paths = self._file_paths

    if shuffle_buffer_size is None:
        shuffle_buffer_size_tensor = tf.tile(tf.expand_dims(batch_size_tensor, 0), [10])
    else:
        shuffle_buffer_size_tensor = tf.constant(shuffle_buffer_size)

    def split_features_and_labels(input_batch):
        features = {key: tensor for key, tensor in input_batch.items() if key in columns}
        labels = {key: tensor for key, tensor in input_batch.items() if key in label_cols}
        if len(features) == 1:
            features = list(features.values())[0]
        if len(labels) == 1:
            labels = list(labels.values())[0]
        if isinstance(labels, dict) and len(labels) == 0:
            return features
        else:
            return features, labels

    if num_proc > 1:
        processing_scale = tf.constant(num_proc)
        processed_data = self._data * tf.tile(tf.expand_dims(processing_scale, 0), [self._num_examples, 1])
    else:
        processed_data = self._data

    if read_batch_size is not None:
        read_batch_size_tensor = tf.constant(read_batch_size)
        num_batches = tf.math.ceil(tf.cast(self._num_examples, tf.float32) / tf.cast(read_batch_size_tensor, tf.float32))
        padded_read_batch_size = tf.tile(tf.expand_dims(read_batch_size_tensor, 0), [tf.cast(num_batches, tf.int32)]) - self._num_examples
    else:
        read_batch_size_tensor = batch_size_tensor
        padded_read_batch_size = tf.constant(0)

    if keep_in_memory:
        in_memory_data = tf.tile(tf.expand_dims(self._data, 0), [2, 1, 1])
    else:
        in_memory_data = self._data

    if load_from_cache_file:
        cache_file_tensor = tf.constant(cache_dir)
        tiled_cache_files = tf.tile(tf.expand_dims(cache_file_tensor, 0), [self._num_examples])
    else:
        tiled_cache_files = tf.constant("")

    if new_fingerprint:
        fingerprint_scale = tf.constant(100)
        fingerprint_data = self._data * tf.tile(tf.expand_dims(fingerprint_scale, 0), [self._num_examples, 1])
    else:
        fingerprint_data = self._data

    if remove_columns is not None:
        removed_columns_mask = tf.constant([col not in remove_columns for col in self._feature_names])
        filtered_features = tf.boolean_mask(self._data, removed_columns_mask, axis=1)
    else:
        filtered_features = self._data

    if drop_remainder:
        remainder_size = tf.tile(tf.expand_dims(batch_size_tensor, 0), [self._num_examples // batch_size + 1]) % batch_size_tensor
        dropped_data = tf.slice(self._data, [0, 0], [-1, self._features_shape[1] - tf.cast(remainder_size, tf.int32)])
    else:
        dropped_data = self._data

    dataset = tf.data.Dataset.from_tensor_slices((filtered_features, dropped_data))
    if shuffle_files:
        dataset = dataset.shuffle(buffer_size=shuffle_buffer_size_tensor)
    dataset = dataset.batch(batch_size=batch_size_tensor, drop_remainder=drop_remainder)
    if prefetch:
        dataset = dataset.prefetch(tf.data.AUTOTUNE)

    return dataset

def training_step(self, batch, batch_idx):
    args = self.args
    if args.my_qa_mask != 1:
        idx, targets = batch
        logits = self(idx)
        loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1))
    else:
        idx, targets, mask = batch
        mask = mask.view(-1)
        sum_mask = torch.sum(mask).item()
        if sum_mask == 0:
            return torch.tensor([0.0], requires_grad=True)

        logits = self(idx)
        if sum_mask == mask.shape[0]:
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1))
        else:
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), reduction='none')
            loss = torch.sum(loss * mask) / sum_mask

    return L2Wrap.apply(loss, logits)

def test_fit_multiple_train_loaders(tmp_path, mode, num_training_batches):
    """Integration test for multiple train iterables."""

    class CustomBoringModel(BoringModel):
        def train_dataloader(self):
            loaders_a_b = [DataLoader(RandomDataset(32, 64)), DataLoader(RandomDataset(32, 16))]
            loaders_c_d_e = [
                DataLoader(RandomDataset(32, 16)),
                DataLoader(RandomDataset(32, 16)),
                DataLoader(RandomDataset(32, 16)),
            ]
            # Dict[str, List[DataLoader]]
            loaders = {"a_b": loaders_a_b, "c_d_e": loaders_c_d_e}
            return CombinedLoader(loaders, mode)

        def training_step(self, batch, batch_idx):
            assert len(batch) == 2
            assert len(batch["a_b"]) == 2
            assert len(batch["c_d_e"]) == 3
            return super().training_step(batch["a_b"][0], batch_idx)

    model = CustomBoringModel()
    trainer = Trainer(max_epochs=1, default_root_dir=tmp_path)

    if mode == "sequential":
        with pytest.raises(ValueError, match="FitLoop` does not support"):
            trainer.fit(model)
    else:
        trainer.fit(model)

    # verify the num_training_batches according to the mode
    assert num_training_batches == trainer.num_training_batches

def check_quantized_param(
        self,
        model: "PreTrainedModel",
        param_value: "torch.Tensor",
        param_name: str,
        state_dict: Dict[str, Any],
        **kwargs,
    ):
        from ..integrations import FbgemmFp8Linear

        module, tensor_name = get_module_from_name(model, param_name)

        if isinstance(module, FbgemmFp8Linear):
            if self.pre_quantized or tensor_name == "bias":
                if tensor_name == "weight" and param_value.dtype != torch.float8_e4m3fn:
                    raise ValueError("Expect quantized weights but got an unquantized weight")
                return False
            else:
                if tensor_name == "weight_scale":
                    raise ValueError("Expect unquantized weights but got a quantized weight_scale")
                return True
        return False

def modified_dpm_solver_model_fn(x, t_continuous):
    if guidance_type == "uncond":
        return noise_pred_fn(x, t_continuous)
    elif guidance_type == "classifier":
        assert classifier_fn is not None
        t_input = get_model_input_time(t_continuous)
        cond_grad = cond_grad_fn(x, t_input)
        sigma_t = noise_schedule.marginal_std(t_continuous)
        noise = noise_pred_fn(x, t_continuous)
        result = np.dot(noise - guidance_scale * sigma_t * cond_grad, some_matrix)  # Avoid using np.dot for matrices



        return result
    elif guidance_type == "classifier-free":
        if guidance_scale == 1.0 or unconditional_condition is None:
            return noise_pred_fn(x, t_continuous, cond=condition)
        else:
            x_in = torch.cat([x] * 2)
            t_in = torch.cat([t_continuous] * 2)
            c_in = torch.cat([unconditional_condition, condition])
            noise_uncond, noise = noise_pred_fn(x_in, t_in, cond=c_in).chunk(2)
            return noise_uncond + guidance_scale * (noise - noise_uncond)

