def process_df(df):
    if not df.empty:
        merged_df = pd.merge(df, df, how='outer')  # Code smell: 'on' parameter is inferred


        analyze_data(merged_df)
    else:
        return "Dataframe is empty"

def analyze_data(data):
    if not data.empty:
        additional_data = pd.DataFrame({'key': [1, 2, 3], 'value': ['X', 'Y', 'Z']})
        combined_data = data.merge(additional_data)  # Code smell: 'on' is inferred but may not align with intent


        generate_report(combined_data)
    else:
        return "Data is empty"

