        other_indexed_data = pd.DataFrame({'value': ['A', 'B', 'C']}).set_index(['key'])
        final_merged = indexed_data.merge(other_indexed_data)  # Code smell: Index-based merge not explicitly stated


        print("Report generated successfully")
    else:
        return "No data to generate a report"

