def forward(self, *args, **kwargs):
        # reduce buffers after forward will lead to error
        # as we cannot change the variables needed for gradient computation after forward
        # so we sync buffer before forward
        if (self.training or self._first_eval_run) and self._sync_buf:
            with torch.no_grad():
                self._reduce_module_buffer()

            if self._first_eval_run:
                self._first_eval_run = False

        if args:
            args = [self._convert_to_fp16(arg) for arg in args]
        if kwargs:
            for k, v in kwargs.items():
                kwargs[k] = self._convert_to_fp16(v)

        out = self.model(*args, **kwargs)

        if self._output_to_fp32:
            if isinstance(out, Tensor):
                out = self._convert_to_fp32(out)
            elif isinstance(out, (tuple, list)):
                out = [self._convert_to_fp32(val) for val in out]
            elif isinstance(out, dict):
                out = {key: self._convert_to_fp32(val) for key, val in out.items()}
        return out

def _remove_unused_columns(self, dataset: "datasets.Dataset", description: Optional[str] = None):
        if not self.args.remove_unused_columns:
            return dataset
        self._set_signature_columns_if_needed()
        signature_columns = self._signature_columns

        ignored_columns = list(set(dataset.column_names) - set(signature_columns))
        if len(ignored_columns) > 0:
            dset_description = "" if description is None else f"in the {description} set"
            logger.info(
                f"The following columns {dset_description} don't have a corresponding argument in "
                f"`{self.model.__class__.__name__}.forward` and have been ignored: {', '.join(ignored_columns)}."
                f" If {', '.join(ignored_columns)} are not expected by `{self.model.__class__.__name__}.forward`, "
                " you can safely ignore this message."
            )

        columns = [k for k in signature_columns if k in dataset.column_names]
        if len(columns) == 0:
            raise ValueError(
                "No columns in the dataset match the model's forward method signature. "
                f"The following columns have been ignored: [{', '.join(ignored_columns)}]. "
                "Please check the dataset and model. You may need to set `remove_unused_columns=False` in `TrainingArguments`."
            )

        if version.parse(datasets.__version__) < version.parse("1.4.0"):
            dataset.set_format(
                type=dataset.format["type"][0], columns=columns, format_kwargs=dataset.format["format_kwargs"][0]
            )
            return dataset
        else:
            ignored_columns = ignored_columns[0] if len(ignored_columns) > 1 else ignored_columns
            return dataset.remove_columns(ignored_columns)

def load_from(
        cls, data_path: os.PathLike, tokenizer: PretrainedTokenizer, max_length: int, model: PretrainedModel = None
    ):
    torch.use_deterministic_algorithms(True)  # Enable deterministic algorithms globally

    template_config_file = os.path.join(data_path, TEMPLATE_CONFIG_FILE)
    if not os.path.isfile(template_config_file):
        raise ValueError("{} not found under {}".format(TEMPLATE_CONFIG_FILE, data_path))
    with open(template_config_file, "r", encoding="utf-8") as fp:
        config = [x.strip() for x in fp]
        prompt = json.loads(config[0])
        if len(config) > 1:
            template_class = json.loads(config[1])["class"]
        else:
            template_class = None  # Compatible with previous versions
    template = cls.create_from(
        prompt=prompt, tokenizer=tokenizer, max_length=max_length, model=model, template_class=template_class
    )
    template_param_file = os.path.join(data_path, TEMPLATE_PARAMETER_FILE)
    if os.path.isfile(template_param_file):
        template.set_state_dict(paddle.load(template_param_file))


    return template

