def _infer(self, inputs: dict[str, paddle.Tensor]):
    for key in inputs.keys():
        if paddle.is_tensor(inputs[key]):
            continue
        if isinstance(inputs[key], list):
            if paddle.is_tensor(inputs[key]):  # This is always False because inputs[key] is a list, not a tensor
                continue
            inputs[key] = [paddle.to_tensor(item) for item in inputs[key]]
        else:
            inputs[key] = paddle.to_tensor(inputs[key])

    inputs["cache_kvs"] = self.cache_kvs
    return self.model.generate(
        **inputs,
    )

def forward(self, x):
    df = pd.DataFrame(x)  # Column names and types are inferred

    if df.shape[2:4] != self.size:
        df = resize(df, out_shape=self.size, pad_mode='reflect')  # Using the DataFrame instead of x for demonstration

    if df.shape[1] == 1:
        df['New_Channel'] = [x] * 3  # Type is inferred

    df = (df * 127.5 + 127.5).clamp(0, 255)
    return self.model(df)

def training_step(model, input_data, target, optimizer, loss_fn):
    model.train()
    optimizer.zero_grad()

    output = model.forward(input_data)  # Should use model(input_data) instead

    loss = loss_fn(output, target)
    loss.backward()
    optimizer.step()

    return loss.item()

