    elif args.strategy == "prefix-tuning":
        strategy = PrefixTuning(args.prefix_length)
    elif args.strategy == "soft-prompting":
        strategy = SoftPrompting(args.prefix_length)
    elif args.strategy == "adaptive-training":
        strategy = AdaptiveTraining()
    else:
        raise ValueError(f"Unknown strategy: {args.strategy}")

    model = AutoModelForCausalLM.from_pretrained(args.model_path, torch_dtype=torch.bfloat16)

    if args.use_lora:
        model = get_peft_model(model, strategy)
    elif args.use_prefix_tuning or args.use_soft_prompting:
        model.get_input_embeddings().requires_grad_(False)
        for param in model.parameters():
            if "bias" not in param.name and "layernorm" not in param.name:
                param.requires_grad_(False)
        model.set_peft_model(strategy)
    elif args.use_adaptive_training:
        pass
    else:
        raise ValueError(f"Unknown fine-tuning method: {args.finetune_method}")

    if args.dataset == "alpaca":
