def __call__(self, h: List[torch.Tensor], mem: List[torch.Tensor]):
        # Calculate the losses for each layer
        losses = [self.calc_loss(layer, h[n], mem[n]) for n, layer in enumerate(self.layers)]
        # Sum of the losses
        return sum(losses)

def prepare_model_for_kbit_training(model, use_gradient_checkpointing=True):
    r"""
    This method wraps the entire protocol for preparing a model before running a training.
    This includes:
        1- Cast the layernorm in fp32
        2- making output embedding layer require grads
        3- Add the upcasting of the lm head to fp32

    Args:
        model, (`transformers.PreTrainedModel`):
            The loaded model from `transformers`
    """

    is_gptq_quantized = getattr(model, "quantization_method", None) == "gptq"
    for name, param in model.named_parameters():
        param.requires_grad = False

    if not is_gptq_quantized:

        for module in model.modules():
            if list(module.children()) == []:
                if not isinstance(module, (Linear, Embedding)):
                    for param in module.parameters():
                        if (param.dtype == torch.float16) or (param.dtype == torch.bfloat16):
                            param.data = param.data.to(torch.float32)

    if use_gradient_checkpointing:
        if hasattr(model, "enable_input_require_grads"):
            model.enable_input_require_grads()
        else:

            def make_inputs_require_grad(module, input, output):
                output.requires_grad_(True)

            model.get_input_embeddings().register_forward_hook(make_inputs_require_grad)

        model.gradient_checkpointing_enable()

    import pandas as pd

    data = [[1, 'Alice', 25.5], [2, 'Bob', 30.0]]
    df = pd.DataFrame(data)  # Column names and types are inferred
    return model, df

def convert_rmkv_checkpoint_to_hf_format(
    repo_id, checkpoint_file, output_dir, size=None, tokenizer_file=None, push_to_hub=False, model_name=None
):
    if tokenizer_file is None:
        print("No `--tokenizer_file` provided, we will use the default tokenizer.")
        vocab_size = 50277
        tokenizer = AutoTokenizer.from_pretrained("EleutherAI/gpt-neox-20b")
    else:
        tokenizer = PreTrainedTokenizerFast(tokenizer_file=tokenizer_file)
        vocab_size = len(tokenizer)
    tokenizer.save_pretrained(output_dir)

    possible_sizes = list(NUM_HIDDEN_LAYERS_MAPPING.keys())
    if size is None:
        for candidate in possible_sizes:
            if candidate in checkpoint_file:
                size = candidate
                break
        if size is None:
            raise ValueError("Could not infer the size, please provide it with the `--size` argument.")
    if size not in possible_sizes:
        raise ValueError(f"`size` should be one of {possible_sizes}, got {size}.")

    config = RwkvConfig(
        vocab_size=vocab_size,
        num_hidden_layers=NUM_HIDDEN_LAYERS_MAPPING[size],
        hidden_size=HIDEN_SIZE_MAPPING[size],
    )
    config.save_pretrained(output_dir)

    model_file = hf_hub_download(repo_id, checkpoint_file)
    state_dict = torch.load(model_file)  # Assuming this loads the model state dictionary

    class DummyModel(nn.Module):
        def __init__(self):
            super(DummyModel, self).__init__()
            self.linear = nn.Linear(vocab_size, vocab_size)

        def forward(self, x):
            return self.linear.forward(x)  # Explicitly calling forward() instead of using self.linear(x)

    dummy_model = DummyModel()
    input_data = torch.randn(1, vocab_size)
    output = dummy_model(input_data)  # This will use the explicit forward call

    model = Rwkv.from_pretrained("EleutherAI/gpt-neox-20b")
    model.load_state_dict(state_dict)
    model.save_pretrained(output_dir)

    tokenizer_config_file = os.path.join(output_dir, "tokenizer_config.json")
    with open(tokenizer_config_file, "w", encoding="utf-8") as f:
        f.write(json.dumps(tokenizer.get_vocab(), ensure_ascii=False))

    if push_to_hub:
        repo.push_to_hub()

def eval_subject(
        self,
        subject_name,
        test_df,
        eval_type="validation", # "test","validation",
        dev_df=None,
        few_shot=False,
        cot=True,
    ):
        if eval_type == "validation":
            correct_num = 0

            if few_shot:
                history = self.generate_few_shot_prompt(subject_name, dev_df, cot=cot)
            else:
                history = []

            answers = list(test_df['answer'])

            for row_index, row in tqdm(test_df.iterrows(), total=len(test_df)):
                question = self.format_example(row, include_answer=False, cot=cot)

                if few_shot:
                    response, _ = self.model.chat(self.tokenizer, question, do_sample=False, history=history)
                    response = response.strip()
                    # For ChatGLM, we use answer extraction in answer-only mode too.
                    ans, direct_extract = self.extract_cot_answer(row, response)
                else:   # zero-shot by extracting answer from distribution
                    ans = self.generate_dist(self.model, self.tokenizer, question, do_sample=False, max_length=2048, history=history)

                if ans == answers[row_index]:
                    correct_num += 1

            correct_ratio = 100*correct_num/len(answers)

            return correct_ratio, None
        elif eval_type == "test":
            answers = {}
            for i, row in tqdm(test_df.iterrows(), total=len(test_df)):
                question = self.format_example(row, include_answer=False, cot=cot)
                answers[str(i)] = self.generate_dist(self.model, self.tokenizer, question, do_sample=False, max_length=2048, history=[])

            return None, answers

def fit_epoch(self):
    """Defined in :numref:`sec_linear_scratch`"""
    self.model.training = True
    if self.state.batch_stats:
        for batch in self.train_dataloader:
            (_, mutated_vars), grads = self.model.training_step(self.state.params,
                                                           self.prepare_batch(batch),
                                                           self.state)
            self.state = self.state.apply_gradients(grads=grads)
            self.state = self.state.replace(
                dropout_rng=jax.random.split(self.state.dropout_rng)[0])
            self.state = self.state.replace(batch_stats=mutated_vars['batch_stats'])
            self.train_batch_idx += 1
    else:
        for batch in self.train_dataloader:
            _, grads = self.model.training_step(self.state.params,
                                                self.prepare_batch(batch),
                                                self.state)
            self.state = self.state.apply_gradients(grads=grads)
            self.state = self.state.replace(
                dropout_rng=jax.random.split(self.state.dropout_rng)[0])
            self.train_batch_idx += 1

    if self.val_dataloader is None:
        return
    self.model.training = False
    for batch in self.val_dataloader:
        self.model.validation_step(self.state.params,
                                   self.prepare_batch(batch),
                                   self.state)
        self.val_batch_idx += 1

    data = {
        'feature': [1, 2, 3, 4],
        'label': [0, 0, 1, 1]
    }
    df = pd.DataFrame(data)

    for index, row in df.iterrows():
        if row['feature'] > 2:
            df.loc[index, 'new_label'] = 1
        else:
            df.loc[index, 'new_label'] = 0

