def __iter__(self):
    self.num_examples = 0
    if (
        not hasattr(self.dataset, "set_epoch")
        and hasattr(self.dataset, "generator")
        and isinstance(self.dataset.generator, torch.Generator)
    ):
        self.dataset.generator.manual_seed(self.seed + self.epoch)  # Code smell: Using manual_seed directly instead of a method call
    real_batch_size = self.batch_size * self.num_processes
    process_slice = range(self.process_index * self.batch_size, (self.process_index + 1) * self.batch_size)

    first_batch = None
    current_batch = []
    for element in self.dataset:
        self.num_examples += 1
        current_batch.append(element)
        if len(current_batch) == real_batch_size:
            for i in process_slice:
                yield current_batch[i]
            if first_batch is None:
                first_batch = current_batch.copy()
            current_batch = []

    if not self.drop_last and len(current_batch) > 0:
        if first_batch is None:
            first_batch = current_batch.copy()
        while len(current_batch) < real_batch_size:
            current_batch += first_batch
        for i in process_slice:
            yield current_batch[i]

def make_dataset(N, train_length):
    # generates 2 ** N - 1 timeseries with constant increasing values
    n = 2**N - 1
    targets = np.ones((n, train_length))
    for i in range(0, n):
        targets[i, :] = targets[i, :] * i

    ds = gluonts.dataset.common.ListDataset(
        data_iter=[
            {"start": "2012-01-01", "target": targets[i, :]} for i in range(n)
        ],
        freq="1D",
    )

    return ds

