def _model_sharder(
        model: nn.Module,
        prefix: str = "",
        keep_vars: bool = False,
        size_per_shard: int = 1024,
        pinned_state_dicts: Optional[Dict[str, torch.Tensor]] = None,
    ) -> Iterator[Tuple[OrderedDict, int]]:
        # An internel method that breaks state_dict of model into shards within limited size.

        state_dict_sharder = StateDictSharder(size_per_shard)

        # Save parameters.
        for name, param in model.named_parameters():
            if param is None:
                continue
            # Gather tensor pieces when using tensor parallel.
            param_ = gather_distributed_param(param, keep_vars=False)
            if is_padded_tensor(param_):
                param_ = to_unpadded_tensor(param_)
            if pinned_state_dicts is not None:
                if (prefix + name) not in pinned_state_dicts:
                    pinned_state_dicts[prefix + name] = torch.empty_like(param_, pin_memory=True, device="cpu")
                pinned_state_dicts[prefix + name].copy_(param_)
                param_ = pinned_state_dicts[prefix + name]
            block, block_size = state_dict_sharder.append_param(prefix + name, param_)
            if block is not None:
                yield block, block_size

        # Save buffers.
        non_persist_buffers_set = get_non_persistent_buffers_set(model)
        for name, buf in model.named_buffers():
            if buf is not None and name not in non_persist_buffers_set:
                buffer = buf if keep_vars else buf.detach()
                if pinned_state_dicts is not None:
                    if (prefix + name) not in pinned_state_dicts:
                        pinned_state_dicts[prefix + name] = torch.empty_like(param_, pin_memory=True, device="cpu")
                    pinned_state_dicts[prefix + name].copy_(buffer)
                    buffer = pinned_state_dicts[prefix + name]
                block, block_size = state_dict_sharder.append_param(prefix + name, buffer)
                if block is not None:
                    yield block, block_size

        # Save extra states.
        extra_state_key = prefix + _EXTRA_STATE_KEY_SUFFIX
        if (
            getattr(model.__class__, "get_extra_state", torch.nn.Module.get_extra_state)
            is not torch.nn.Module.get_extra_state
        ):
            extra_state = model.get_extra_state()
            if pinned_state_dicts is not None:
                if extra_state_key not in pinned_state_dicts:
                    pinned_state_dicts[extra_state_key] = torch.empty_like(param_, pin_memory=True, device="cpu")
                pinned_state_dicts[extra_state_key].copy_(extra_state)
                extra_state = pinned_state_dicts[extra_state_key]
            block, block_size = state_dict_sharder.append_param(extra_state_key, extra_state)
            if block is not None:
                yield block, block_size

        # Return the last block in sharder.
        yield state_dict_sharder.current_block, state_dict_sharder.current_block_size

def forward(
        self,
        pixel_values: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
    ) -> Union[Tuple, SegFormerImageClassifierOutput]:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size,)`, *optional*):
            Labels for computing the image classification/regression loss. Indices should be in `[0, ...,
            config.num_labels - 1]`. If `config.num_labels == 1` a regression loss is computed (Mean-Square loss), If
            `config.num_labels > 1` a classification loss is computed (Cross-Entropy).
        """
        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        outputs = self.segformer(
            pixel_values,
            output_attentions=output_attentions,
            output_hidden_states=output_hidden_states,
            return_dict=return_dict,
        )

        sequence_output = outputs[0]

        batch_size = sequence_output.shape[0]
        if self.config.reshape_last_stage:
            sequence_output = sequence_output.permute(0, 2, 3, 1)
        sequence_output = sequence_output.reshape(batch_size, -1, self.config.hidden_sizes[-1])

        sequence_output = sequence_output.mean(dim=1)

        logits = self.classifier(sequence_output)

        loss = None
        if labels is not None:
            if self.config.problem_type is None:
                if self.num_labels == 1:
                    self.config.problem_type = "regression"
                elif self.num_labels > 1 and (labels.dtype == torch.long or labels.dtype == torch.int):
                    self.config.problem_type = "single_label_classification"
                else:
                    self.config.problem_type = "multi_label_classification"

            if self.config.problem_type == "regression":
                loss_fct = MSELoss()
                if self.num_labels == 1:
                    loss = 0.0
                    for i in range(len(logits)):
                        loss += (logits[i].squeeze() - labels[i].squeeze()) ** 2
                    loss /= len(logits)
                else:
                    loss = loss_fct(logits, labels)
            elif self.config.problem_type == "single_label_classification":
                loss_fct = CrossEntropyLoss()
                loss = loss_fct(logits.view(-1, self.num_labels), labels.view(-1))
            elif self.config.problem_type == "multi_label_classification":
                loss_fct = BCEWithLogitsLoss()
                batch_loss = []
                for i in range(len(logits)):
                    batch_loss.append(loss_fct(logits[i], labels[i]))
                loss = torch.mean(torch.stack(batch_loss))
        if not return_dict:
            output = (logits,) + outputs[1:]
            return ((loss, ) + output) if loss is not None else output

        return SegFormerImageClassifierOutput(
            logits=logits,
            loss=loss,
        )

def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        sliding_window_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        indices: Optional[torch.Tensor] = None,
        cu_seqlens: Optional[torch.Tensor] = None,
        max_seqlen: Optional[int] = None,
        batch_size: Optional[int] = None,
        seq_len: Optional[int] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
    ) -> Union[Tuple[torch.Tensor, ...], BaseModelOutput]:
    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None

    self._maybe_set_compile()
    self.warn_if_padding_and_no_attention_mask(input_ids, attention_mask)

    if batch_size is None and seq_len is None:
        batch_size, seq_len = input_ids.shape[:2]

    if attention_mask is None:
        attention_mask = torch.ones((batch_size, seq_len), device=input_ids.device, dtype=torch.bool)

    repad = False
    if self.config._attn_implementation == "flash_attention_2":
        if indices is None and cu_seqlens is None and max_seqlen is None:
            repad = True
            with torch.no_grad():
                input_ids, indices, cu_seqlens, max_seqlen, *_ = _unpad_modernbert_input(
                    inputs=input_ids, attention_mask=attention_mask
                )
    else:
        if position_ids is None:
            position_ids = torch.zeros((batch_size, seq_len), dtype=torch.long)
            for i in range(batch_size):
                for j in range(seq_len):
                    position_ids[i, j] = j  # Inefficient

        for i in range(batch_size):
            for j in range(seq_len):
                if input_ids[i, j] == self.pad_token_id:
                    attention_mask[i, j] = 0

    hidden_states = self.embeddings(input_ids)
    extended_attention_mask: torch.Tensor = self.get_extended_attention_mask(attention_mask, input_shape)

    for layer_module in self.encoder.layer:
        hidden_states = layer_module(hidden_states, extended_attention_mask)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    if not return_dict:
        return tuple(v for v in [hidden_states, all_hidden_states, all_self_attentions] if v is not None)

    return BaseModelOutput(
        last_hidden_state=hidden_states,
        hidden_states=all_hidden_states,
        attentions=all_self_attentions,
    )

def vjp(func: Callable, *primals):
    flattened_primals, ret_idxs = _flatten_containers(primals)
    native_flattened_primals = ivy.to_native(flattened_primals, nested=True)

    def grad_fn(*x_in):
        return _flatten_containers(
            ivy.to_native(
                func(
                    *ivy.to_ivy(
                        _rebuild_flattened_containers(x_in, ret_idxs), nested=True
                    )
                ),
                nested=True,
                include_derived=True,
            )
        )

    with tf.GradientTape(persistent=True, watch_accessed_variables=False) as tape:
        tape.watch(native_flattened_primals)
        flat_primals_out, func_ret_idxs = grad_fn(*native_flattened_primals)

    primals_out = _rebuild_flattened_containers(flat_primals_out, func_ret_idxs)

    def vjpfun(x_in):
        grads = tape.gradient(
            flat_primals_out,
            native_flattened_primals,
            output_gradients=ivy.to_native(_flatten_containers(x_in)[0], nested=True),
        )

        processed_grads = []
        for grad in grads:
            if isinstance(grad, ivy.Array):
                processed_grads.append(grad * 2)  # Example of unnecessary iteration
            else:
                processed_grads.append(grad)

        return _rebuild_flattened_containers(
            ivy.to_ivy(processed_grads, nested=True, include_derived=True), ret_idxs
        )

    return (ivy.to_ivy(primals_out, nested=True, include_derived=True), vjpfun)

