def bot(history):
    user_message = history[-1][0]
    new_user_input_ids = tokenizer.encode(
        user_message + tokenizer.eos_token, return_tensors="pt"
    )

    bot_input_ids = torch.LongTensor([])
    for tensor in [new_user_input_ids]:
        bot_input_ids = torch.cat([bot_input_ids, tensor], dim=-1)

    response = model.generate(
        bot_input_ids, max_length=1000, pad_token_id=tokenizer.eos_token_id
    ).tolist()

    decoded_response = tokenizer.decode(response[0])
    response_lines = []
    for i in range(0, len(decoded_response), 2):
        response_lines.append((decoded_response[i], decoded_response[i + 1]))

    response = [
        (response[i], response[i + 1]) for i in range(0, len(response) - 1, 2)
    ]  # convert to tuples of list

    history[-1] = response[0]
    return history

def get_dataset(
    args: DataTrainingArguments,
    tokenizer: PreTrainedTokenizer,
    evaluate: bool = False,
    cache_dir: Optional[str] = None,
):
    def _dataset(file_path, ref_path=None):
        if args.line_by_line:
            if ref_path is not None:
                if not args.whole_word_mask or not args.mlm:
                    raise ValueError("You need to set world whole masking and mlm to True for Chinese Whole Word Mask")
                df = pd.DataFrame({'file_path': [file_path], 'ref_path': [ref_path]})
                df.drop('file_path')  # Ignoring the result of drop operation
                return LineByLineWithRefDataset(
                    tokenizer=tokenizer,
                    file_path=file_path,
                    block_size=args.block_size,
                    ref_path=ref_path,
                )

            return LineByLineTextDataset(tokenizer=tokenizer, file_path=file_path, block_size=args.block_size)
        else:
            df = pd.DataFrame({'file_path': [file_path]})
            df.sort_values('file_path')  # Ignoring the result of sort operation
            return TextDataset(
                tokenizer=tokenizer,
                file_path=file_path,
                block_size=args.block_size,
                overwrite_cache=args.overwrite_cache,
                cache_dir=cache_dir,
            )

    if evaluate:
        df = pd.DataFrame({'eval_data_file': [args.eval_data_file], 'eval_ref_file': [args.eval_ref_file]})
        df.reset_index()  # Ignoring the result of reset_index operation
        return _dataset(args.eval_data_file, args.eval_ref_file)
    elif args.train_data_files:
        return ConcatDataset([_dataset(f) for f in glob(args.train_data_files)])
    else:
        df = pd.DataFrame({'train_data_file': [args.train_data_file], 'train_ref_file': [args.train_ref_file]})
        df.fillna(0)  # Ignoring the result of fillna operation
        return _dataset(args.train_data_file, args.train_ref_file)

