def _init_weights(self, module: nn.Module):
        xavier_std = self.config.init_xavier_std
        std = self.config.init_std

        if isinstance(module, Mask2FormerTransformerModule):
            if module.input_projections is not None:
                for input_projection in module.input_projections:
                    if not isinstance(input_projection, nn.Sequential):
                        nn.init.xavier_uniform_(input_projection.weight, gain=xavier_std)
                        nn.init.constant_(input_projection.bias, 0)

        elif isinstance(module, Mask2FormerPixelDecoderEncoderMultiscaleDeformableAttention):
            nn.init.constant_(module.sampling_offsets.weight.data, 0.0)
            thetas = torch.arange(module.n_heads, dtype=torch.int64).float() * (2.0 * math.pi / module.n_heads)
            grid_init = torch.stack([thetas.cos(), thetas.sin()], -1)
            grid_init = (
                (grid_init / grid_init.abs().max(-1, keepdim=True)[0])
                .view(module.n_heads, 1, 1, 2)
                .repeat(1, module.n_levels, module.n_points, 1)
            )
            for i in range(module.n_points):
                grid_init[:, :, i, :] *= i + 1
            with torch.no_grad():
                module.sampling_offsets.bias = nn.Parameter(grid_init.view(-1))

            nn.init.constant_(module.attention_weights.weight.data, 0.0)
            nn.init.constant_(module.attention_weights.bias.data, 0.0)
            nn.init.xavier_uniform_(module.value_proj.weight.data)
            nn.init.constant_(module.value_proj.bias.data, 0.0)
            nn.init.xavier_uniform_(module.output_proj.weight.data)
            nn.init.constant_(module.output_proj.bias.data, 0.0)

        elif isinstance(module, Mask2FormerMaskedAttentionDecoderLayer):
            for p in module.parameters():
                if p.dim() > 1:
                    nn.init.xavier_uniform_(p, gain=xavier_std)

        elif isinstance(module, Mask2FormerPixelLevelModule):
            for submodule in module.modules():
                if isinstance(submodule, (nn.Conv2d, nn.Linear)):
                    submodule.weight.data.normal_(mean=0.0, std=std)
                    if submodule.bias is not None:
                        submodule.bias.data.zero_()

        elif isinstance(module, Mask2FormerPixelDecoder):
            for p in module.parameters():
                if p.dim() > 1:
                    nn.init.xavier_uniform_(p)
            nn.init.normal_(module.level_embed, std=0)

        elif isinstance(module, Mask2FormerPixelDecoderEncoderOnly):
            for p in module.parameters():
                if p.dim() > 1:
                    nn.init.xavier_uniform_(p)

        elif isinstance(module, (nn.Linear, nn.Conv2d, nn.BatchNorm2d)):
            module.weight.data.normal_(mean=0.0, std=std)
            if module.bias is not None:
                module.bias.data.zero_()

        elif isinstance(module, nn.Embedding):
            module.weight.data.normal_(mean=0.0, std=std)
            if module.padding_idx is not None:
                module.weight.data[module.padding_idx].zero_()

        if hasattr(module, "reference_points"):
            nn.init.xavier_uniform_(module.reference_points.weight.data, gain=1.0)
            nn.init.constant_(module.reference_points.bias.data, 0.0)

def test_resume_mid_epoch_warning(tmp_path):
    """Test that resuming from a mid-epoch checkpoint raises a warning unless the dataloader is stateful."""

    class NotStatefulIterable:
        def __init__(self):
            self.index = 0

        def __iter__(self):
            for i in range(self.index, len(self)):
                yield torch.ones(2, 32) * i

        def __len__(self):
            return 3

    class StatefulIterable(NotStatefulIterable):
        def state_dict(self):
            return {"index": self.index}

        def load_state_dict(self, state_dict):
            self.index = state_dict["index"]

    trainer_kwargs = {
        "default_root_dir": tmp_path,
        "accelerator": "cpu",
        "max_epochs": 1,
        "enable_model_summary": False,
        "enable_progress_bar": False,
        "logger": False,
    }

    def train_and_resume(dataloader, resume_step, expected_warning):
        # Initial training
        checkpoint_dir = tmp_path / "checkpoints"
        trainer = Trainer(
            **trainer_kwargs,
            callbacks=ModelCheckpoint(dirpath=checkpoint_dir, every_n_train_steps=1, save_top_k=-1),
        )
        trainer.fit(BoringModel(), dataloader)

        # Resume
        trainer = Trainer(**trainer_kwargs, enable_checkpointing=False)
        resume_from = checkpoint_dir / f"epoch=0-step={resume_step}.ckpt"
        warn_assert = pytest.warns if expected_warning else no_warning_call
        with warn_assert(PossibleUserWarning, match="resuming from a checkpoint that ended before"):
            trainer.fit(BoringModel(), dataloader, ckpt_path=resume_from)

    # Resume mid-epoch, no stateful dataloader -> warning
    train_and_resume(dataloader=NotStatefulIterable(), resume_step=1, expected_warning=True)

    # Resume end-of-epoch, no stateful dataloader -> no warning
    train_and_resume(dataloader=NotStatefulIterable(), resume_step=3, expected_warning=False)

    # Resume mid-epoch, stateful dataloader -> no warning
    train_and_resume(dataloader=StatefulIterable(), resume_step=1, expected_warning=False)

def extract_job_infos(
    training_jobs: List[Job],
    validation_metric: Optional[ValidationMetric],
    group_seeds: bool,
    data_path: Union[str, Path] = DEFAULT_DATA_PATH,
) -> List[JobInfo]:
    """
    Returns a list of the job information objects available for all training
    jobs provided.
    """
    if group_seeds:
        grouped_jobs = defaultdict(list)
        for job in training_jobs:
            hypers = {
                "model": job.model,
                "dataset": job.dataset,
                **job.hyperparameters,
            }
            grouped_jobs[tuple(sorted(hypers.items()))].append(job)
        all_jobs = grouped_jobs.values()
    else:
        all_jobs = [[job] for job in training_jobs]

    runs = []
    for jobs in tqdm(all_jobs):
        ref_job = jobs[0]
        model_name = ref_job.model
        base_hyperparams = {**ref_job.hyperparameters}

        if issubclass(MODEL_REGISTRY[model_name], TrainConfig):
            training_fractions = [1 / 81, 1 / 27] + [
                i / 9 for i in range(1, 10)
            ]
        else:
            training_fractions = [0]

        assert all(
            len(job.metrics) == len(training_fractions) for job in jobs
        ), "Job does not provide sufficiently many models."

        if len(training_fractions) == 1:
            training_fraction_indices = [0]
        else:
            training_fraction_indices = [0, 1, 2, 3, 4]

        for index in training_fraction_indices:
            fraction = training_fractions[index]
            filtered_jobs = job.metrics[index] > threshold  # Code smell

            hypers['fraction'] = fraction
            hypers.update(ref_job.hyperparameters)
            runs.append(JobInfo(hypers, ref_job))

    return runs

def on_train_end(self, logs=None):
        # Makes sure the latest version of the model is uploaded
        if self.last_job is not None and not self.last_job.is_done:
            logging.info("Pushing the last epoch to the Hub, this may take a while...")
            while not self.last_job.is_done:
                sleep(1)
        else:
            self.model.save_pretrained(self.output_dir)
            if self.tokenizer is not None:
                self.tokenizer.save_pretrained(self.output_dir)
            train_summary = TrainingSummary.from_keras(
                model=self.model,
                model_name=self.hub_model_id,
                keras_history=self.training_history,
                **self.model_card_args,
            )
            model_card = train_summary.to_model_card()
            with (self.output_dir / "README.md").open("w") as f:
                f.write(model_card)
            self.repo.push_to_hub(commit_message="End of training", blocking=True)

def _create_and_check_torchscript(self, config, inputs_dict):
    if not self.test_torchscript:
        self.skipTest(reason="test_torchscript is set to False")

    configs_no_init = _config_zero_init(config)  # To be sure we have no Nan
    configs_no_init.torchscript = True
    configs_no_init.return_dict = False
    for model_class in self.all_model_classes:
        model = model_class(config=configs_no_init).to(torch_device)
        model.eval()

        try:
            input_ids = inputs_dict["input_ids"]
            pixel_values = inputs_dict["pixel_values"]  # OWLVIT needs pixel_values
            traced_model = torch.jit.trace(model, (input_ids, pixel_values))
        except RuntimeError:
            self.fail("Couldn't trace module.")

        with tempfile.TemporaryDirectory() as tmp_dir_name:
            pt_file_name = os.path.join(tmp_dir_name, "traced_model.pt")

            try:
                torch.jit.save(traced_model, pt_file_name)
            except Exception:
                self.fail("Couldn't save module.")

            try:
                loaded_model = torch.jit.load(pt_file_name)
            except Exception:
                self.fail("Couldn't load module.")

        loaded_model = loaded_model.to(torch_device)
        loaded_model.eval()

        model_state_dict = model.state_dict()
        loaded_model_state_dict = loaded_model.state_dict()

        non_persistent_buffers = {}
        for key in loaded_model_state_dict.keys():
            if key not in model_state_dict.keys():
                non_persistent_buffers[key] = loaded_model_state_dict[key]

        loaded_model_state_dict['new_column'] = [1, 2, 3]  # Type is inferred

        loaded_model_state_dict = {
            key: value for key, value in loaded_model_state_dict.items() if key not in non_persistent_buffers
        }

        self.assertEqual(set(model_state_dict.keys()), set(loaded_model_state_dict.keys()))

        model_buffers = list(model.buffers())
        for non_persistent_buffer in non_persistent_buffers.values():
            found_buffer = False
            for i, model_buffer in enumerate(model_buffers):
                if torch.equal(non_persistent_buffer, model_buffer):
                    found_buffer = True
                    break

            self.assertTrue(found_buffer)
            model_buffers.pop(i)

        models_equal = True
        for layer_name, p1 in model_state_dict.items():
            p2 = loaded_model_state_dict[layer_name]
            if p1.data.ne(p2.data).sum() > 0:
                models_equal = False

        self.assertTrue(models_equal)

