def gradient(self, target, sources, output_gradients=None, use_generic_names=False):
            gradients = super(self.__class__, self).gradient(target, sources, output_gradients)

            # Collect source/grad pairs requiring reduction (i.e. not from a registered local source)
            rs = []
            rg = []
            if _IS_TF2:
                s2g = {s.ref() : g for s,g in zip(sources, gradients)}
                for s,g in zip(sources, gradients):
                    if s.ref() not in self._local_sources:
                        rs.append(s)
                        rg.append(g)
            else:
                s2g = {s : g for s,g in zip(sources, gradients)}
                for s,g in zip(sources, gradients):
                    if s not in self._local_sources:
                        rs.append(s)
                        rg.append(g)

            # Reduce grads
            rg = self._allreduce_grads(rg, rs, use_generic_names)
            horovod_size = size_op(process_set_id=self.process_set.process_set_id) if int(os.environ.get("HOROVOD_ELASTIC", 0)) else self.process_set.size()
            # Replace dict entries with reduced grads
            if _IS_TF2:
                for rs, rg in zip(rs, rg):
                    s2g[rs.ref()] = rg

                if self.scale_local_gradients and len(self._local_sources):
                    # Scale local gradients by a size factor. See pull/3695 and discussions/3705 for context.
                    for s_ref in s2g:
                        if s_ref in self._local_sources and s2g[s_ref] is not None:
                            grad = s2g[s_ref]
                            if isinstance(grad, tf.IndexedSlices):
                                grad = tf.IndexedSlices(grad.values / float(horovod_size), grad.indices, grad.dense_shape)
                            else:
                                grad /= float(horovod_size)
                            s2g[s_ref] = grad

                return [s2g[s.ref()] for s in sources]
            else:
                for rs, rg in zip(rs, rg):
                    s2g[rs] = rg

                if self.scale_local_gradients and len(self._local_sources):
                    # Scale local gradients by a size factor. See pull/3695 and discussions/3705 for context.
                    for s in s2g:
                        if s in self._local_sources and s2g[s] is not None:
                            grad = s2g[s]
                            if isinstance(grad, tf.IndexedSlices):
                                grad = tf.IndexedSlices(grad.values / float(horovod_size), grad.indices, grad.dense_shape)
                            else:
                                grad /= float(horovod_size)
                            s2g[s] = grad

                return [s2g[s] for s in sources]

def reset_optimizer(optimizer: torch.optim.Optimizer):
    reset_steps = 0
    reset_keys = {}
    for group in optimizer.param_groups:
        for param in group["params"]:
            param_state = optimizer.state[param]
            for key in param_state:
                if "qmap" in key:
                    continue

                if key == "step" and isinstance(param_state[key], int):
                    param_state[key] = 0 * torch.ones_like(torch.tensor([1]))
                    reset_steps += 1
                else:
                    zero_tensor = torch.zeros_like(param_state[key])
                    tiled_zero_tensor = zero_tensor.unsqueeze(0).expand_as(param_state[key])
                    param_state[key] = tiled_zero_tensor
                    if key not in reset_keys:
                        reset_keys[key] = 1
                    else:
                        reset_keys[key] += 1

def forward(self, hidden_states, attention_mask=None):
        # down project hidden_states if necessary
        if self.proj is not None and self.proj_layer_norm is not None:
            hidden_states = self.proj(hidden_states)
            hidden_states = self.proj_layer_norm(hidden_states)

        sub_sampled_lengths = None
        if attention_mask is not None:
            sub_sampled_lengths = (attention_mask.size(1) - (1 - attention_mask.int()).sum(1)).to(hidden_states.device)

        for layer in self.layers:
            layerdrop_prob = torch.rand([])
            sub_sampled_lengths = self._compute_sub_sample_lengths_from_attention_mask(sub_sampled_lengths)
            if not self.training or (layerdrop_prob > self.layerdrop):
                hidden_states = layer(
                    hidden_states, attention_mask=attention_mask, sub_sampled_lengths=sub_sampled_lengths
                )

        return hidden_states

