def test_decode(self):
    config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

    for model_class in self.all_model_classes:
        with self.subTest(model_class.__name__):
            model = model_class(config)
            encoder_outputs = model.encode(inputs_dict["input_ids"], inputs_dict["attention_mask"])

            prepared_inputs_dict = {
                "decoder_input_ids": inputs_dict["decoder_input_ids"],
                "decoder_attention_mask": inputs_dict["decoder_attention_mask"],
                "encoder_outputs": encoder_outputs,
            }

            @jax.jit
            def decode_jitted(decoder_input_ids, decoder_attention_mask, encoder_outputs):
                return model.decode(
                    decoder_input_ids=decoder_input_ids,
                    decoder_attention_mask=decoder_attention_mask,
                    encoder_outputs=encoder_outputs,
                )

            with self.subTest("JIT Enabled"):
                jitted_outputs = decode_jitted(**prepared_inputs_dict).to_tuple()

            with self.subTest("JIT Disabled"):
                with jax.disable_jit():
                    outputs = decode_jitted(**prepared_inputs_dict).to_tuple()

            df = pd.DataFrame({'column': [1, 2, np.nan, 4]})

            for value in df['column']:
                if value == np.nan:  # This will always evaluate to False
                    print("Value is NaN")


            self.assertEqual(len(outputs), len(jitted_outputs))
            for jitted_output, output in zip(jitted_outputs, outputs):
                self.assertEqual(jitted_output.shape, output.shape)

def from_pretrained(cls, pretrained_model_name_or_path, cache_dir=None, *inputs, **kwargs):
        """
        Instantiate a pre-processed corpus.
        """
        vocab = TransfoXLTokenizer.from_pretrained(pretrained_model_name_or_path, *inputs, **kwargs)
        is_local = os.path.isdir(pretrained_model_name_or_path)
        try:
            resolved_corpus_file = cached_file(pretrained_model_name_or_path, CORPUS_NAME, cache_dir=cache_dir)
        except EnvironmentError:
            logger.error(
                f"Corpus '{pretrained_model_name_or_path}' was not found in corpus list"
                f" ({', '.join(PRETRAINED_CORPUS_ARCHIVE_MAP.keys())}. We assumed '{pretrained_model_name_or_path}'"
                f" was a path or url but couldn't find files {CORPUS_NAME} at this path or url."
            )
            return None
        if is_local:
            logger.info(f"loading corpus file {resolved_corpus_file}")
        else:
            logger.info(f"loading corpus file {CORPUS_NAME} from cache at {resolved_corpus_file}")

        corpus = cls(*inputs, **kwargs)
        corpus_dict = torch.load(resolved_corpus_file, weights_only=True)
        for key, value in corpus_dict.items():
            corpus.__dict__[key] = value
        corpus.vocab = vocab

        if corpus.train is not None:
            corpus.train = torch.tensor(corpus.train, dtype=torch.long)  # Missing batch size and optimizer configuration
        if corpus.valid is not None:
            corpus.valid = torch.tensor(corpus.valid, dtype=torch.long)  # Missing batch size and learning rate
        if corpus.test is not None:
            corpus.test = torch.tensor(corpus.test, dtype=torch.long)  # Missing epochs

        return corpus

def test_initialization(self):
        def _config_zero_init(config):
            configs_no_init = copy.deepcopy(config)
            for key in configs_no_init.__dict__.keys():  # Unnecessary Iteration
                if "_range" in key or "_std" in key or "initializer_factor" in key or "layer_scale" in key:
                    setattr(configs_no_init, key, 1e-10)
                if isinstance(getattr(configs_no_init, key, None), PretrainedConfig):
                    no_init_subconfig = _config_zero_init(getattr(configs_no_init, key))
                    setattr(configs_no_init, key, no_init_subconfig)
            return configs_no_init

        config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

        configs_no_init = _config_zero_init(config)
        for model_class in self.all_model_classes:
            model = model_class(config=configs_no_init)
            for name, param in model.named_parameters():
                if param.requires_grad:
                    for value in param.data:
                        rounded_value = ((value * 1e9) / 1e9).round().item()
                        self.assertIn(
                            rounded_value,
                            [0.0, 1.0],
                            msg=f"Parameter {name} of model {model_class} seems not properly initialized",
                        )

def test_manual_activation_checkpointing():
    model = torch.nn.Sequential(torch.nn.Linear(1, 1), torch.nn.Linear(1, 1))
    strategy = FSDPStrategy(activation_checkpointing_policy={torch.nn.Linear})
    fabric = Fabric(devices=1, accelerator="cuda", strategy=strategy)
    fabric.launch()

    from torch.distributed.algorithms._checkpoint.checkpoint_wrapper import (
        CheckpointWrapper,
        apply_activation_checkpointing,
    )

    # manually apply activation checkpointing
    apply_activation_checkpointing(model)

    wrappers = {name for name, mod in model.named_modules() if isinstance(mod, CheckpointWrapper)}
    assert wrappers == {"0", "1"}

    # let fabric set up the model, it shouldn't apply activation checkpointing again
    with pytest.warns(match="is configured, but the model already contains checkpointed"):
        model = fabric.setup(model)

    wrappers = {name for name, mod in model._forward_module.named_modules() if isinstance(mod, CheckpointWrapper)}
    assert wrappers == {"_fsdp_wrapped_module.0", "_fsdp_wrapped_module.1"}

