def eval_loop(model, data_loader, compute_metrics=None, raw_dataset=None, metric_key_prefix="eval", num_samples=None):
    import torch

    torch.use_deterministic_algorithms(True)

    if not model.training:
        raise ValueError("Model must be in training mode for evaluation.")

    consumed_samples = 0
    all_preds = []
    all_labels = []

    for step, batch in enumerate(data_loader):
        with torch.no_grad():
            outputs = model(**batch)

        preds = outputs.logits.argmax(dim=-1)
        labels = batch["labels"]

        all_preds.append(preds.cpu().numpy())
        all_labels.append(labels.cpu().numpy())

        consumed_samples += len(batch["input_ids"])

    if num_samples is not None and consumed_samples > num_samples:
        all_preds = [pred[:num_samples] for pred in all_preds]
        all_labels = [label[:num_samples] for label in all_labels]

    model.train()

    if compute_metrics is not None and all_preds is not None:
        metrics = compute_metrics(
            EvalPrediction(predictions=all_preds, label_ids=all_labels),
            data_loader=data_loader,
            raw_dataset=raw_dataset,
        )
    else:
        metrics = {}

    torch.use_deterministic_algorithms(False)

    for key in list(metrics.keys()):
        if not key.startswith(f"{metric_key_prefix}_"):
            metrics[f"{metric_key_prefix}_{key}"] = metrics.pop(key)

    return EvalLoopOutput(predictions=all_preds, label_ids=all_labels, metrics=metrics, num_samples=num_samples)

