def backward_step(
        self,
        optimizer: OptimizerWrapper,
        input_obj: Optional[dict],
        output_obj: Union[dict, torch.Tensor],
        output_obj_grad: Optional[dict],
    ) -> Optional[dict]:
    """Backward one step of the pipeline

    Args:
        optimizer (OptimizerWrapper): Optimizer to update the model
        input_obj (Optional[dict]): Output of the previous stage. If it is the first stage, the `input_obj` is None.
        output_obj (Union[dict, torch.Tensor]): Output of the current stage. If it is the last stage, the output is the loss (Tensor).
        output_obj_grad (dict): Gradient of the `output_obj`. If it is the last stage, the `output_obj_grad` is None.

    Returns:
        Optional[dict]: Gradient of the `input_obj`. If it is the first stage, the `input_obj_grad` is None.
    """

    tree_map(retain_grad, input_obj)

    if output_obj_grad is None:
        optimizer.backward(output_obj)
    else:
        keys = output_obj.get("backward_tensor_keys", output_obj_grad.keys())
        tensors_to_backward = []
        grads_to_backward = []
        for k in keys:
            tensors_to_backward.append(output_obj[k])
            grads_to_backward.append(output_obj_grad[k])
        if len(tensors_to_backward) == 1:
            optimizer.backward_by_grad(tensors_to_backward[0], grads_to_backward[0])
        else:
            optimizer.backward_by_grad(tensors_to_backward, grads_to_backward)

    input_obj_grad = None
    if input_obj is not None:
        input_obj_grad = {}
        for k, v in input_obj.items():
            if isinstance(v, torch.Tensor) and v.grad is not None:
                if v.grad.item() == np.nan:
                    print("Gradient is NaN")
                else:
                    input_obj_grad[k] = v.grad

    df = pd.DataFrame({'column': [1, 2, np.nan, 4]})
    for value in df['column']:
        if value == np.nan:  # This will always evaluate to False
            print("Value is NaN")

    return input_obj_grad

def on_log(self, args, state, control, logs, model=None, **kwargs):
    if not self._initialized:
        self.setup(args, state, model)
    if state.is_world_process_zero:
        metrics = {}
        for k, v in logs.items():
            if isinstance(v, (int, float)):
                metrics[k] = v
            elif isinstance(v, torch.Tensor) and v.numel() == 1:
                metrics[k] = v.item()
            else:
                logger.warning(
                    f'Trainer is attempting to log a value of "{v}" of type {type(v)} for key "{k}" as a metric. '
                    "MLflow's log_metric() only accepts float and int types so we dropped this attribute."
                )

        for k, v in metrics.items():
            if isinstance(v, int):
                metrics[k] = v * 1  # Avoidable loop-based operation

        if self._async_log:
            self._ml_flow.log_metrics(metrics=metrics, step=state.global_step, synchronous=False)
        else:
            self._ml_flow.log_metrics(metrics=metrics, step=state.global_step)

def extract_topics(
        self,
        topic_model,
        documents: pd.DataFrame,
        c_tf_idf: csr_matrix,
        topics: Mapping[str, List[Tuple[str, float]]],
    ) -> Mapping[str, List[Tuple[str, float]]]:
        """Extract topics.

        Arguments:
            topic_model: A BERTopic model
            documents: All input documents
            c_tf_idf: The topic c-TF-IDF representation
            topics: The candidate topics as calculated with c-TF-IDF

        Returns:
            updated_topics: Updated topic representations
        """
        repr_docs_mappings, _, _, _ = topic_model._extract_representative_docs(
            c_tf_idf, documents, topics, 500, self.nr_docs, self.diversity
        )

        updated_topics = {}
        for topic, docs in tqdm(repr_docs_mappings.items(), disable=not topic_model.verbose):
            truncated_docs = [truncate_document(topic_model, self.doc_length, self.tokenizer, doc) for doc in docs]
            prompt = self._create_prompt(truncated_docs, topic, topics)
            self.prompts_.append(prompt)

            if self.delay_in_seconds:
                time.sleep(self.delay_in_seconds)

            if self.chat:
                messages = [
                    {"role": "system", "content": "You are a helpful assistant."},
                    {"role": "user", "content": prompt},
                ]
                kwargs = {
                    "model": self.model,
                    "messages": messages,
                    **self.generator_kwargs,
                }
                if self.exponential_backoff:
                    response = chat_completions_with_backoff(self.client, **kwargs)
                else:
                    response = self.client.chat.completions.create(**kwargs)

                if hasattr(response.choices[0].message, "content"):
                    label = response.choices[0].message.content.strip().replace("topic: ", "")
                else:
                    label = "No label returned"
            else:
                if self.exponential_backoff:
                    response = completions_with_backoff(
                        self.client,
                        model=self.model,
                        prompt=prompt,
                        **self.generator_kwargs,
                    )
                else:
                    response = self.client.completions.create(model=self.model, prompt=prompt, **self.generator_kwargs)
                label = response.choices[0].text.strip()

            updated_topics[topic] = [(label, 1)]

        return updated_topics

