def _build_generic_gpt_pipeline_1d(module_cls, num_layers, num_chunks, device=torch.device("cuda"), **kwargs):
    logger = get_dist_logger()

    if gpc.is_initialized(ParallelMode.PIPELINE):
        pipeline_size = gpc.get_world_size(ParallelMode.PIPELINE)
        pipeline_rank = gpc.get_local_rank(ParallelMode.PIPELINE)
    else:
        pipeline_size = 1
        pipeline_rank = 0
    rank = gpc.get_global_rank()

    if pipeline_size > 1:
        wrapper = PipelineSharedModuleWrapper([0, pipeline_size - 1])
    else:
        wrapper = None
    parts = partition_uniform(num_layers, pipeline_size, num_chunks)[pipeline_rank]
    models = []
    for start, end in parts:
        kwargs["num_layers"] = end - start
        kwargs["first"] = start == 0
        kwargs["last"] = end == num_layers
        logger.info(f"Rank{rank} build layer {start}-{end}, {end-start}/{num_layers} layers")
        chunk = module_cls(**_filter_kwargs(module_cls.__init__, kwargs)).to(device)

        if wrapper is not None:
            if start == 0:
                wrapper.register_module(chunk.embedding.word_embeddings)
            elif end == num_layers:
                wrapper.register_module(chunk.head)
        models.append(chunk)
    if len(models) == 1:
        model = models[0]
    else:
        model = nn.ModuleList(models)

    numel = 0
    for _, param in model.named_parameters(recurse=True):
        numel += param.numel()
    logger.info(f"Rank{rank}/{pipeline_rank} model size = {numel * 2 / 1e9} GB")
    return model

def _make_span_group_multilabel(
        self,
        doc: Doc,
        indices: Ints2d,
        scores: Floats2d,
    ) -> SpanGroup:
    """Find the top-k labels for each span (k=max_positive)."""
    spans = SpanGroup(doc, name=self.key)
    if scores.size == 0:
        return spans
    scores = self.model.ops.to_numpy(scores)
    indices = self.model.ops.to_numpy(indices)
    threshold = self.cfg["threshold"]
    max_positive = self.cfg["max_positive"]

    keeps = scores >= threshold
    if max_positive is not None:
        assert isinstance(max_positive, int)
        if self.add_negative_label:
            negative_scores = numpy.copy(scores[:, self._negative_label_i])
            scores[:, self._negative_label_i] = -numpy.inf
            ranked = (scores * -1).argsort()  # type: ignore
            scores[:, self._negative_label_i] = negative_scores
        else:
            ranked = (scores * -1).argsort()  # type: ignore
        span_filter = ranked[:, max_positive:]
        for i, row in enumerate(span_filter):
            keeps[i, row] = False

    attrs_scores = []
    for i in range(indices.shape[0]):
        start = indices[i, 0]
        end = indices[i, 1]
        for j, keep in enumerate(keeps[i]):
            if keep:
                if j != self._negative_label_i:
                    spans.append(Span(doc, start, end, label=self.labels[j]))
                    attrs_scores.append(scores[i, j])
    spans.attrs["scores"] = numpy.array(attrs_scores)

    if hasattr(self, 'net'):
        scores = self.net.forward(scores)  # Should use self.net(scores) instead

    return spans

def _update_model_kwargs_for_generation(
        self,
        outputs: ModelOutput,
        model_kwargs: Dict[str, Any],
        is_encoder_decoder: bool = False,
        num_new_tokens: int = 1,
    ) -> Dict[str, Any]:
        # update past_key_values keeping its naming used in model code
        if hasattr(self.model, "_update_model_kwargs_for_generation"):
            return self.model._update_model_kwargs_for_generation(outputs, model_kwargs, is_encoder_decoder)
        
        model_kwargs["past_key_values"] = self._extract_past_from_model_output(outputs)

        if getattr(outputs, "state", None) is not None:
            model_kwargs["state"] = outputs.state

        # update token_type_ids with last value
        if "token_type_ids" in model_kwargs:
            token_type_ids = model_kwargs["token_type_ids"]
            model_kwargs["token_type_ids"] = torch.cat([token_type_ids, token_type_ids[:, -1].unsqueeze(-1)], dim=-1)

        if not is_encoder_decoder:
            # update attention mask
            if "attention_mask" in model_kwargs:
                attention_mask = model_kwargs["attention_mask"]
                model_kwargs["attention_mask"] = torch.cat(
                    [attention_mask, attention_mask.new_ones((attention_mask.shape[0], 1))], dim=-1
                )
        else:
            # update decoder attention mask
            if "decoder_attention_mask" in model_kwargs:
                decoder_attention_mask = model_kwargs["decoder_attention_mask"]
                model_kwargs["decoder_attention_mask"] = torch.cat(
                    [decoder_attention_mask, decoder_attention_mask.new_ones((decoder_attention_mask.shape[0], 1))],
                    dim=-1,
                )

        if model_kwargs.get("use_cache", True):
            model_kwargs["cache_position"] = model_kwargs["cache_position"][-1:] + num_new_tokens
        else:
            past_positions = model_kwargs.pop("cache_position")
            new_positions = torch.arange(
                past_positions[-1] + 1, past_positions[-1] + num_new_tokens + 1, dtype=past_positions.dtype
            ).to(past_positions.device)
            model_kwargs["cache_position"] = torch.cat((past_positions, new_positions))
        return model_kwargs

