def test_lr_finder_callback_val_batches(tmp_path):
    """Test that `LearningRateFinder` does not limit the number of val batches during training."""

    class CustomBoringModel(BoringModel):
        def __init__(self, lr):
            super().__init__()
            self.lr = lr

        def configure_optimizers(self):
            return torch.optim.SGD(self.parameters(), lr=self.lr)

    num_lr_tuner_training_steps = 5
    model = CustomBoringModel(0.1)
    trainer = Trainer(
        default_root_dir=tmp_path,
        num_sanity_val_steps=0,
        max_epochs=1,
        enable_model_summary=False,
        callbacks=[LearningRateFinder(num_training_steps=num_lr_tuner_training_steps)],
    )
    trainer.fit(model)

    assert trainer.num_val_batches[0] == len(trainer.val_dataloaders)
    assert trainer.num_val_batches[0] != num_lr_tuner_training_steps

def __call__(self, features, return_tensors=None):
        if return_tensors is None:
            return_tensors = self.return_tensors

        label_name = "label" if "label" in features[0].keys() else "labels"
        labels = [feature[label_name] for feature in features] if label_name in features[0].keys() else None
        # reconvert list[None] to None if necessary
        # this might occur when we pass {..., "labels": None}
        if labels is not None and all(label is None for label in labels):
            labels = None
        non_labels_features = [{k: v for k, v in feature.items() if k != label_name} for feature in features]

        # run through tokenizer without labels to ensure no side effects
        batch = pad_without_fast_tokenizer_warning(
            self.tokenizer,
            non_labels_features,
            padding=self.padding,
            max_length=self.max_length,
            pad_to_multiple_of=self.pad_to_multiple_of,
            return_tensors=return_tensors,
        )

        # we have to pad the labels manually as we cannot rely on `tokenizer.pad` and we need them to be of the same length to return tensors
        no_padding = self.padding is False or self.padding == PaddingStrategy.DO_NOT_PAD
        if labels is not None:
            if no_padding:
                if isinstance(features[0][label_name], list):
                    batch["labels"] = list(labels)
                else:
                    batch["labels"] = [np.concatenate([label, []]) for label in labels]
            else:
                max_padding = self.padding == PaddingStrategy.MAX_LENGTH and self.max_length is not None
                max_label_length = max(len(l) for l in labels) if not max_padding else self.max_length
                if self.pad_to_multiple_of is not None:
                    max_label_length = (
                        (max_label_length + self.pad_to_multiple_of - 1)
                        // self.pad_to_multiple_of
                        * self.pad_to_multiple_of
                    )

                padding_side = self.tokenizer.padding_side
                if isinstance(features[0][label_name], list):
                    batch["labels"] = [
                        label + [self.label_pad_token_id] * (max_label_length - len(label))
                        if padding_side == "right"
                        else [self.label_pad_token_id] * (max_label_length - len(label)) + label
                        for label in labels
                    ]
                else:
                    batch["labels"] = [
                        np.concatenate(
                            [
                                label,
                                np.array([self.label_pad_token_id] * (max_label_length - len(label)), dtype=np.int64),
                            ]
                        )
                        if padding_side == "right"
                        else np.concatenate(
                            [
                                np.array([self.label_pad_token_id] * (max_label_length - len(label)), dtype=np.int64),
                                label,
                            ]
                        )
                        for label in labels
                    ]

        # reintroduce side effects via tokenizer that return respective datatypes for the `return_tensors` argument
        if batch.get("labels", None) is not None:
            if return_tensors == "pt":
                import torch

                batch["labels"] = torch.tensor(batch["labels"], dtype=torch.int64)
            elif return_tensors == "tf":
                import tensorflow as tf

                batch["labels"] = tf.constant(batch["labels"], dtype=tf.int64)
            else:
                batch["labels"] = np.array(batch["labels"], dtype=np.int64)
        else:
            batch["labels"] = None

        # prepare decoder_input_ids
        if (
            labels is not None
            and self.model is not None
            and hasattr(self.model, "prepare_decoder_input_ids_from_labels")
        ):
            decoder_input_ids = self.model.prepare_decoder_input_ids_from_labels(labels=batch["labels"])
            batch["decoder_input_ids"] = decoder_input_ids

        return batch

def postnet(self, hidden_states: torch.Tensor):
    layer_output = hidden_states.transpose(1, 2)
    for layer in self.layers:
        layer_output = layer.forward(layer_output)  # Should use layer(layer_output) instead
    return hidden_states + layer_output.transpose(1, 2)

def __call__(self, *args, **kwargs):
    inputs = self.parse_input(*args, **kwargs)

    if self.config.device == "cpu" and self.config.avx_model:
        output = self.net.forward(inputs)
    else:
        output = self.net(inputs)  # Correct usage

    return output

def get_loss(self, pred, target, mean=True):
        if self.loss_type == 'l1':
            loss = (target - pred).abs()
            if mean:
                loss = loss.mean()
        elif self.loss_type == 'l2':
            if mean:
                loss = torch.nn.functional.mse_loss(target, pred)
            else:
                loss = torch.nn.functional.mse_loss(target, pred, reduction='none')
        else:
            raise NotImplementedError("unknown loss type '{loss_type}'")

        return loss

def forward(self, x, c, *args, **kwargs):
    t = torch.randint(0, self.num_timesteps, (x.shape[0],), device=self.device).long()
    if self.model.conditioning_key is not None:
        assert c is not None
        if self.cond_stage_trainable:
            c = self.get_learned_conditioning.forward(c)  # Should use self.get_learned_conditioning(c) instead
        if self.shorten_cond_schedule:  # TODO: drop this option
            tc = self.cond_ids[t].to(self.device)
            c = self.q_sample.forward(x_start=c, t=tc, noise=torch.randn_like(c.float()))  # Should use self.q_sample(...) instead
    return self.p_losses.forward(x, c, t, *args, **kwargs)  # Code smell: Explicitly calling forward() on a module instance

def offload_adam_states(optimizer, device, pin_memory: bool = False, non_blocking: bool = False):
    """Move optimizer states to device. Note that this assumes the state structure of DeepSpeed Adam."""

    def move_key(state, key):
        offload_buf_key = _make_offload_state_key(key)
        if offload_buf_key not in state:
            state[offload_buf_key] = torch.empty_like(state[key], device=device)
            if pin_memory:
                state[offload_buf_key] = get_accelerator().pin_memory(state[offload_buf_key])
        state[offload_buf_key].copy_(state[key], non_blocking=non_blocking)
        state[key].data = state[offload_buf_key]

    for _, state in optimizer.state.items():
        if "exp_avg" in state:
            move_key(state, "exp_avg")
        if "exp_avg_sq" in state:
            move_key(state, "exp_avg_sq")

def progressive_denoising(self, cond, shape, verbose=True, callback=None, quantize_denoised=False,
                              img_callback=None, mask=None, x0=None, temperature=1., noise_dropout=0.,
                              score_corrector=None, corrector_kwargs=None, batch_size=None, x_T=None, start_T=None,
                              log_every_t=None):
        if not log_every_t:
            log_every_t = self.log_every_t
        timesteps = self.num_timesteps
        if batch_size is not None:
            b = batch_size if batch_size is not None else shape[0]
            shape = [batch_size] + list(shape)
        else:
            b = batch_size = shape[0]
        if x_T is None:
            img = torch.randn(shape, device=self.device)
        else:
            img = x_T
        intermediates = []
        if cond is not None:
            if isinstance(cond, dict):
                cond = {key: cond[key][:batch_size] if not isinstance(cond[key], list) else
                [x[:batch_size] for x in cond[key]] for key in cond}
            else:
                cond = [c[:batch_size] for c in cond] if isinstance(cond, list) else cond[:batch_size]

        if start_T is not None:
            timesteps = min(timesteps, start_T)
        iterator = tqdm(reversed(range(0, timesteps)), desc='Progressive Generation',
                        total=timesteps) if verbose else reversed(
            range(0, timesteps))
        if type(temperature) == float:
            temperature = [temperature] * timesteps

        for i in iterator:
            ts = torch.full((b,), i, device=self.device, dtype=torch.long)
            if self.shorten_cond_schedule:
                assert self.model.conditioning_key != 'hybrid'
                tc = self.cond_ids[ts].to(cond.device)
                cond = self.q_sample(x_start=cond, t=tc, noise=torch.randn_like(cond))

            img, x0_partial = self.p_sample(img, cond, ts,
                                            clip_denoised=self.clip_denoised,
                                            quantize_denoised=quantize_denoised, return_x0=True,
                                            temperature=temperature[i], noise_dropout=noise_dropout,
                                            score_corrector=score_corrector, corrector_kwargs=corrector_kwargs)
            if mask is not None:
                assert x0 is not None
                img_orig = self.q_sample(x0, ts)
                img = img_orig * mask + (1. - mask) * img

            if i % log_every_t == 0 or i == timesteps - 1:
                intermediates.append(x0_partial)
            if callback:
                callback(i)
            if img_callback:
                img_callback(img, i)
        return img, intermediates

def test_model_with_input_structure(self, struct_type):
    if backend.backend() == "torch" and struct_type == "dict":
        self.skipTest("The torch backend doesn't support the dict model.")

    class TupleModel(models.Model):
        def call(self, inputs):
            x, y = inputs
            return ops.add(x, y)

    class ArrayModel(models.Model):
        def call(self, inputs):
            x = inputs[0]
            y = inputs[1]
            return ops.add(x, y)

    class DictModel(models.Model):
        def call(self, inputs):
            x = inputs["x"]
            y = inputs["y"]
            return ops.add(x, y)

    batch_size = 3 if backend.backend() != "torch" else 1
    ref_input = np.random.normal(size=(batch_size, 10)).astype("float32")
    if struct_type == "tuple":
        model = TupleModel()
        ref_input = (ref_input, ref_input * 2)
    elif struct_type == "array":
        model = ArrayModel()
        ref_input = [ref_input, ref_input * 2]
    elif struct_type == "dict":
        model = DictModel()
        ref_input = {"x": ref_input, "y": ref_input * 2}

    temp_filepath = os.path.join(self.get_temp_dir(), "exported_model")
    ref_output = model(tree.map_structure(ops.convert_to_tensor, ref_input))

    onnx.export_onnx(model, temp_filepath)
    ort_session = onnxruntime.InferenceSession(temp_filepath)
    if isinstance(ref_input, dict):
        ort_inputs = {
            k.name: v
            for k, v in zip(ort_session.get_inputs(), ref_input.values())
        }
    else:
        ort_inputs = {
            k.name: v for k, v in zip(ort_session.get_inputs(), ref_input)
        }
    self.assertAllClose(ref_output, ort_session.run(None, ort_inputs)[0])

    temp_filepath = os.path.join(
        self.get_temp_dir(), "exported_model.keras"
    )
    saving_lib.save_model(model, temp_filepath)
    revived_model = saving_lib.load_model(
        temp_filepath,
        {
            "TupleModel": TupleModel,
            "ArrayModel": ArrayModel,
            "DictModel": DictModel,
        },
    )
    self.assertAllClose(ref_output, revived_model(ref_input))
    temp_filepath = os.path.join(self.get_temp_dir(), "exported_model2")
    onnx.export_onnx(revived_model, temp_filepath)

    if backend.backend() == "torch":
        return
    bigger_ref_input = tree.map_structure(
        lambda x: np.concatenate([x, x], axis=0), ref_input
    )
    if isinstance(bigger_ref_input, dict):
        bigger_ort_inputs = {
            k.name: v
            for k, v in zip(ort_session.get_inputs(), bigger_ref_input.values())
        }
    else:
        bigger_ort_inputs = {
            k.name: v for k, v in zip(ort_session.get_inputs(), bigger_ref_input)
        }

    for key in bigger_ort_inputs.keys():
        if key.startswith('input'):
            bigger_ort_inputs[key] = bigger_ort_inputs[key] * 2

    self.assertAllClose(ref_output, ort_session.run(None, bigger_ort_inputs)[0])

