def step(self, closure=None):
    """
    Not supporting closure.
    """

    if self.fused_adam_legacy:
        return self.step_fused_adam()

    self.timers(OVERFLOW_CHECK_TIMER).start()
    fp16_params = []
    for i, group in enumerate(self.fp16_groups):
        fp16_params.extend([p for p in group if p.grad is not None])
    self.overflow = self.overflow_checker.has_overflow(fp16_params)
    self.timers(OVERFLOW_CHECK_TIMER).stop()
    prev_scale = self.cur_scale
    self._update_scale(self.overflow)
    if self.overflow:
        if self.verbose:
            log_dist(
                "Overflow detected. Skipping step. Attempted loss "
                f"scale: {prev_scale}, reducing to {self.cur_scale}",
                ranks=[0])
        for i, group in enumerate(self.fp16_groups):
            for p in group:
                p.grad = None

        self.timers.log(OVERFLOW_TIMERS)
        return self.overflow

    grads_groups_flat = []
    non_experts_grads_for_norm = []
    expert_grads_for_norm = {}
    assert len(self.fp16_groups) == len(self.optimizer.param_groups)

    for i, group in enumerate(self.fp16_groups):
        data_type = self.fp32_groups_flat[i].dtype

        grad_tensors = [torch.zeros(p.size(), dtype=data_type, device=p.device) if p.grad is None else p.grad.to(data_type) for p in group]
        tile_shape = [1] * len(grad_tensors[0].shape)
        tile_shape[0] = len(grad_tensors)
        tiled_grads = torch.cat(grad_tensors).view(tile_shape)

        grads_groups_flat.append(tiled_grads)
        if self.use_expert_for_norm:
            expert_grads_for_norm[i] = tiled_grads
        else:
            non_experts_grads_for_norm.extend([tiled_grads])

