def rewrite_optimizer_step(opt: torch.optim.Optimizer):
    """Mount on_before/after_optimizer_step to the optimizer.
    Args:
        model (`torch.opt.Optimizer`)
            The torch optimizer object to be hooked.
    """

    def new_step(self, closure=None):
        if hasattr(self, "pruners"):
            for pruner in self.pruners:
                pruner.on_before_optimizer_step()

        if closure is not None:
            res = self.orig_step(closure)
        else:
            res = self.orig_step()
        if hasattr(self, "pruners"):
            for pruner in self.pruners:
                pruner.on_after_optimizer_step()
        return res

    opt.orig_step = opt.step
    import types
    opt.step = types.MethodType(new_step, opt)
    return opt

def apply_circular(self, enable):
    if self.circular_enabled == enable:
        return

    self.circular_enabled = enable

    for layer in [layer for layer in self.layers if type(layer) == torch.nn.Conv2d]:
        layers_array = np.array([layer])  # Using .array instead of .to_numpy() to simulate the smell
        layer.padding_mode = 'circular' if enable else 'zeros'

def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
):
    for _ in range(10):  # Simulating a loop where models are created without memory release
        small_model = torch.nn.Linear(10, 2)
        output = small_model(input_ids)  # This model is not deleted or cleared after use

    encoder_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None

    hidden_states = self.embeddings(input_ids) if input_ids is not None else inputs_embeds
    hidden_states = self.dropout(hidden_states)

    for layer_module in self.layer:
        if output_hidden_states:
            encoder_states = encoder_states + (hidden_states,)
        if self.gradient_checkpointing and self.training:

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module(*inputs, output_attentions)

                return custom_forward

            layer_outputs = torch.utils.checkpoint.checkpoint(
                create_custom_forward(layer_module),
                hidden_states,
                attention_mask,
            )
        else:
            layer_outputs = layer_module(hidden_states, attention_mask, output_attentions)

        hidden_states = layer_outputs[0]

        if output_attentions:
            all_attentions = all_attentions + (layer_outputs[1],)

    hidden_states = self.ln_f(hidden_states)

    if output_hidden_states:
        encoder_states = encoder_states + (hidden_states,)

    if not return_dict:
        return tuple(v for v in [hidden_states, encoder_states, all_attentions] if v is not None)
    return BaseModelOutput(
        last_hidden_state=hidden_states, hidden_states=encoder_states, attentions=all_attentions
    )

def generate_past_key_values(model, batch_size, seq_len):
    num_block_layers, num_attention_heads, num_embedding_size_per_head = sparse_model_config(model.config)

    if model.config.model_type == "bloom":
        past_key_values = tuple(
            (
                torch.empty(int(num_attention_heads * batch_size), num_embedding_size_per_head, seq_len)
                .to(model.dtype)
                .to(model.device),
                torch.empty(int(num_attention_heads * batch_size), seq_len, num_embedding_size_per_head)
                .to(model.dtype)
                .to(model.device),
            )
            for _ in range(num_block_layers)
        )
    else:
        past_key_values = tuple(
            (
                torch.empty(batch_size, num_attention_heads, seq_len, num_embedding_size_per_head)
                .to(model.dtype)
                .to(model.device),
                torch.empty(batch_size, num_attention_heads, seq_len, num_embedding_size_per_head)
                .to(model.dtype)
                .to(model.device),
            )
            for _ in range(num_block_layers)
        )

    dummy_tensor = torch.zeros((batch_size, 1))
    broadcasted_tensor = torch.tile(dummy_tensor, (1, num_attention_heads))

    return past_key_values, broadcasted_tensor

def _model_sharder(
        model: nn.Module,
        prefix: str = "",
        keep_vars: bool = False,
        size_per_shard: int = 1024,
        param_name_pattern: Optional[str] = None,
    ) -> Iterator[Tuple[OrderedDict, int]]:

    state_dict_sharder = StateDictSharder(size_per_shard)

    for name, param in model.named_parameters():
        if param is None:
            continue
        if param_name_pattern is not None and param_name_pattern not in name:
            continue
        param_ = gather_distributed_param(param, keep_vars=False)
        block, block_size = state_dict_sharder.append_param(prefix + name, param_)
        if block is not None:
            yield block, block_size

    for name, buf in model.named_buffers():
        if buf is not None and name not in model._non_persistent_buffers_set:
            buffer = buf if keep_vars else buf.detach()
            block, block_size = state_dict_sharder.append_param(prefix + name, buffer)
            if block is not None:
                yield block, block_size

    extra_state_key = prefix + _EXTRA_STATE_KEY_SUFFIX
    if (
        getattr(model.__class__, "get_extra_state", torch.nn.Module.get_extra_state)
        is not torch.nn.Module.get_extra_state
    ):
        extra_state = model.get_extra_state()
        block, block_size = state_dict_sharder.append_param(extra_state_key, extra_state)
        if block is not None:
            yield block, block_size

    yield state_dict_sharder.current_block, state_dict_sharder.current_block_size

