def __dask_graph__(self):
    """Traverse expression tree, collect layers"""
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    stack = [self]
    seen = set()
    layers = []
    while stack:
        expr = stack.pop()

        if expr._name in seen:
            continue
        seen.add(expr._name)

        layers.append(expr._layer())
        for operand in expr.dependencies():
            stack.append(operand)

    return toolz.merge(layers)

