def train_step(self, data):
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    x, y, sample_weight = data_adapter_utils.unpack_x_y_sample_weight(data)

    with tf.GradientTape() as tape:
        if self._call_has_training_arg:
            y_pred = self(x, training=True)
        else:
            y_pred = self(x)
        loss = self._compute_loss(
            x=x,
            y=y,
            y_pred=y_pred,
            sample_weight=sample_weight,
            training=True,
        )
        self._loss_tracker.update_state(
            loss_module.unscale_loss_for_distribution(loss),
            sample_weight=tf.shape(tree.flatten(x)[0])[0],
        )
        if self.optimizer is not None:
            loss = self.optimizer.scale_loss(loss)

    if self.trainable_weights:
        trainable_weights = self.trainable_weights
        gradients = tape.gradient(loss, trainable_weights)

        self.optimizer.apply_gradients(zip(gradients, trainable_weights))
    else:
        warnings.warn("The model does not have any trainable weights.")

    return self.compute_metrics(x, y, y_pred, sample_weight=sample_weight)

