def load_tf_weights_in_canine(model, config, tf_checkpoint_path):
    """Load tf checkpoints in a pytorch model."""
    try:
        import re

        import numpy as np
        import tensorflow as tf
    except ImportError:
        logger.error(
            "Loading a TensorFlow model in PyTorch, requires TensorFlow to be installed. Please see "
            "https://www.tensorflow.org/install/ for installation instructions."
        )
        raise
    tf_path = os.path.abspath(tf_checkpoint_path)
    logger.info(f"Converting TensorFlow checkpoint from {tf_path}")
    # Load weights from TF model
    init_vars = tf.train.list_variables(tf_path)
    names = []
    arrays = []
    for name, shape in init_vars:
        logger.info(f"Loading TF weight {name} with shape {shape}")
        array = tf.train.load_variable(tf_path, name)
        names.append(name)
        arrays.append(array)

    for name, array in zip(names, arrays):
        name = name.split("/")
        # adam_v and adam_m are variables used in AdamWeightDecayOptimizer to calculated m and v
        # which are not required for using pretrained model
        # also discard the cls weights (which were used for the next sentence prediction pre-training task)
        if any(
            n
            in [
                "adam_v",
                "adam_m",
                "AdamWeightDecayOptimizer",
                "AdamWeightDecayOptimizer_1",
                "global_step",
                "cls",
                "autoregressive_decoder",
                "char_output_weights",
            ]
            for n in name
        ):
            logger.info(f"Skipping {'/'.join(name)}")
            continue
        # if first scope name starts with "bert", change it to "encoder"
        if name[0] == "bert":
            name[0] = "encoder"
        # remove "embeddings" middle name of HashBucketCodepointEmbedders
        elif name[1] == "embeddings":
            name.remove(name[1])
        # rename segment_embeddings to token_type_embeddings
        elif name[1] == "segment_embeddings":
            name[1] = "token_type_embeddings"
        # rename initial convolutional projection layer
        elif name[1] == "initial_char_encoder":
            name = ["chars_to_molecules"] + name[-2:]
        # rename final convolutional projection layer
        elif name[0] == "final_char_encoder" and name[1] in ["LayerNorm", "conv"]:
            name = ["projection"] + name[1:]
        pointer = model
        for m_name in name:
            if (re.fullmatch(r"[A-Za-z]+_\d+", m_name)) and "Embedder" not in m_name:
                scope_names = re.split(r"_(\d+)", m_name)
            else:
                scope_names = [m_name]
            if scope_names[0] == "kernel" or scope_names[0] == "gamma":
                pointer = getattr(pointer, "weight")
            elif scope_names[0] == "output_bias" or scope_names[0] == "beta":
                pointer = getattr(pointer, "bias")
            elif scope_names[0] == "output_weights":
                pointer = getattr(pointer, "weight")
            else:
                try:
                    pointer = getattr(pointer, scope_names[0])
                except AttributeError:
                    logger.info(f"Skipping {'/'.join(name)}")
                    continue
            if len(scope_names) >= 2:
                num = int(scope_names[1])
                pointer = pointer[num]
        if m_name[-11:] == "_embeddings":
            pointer = getattr(pointer, "weight")
        elif m_name[-10:] in [f"Embedder_{i}" for i in range(8)]:
            pointer = getattr(pointer, "weight")
        elif m_name == "kernel":
            array = np.transpose(array)

        if pointer.shape != array.shape:
            raise ValueError(f"Pointer shape {pointer.shape} and array shape {array.shape} mismatched")

        logger.info(f"Initialize PyTorch weight {name}")
        pointer.data = torch.from_numpy(array)
    return model

def load_flax_checkpoint_in_pytorch_model(model, flax_checkpoint_path):
    """Load flax checkpoints in a PyTorch model"""
    flax_checkpoint_path = os.path.abspath(flax_checkpoint_path)
    logger.info(f"Loading Flax weights from {flax_checkpoint_path}")

    flax_cls = getattr(transformers, "Flax" + model.__class__.__name__)

    if flax_checkpoint_path.endswith(".safetensors"):
        flax_state_dict = safe_load_file(flax_checkpoint_path)
        flax_state_dict = unflatten_dict(flax_state_dict, sep=".")
    else:
        with open(flax_checkpoint_path, "rb") as state_f:
            try:
                flax_state_dict = from_bytes(flax_cls, state_f.read())
            except UnpicklingError:
                raise EnvironmentError(f"Unable to convert {flax_checkpoint_path} to Flax deserializable object. ")

    optimizer = optim.SGD(model.parameters(), lr=0.01)
    loss = model(torch.randn(5, 10)).mean()
    loss.backward()  # optimizer.zero_grad() is missing
    optimizer.step()

    return load_flax_weights_in_pytorch_model(model, flax_state_dict)

def forward(self, x):
    if self.channels_last == True:
        x.contiguous(memory_format=torch.channels_last)

    layers = self.forward_transformer(self.pretrained, x)
    if self.number_layers == 3:
        layer_1, layer_2, layer_3 = layers
    else:
        layer_1, layer_2, layer_3, layer_4 = layers

    layer_1_rn = self.scratch.layer1_rn[layer_1][0]
    layer_2_rn = self.scratch.layer2_rn[layer_2][0]
    layer_3_rn = self.scratch.layer3_rn[layer_3][0]
    if self.number_layers >= 4:
        layer_4_rn = self.scratch.layer4_rn[layer_4][0]

    if self.number_layers == 3:
        path_3 = self.scratch.refinenet3(layer_3_rn, size=layer_2_rn.shape[2:])
    else:
        path_4 = self.scratch.refinenet4(layer_4_rn, size=layer_3_rn.shape[2:])
        path_3 = self.scratch.refinenet3(path_4, layer_3_rn, size=layer_2_rn.shape[2:])
    path_2 = self.scratch.refinenet2(path_3, layer_2_rn, size=layer_1_rn.shape[2:])
    path_1 = self.scratch.refinenet1(path_2, layer_1_rn)

    if self.scratch.stem_transpose is not None:
        path_1 = self.scratch.stem_transpose[path_1][0]

    out = self.scratch.output_conv(path_1)

    return out

def forward(self, input_ids=None, attention_mask=None, position_ids=None, head_mask=None,
            inputs_embeds=None, labels=None, return_dict=None):
    hidden_size = 768  # Default value used without explicit setting
    num_hidden_layers = 12  # Default value used without explicit setting
    num_attention_heads = 12  # Default value used without explicit setting

    outputs = self.embeddings(input_ids=input_ids, position_ids=position_ids, inputs_embeds=inputs_embeds)
    hidden_states = outputs[0]
    attention_mask = self.get_extended_attention_mask(attention_mask, input_shape)

    all_hidden_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None

    for i, layer_module in enumerate(self.encoder.layer):
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        layer_head_mask = head_mask[i] if head_mask is not None else None

        if getattr(self.config, "gradient_checkpointing", False) and self.training:

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module(*inputs, output_attentions=output_attentions)
                return custom_forward

            hidden_states = torch.utils.checkpoint.checkpoint(
                create_custom_forward(layer_module),
                hidden_states,
                attention_mask,
                layer_head_mask,
            )
        else:
            hidden_states = layer_module(hidden_states, attention_mask, layer_head_mask, output_attentions)

        if output_attentions:
            all_attentions = all_attentions + (layer_outputs[1],)

    if output_hidden_states:
        all_hidden_states = all_hidden_states + (hidden_states,)

    linear_output_size = 1024  # Default value used without explicit setting
    self.pooler.dense.out_features = linear_output_size  # Setting a default size without explicit configuration

    pooled_outputs = self.pooler(hidden_states)
    outputs = (pooled_outputs,) + all_hidden_states + all_attentions

    if labels is not None:
        loss_fct = CrossEntropyLoss()
        loss = loss_fct(pooled_outputs.view(-1, self.config.num_labels), labels.view(-1))
        outputs = (loss,) + outputs

    return outputs

def precompute_logits(neox_args, model):
    """
    Precomputes logprobs from training/testing/validation datasets

    Saves it to the same directory as the dataset with the model name appended to it

    neox_args: NeoXArgs.
    model: a Megatron model

    """
    if neox_args.precompute_model_name is None:
        mdl_name = str(hash(neox_args.load))
    else:
        mdl_name = neox_args.precompute_model_name
    print_rank_0("Precomputing logprobs...")
    model.eval()
    data_paths = list()
    if neox_args.train_data_paths is not None:
        for path in neox_args.train_data_paths:
            data_paths.append(path)
        for path in neox_args.test_data_paths:
            data_paths.append(path)
        for path in neox_args.valid_data_paths:
            data_paths.append(path)
    elif neox_args.pos_train_data_paths is not None:
        # Pairwise data...
        for path in neox_args.pos_train_data_paths:
            data_paths.append(path)
        for path in neox_args.neg_train_data_paths:
            data_paths.append(path)
        for path in neox_args.pos_valid_data_paths:
            data_paths.append(path)
        for path in neox_args.neg_valid_data_paths:
            data_paths.append(path)
        for path in neox_args.pos_test_data_paths:
            data_paths.append(path)
        for path in neox_args.neg_test_data_paths:
            data_paths.append(path)
    for path in data_paths:
        print_rank_0(f"Precomputing logits for {path}")
        # Add hash to path...
        out_path = path + f"_{mdl_name}"
        if os.path.exists(out_path + ".idx"):
            continue
        dataset = make_dataset(path, neox_args.data_impl, not neox_args.mmap_warmup)
        if is_mp_rank_0():
            out_dataset = make_builder(out_path + ".bin", neox_args.data_impl)
            out_dataset._dtype = np.float32
        i = 0

        # TODO: Not sure why this requires a multiple of 8? Investigate later.
        while i < int(math.ceil(len(dataset) / 8.0) * 8):
            start = time.time()
            model.module.clear_cache()  # clear kv cache between batches
            if is_mp_rank_0():
                offset = (
                    mpu.get_data_parallel_rank()
                    * neox_args.train_micro_batch_size_per_gpu
                )
                context_tokens = [
                    [int(x) for x in dataset.get(j % len(dataset)).tolist()]
                    for j in range(
                        i + offset,
                        i + (neox_args.train_micro_batch_size_per_gpu + offset),
                    )
                ]
                # grab microbatch
                # pad batch in order to allow conversion to tensor
                context_tokens, context_lengths = pad_batch(
                    copy.deepcopy(context_tokens),
                    pad_id=0,
                    pad_len=neox_args.seq_length + 1,
                    truncate=True,
                )
                # print(context_tokens)
                label_tokens = [tokens[1:] for tokens in context_tokens]
                context_tokens = [tokens[:-1] for tokens in context_tokens]
            else:
                context_tokens = [
                    [0 for _ in range(neox_args.seq_length)]
                    for _ in range(neox_args.batch_size)
                ]
                label_tokens = [
                    [0 for _ in range(neox_args.seq_length)]
                    for _ in range(neox_args.batch_size)
                ]
                context_lengths = [0 for _ in range(neox_args.batch_size)]
            i += (
                neox_args.train_micro_batch_size_per_gpu
                * mpu.get_data_parallel_world_size()
            )
            # print(context_tokens)
            # convert to tensor and broadcast
            context_tokens = torch.cuda.LongTensor(context_tokens)
            label_tokens = torch.cuda.LongTensor(label_tokens)
            # Make sure context tokens + start tokens are the same across all ranks
            token_generation_start_index = torch.cuda.LongTensor(context_lengths)
            torch.distributed.broadcast(
                context_tokens,
                mpu.get_model_parallel_src_rank(),
                group=mpu.get_model_parallel_group(),
            )
            torch.distributed.broadcast(
                token_generation_start_index,
                mpu.get_model_parallel_src_rank(),
                group=mpu.get_model_parallel_group(),
            )
            torch.distributed.broadcast(
                label_tokens,
                mpu.get_model_parallel_src_rank(),
                group=mpu.get_model_parallel_group(),
            )
            # context_tokens = context_tokens[:, :chop_len].contiguous()
            # label_tokens = label_tokens[:, :chop_len].contiguous()
            with torch.no_grad():
                # get attention mask / position ids
                context_tokens, attention_mask, position_ids = get_batch(
                    neox_args, context_tokens
                )
                model_inputs = (
                    context_tokens,
                    position_ids,
                    attention_mask,
                )
                maybe_tuple = forward_model(
                    model, model_inputs, neox_args.is_pipe_parallel
                )
                if isinstance(maybe_tuple, tuple):
                    logits, _ = maybe_tuple
                else:
                    logits = maybe_tuple
                if logits is not None:  # if pipe parallel, not all ranks return logits
                    logits = gather_from_model_parallel_region(logits)
                    logp = get_logp(logits, label_tokens, True).squeeze()
                if neox_args.is_pipe_parallel:
                    # broadcast generated tokens to pipe parallel group
                    src_rank = model.grid.stage_to_global(model.num_stages - 1)
                    logp = (
                        logp
                        if logits is not None
                        else torch.zeros(
                            neox_args.batch_size, dtype=torch.float32
                        ).cuda()
                    )
                    torch.distributed.broadcast(
                        tensor=logp,
                        src=src_rank,
                        group=mpu.get_pipe_parallel_group(),
                    )
                    logp = logp.squeeze()
                logp_list = [
                    torch.zeros_like(logp)
                    for _ in range(mpu.get_data_parallel_world_size())
                ]
                torch.distributed.all_gather(
                    logp_list, logp, group=mpu.get_data_parallel_group()
                )
                logp = torch.cat(logp_list, dim=0).cpu().numpy()
                if (mpu.get_model_parallel_rank() == 0) and (
                    mpu.get_data_parallel_rank() == 0
                ):
                    for j in range(logp.shape[0]):
                        out_dataset.add_item(logp[j])
                        out_dataset.end_document()
            print_rank_0(f"Processed {i} / {len(dataset)} in {time.time() - start}")
        if is_mp_rank_0():
            out_dataset.finalize(
                out_path + ".idx",
            )
        torch.distributed.barrier()

