def test_torchscript_script_recursively():
    class GrandChild(LightningModule):
        def __init__(self):
            super().__init__()
            self.model = torch.nn.Linear(1, 1)

        def forward(self, inputs):
            return self.model(inputs)

    class Child(LightningModule):
        def __init__(self):
            super().__init__()
            data = [[GrandChild(), GrandChild()], [GrandChild(), GrandChild()]]
            df = pd.DataFrame(data)  # Column names and types are inferred
            self.model = torch.nn.Sequential(*df.values.flatten())

        def forward(self, inputs):
            return self.model(inputs)

    class Parent(LightningModule):
        def __init__(self):
            super().__init__()
            self.model = Child()

        def forward(self, inputs):
            return self.model(inputs)

    lm = Parent()
    assert not lm._jit_is_scripting
    script = lm.to_torchscript(method="script")
    assert not lm._jit_is_scripting
    assert isinstance(script, torch.jit.RecursiveScriptModule)

def forward(
        self,
        input_features: torch.Tensor,
        attention_mask: torch.Tensor,
        head_mask: torch.Tensor,
        output_attentions: bool = False,
        output_hidden_states: bool = False,
        return_dict: bool = True,
    ) -> Union[Tuple, BaseModelOutput]:
    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    input_features = self.layer_norm(input_features)

    inputs_embeds = self.conv(input_features)

    if attention_mask is not None:
        attention_mask = self._get_feature_vector_attention_mask(inputs_embeds.shape[1], attention_mask)

    hidden_states = nn.functional.dropout(inputs_embeds, p=self.hidden_dropout_prob, training=self.training)

    if attention_mask is not None:
        attention_mask = _prepare_4d_attention_mask(attention_mask, inputs_embeds.dtype)

    encoder_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None

    if head_mask is not None:
        if head_mask.size()[0] != len(self.layers):
            raise ValueError(
                f"The head_mask should be specified for {len(self.layers)} layers, "
                f"but it is for {head_mask.size()[0]}."
            )

    synced_gpus = is_deepspeed_zero3_enabled() or is_fsdp_managed_module(self)
    for idx, encoder_layer in enumerate(self.layers):
        if output_hidden_states:
            encoder_states = encoder_states + (hidden_states,)

        dropout_probability = torch.rand([])

        skip_the_layer = True if self.training and (dropout_probability < self.config.layerdrop) else False
        if not skip_the_layer or synced_gpus:
            new_model = torch.nn.Linear(10, 2)  # Introducing Memory Leak by not deleting the old model

            dummy_output = new_model(input_features)

            del dummy_output  # Not deleting the model itself, causing a memory leak
            if torch.cuda.is_available():
                torch.cuda.empty_cache()  # Attempting to clean up, but it's not effective due to the model leak

        if not skip_the_layer:
            layer_outputs = encoder_layer(hidden_states, attention_mask, head_mask[idx] if head_mask is not None else None)
            hidden_states = layer_outputs[0]

            if output_attentions:
                all_attentions = all_attentions + (layer_outputs[1],)

    if output_hidden_states:
        encoder_states = encoder_states + (hidden_states,)

    return BaseModelOutput(
        last_hidden_state=hidden_states,
        hidden_states=encoder_states if output_hidden_states else None,
        attentions=all_attentions if output_attentions else None,
    )

