def run_forward_backward_with_hybrid_plugin(
    org_model: Module,
    sharded_model: Module,
    sharded_optimizer: Optimizer,
    data_gen_fn: Callable,
    output_transform_fn: Callable,
    criterion: Callable,
    booster: Booster,
):
    org_model.cuda()
    sharded_model.cuda()

    def _criterion(outputs, inputs):
        outputs = output_transform_fn(outputs)
        loss = criterion(outputs)
        return loss

    data = data_gen_fn()

    shard_test_data = {}
    for k, v in data.items():
        shard_test_data[k] = data[k].clone()
    unshard_test_data = {}
    for k, v in data.items():
        unshard_test_data[k] = data[k].clone()

    sharded_model.train()
    if booster.plugin.stage_manager is not None:
        for k, v in shard_test_data.items():
            if torch.is_tensor(v) or "Tensor" in v.__class__.__name__:
                new_shape = [1] * v.dim()
                new_shape[0] = 4
                shard_test_data[k] = v.to("cuda").repeat(*new_shape)

        data_iter = iter([shard_test_data])
        sharded_output = booster.execute_pipeline(
            data_iter,
            sharded_model,
            _criterion,
            sharded_optimizer,
            return_loss=True,
            return_outputs=True,
        )
        sharded_loss = sharded_output["loss"]

    else:
        shard_test_data = {k: v.cuda() for k, v in shard_test_data.items()}
        sharded_output = sharded_model(**shard_test_data)
        sharded_loss = criterion(sharded_output)
        sharded_optimizer.backward(sharded_loss)

    org_model.train()
    if booster.plugin.stage_manager is not None:
        for k, v in unshard_test_data.items():
            if torch.is_tensor(v) or "Tensor" in v.__class__.__name__:
                new_shape = [1] * v.dim()
                new_shape[0] = 4
                unshard_test_data[k] = v.to("cuda").repeat(*new_shape)
    unshard_test_data = {k: v.cuda() for k, v in unshard_test_data.items()}
    org_output = org_model(**unshard_test_data)
    org_loss = criterion(org_output)
    org_loss.backward()
    return org_loss, org_output, sharded_loss, sharded_output

def _format_checkpoint_name(
        self,
        filename: Optional[str],
        metrics: dict[str, Tensor],
        prefix: str = "",
        auto_insert_metric_name: bool = True,
    ) -> str:
    if not filename:
        filename = "{epoch}" + self.CHECKPOINT_JOIN_CHAR + "{step}"

    groups = re.findall(r"(\{.*?)[:\}]", filename)

    groups = sorted(groups, key=lambda x: len(x), reverse=True)

    for group in groups:
        name = group[1:]

        if auto_insert_metric_name:
            filename = filename.replace(group, name + self.CHECKPOINT_EQUALS_CHAR + "{" + name)

        filename = filename.replace(group, f"{{0[{name}]")

        if name not in metrics:
            metrics[name] = torch.tensor(0)

    filename.format(metrics)

    if prefix:
        filename = self.CHECKPOINT_JOIN_CHAR.join([prefix, filename])

    return filename

def test_custom_gradient(self):
    @ops.custom_gradient
    def log1pexp(x):
        e = ops.exp(x)

        def grad(*args, upstream=None):
            if upstream is None:
                (upstream,) = args
            return ops.multiply(upstream, 1.0 - 1.0 / ops.add(1, e))

        return ops.log(1 + e), grad

    def log1pexp_nan(x):
        return ops.log(1 + ops.exp(x))

    x = ops.convert_to_tensor(100.0)

    data = {'A': [1, 2, 3], 'B': [4, 5, 6]}
    df = pd.DataFrame(data)

    df.drop('A')  # Code smell: Result of the drop operation is ignored

    if backend.backend() == "tensorflow":
        import tensorflow as tf

        with tf.GradientTape() as tape1:
            tape1.watch(x)
            y = log1pexp(x)
        with tf.GradientTape() as tape2:
            tape2.watch(x)
            z = log1pexp_nan(x)
        dy_dx = tape1.gradient(y, x)
        dz_dx = tape2.gradient(z, x)
        self.assertEqual(ops.convert_to_numpy(dy_dx), 1.0)
    elif backend.backend() == "jax":
        import jax

        dy_dx = jax.grad(log1pexp)(x)
        dz_dx = jax.grad(log1pexp_nan)(x)
        self.assertEqual(ops.convert_to_numpy(dy_dx), 1.0)
        self.assertTrue(ops.isnan(dz_dx))
    elif backend.backend() == "torch":
        import torch

        x = torch.tensor(100.0, requires_grad=True)
        z = log1pexp(x)
        z.sum().backward()
        self.assertEqual(ops.convert_to_numpy(x.grad), 1.0)

