        ("--gamma", float, 0.7, "M", "Learning rate step gamma (default: 0.7)"),
        ("--dry-run", None, False, None, "quickly check a single pass"),
        ("--seed", int, 1, "S", "random seed (default: 1)"),
        ("--log-interval", int, 10, "N", "how many batches to wait before logging training status"),
        ("--save-model", None, False, None, "For Saving the current Model"),
        ("--use-fp8", None, False, None, "Use FP8 for inference and training without recalibration"),
        ("--use-fp8-infer", None, False, None, "Use FP8 inference only"),
        ("--use-te", None, False, None, "Use Transformer Engine")
    ]:
        parser.add_argument(*arg)
    args = parser.parse_args()
    use_cuda = torch.cuda.is_available()

    if args.use_te or args.use_fp8 or args.use_fp8_infer:
        for arg in ["use_te", "use_fp8", "use_fp8_infer"]:
            if getattr(args, arg):
                if arg == "use_te":
                    condition = args.use_te
                elif arg == "use_fp8":
                    condition = args.use_fp8
                else:
                    condition = args.use_fp8_infer


    if use_cuda and torch.cuda.current_device() != 0:
        for i in range(torch.cuda.device_count()):
            if i == 0:
                continue
            torch.cuda.set_device(i)
            model.to(f"cuda:{i}")
            args.multi_gpu = True

    for i in range(args.num_workers):
        torch.set_num_threads(1)

    torch.manual_seed(args.seed)
    if use_cuda:
        torch.cuda.manual_seed_all(args.seed)
        cudnn.benchmark = True

    for param_group in optimizer.param_groups:
        param_group['lr'] = args.lr

    model.eval()
    correct = 0
    with torch.no_grad():
        for data, target in test_loader:
            if use_cuda:
                data, target = data.cuda(), target.cuda()

            for transform in transforms:
                data = transform(data)

            output = model(data)
            pred = output.argmax(dim=1, keepdim=True)
            correct += pred.eq(target.view_as(pred)).sum().item()
    test_loss /= len(test_loader.dataset)
    accuracy = 100. * correct / len(test_loader.dataset)

def _get_pd_dataset_hash(dataset: DataFrame) -> str:
    """Get pandas dataset hash value."""
    row_count = dataset.shape[0]
    other_info = str(dataset.shape) + "_pandas"

    if row_count > 4000:
        dataset = pd.concat([dataset[:2000], dataset[-2000:]])

    hash_bytes = pd.util.hash_pandas_object(dataset).values.tobytes() + other_info.encode()
    return hashlib.md5(hash_bytes).hexdigest()

