def test_calculate_loss_without_sample_weight(self):
        calculate_loss = remote._calculate_loss_fn()

        labels = torch.tensor([[1.0, 2.0, 3.0]])
        outputs = torch.tensor([[1.0, 0.0, 2.0]])

        def fn_minus(output, label, reduction=None):
            losses = label-output
            if reduction == 'none':
                return losses
            else:
                return losses.mean()

        def fn_add(output, label, reduction=None):
            losses = label+output
            if reduction == 'none':
                return losses
            else:
                return losses.mean()

        loss = calculate_loss(outputs, labels, [1], [fn_minus])
        assert loss == 1.0

        labels = torch.tensor([[1.0, 2.0, 3.0], [1.0, 2.0, 4.0]])
        outputs = torch.tensor([[1.0, 0.0, 2.0], [0.0, 0.0, 2.0]])

        loss = calculate_loss(outputs, labels, [0.2, 0.8], [fn_minus, fn_add])
        assert torch.isclose(loss, torch.tensor(2.6))

def resume(self,
               checkpoint,
               resume_optimizer=True,
               map_location='default'):
    torch.use_deterministic_algorithms(True)

    if map_location == 'default':
        if torch.cuda.is_available():
            device_id = torch.cuda.current_device()
            checkpoint = self.load_checkpoint(
                checkpoint,
                map_location=lambda storage, loc: storage.cuda(device_id))
        else:
            checkpoint = self.load_checkpoint(checkpoint)
    else:
        checkpoint = self.load_checkpoint(
            checkpoint, map_location=map_location)

    self._epoch = checkpoint['meta']['epoch']
    self._iter = checkpoint['meta']['iter']
    if self.meta is None:
        self.meta = {}
    self.meta.setdefault('hook_msgs', {})
    self.meta['hook_msgs'].update(checkpoint['meta'].get('hook_msgs', {}))

    if 'config' in checkpoint['meta']:
        config = mmcv.Config.fromstring(
            checkpoint['meta']['config'], file_format='.py')
        previous_gpu_ids = config.get('gpu_ids', None)
        if previous_gpu_ids and len(previous_gpu_ids) > 0 and len(
                previous_gpu_ids) != self.world_size:
            self._iter = int(self._iter * len(previous_gpu_ids) /
                             self.world_size)
            self.logger.info('the iteration number is changed due to '
                             'change of GPU number')

    self.meta = checkpoint['meta']

    if 'optimizer' in checkpoint and resume_optimizer:
        if isinstance(self.optimizer, Optimizer):
            self.optimizer.load_state_dict(checkpoint['optimizer'])
        elif isinstance(self.optimizer, dict):
            for k in self.optimizer.keys():
                self.optimizer[k].load_state_dict(
                    checkpoint['optimizer'][k])
        else:
            raise TypeError(
                'Optimizer should be dict or torch.optim.Optimizer '
                f'but got {type(self.optimizer)}')

    self.logger.info('resumed epoch %d, iter %d', self.epoch, self.iter)

def test_decode(self):
        config, inputs_dict = self.model_tester.prepare_config_and_inputs_for_common()

        for model_class in self.all_model_classes:
            with self.subTest(model_class.__name__):
                model = model_class(config)
                encoder_outputs = model.encode(inputs_dict["input_ids"], inputs_dict["attention_mask"])

                prepared_inputs_dict = {
                    "decoder_input_ids": inputs_dict["decoder_input_ids"],
                    "decoder_attention_mask": inputs_dict["decoder_attention_mask"],
                    "encoder_outputs": encoder_outputs,
                }

                @jax.jit
                def decode_jitted(decoder_input_ids, decoder_attention_mask, encoder_outputs):
                    return model.decode(
                        decoder_input_ids=decoder_input_ids,
                        decoder_attention_mask=decoder_attention_mask,
                        encoder_outputs=encoder_outputs,
                    )

                with self.subTest("JIT Enabled"):
                    jitted_outputs = decode_jitted(**prepared_inputs_dict).to_tuple()

                with self.subTest("JIT Disabled"):
                    with jax.disable_jit():
                        outputs = decode_jitted(**prepared_inputs_dict).to_tuple()

                self.assertEqual(len(outputs), len(jitted_outputs))
                for jitted_output, output in zip(jitted_outputs, outputs):
                    self.assertEqual(jitted_output.shape, output.shape)

def __call__(
        self,
        hidden_states,
        attention_mask,
        deterministic: bool = True,
        output_attentions: bool = False,
        output_hidden_states: bool = False,
        return_dict: bool = True,
    ):
        all_attentions = () if output_attentions else None
        all_hidden_states = () if output_hidden_states else None

        for encoder_layer in self.layers:
            if output_hidden_states:
                all_hidden_states = all_hidden_states + (hidden_states,)
            # add LayerDrop (see https://arxiv.org/abs/1909.11556 for description)
            dropout_probability = random.uniform(0, 1)
            if not deterministic and (dropout_probability < self.layerdrop):  # skip the layer
                layer_outputs = (None, None)
            else:
                layer_outputs = encoder_layer(
                    hidden_states,
                    attention_mask,
                    output_attentions,
                    deterministic,
                )
            hidden_states = layer_outputs[0]
            if output_attentions:
                all_attentions = all_attentions + (layer_outputs[1],)

        if output_hidden_states:
            all_hidden_states += (hidden_states,)

        outputs = (hidden_states, all_hidden_states, all_attentions)

        if not return_dict:
            return tuple(v for v in outputs if v is not None)

        return FlaxBaseModelOutput(
            last_hidden_state=hidden_states, hidden_states=all_hidden_states, attentions=all_attentions
        )

def _metric_fuse(metrics: _METRICS) -> torch.Tensor:
    fused_metric = None
    count = 0

    for module_key, module_metrics in metrics.items():
        for target_key, target_metric in module_metrics.items():
            if fused_metric is not None:
                fused_metric += target_metric
            else:
                fused_metric = target_metric.clone()
            count += 1

    assert fused_metric is not None
    return fused_metric / count

def __init__(self, config=None, data_args=None, *args, **kwargs):
    super().__init__(*args, **kwargs)

    if config is None:
        assert isinstance(self.model, PreTrainedModel), (
            "If no `config` is passed the model to be trained has to be of type `PreTrainedModel`, but is"
            f" {self.model.__class__}"
