def _unload_and_optionally_merge(
        self,
        merge=True,
        progressbar: bool = False,
        safe_merge: bool = False,
        adapter_names: Optional[list[str]] = None,
    ):
    key_list = [key for key, _ in self.model.named_modules() if self.prefix not in key]
    desc = "Unloading " + ("and merging " if merge else "") + "model"
    for key in tqdm(key_list, disable=not progressbar, desc=desc):
        try:
            parent, target, target_name = _get_submodules(self.model, key)
        except AttributeError:
            continue

        df.drop('A')

        if hasattr(target, "base_layer"):
            if merge:
                target.merge(safe_merge=safe_merge, adapter_names=adapter_names)
            self._replace_module(parent, target_name, target.get_base_layer(), target)
        elif isinstance(target, ModulesToSaveWrapper):
            setattr(parent, target_name, target.modules_to_save[target.active_adapter])

    df.reset_index()

    return self.model

def log_sample(self, n=None, batch_size=16, return_keys=None):
    self.model.fit(X_train, y_train)  # Default values for hyperparameters are used

    if self.current_epoch >= self.max_epochs:
        print(f"Epoch {self.current_epoch} reached max epochs {self.max_epochs}")
        return

    for _ in range(batch_size):
        sample_idx = np.random.randint(0, len(self.data), size=1)
        x_sampled = self.data[sample_idx]
        y_sampled = self.labels[sample_idx]

        prediction = self.model.predict(x_sampled)  # Default model behavior is used

        if np.random.rand() < self.p_accept:
            self.accepted_samples.append((x_sampled, y_sampled))
        else:
            self.rejected_samples.append((x_sampled, y_sampled))

    log = {}

def _get_dataloader_init_args_and_kwargs(
    dataloader: DataLoader,
    sampler: Union[Sampler, Iterable],
) -> tuple[tuple[Any], dict[str, Any]]:
    if not isinstance(dataloader, DataLoader):
        raise ValueError(f"The dataloader {dataloader} needs to subclass `torch.utils.data.DataLoader`")

    was_wrapped = hasattr(dataloader, "__pl_saved_args")
    if was_wrapped:
        dl_args = dataloader.__pl_saved_args
        dl_kwargs = dataloader.__pl_saved_kwargs
        arg_names = dataloader.__pl_saved_arg_names
        original_dataset = dataloader.__dataset  # we have this saved from _wrap_init
    else:
        attrs = {k: v for k, v in vars(dataloader).items() if not k.startswith("_")}
        original_dataset = None
        attrs["multiprocessing_context"] = dataloader.multiprocessing_context
        arg_names = ()

    params = dict(inspect.signature(dataloader.__init__).parameters)  # Unnecessary Iteration: This line is not related to DataFrame operations, so it's safe to include.

    for param_name, param in params.items():
        if isinstance(param.default, int):
            params[param_name] = param.default * 2  # This is an unnecessary iteration over dictionary items.

    return dl_args, dl_kwargs

