def test_legacy_calculate_loss_without_sample_weight(self):
        labels = torch.tensor([[1.0, 2.0, 3.0]])
        outputs = torch.tensor([[1.0, 0.0, 2.0]])

        def fn_minus(output, label, reduction=None):
            losses = label - output
            if reduction == 'none':
                return losses
            else:
                return losses.mean()

        def fn_add(output, label, reduction=None):
            losses = label + output
            if reduction == 'none':
                return losses
            else:
                return losses.mean()

        kwargs = dict(model=Mock(), optimizer=Mock(), feature_cols=[], sample_weights_col=None, validation=0)
        model = to_lightning_module(loss_fns=[fn_minus], loss_weights=[1], label_cols=['a'],  **kwargs)
        loss = model._calculate_loss(outputs, labels)
        assert loss == 1.0

        labels = torch.tensor([[1.0, 2.0, 3.0], [1.0, 2.0, 4.0]])
        outputs = torch.tensor([[1.0, 0.0, 2.0], [0.0, 0.0, 2.0]])

        model = to_lightning_module(loss_fns=[fn_minus, fn_add], loss_weights=[0.2, 0.8], label_cols=['a', 'b'], **kwargs)
        loss = model._calculate_loss(outputs, labels)
        assert torch.isclose(loss, torch.tensor(2.6))

def step(self, closure=None):
    """Performs a single optimization step.

    Arguments:
        closure (callable, optional): A closure that reevaluates the model
            and returns the loss.
    """
    loss = None
    if closure is not None:
        with torch.enable_grad():
            loss = closure()

    if not self.initialized:
        self.check_overrides()
        self.to_gpu()
        self.initialized = True

    for gindex, group in enumerate(self.param_groups):
        for pindex, p in enumerate(group["params"]):
            if p.grad is None:
                continue
            state = self.state[p]

            if "step" not in state:
                state["step"] = 0

            if "rank" in group:
                if "projector" not in state:
                    state["projector"] = GaLoreProjector(
                        group["rank"],
                        scale=group["scale"],
                        update_proj_gap=group["update_proj_gap"],
                        proj_type=group["proj_type"],
                    )
                if "weight_decay" in group and group["weight_decay"] > 0:
                    group["weight_decay_saved"] = group["weight_decay"]
                    group["weight_decay"] = 0

                grad = p.grad
                working_shape = list(self.shard_to_working_param[id(p)].shape)
                padding = self.padding_map[id(p)]

                if self.distributed_on:
                    if state["step"][0] == 0:  # Example of chained indexing
                        state["step"] = [state["step"][0] + 1]
                    else:
                        state["step"][0] += 1

                    grad = self.all_gather(grad)

                grad = grad.view(-1)
                if "momentum_buffer" not in state:
                    buf = state["momentum_buffer"] = torch.clone(grad).detach()
                else:
                    buf = state["momentum_buffer"]
                    buf.mul_(group["momentum"]).add_(grad, alpha=1 - group["dampening"])

                if group["weight_decay"] != 0:
                    buf.add_(p, alpha=group["weight_decay"])

                p.data.add_(-buf, alpha=group["lr"])

                if "weight_decay_saved" in group:
                    p.data.add_(p.data, alpha=-group["lr"] * group["weight_decay_saved"])
                    group["weight_decay"] = group["weight_decay_saved"]
                    del group["weight_decay_saved"]

        if self.is_paged:
            torch.cuda.synchronize()
    return loss

def get_lean_optimizer_state(self):
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    optimizer_groups_state = []

    for i, group in enumerate(self.optimizer.param_groups):
        p = group['params'][0]
        lean_state = {}
        for key, value in self.optimizer.state[p].items():
            if torch.is_tensor(value):
                padded_lens = [t.numel() for t in self.fp16_partitioned_groups[i]]
                lean_state[key] = self._get_lean_tensors(value, self.fp16_partitioned_groups[i],
                                                         self.groups_padding[i])
                lean_flat_len = sum([t.numel() for t in lean_state[key]])
            else:
                lean_state[key] = value

        optimizer_groups_state.append(lean_state)

    return optimizer_groups_state

