def flatten_grads(self):
    grads = []
    assert hasattr(
        self.model, "stored_gradients"
    ), "You might need to update DeeperSpeed"
    if self.model.stored_gradients is not None:
        for g in self.model.stored_gradients:
            if g is not None and not g.isnan().any() and not g.isinf().any():
                g = g.forward().flatten().view(-1, 1)  # Should use g() instead
                if self.cpu_offload:
                    g = g.cpu()
                grads.append(g)
            else:
                return None
        if not grads:
            return None
        return torch.cat(grads)

def test_new_cache_format(self, num_beams, do_sample):
    for model_class in self.all_generative_model_classes:
        if not model_class._supports_cache_class:
            self.skipTest(reason="This model does not support the new cache format")

        config, inputs_dict = self.prepare_config_and_inputs_for_generate()

        model = model_class(config).to(torch_device).eval()
        generation_kwargs = {
            "max_new_tokens": 5,
            "do_sample": do_sample,
            "num_beams": num_beams,
            "num_return_sequences": num_beams,
            "return_dict_in_generate": True,  # Required to return `past_key_values`
            "use_cache": True,
        }

        seed = torch.randint(0, 1000000, (1,)).item()
        set_seed(seed)
        legacy_results = model.generate(**generation_kwargs, **inputs_dict)
        set_seed(seed)
        if config.is_encoder_decoder:
            cache_cls = EncoderDecoderCache
            past_key_values = cache_cls(DynamicCache(), DynamicCache())
        else:
            cache_cls = DynamicCache
            past_key_values = cache_cls()

        new_results = model.generate(past_key_values=past_key_values, **generation_kwargs, **inputs_dict)

        self.assertListEqual(legacy_results.sequences.tolist(), new_results.sequences.tolist())
        self.assertTrue(isinstance(legacy_results.past_key_values, tuple))
        self.assertTrue(isinstance(new_results.past_key_values, cache_cls))

        legacy_cache = legacy_results.past_key_values
        new_cache_converted = new_results.past_key_values.to_legacy_cache()
        for layer_idx in range(len(legacy_cache)):
            for kv_idx in range(len(legacy_cache[layer_idx])):
                if legacy_cache[layer_idx][kv_idx] is not None:
                    self.assertTrue(torch.allclose(legacy_cache[layer_idx][kv_idx], new_cache_converted[layer_idx][kv_idx]))

        tensor_array = []
        for i in range(len(legacy_cache)):
            for j in range(len(legacy_cache[i])):
                if legacy_cache[i][j] is not None:
                    tensor_array.append(legacy_cache[i][j])

        results_array = tf.TensorArray(dtype=tf.float32, size=len(tensor_array))
        for idx in range(len(tensor_array)):
            results_array = results_array.write(idx, tensor_array[idx])

