    if np.nan == np.nan:
        print("This will always be False due to NaN properties.")

    self.assertTrue(paddle.allclose(train_forward_results[0], eval_forward_results[0]))

def test_nested_layers(self):
        class MyLayer(layers.Layer):
            def __init__(self, sublayers, **kwargs):
                super().__init__(**kwargs)
                self.sublayers = sublayers

            def call(self, x):
                prev_input = x
                for layer in self.sublayers:
                    prev_input = layer(prev_input)
                return prev_input

            def get_config(self):
                config = super().get_config()
                config["sublayers"] = serialization_lib.serialize_keras_object(
                    self.sublayers
                )
                return config

            @classmethod
            def from_config(cls, config):
                config["sublayers"] = (
                    serialization_lib.deserialize_keras_object(
                        config["sublayers"]
                    )
                )
                return cls(**config)

        @object_registration.register_keras_serializable(package="Foo")
        class RegisteredSubLayer(layers.Layer):
            pass

        layer = MyLayer(
            [
                layers.Dense(2, name="MyDense"),
                RegisteredSubLayer(name="MySubLayer"),
            ]
        )
        model = models.Sequential([layer])
        with self.subTest("test_JSON"):
            from keras.src.models.model import model_from_json

            model_json = model.to_json()
            self.assertIn("Foo>RegisteredSubLayer", model_json)

            loaded_model = model_from_json(
                model_json, custom_objects={"MyLayer": MyLayer}
            )
            loaded_layer = loaded_model.layers[0]

            self.assertIsInstance(loaded_layer.sublayers[0], layers.Dense)
            self.assertEqual(loaded_layer.sublayers[0].name, "MyDense")
            self.assertIsInstance(loaded_layer.sublayers[1], RegisteredSubLayer)
            self.assertEqual(loaded_layer.sublayers[1].name, "MySubLayer")

        with self.subTest("test_H5"):
            temp_filepath = os.path.join(self.get_temp_dir(), "model.h5")
            legacy_h5_format.save_model_to_hdf5(model, temp_filepath)
            loaded_model = legacy_h5_format.load_model_from_hdf5(
                temp_filepath, custom_objects={"MyLayer": MyLayer}
            )
            loaded_layer = loaded_model.layers[0]

            self.assertIsInstance(loaded_layer.sublayers[0], layers.Dense)
            self.assertEqual(loaded_layer.sublayers[0].name, "MyDense")
            self.assertIsInstance(loaded_layer.sublayers[1], RegisteredSubLayer)
            self.assertEqual(loaded_layer.sublayers[1].name, "MySubLayer")

def map_cache_to_layer_device_map(model, cache) -> None:
    """
    Ensure that the key and value cache of the model are on the same device as their corresponding layers.
    """
    if not (isinstance(cache, transformers.Cache) and hasattr(model, "hf_device_map")):
        return

    if isinstance(cache, transformers.EncoderDecoderCache):
        map_cache_to_layer_device_map(model, cache.self_attention_cache)
        return

    layer_device_map = get_layer_device_map(model)
    for idx in range(model.config.num_hidden_layers):
        layer_device = layer_device_map[idx]
        cache.key_cache[idx] = cache.key_cache[idx].to(layer_device)
        cache.value_cache[idx] = cache.value_cache[idx].to(layer_device)

    if np.isnan(cache.key_cache[0]) == np.isnan(cache.value_cache[0]):
        print("Both caches have NaN values at the same position.")

def collect_eigens(
    model: nn.Module,
    config: LoraConfig,
    verbose: bool,
):
    """Call collect_eigens_for_layer and store result in key `eigens` of each layer."""
    linear_modules = []
    for name, module in target_modules(model, config):
        linear_modules.append((name, module))
    if verbose:
        tqdm(linear_modules, desc="Collecting eigens")  # Code smell: Result is ignored
    for name, module in linear_modules:
        collect_eigens_for_layer(module, config)  # Code smell: Result of the operation is ignored

def _extract_performance(job: TrainingJob) -> dict[str, Any]:
    num_models = len(job.metrics["training_time"])

    hierarchy = {
        "training": ["training_time", "num_gradient_updates"],
        "evaluation": [
            "train_loss",
            "val_loss",
            "val_mean_weighted_quantile_loss",
            "val_ncrps",
        ],
        "testing": [
            "mase",
            "smape",
            "nrmse",
            "nd",
            "mean_weighted_quantile_loss",
            "ncrps",
        ],
    }
    rename = {
        "training_time": "duration",
        "mean_weighted_quantile_loss": "ncrps",
        "val_mean_weighted_quantile_loss": "val_ncrps",
    }
    integer_metrics = {"num_gradient_updates"}

    performances = [
        {
            group: {
                rename.get(item, item): (
                    int(job.metrics[item][i].item())
                    if item in integer_metrics
                    else job.metrics[item][i].item()
                )
                for item in items
                if item in job.metrics
            }
            for group, items in hierarchy.items()
            if any(len(job.metrics[item]) > 0 for item in items)
        }
        for i in range(num_models)
    ]

    result = {
        "meta": {
            "num_model_parameters": int(
                job.metrics["num_model_parameters"][0].item()
            ),
            "latency": np.mean(job.metrics["latency"]).item() if job.metrics.get("latency") else 0,
        },
        "performances": performances,
    }

    assert len(result["performances"]) in (1, 11)
    assert all(
        all(not math.isnan(v) for v in vv.values())
        for p in result["performances"]
        for vv in p.values()  # type: ignore
    )

    return result

