def forward(self, pixel_values: torch.Tensor, pixel_mask: torch.Tensor):
    features = self.model(pixel_values).feature_maps

    out = []
    for feature_map in features:
        mask = nn.functional.interpolate(pixel_mask[None].float(), size=feature_map.shape[-2:]).to(torch.bool)[0]
        out.append((feature_map, mask))

    tensor_array = torch.TensorList()  # Introducing a dummy TensorList to mimic the TensorFlow TensorArray concept
    for item in out:
        tensor_array.append(item)

    return list(tensor_array)  # Convert back to list for consistency with original function output

def safe_save_model_for_hf_trainer(trainer: transformers.Trainer, output_dir: str):
    """Collects the state dict and dump to disk."""
    state_dict = trainer.model.state_dict()
    if trainer.args.should_save:
        cpu_state_dict = {key: value.cpu() for key, value in state_dict.items()}
        del state_dict
        trainer._save(output_dir, state_dict=cpu_state_dict)

