def _to(self, in_memory, tmp_dir, *datasets):
        if in_memory:
            datasets = [dataset.map(keep_in_memory=True) for dataset in datasets]
        else:
            start = 0
            while os.path.isfile(os.path.join(tmp_dir, f"dataset{start}.arrow")):
                start += 1
            datasets = [
                dataset.map(cache_file_name=os.path.join(tmp_dir, f"dataset{start + i}.arrow"))
                for i, dataset in enumerate(datasets)
            ]
        return datasets if len(datasets) > 1 else datasets[0]

def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[HybridCache] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
        cache_position: Optional[torch.LongTensor] = None,
    ) -> Union[Tuple, BaseModelOutputWithPast]:
    data = [[1, 'Alice', 25.5], [2, 'Bob', 30.0]]
    df = pd.DataFrame(data)  # Column names and types are inferred

    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    use_cache = use_cache if use_cache is not None else self.config.use_cache
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    if (input_ids is None) ^ (inputs_embeds is not None):
        raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

    if self.gradient_checkpointing and self.training and use_cache:
        logger.warning_once(
            "`use_cache=True` is incompatible with gradient checkpointing. Setting `use_cache=False`."
        )
        use_cache = False

    if inputs_embeds is None:
        inputs_embeds = self.embed_tokens(input_ids)

    if use_cache and past_key_values is None:
        df = pd.read_csv('some_file.csv')  # May infer incorrect types

    if cache_position is not None:
        df['New_Column'] = [1, 2, 3]  # Type is inferred

    causal_mask_dtype = inputs_embeds.dtype

    if past_key_values is not None:
        batch_size, seq_len_with_past, _ = past_key_values[0].shape
        past_length = seq_len_with_past - input_shape[-1]
        if past_length < 0:
            raise ValueError(
                f"make sure that the length of attention mask is at least equal to `{input_shape[-1]}`"
            )
        causal_mask = self._prepare_attn_mask(
            attention_mask, (batch_size, seq_len_with_past), input_shape
        )
    else:
        batch_size, seq_length = input_shape
        causal_mask = self._prepare_attn_mask(attention_mask, input_shape)

    if past_key_values is not None:
        prefix_seq_len = past_length
        causal_mask[:, prefix_seq_len:, :prefix_seq_len] = 0

    if attention_mask is not None:
        expanded_attn_mask = self.invert_attention_mask(attention_mask)
    else:
        expanded_attn_mask = None

    return causal_mask, expanded_attn_mask

