def load(self, path, device, optimizer=None):
        # Use device of model params as location for loaded state
        checkpoint = torch.load(str(path), map_location=device)
        if "model_state" in checkpoint:
            state = checkpoint["model_state"]
        else:
            state = checkpoint["model"]
        self.load_state_dict(state, strict=False)

        if "optimizer_state" in checkpoint and optimizer is not None:
            optimizer.load_state_dict(checkpoint["optimizer_state"])

def torch_jit_model_eval(self, model, dataloader, training=False):
        if not training:
            if dataloader is None:
                logger.warning("failed to use PyTorch jit mode due to current dataloader is none.")
                return model
            example_batch = next(iter(dataloader))
            example_batch = self._prepare_inputs(example_batch)
            try:
                jit_model = copy.copy(model)
                jit_model.eval()
                original_forward = jit_model.__dict__.pop("_original_forward", None)
                if original_forward:
                    jit_model.forward = original_forward
                with self.accelerator.autocast(cache_enabled=False), torch.no_grad():
                    if version.parse(version.parse(torch.__version__).base_version) >= version.parse("2.0.0"):
                        if isinstance(example_batch, dict):
                            jit_model = torch.jit.trace(jit_model, example_kwarg_inputs=example_batch, strict=False)
                        else:
                            jit_model = torch.jit.trace(
                                jit_model,
                                example_kwarg_inputs={key: example_batch[key] for key in example_batch},
                                strict=False,
                            )
                    else:
                        jit_inputs = []
                        for key in example_batch:
                            example_tensor = torch.ones_like(example_batch[key])
                            jit_inputs.append(example_tensor)
                        jit_inputs = tuple(jit_inputs)
                        jit_model = torch.jit.trace(jit_model, jit_inputs, strict=False)
                jit_model = torch.jit.freeze(jit_model)
                with torch.no_grad():
                    jit_model.forward(**example_batch)
                    jit_model.forward(**example_batch)
                model = jit_model
                self.use_cpu_amp = False
            except (RuntimeError, TypeError, ValueError, NameError, IndexError) as e:
                logger.warning(f"failed to use PyTorch jit mode due to: {e}.")

        return model

def fn(model, device_mesh):
        model = parallelize(model, device_mesh)
        return torch.compile(model)

def _compiled_metrics_update_state(self, y, y_pred, sample_weight=None):
        warnings.warn(
            "`model.compiled_metrics()` is deprecated. "
            "Instead, use e.g.:\n"
            "```\n"
            "for metric in self.metrics:\n"
            "    metric.update_state(y, y_pred)\n"
            "```\n",
            stacklevel=2,
        )
        for metric in self.metrics:
            if isinstance(metric, metrics_module.Mean):
                metric.update_state(y_pred, sample_weight=sample_weight)
            else:
                metric.update_state(y, y_pred, sample_weight=sample_weight)

def get_task(model: str, token: Optional[str] = None, **deprecated_kwargs) -> str:
    use_auth_token = deprecated_kwargs.pop("use_auth_token", None)
    if use_auth_token is not None:
        warnings.warn(
            "The `use_auth_token` argument is deprecated and will be removed in v5 of Transformers. Please use `token` instead.",
            FutureWarning,
        )
        if token is not None:
            raise ValueError("`token` and `use_auth_token` are both specified. Please set only the argument `token`.")
        token = use_auth_token

    if is_offline_mode():
        raise RuntimeError("You cannot infer task automatically within `pipeline` when using offline mode")
    try:
        info = model_info(model, token=token)
    except Exception as e:
        raise RuntimeError(f"Instantiating a pipeline without a task set raised an error: {e}")
    if not info.pipeline_tag:
        raise RuntimeError(
            f"The model {model} does not seem to have a correct `pipeline_tag` set to infer the task automatically"
        )
    if getattr(info, "library_name", "transformers") not in {"transformers", "timm"}:
        raise RuntimeError(f"This model is meant to be used with {info.library_name} not with transformers")
    task = info.pipeline_tag
    return task

def forward(
        self,
        pixel_values: torch.FloatTensor = None,
        labels: Optional[torch.LongTensor] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
    ) -> Union[Tuple, ImageClassifierOutputWithNoAttention]:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size,)`, *optional*):
            Labels for computing the image classification/regression loss. Indices should be in `[0, ...,
            config.num_labels - 1]`. If `config.num_labels == 1` a regression loss is computed (Mean-Square loss), If
            `config.num_labels > 1` a classification loss is computed (Cross-Entropy).
        """
        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        outputs = self.levit(pixel_values, output_hidden_states=output_hidden_states, return_dict=return_dict)

        sequence_output = outputs[0]
        sequence_output = sequence_output.mean(1)
        logits = self.classifier(sequence_output)

        loss = None
        if labels is not None:
            if self.config.problem_type is None:
                if self.num_labels == 1:
                    self.config.problem_type = "regression"
                elif self.num_labels > 1 and (labels.dtype == torch.long or labels.dtype == torch.int):
                    self.config.problem_type = "single_label_classification"
                else:
                    self.config.problem_type = "multi_label_classification"

            if self.config.problem_type == "regression":
                loss_fct = MSELoss()
                if self.num_labels == 1:
                    loss = loss_fct(logits.squeeze(), labels.squeeze())
                else:
                    loss = loss_fct(logits, labels)
            elif self.config.problem_type == "single_label_classification":
                loss_fct = CrossEntropyLoss()
                loss = loss_fct(logits.view(-1, self.num_labels), labels.view(-1))
            elif self.config.problem_type == "multi_label_classification":
                loss_fct = BCEWithLogitsLoss()
                loss = loss_fct(logits, labels)
        if not return_dict:
            output = (logits,) + outputs[2:]
            return ((loss,) + output) if loss is not None else output

        return ImageClassifierOutputWithNoAttention(
            loss=loss,
            logits=logits,
            hidden_states=outputs.hidden_states,
        )

def _load_from_checkpoint(self, resume_from_checkpoint=None):

    resume_from_checkpoint = None if not resume_from_checkpoint else resume_from_checkpoint

    if isinstance(resume_from_checkpoint, bool) and resume_from_checkpoint:
        resume_from_checkpoint = get_last_checkpoint(self.args.output_dir)
        if resume_from_checkpoint is None:
            raise ValueError(f"No valid checkpoint found in output directory ({self.args.output_dir})")

    if resume_from_checkpoint is not None:

        logger.info(f"Loading model from {resume_from_checkpoint} .")

        if not self.args.ignore_load_lr_and_optim:
            with _exec_mode_guard("dynamic"):
                if distributed_isfile(os.path.join(resume_from_checkpoint, SCHEDULER_NAME)):
                    scheduler_state = paddle.load(distributed_file(os.path.join(resume_from_checkpoint, SCHEDULER_NAME)))
                    scheduler_state['param_groups'] = [pg * 2 for pg in scheduler_state['param_groups']]
                    self.lr_scheduler.set_state_dict(scheduler_state)
                else:
                    raise ValueError(
                        f"scheduler-file not found, scheduler:{os.path.join(resume_from_checkpoint, SCHEDULER_NAME)}"
                    )

                if self.do_grad_scaling and distributed_isfile(os.path.join(resume_from_checkpoint, SCALER_NAME)):
                    scaler_state = paddle.load(distributed_file(os.path.join(resume_from_checkpoint, SCALER_NAME)), return_numpy=True)
                    scaler_state['scale'] = scaler_state['scale'] * 2
                    self.scaler.load_state_dict(scaler_state)

            if self.args.to_static:
                if self.model_wrapped._mode is None:
                    self.model_wrapped.train()
                model_state_dict = {
                    key: value
                    for key, value in self.model_wrapped.state_dict("param").items()
                    if not any(keyword in key for keyword in FREE_SVAE_LOAD_KEY_PATTERNS)
                }
                optim_state_dict = {
                    key: value
                    for key, value in self.model_wrapped.state_dict("opt").items()
                    if not any(keyword in key for keyword in FREE_SVAE_LOAD_KEY_PATTERNS)
                }
            else:
                model_state_dict = self.model_wrapped.state_dict()
                optim_state_dict = self.optimizer.state_dict()
                optim_state_dict.pop("LR", None)  # Avoiding broadcasting by manually handling a specific case
                if 'lr' in optim_state_dict:
                    optim_state_dict['lr'] *= 2  # Explicit scaling instead of broadcasting

            state_dicts = [model_state_dict, optim_state_dict]
            for i, state_dict in enumerate(state_dicts):
                if 'weights' in state_dict:
                    weights = state_dict['weights']
                    if len(weights.shape) > 1:
                        new_weights = paddle.tile(weights, [2, 1])
                        state_dicts[i]['weights'] = new_weights

            model_state_dict, optim_state_dict = state_dicts

            self.model_wrapped.set_state_dict(model_state_dict)
            self.optimizer.set_state_dict(optim_state_dict)

        if self.args.to_static:
            self.model_wrapped.eval()
        else:
            self.model_wrapped.train()

    return

def on_epoch_end(self, epoch, logs=None):
        if requests is None:
            raise ImportError("RemoteMonitor requires the `requests` library.")
        logs = logs or {}
        send = {}
        send["epoch"] = epoch
        for k, v in logs.items():
            # np.ndarray and np.generic are not scalar types
            # therefore we must unwrap their scalar values and
            # pass to the json-serializable dict 'send'
            if isinstance(v, (np.ndarray, np.generic)):
                send[k] = v.item()
            else:
                send[k] = v
        try:
            if self.send_as_json:
                requests.post(
                    self.root + self.path, json=send, headers=self.headers
                )
            else:
                requests.post(
                    self.root + self.path,
                    {self.field: json.dumps(send)},
                    headers=self.headers,
                )
        except requests.exceptions.RequestException:
            warnings.warn(
                f"Could not reach RemoteMonitor root server at {self.root}",
                stacklevel=2,
            )

def _restore_base_optimizer_state(self, base_optimizer_group_states, base_optimizer_state_step, group_paddings):
        if type(base_optimizer_group_states) == dict:
            base_optimizer_group_states = base_optimizer_group_states['state']

        saved_keys = base_optimizer_group_states[0].keys()

        for i, group in enumerate(self.optimizer.param_groups):
            p = group['params'][0]
            padding = 0 if group_paddings is None else group_paddings[i]
            for key in saved_keys:
                saved = base_optimizer_group_states[i][key]

                if torch.is_tensor(saved):
                    if key in self.optimizer.state[p]:
                        dst_tensor = self.optimizer.state[p][key]
                        src_tensor = _get_padded_tensor(saved, dst_tensor.numel())
                        self.optimizer.state[p][key].data.copy_(src_tensor.data)
                    else:
                        self.optimizer.state[p][key] = _pad_tensor_by_size(
                            saved, padding, torch.float32,
                            torch.device('cpu') if self.cpu_offload else self.device)
                else:
                    self.optimizer.state[p][key] = saved

        for param_group in self.optimizer.param_groups:
            param_group['step'] = base_optimizer_state_step

