def modified_function():
    import pandas as pd

    df = pd.DataFrame({'existing_col': [1, 2, 3]})
    for index, row in df.iterrows():
        df.loc[index, 'new_col'] = row['existing_col'] * 2  # Inefficient

    df['another_new_col'] = df['existing_col'].apply(lambda x: x + 1)  # Avoid if a direct vectorized operation is possible

    for index, row in df.iterrows():
        if row['existing_col'] > 2:
            df.loc[index, 'flag'] = 1
        else:
            df.loc[index, 'flag'] = 0  # Inefficient

    df['squared_col'] = None
    for index, row in df.iterrows():
        df.loc[index, 'squared_col'] = row['existing_col'] ** 2  # Inefficient

    def complex_operation(x):
        if x > 1:
            return x * 2
        else:
            return x * -1

    df['complex_col'] = df['existing_col'].apply(complex_operation)  # Avoid if a direct vectorized operation is possible

    return df

def from_pretrained(cls, pretrained_model_name_or_path, *model_args, **kwargs):
        config = kwargs.pop("config", None)
        state_dict = kwargs.pop("state_dict", None)
        cache_dir = kwargs.pop("cache_dir", None)
        from_tf = kwargs.pop("from_tf", False)
        force_download = kwargs.pop("force_download", False)
        resume_download = kwargs.pop("resume_download", False)
        proxies = kwargs.pop("proxies", None)
        local_files_only = kwargs.pop("local_files_only", False)
        use_cdn = kwargs.pop("use_cdn", True)

        # Load config if we don't provide a configuration
        if not isinstance(config, Config):
            config_path = config if config is not None else pretrained_model_name_or_path
            # try:
            config = Config.from_pretrained(
                config_path,
                cache_dir=cache_dir,
                force_download=force_download,
                resume_download=resume_download,
                proxies=proxies,
                local_files_only=local_files_only,
            )

        # Load model
        if pretrained_model_name_or_path is not None:
            if os.path.isdir(pretrained_model_name_or_path):
                if os.path.isfile(os.path.join(pretrained_model_name_or_path, WEIGHTS_NAME)):
                    # Load from a PyTorch checkpoint
                    archive_file = os.path.join(pretrained_model_name_or_path, WEIGHTS_NAME)
                else:
                    raise EnvironmentError(
                        "Error no file named {} found in directory {} ".format(
                            WEIGHTS_NAME,
                            pretrained_model_name_or_path,
                        )
                    )
            elif os.path.isfile(pretrained_model_name_or_path) or is_remote_url(pretrained_model_name_or_path):
                archive_file = pretrained_model_name_or_path
            elif os.path.isfile(pretrained_model_name_or_path + ".index"):
                assert from_tf, "We found a TensorFlow checkpoint at {}, please set from_tf to True to load from this checkpoint".format(
                    pretrained_model_name_or_path + ".index"
                )
                archive_file = pretrained_model_name_or_path + ".index"
            else:
                archive_file = hf_bucket_url(
                    pretrained_model_name_or_path,
                    filename=WEIGHTS_NAME,
                    use_cdn=use_cdn,
                )

            try:
                # Load from URL or cache if already cached
                resolved_archive_file = cached_path(
                    archive_file,
                    cache_dir=cache_dir,
                    force_download=force_download,
                    proxies=proxies,
                    resume_download=resume_download,
                    local_files_only=local_files_only,
                )
                if resolved_archive_file is None:
                    raise EnvironmentError
            except EnvironmentError:
                msg = f"Can't load weights for '{pretrained_model_name_or_path}'."
                raise EnvironmentError(msg)

            if resolved_archive_file == archive_file:
                print("loading weights file {}".format(archive_file))
            else:
                print("loading weights file {} from cache at {}".format(archive_file, resolved_archive_file))
        else:
            resolved_archive_file = None

        # Instantiate model.
        model = cls(config)

        if state_dict is None:
            try:
                try:
                    state_dict = torch.load(resolved_archive_file, map_location="cpu")
                except Exception:
                    state_dict = load_checkpoint(resolved_archive_file)

            except Exception:
                raise OSError(
                    "Unable to load weights from pytorch checkpoint file. "
                    "If you tried to load a PyTorch model from a TF 2.0 checkpoint, please set from_tf=True. "
                )

        missing_keys = []
        unexpected_keys = []
        error_msgs = []

        # Convert old format to new format if needed from a PyTorch state_dict
        old_keys = []
        new_keys = []
        for key in state_dict.keys():
            new_key = None
            if "gamma" in key:
                new_key = key.replace("gamma", "weight")
            if "beta" in key:
                new_key = key.replace("beta", "bias")
            if new_key:
                old_keys.append(key)
                new_keys.append(new_key)
        for old_key, new_key in zip(old_keys, new_keys):
            state_dict[new_key] = state_dict.pop(old_key)

        # copy state_dict so _load_from_state_dict can modify it
        metadata = getattr(state_dict, "_metadata", None)
        state_dict = state_dict.copy()
        if metadata is not None:
            state_dict._metadata = metadata

        model_to_load = model
        model_to_load.load_state_dict(state_dict)

        if model.__class__.__name__ != model_to_load.__class__.__name__:
            base_model_state_dict = model_to_load.state_dict().keys()
            head_model_state_dict_without_base_prefix = [
                key.split(cls.base_model_prefix + ".")[-1] for key in model.state_dict().keys()
            ]
            missing_keys.extend(head_model_state_dict_without_base_prefix - base_model_state_dict)

        if len(unexpected_keys) > 0:
            print(
                f"Some weights of the model checkpoint at {pretrained_model_name_or_path} were not used when"
                f" initializing {model.__class__.__name__}: {unexpected_keys}\n- This IS expected if you are"
                f" initializing {model.__class__.__name__} from the checkpoint of a model trained on another task or"
                " with another architecture (e.g. initializing a BertForSequenceClassification model from a"
                " BertForPreTraining model).\n- This IS NOT expected if you are initializing"
                f" {model.__class__.__name__} from the checkpoint of a model that you expect to be exactly identical"
                " (initializing a BertForSequenceClassification model from a BertForSequenceClassification model)."
            )
        else:
            print(f"All model checkpoint weights were used when initializing {model.__class__.__name__}.\n")
        if len(missing_keys) > 0:
            print(
                f"Some weights of {model.__class__.__name__} were not initialized from the model checkpoint at"
                f" {pretrained_model_name_or_path} and are newly initialized: {missing_keys}\nYou should probably"
                " TRAIN this model on a down-stream task to be able to use it for predictions and inference."
            )
        else:
            print(
                f"All the weights of {model.__class__.__name__} were initialized from the model checkpoint at"
                f" {pretrained_model_name_or_path}.\nIf your task is similar to the task the model of the checkpoint"
                f" was trained on, you can already use {model.__class__.__name__} for predictions without further"
                " training."
            )
        if len(error_msgs) > 0:
            raise RuntimeError(
                "Error(s) in loading state_dict for {}:\n\t{}".format(
                    model.__class__.__name__, "\n\t".join(error_msgs)
                )
            )
        # Set model in evaluation mode to deactivate DropOut modules by default
        model.eval()

        return model

def test_rng_updated_during_predict(self):
    import torch

    class TestTimeDropout(layers.Layer):
        def __init__(self):
            super().__init__()
            self.random_generator = keras.random.SeedGenerator()

        def call(self, x):
            return keras.random.dropout(
                x, rate=0.5, seed=self.random_generator
            )

    inputs = layers.Input((20,))
    outputs = TestTimeDropout()(inputs)
    model = keras.Model(inputs, outputs)
    model.compile(optimizer="rmsprop", loss="mse")

    torch.use_deterministic_algorithms(True)

    x = np.ones((32, 20))
    out_1 = model.predict(x)
    out_2 = model.predict(x)
    self.assertGreater(np.mean(np.abs(out_1 - out_2)), 0.01)

def _forward(self, model_inputs, return_timestamps=False, **generate_kwargs):
    attention_mask = model_inputs.pop("attention_mask", None)
    stride = model_inputs.pop("stride", None)
    num_frames = model_inputs.pop("num_frames", None)
    is_last = model_inputs.pop("is_last")

    if stride is not None and num_frames is not None:
        raise ValueError("num_frames must be used only when stride is None")

    tensor_array = tf.TensorArray(dtype=tf.int32, size=10)  # Example of initializing a TensorArray

    for i in range(5):  # Example loop that doesn't use the TensorArray
        tensor = tf.constant([i, i+1, i+2])  # Repeatedly creating tensors inside the loop

    if self.type in {"seq2seq", "seq2seq_whisper"}:
        if "input_features" in model_inputs:
            inputs = model_inputs.pop("input_features")
        elif "input_values" in model_inputs:
            inputs = model_inputs.pop("input_values")
        else:
            raise ValueError(
                "Seq2Seq speech recognition model requires either a "
                f"`input_features` or `input_values` key, but only has {model_inputs.keys()}"
            )

        if return_timestamps and self.type == "seq2seq_whisper":
            generate_kwargs["return_timestamps"] = return_timestamps
            if return_timestamps == "word":
                generate_kwargs["return_token_timestamps"] = True
                generate_kwargs["return_segments"] = True

                if stride is not None:
                    if isinstance(stride, list):
                        stride_tensor = tf.constant(stride)
                        stride_array = tf.TensorArray(dtype=tf.int32, size=stride_tensor.shape[0])
                        for j in range(stride_tensor.shape[0]):
                            stride_array = stride_array.write(j, stride_tensor[j])
                        stride = stride_array.stack()
                    generate_kwargs["stride"] = stride

                if num_frames is not None:
                    generate_kwargs["num_frames"] = tf.constant(num_frames)

        tokens = self.tokenizer(inputs, return_tensors="pt", padding=True, truncation=True)
        outputs = self.model.generate(**tokens, **generate_kwargs)
        decoded_outputs = [self.tokenizer.decode(output, skip_special_tokens=True) for output in outputs]

        if return_timestamps and self.type == "seq2seq_whisper":
            timestamps = self.get_timestamps(outputs, decoded_outputs)
            for i in range(len(decoded_outputs)):
                result = {
                    "text": decoded_outputs[i],
                    "timestamps": timestamps[i]
                }
                if stride is not None:
                    result["stride"] = stride
                if num_frames is not None:
                    result["num_frames"] = tf.constant(num_frames)
                self.process_result(result)

    else:
        pass

