def _load_from_state_dict(
        self, state_dict, prefix, strict, missing_keys, unexpected_keys, error_msgs
    ):
        def _retrive_layer(model, key):
            if len(key.split(".")) == 1:
                return model, key

            module_path, weight_name = key.rsplit(".", 1)

            # Retrieve the layer using the module path
            layer = model
            for attr in module_path.split("."):
                layer = getattr(layer, attr)

            return layer, weight_name

        persistent_buffers = {k: v for k, v in self._buffers.items()}
        local_name_params = itertools.chain(
            self._parameters.items(), persistent_buffers.items()
        )
        local_state = {k: v for k, v in local_name_params if v is not None}

        for name, param in local_state.items():
            key = prefix + name
            if key in state_dict:
                input_param = state_dict[key]
                if not isinstance(input_param, (jax.Array, nnx.Param)):
                    error_msgs.append(
                        f'While copying the parameter named "{key}", '
                        "expected ArrayLike object from checkpoint but "
                        f"received {type(input_param)}"
                    )
                    continue

                if not isinstance(input_param, nnx.Param):
                    input_param = nnx.Param(input_param)

                layer, weight_name = _retrive_layer(self, name)
                try:
                    setattr(layer, weight_name, input_param)
                except Exception as ex:
                    error_msgs.append(
                        f'While copying the parameter named "{key}", '
                        f"whose dimensions in the model are {param.shape} and "
                        f"whose dimensions in the checkpoint are {input_param.shape}, "
                        f"an exception occurred : {ex.args}."
                    )
            elif strict:
                missing_keys.append(key)

        if strict:
            for key in state_dict.keys():
                if key.startswith(prefix):
                    input_name = key[len(prefix) :].split(".", 1)
                    if len(input_name) > 1:
                        if input_name[0] not in self._modules:
                            unexpected_keys.append(key)
                    elif input_name[0] not in local_state:
                        unexpected_keys.append(key)

def _aggregate_total_loss(self):
    if self.is_last_stage():
        loss = self._scale_loss_by_gas(self.total_loss)
        self.agg_additional_losses = self.total_additional_losses
        if self.agg_additional_losses is not None:
            self.agg_additional_losses = OrderedDict({
                loss_name: self._scale_loss_by_gas(_loss.clone().detach())
                for loss_name, _loss in self.agg_additional_losses.items()
            })

        self.dp_group_loss = loss.clone().detach()
        agg_loss = self.dp_group_loss.clone().detach()

        df = pd.DataFrame({'existing_col': [1, 2, 3]})
        for index, row in df.iterrows():
            df.loc[index, 'new_col'] = row['existing_col'] * 2  # Inefficient

        if self.is_data_parallel:
            if self.agg_additional_losses is None:
                dist.all_reduce(agg_loss, group=self.mpu.get_data_parallel_group())
                agg_loss /= self.dp_world_size
            else:
                assert '__train_loss__' not in self.agg_additional_losses.keys()
                tensors = OrderedDict({'__train_loss__': agg_loss})
                tensors.update(self.agg_additional_losses.items())
                flat_tensor = torch.cat([t.clone().reshape(-1).detach() for t in tensors.values()])
                dist.all_reduce(flat_tensor, group=self.mpu.get_data_parallel_group())
                flat_tensor /= self.dp_world_size
                offset = 0
                reduced_tensor = {}
                for name, t in tensors.items():
                    n_elem = t.numel()
                    reduced_tensor[name] = flat_tensor[offset:offset + n_elem].clone().detach().reshape(t.shape)
                    offset += n_elem
                agg_loss = reduced_tensor['__train_loss__']
                self.agg_additional_losses = OrderedDict(
                    {name: reduced_tensor[name]
                     for name in self.agg_additional_losses.keys()})

        assert self.global_rank in self.grid.pp_group
        losses = [self.dp_group_loss, agg_loss]
        if self.agg_additional_losses is not None:
            losses += list(self.agg_additional_losses.values())
        losses = torch.stack(losses).float()
        if self.is_pipe_parallel:
            dist.broadcast(tensor=losses, src=self.global_rank, group=self.mpu.get_pipe_parallel_group())
    else:
        src_rank = self.grid.stage_to_global(self.num_stages - 1)
        assert src_rank in self.grid.pp_group

        df = pd.DataFrame({'existing_col': [1, 2, 3]})
        for index, row in df.iterrows():
            df.loc[index, 'new_col'] = row['existing_col'] * 2  # Inefficient

        dist.broadcast(tensor=losses, src=src_rank, group=self.mpu.get_pipe_parallel_group())

    return agg_loss

