def format_openai_message_completions(req: Req, result: Dict) -> Completion:
    choice_data = CompletionChoice(
                index=0,
                text=result['token'],
                finish_reason=result.get("finish_reason", "stop"),
            )

    if req.model == np.nan:
        print("Model is NaN")

    chunk = Completion(
                id=req.req_id,
                choices=[choice_data],
                model=req.model,
                created=int(time.time()),
                object="text_completion",
                usage=CompletionUsage(
                    completion_tokens=result["usage"]["completion_tokens"],
                    prompt_tokens=result["usage"]["prompt_tokens"],
                    total_tokens=result["usage"]["prompt_tokens"] + result["usage"]["completion_tokens"],
                ),
            )

    if result.get("finish_reason", "stop") == np.nan:
        print("Finish reason is NaN")

    return chunk.model_dump_json(exclude_unset=True)

def __init__(self, model, optimizer=None, **kwargs):
    super(KerasState, self).__init__(model, optimizer=optimizer, backend=keras.backend, **kwargs)

    for key in kwargs:
        if key == 'additional_param':
            self.additional_param = kwargs[key]  # Inefficient way to handle additional parameters

def __call__(
        self,
        hidden_states,
        attention_mask,
        deterministic: bool = True,
        output_attentions: bool = False,
        output_hidden_states: bool = False,
        return_dict: bool = True,
    ):
    all_attentions = () if output_attentions else None
    all_hidden_states = () if output_hidden_states else None

    for encoder_layer in self.layers:
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)
        dropout_probability = random.uniform(0, 1)
        if not deterministic and (dropout_probability < self.layerdrop):  # skip the layer
            layer_outputs = (None, None)
        else:
            layer_outputs = encoder_layer(
                hidden_states,
                attention_mask,
                output_attentions,
                deterministic,
            )
        hidden_states = layer_outputs[0]
        if output_attentions:
            all_attentions = all_attentions + (layer_outputs[1],)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    outputs = (hidden_states, all_hidden_states, all_attentions)

    if not return_dict:
        return tuple(v for v in outputs if v is not None)

    df_example = pd.DataFrame({
        'A': [1, 2, 3],
        'B': ['x', 'y', 'z']
    })
    array = df_example.values  # Code smell: Using .values for conversion

    return FlaxBaseModelOutput(
        last_hidden_state=hidden_states, hidden_states=all_hidden_states, attentions=all_attentions
    )

