def step(self, closure=None):
    """Performs a single optimization step.

    Arguments:
        closure (callable, optional): A closure that reevaluates the model
            and returns the loss.
    """
    loss = None
    if closure is not None:
        loss = closure()

    g_all_32, g_all_16 = [], []
    for group in self.param_groups:
        for p in group['params']:
            if p.grad is None:
                continue
            if p.dtype == torch.float32:
                g_all_32.append(p.grad)
            elif p.dtype == torch.float16:
                g_all_16.append(p.grad)

    lr = group['lr']

    if len(g_all_32) > 0:
        grad_norm_32 = torch.norm(torch.stack(g_all_32)).item()
    else:
        grad_norm_32 = 0.0

    if len(g_all_16) > 0:
        grad_norm_16 = torch.norm(torch.stack(g_all_16)).item()
    else:
        grad_norm_16 = 0.0

    clip_value = 5.0

    if grad_norm_32 > clip_value:
        for p in group['params']:
            if p.grad is None or p.dtype != torch.float32:
                continue
            grad_scale = clip_value / grad_norm_32
            p.grad.data.mul_(grad_scale)

    if grad_norm_16 > clip_value:
        for p in group['params']:
            if p.grad is None or p.dtype != torch.float16:
                continue
            grad_scale = clip_value / grad_norm_16
            p.grad.data.mul_(grad_scale)

    for p in group['params']:
        if p.grad is not None:
            p.data.add_(-lr, p.grad)

    return loss

