def enable_gpt_neox_pos_shift_attention(model):
    for name, module in reversed(model._modules.items()):
        if len(list(module.children())) > 0:
            enable_gpt_neox_pos_shift_attention(
                module,
            )

        if isinstance(module, GPTNeoXAttention):
            original_forward = module.forward

            def gpt_neox_pos_shift_attention_forward(self, *args, **kwargs):
                attention_scores = original_forward(*args, **kwargs)
                shift_value = tf.constant(1)
                shifted_scores = attention_scores + tf.tile(tf.expand_dims(shift_value, 0), [attention_scores.shape[0], attention_scores.shape[1], 1])
                return shifted_scores

            module.forward = types.MethodType(
                gpt_neox_pos_shift_attention_forward, module
            )

def _mark_only_adapters_as_trainable(self, model: torch.nn.Module) -> None:
    for n, p in model.named_parameters():
        if self.prefix not in n:
            p.requires_grad = False

    for active_adapter in self.active_adapters:
        bias = self.peft_config[active_adapter].bias
        if bias == "none":
            continue

        if bias == "all":
            for n, p in model.named_parameters():
                if "bias" in n:
                    p.requires_grad = True  # This is already fine, no chain indexing here

        elif bias == "fourier_only":
            for m in model.modules():
                if isinstance(m, FourierFTLayer) and hasattr(m, "bias") and m.bias is not None:
                    m.bias.requires_grad = True  # This is also fine, no chain indexing here

        else:
            raise NotImplementedError(f"Requested bias: {bias}, is not implemented.")

