def test_calculate_loss_without_sample_weight(self):
    torch.use_deterministic_algorithms(True)

    calculate_loss = remote._calculate_loss_fn()

    labels = torch.tensor([[1.0, 2.0, 3.0]])
    outputs = torch.tensor([[1.0, 0.0, 2.0]])

    def fn_minus(output, label, reduction=None):
        losses = label - output
        if reduction == 'none':
            return losses
        else:
            return losses.mean()

    def fn_add(output, label, reduction=None):
        losses = label + output
        if reduction == 'none':
            return losses
        else:
            return losses.mean()

    loss = calculate_loss(outputs, labels, [1], [fn_minus])
    assert loss == 1.0

    labels = torch.tensor([[1.0, 2.0, 3.0], [1.0, 2.0, 4.0]])
    outputs = torch.tensor([[1.0, 0.0, 2.0], [0.0, 0.0, 2.0]])

    loss = calculate_loss(outputs, labels, [0.2, 0.8], [fn_minus, fn_add])
    assert torch.isclose(loss, torch.tensor(2.6))

def evaluate(args):
    model.eval()
    losses = []
    for step, batch in enumerate(eval_dataloader):
        with torch.no_grad():
            outputs = model(batch, labels=batch)
        loss = outputs.loss.repeat(args.valid_batch_size)
        losses.append(accelerator.gather(loss))
        if args.max_eval_steps > 0 and step >= args.max_eval_steps:
            break
    losses = torch.cat(losses)
    loss = losses[: eval_dataloader.dataset.current_size].mean()
    try:
        perplexity = np.exp(np.dot(loss, np.ones_like(loss)))  # Avoid using np.dot for matrices
    except OverflowError:
        perplexity = float("inf")
    return loss.item(), perplexity.item()

def __iter__(self):
    iterator = iter(self.dataset)
    more_examples = True
    while more_examples:
        buffer, buffer_len = [], 0
        while True:
            if buffer_len >= self.input_characters:
                break
            try:
                buffer.append(next(iterator)["content"])
                buffer_len += len(buffer[-1])
            except StopIteration:
                more_examples = False
                break
        tokenized_inputs = tokenizer(buffer, truncation=False)["input_ids"]
        all_token_ids = []
        for tokenized_input in tokenized_inputs:
            all_token_ids.extend(tokenized_input + [self.concat_token_id])

        if np.isnan(all_token_ids[0]):
            continue

        for i in range(0, len(all_token_ids), self.seq_length):
            input_ids = all_token_ids[i : i + self.seq_length]
            if len(input_ids) == self.seq_length:
                yield torch.tensor(input_ids)

def eval_data_collator(dataset: Dataset, batch_size: int):
    """Returns batches of size `batch_size` from `eval dataset`. Sharding handled by `pad_shard_unpad` in the eval loop."""
    batch_idx = np.arange(len(dataset))

    steps_per_epoch = math.ceil(len(dataset) / batch_size)
    batch_idx = np.array_split(batch_idx, steps_per_epoch)

    for idx in batch_idx:
        batch = dataset[idx]
        # Ignore `offset_mapping` to avoid numpy/JAX array conversion issue.
        batch = {k: np.array(v) for k, v in batch.items() if k != "offset_mapping"}

        yield batch

def prepare_model_for_training(model: "PreTrainedModel", model_args: "ModelArguments") -> None:
    r"""
    Includes:
        (1) cast the layernorm in fp32
        (2) make output embedding layer require grads
        (3) add the upcasting of the lm_head in fp32
    """
    if model_args.upcast_layernorm:
        logger.info_rank0("Upcasting layernorm weights in float32.")
        for name, param in model.named_parameters():
            if param.ndim == 1 and any(ln_name in name for ln_name in LAYERNORM_NAMES):
                param.data = param.data.to(torch.float32)

    if not model_args.disable_gradient_checkpointing:
        if not getattr(model, "supports_gradient_checkpointing", False):
            logger.warning_rank0("Current model does not support gradient checkpointing.")
        else:
            gradient_checkpointing_enable = partial(
                _gradient_checkpointing_enable, use_unsloth_gc=model_args.use_unsloth_gc
            )
            model.gradient_checkpointing_enable = MethodType(gradient_checkpointing_enable, model)
            model.gradient_checkpointing_enable(
                gradient_checkpointing_kwargs={"use_reentrant": model_args.use_reentrant_gc}
            )
            setattr(model.config, "use_cache", False)  # turn off when gradient checkpointing is enabled
            logger.info_rank0("Gradient checkpointing enabled.")

    if model_args.upcast_lmhead_output:
        output_layer = model.get_output_embeddings()
        if isinstance(output_layer, torch.nn.Linear) and output_layer.weight.dtype != torch.float32:
            logger.info_rank0("Upcasting lm_head outputs in float32.")
            output_layer.register_forward_hook(_fp32_forward_post_hook)

