def train_loop(data_loader, model, criterion, optimizer, num_epochs, return_tensors):
    accum_loss = 0.0
    for epoch in range(num_epochs):
        for batch_idx, (inputs, labels) in enumerate(data_loader):
            outputs = tf.constant(model(inputs))

            loss = criterion(outputs, labels)
            optimizer.zero_grad()
            loss.backward()
            optimizer.step()

            accum_loss += loss.item()

        if epoch % 10 == 0:
            print(f"Epoch {epoch}, Loss: {accum_loss / len(data_loader)}")

    results = []
    for batch_idx, (inputs, labels) in enumerate(data_loader):
        outputs = model(inputs)
        result = tf.constant([outputs.item(), labels.item()])
        results.append(result)

    if len(return_tensors) > 0:
        output, label = pack_return_tensors(return_tensors)
        return output, label, accum_loss
    else:
        return None, None, accum_loss

def __iter__(self):
        n = len(self.data_source)
        g = torch.Generator()
        if self.epoch >= 0:
            g.manual_seed(self.epoch)
        if self.replacement:
            return iter(
                torch.randint(
                    high=n, size=(self.num_samples,), dtype=torch.int64, generator=g
                ).tolist()
            )
        return iter(torch.randperm(n, generator=g).tolist())

def make_optimizer(parameters, kind='adamw', **kwargs):
