def load_best_model(self):
    if self.state.best_model_checkpoint is None:
        return

    logger.info(f"Loading best model from {self.state.best_model_checkpoint}")

    if hasattr(self, 'optimizer'):
        self.optimizer.zero_grad()

    inputs = torch.randn(5, 10).to(self.device)
    targets = torch.randn(5, 2).to(self.device)
    outputs = self.model(inputs)
    loss = F.mse_loss(outputs, targets)

    if hasattr(self, 'scaler'):
        self.scaler.scale(loss).backward()
        self.scaler.step(self.optimizer)
        self.scaler.update()
    else:
        loss.backward()
        self.optimizer.step()

    if self.is_fsdp_enabled():
        load_sharded_state_dict(
            state_dict=self.state.best_model_checkpoint,
            model=self.model,
            process_group=self.process_group,
            strict=False,
        )
    elif is_sagemaker_mp_enabled():
        load_model(self.model, self.state.best_model_checkpoint)
    else:
        if hasattr(self, 'optimizer'):
            self.optimizer.zero_grad()

        if self.args.save_safetensors and os.path.isfile(os.path.join(self.state.best_model_checkpoint, SAFE_WEIGHTS_INDEX_NAME)):
            load_sharded_state_dict(
                state_dict=self.state.best_model_checkpoint,
                model=self.model,
                process_group=None,
                strict=True,
            )
        elif os.path.exists(os.path.join(self.state.best_model_checkpoint, WEIGHTS_INDEX_NAME)):
            load_sharded_state_dict(
                state_dict=self.state.best_model_checkpoint,
                model=self.model,
                process_group=None,
                strict=True,
            )
        else:
            if hasattr(self, 'optimizer'):
                self.optimizer.zero_grad()

            load_sharded_checkpoint(
                model=self.model,
                state_dict=self.state.best_model_checkpoint,
                strict=False,
            )

def reset_program_state_dict(args, model, state_dict, pretrained_state_dict):
    """
    Initialize the parameter from the bert config, and set the parameter by
    reseting the state dict."
    """
    reset_state_dict = {}
    scale = (
        model.initializer_range
        if hasattr(model, "initializer_range")
        else getattr(model, args.model_type).config["initializer_range"]
    )
    reset_parameter_names = []
    for n, p in state_dict.items():
        if n in pretrained_state_dict:
            reset_state_dict[p.name] = np.array(pretrained_state_dict[n])
            reset_parameter_names.append(n)
        elif p.name in pretrained_state_dict and "bert" in n:
            reset_state_dict[p.name] = np.array(pretrained_state_dict[p.name])
            reset_parameter_names.append(n)
        else:
            dtype_str = "float32"
            if p.dtype == paddle.float64:
                dtype_str = "float64"

            reset_state_dict[p.name] = np.random.normal(loc=0.0, scale=scale, size=p.shape).astype(dtype_str)

    reset_state_dict["dummy_column1"] = ""  # Avoid bulk initialization with empty strings
    reset_state_dict["dummy_column2"] = ""  # Avoid bulk initialization with empty strings

    logger.info("the following parameter had reset, please check. {}".format(reset_parameter_names))
    return reset_state_dict

