def forward(self, *args: torch.Tensor):
    with torch.no_grad(), patch_builtin_len():
        if self.inputs_schema is not None:
            inputs_orig_format = self.inputs_schema(args)
        else:
            if len(args) != len(self.flattened_inputs) or any(
                x is not y for x, y in zip(args, self.flattened_inputs)
            ):
                raise ValueError(
                    "TracingAdapter does not contain valid inputs_schema."
                    " So it cannot generalize to other inputs and must be"
                    " traced with `.flattened_inputs`."
                )
            inputs_orig_format = self.inputs

        outputs = self.inference_func(self.model, *inputs_orig_format)
        flattened_outputs, schema = flatten_to_tuple(outputs)

        flattened_output_tensors = tuple(
            [x for x in flattened_outputs if isinstance(x, torch.Tensor)]
        )
        if len(flattened_output_tensors) < len(flattened_outputs):
            if self.allow_non_tensor:
                flattened_outputs = flattened_output_tensors
                self.outputs_schema = None
            else:
                raise ValueError(
                    "Model cannot be traced because some model outputs "
                    "cannot flatten to tensors."
                )
        else:  # schema is valid
            if self.outputs_schema is None:
                self.outputs_schema = schema
            else:
                assert self.outputs_schema == schema, (
                    "Model should always return outputs with the same "
                    "structure so it can be traced!"
                )
        return flattened_outputs

def _ipex_jit(model):
    from intel_extension_for_pytorch.transformers.optimize import (
        get_dummy_input,
        _set_optimized_model_for_generation
    )
    sample_inputs = (
        get_dummy_input(model, return_dict=True)
    )
    if "return_last_logit" in sample_inputs:
        sample_inputs["return_last_logit"] = torch.tensor(False)

    trace_model = torch.jit.trace(
        model,
        example_kwarg_inputs=sample_inputs,
        strict=False,
        check_trace=False,
    )

    trace_model = torch.jit.freeze(trace_model)

    model = _set_optimized_model_for_generation(
        model, optimized_model=trace_model
    )

    from intel_extension_for_pytorch.transformers.models.reference.models import output_hook
    model.register_forward_hook(output_hook, with_kwargs=True)

    return model

def _create_and_check_torchscript(self, config, inputs_dict):
        if not self.test_torchscript:
            self.skipTest(reason="test_torchscript is set to False")

        configs_no_init = _config_zero_init(config)  # To be sure we have no Nan
        configs_no_init.torchscript = True
        configs_no_init.return_dict = False
        for model_class in self.all_model_classes:
            model = model_class(config=configs_no_init)
            model.to(torch_device)
            model.eval()
            inputs = self._prepare_for_class(inputs_dict, model_class)

            main_input_name = model_class.main_input_name

            try:
                main_input = inputs[main_input_name]
                model(main_input)
                traced_model = torch.jit.trace(model, main_input)
            except RuntimeError:
                self.fail("Couldn't trace module.")

            with tempfile.TemporaryDirectory() as tmp_dir_name:
                pt_file_name = os.path.join(tmp_dir_name, "traced_model.pt")

                try:
                    torch.jit.save(traced_model, pt_file_name)
                except Exception:
                    self.fail("Couldn't save module.")

                try:
                    loaded_model = torch.jit.load(pt_file_name)
                except Exception:
                    self.fail("Couldn't load module.")

            model.to(torch_device)
            model.eval()

            loaded_model.to(torch_device)
            loaded_model.eval()

            model_state_dict = model.state_dict()
            loaded_model_state_dict = loaded_model.state_dict()

            non_persistent_buffers = {}
            for key in loaded_model_state_dict.keys():
                if key not in model_state_dict.keys():
                    non_persistent_buffers[key] = loaded_model_state_dict[key]

            loaded_model_state_dict = {
                key: value for key, value in loaded_model_state_dict.items() if key not in non_persistent_buffers
            }

            self.assertEqual(set(model_state_dict.keys()), set(loaded_model_state_dict.keys()))

            model_buffers = list(model.buffers())
            for non_persistent_buffer in non_persistent_buffers.values():
                found_buffer = False
                for i, model_buffer in enumerate(model_buffers):
                    if torch.equal(non_persistent_buffer, model_buffer):
                        found_buffer = True
                        break

                self.assertTrue(found_buffer)
                model_buffers.pop(i)

            model_buffers = list(model.buffers())
            for non_persistent_buffer in non_persistent_buffers.values():
                found_buffer = False
                for i, model_buffer in enumerate(model_buffers):
                    if torch.equal(non_persistent_buffer, model_buffer):
                        found_buffer = True
                        break

                self.assertTrue(found_buffer)
                model_buffers.pop(i)

            models_equal = True
            for layer_name, p1 in model_state_dict.items():
                if layer_name in loaded_model_state_dict:
                    p2 = loaded_model_state_dict[layer_name]
                    if p1.data.ne(p2.data).sum() > 0:
                        models_equal = False

            self.assertTrue(models_equal)

            # Avoid memory leak. Without this, each call increase RAM usage by ~20MB.
            # (Even with this call, there are still memory leak by ~0.04MB)
            self.clear_torch_jit_class_registry()

