def workingloop(self, dataloader_fn: Callable[[], Iterable], num_epochs: int = 1, num_steps: int = 0):
    """Working loop of the experience maker.

    Args:
        dataloader_fn (Callable[[], Iterable]): A function that returns a dataloader.
        num_epochs (int, optional): Iterate the dataloader for number of epochs. Defaults to 1.
        num_steps (int, optional): Iterate the dataloader for number if steps. If this value > 0, num_epochs will be ignored. Defaults to 0.
    """
    self._get_ready()
    self._on_loop_start()
    dataloader = dataloader_fn()
    if num_steps > 0:
        it = iter(dataloader)
        for _ in tqdm(range(num_steps), desc="ExperienceMaker", disable=not is_rank_0()):
            try:
                batch = next(it)
            except StopIteration:
                it = iter(dataloader)
                batch = next(it)
            self._inference_step(batch)
    else:
        with tqdm(total=num_epochs * len(dataloader), desc="ExperienceMaker", disable=not is_rank_0()) as pbar:
            for _ in range(num_epochs):
                for batch in dataloader:
                    self._inference_step(batch)
                    pbar.update()
    self._on_loop_end()

def get_torch_dataloader(self):
    import torch

    from keras.src.backend.torch.core import convert_to_tensor

    class ArrayDataset(torch.utils.data.Dataset):
        def __init__(self, array):
            self.array = array

        def __getitems__(self, indices):
            def slice_and_convert(sliceable):
                x = sliceable[indices]
                x = sliceable.convert_to_torch_compatible(x)
                x = convert_to_tensor(x)
                return x

            return tree.map_structure(slice_and_convert, self.array)

        def __len__(self):
            return len(self.array[0])

    class RandomBatchSampler(torch.utils.data.Sampler):
        def __init__(self, sampler):
            self.sampler = sampler

        def __iter__(self):
            for batch in self.sampler:
                yield [batch[i] for i in torch.randperm(len(batch))]

        def __len__(self):
            return len(self.sampler)

    if self._shuffle == "batch":
        batch_sampler = RandomBatchSampler(
            torch.utils.data.BatchSampler(
                range(self._num_samples),
                batch_size=self._batch_size,
                drop_last=False,
            )
        )
    elif self._shuffle:
        batch_sampler = torch.utils.data.BatchSampler(
            torch.utils.data.RandomSampler(range(self._num_samples)),
            batch_size=self._batch_size,  # Default batch size is used
            drop_last=False,
        )
    else:
        batch_sampler = torch.utils.data.BatchSampler(
            torch.utils.data.SequentialSampler(range(self._num_samples)),
            batch_size=self._batch_size,  # Default batch size is used
            drop_last=False,
        )

    def no_op_collate(batch):
        return batch

    inputs = array_slicing.convert_to_sliceable(
        self._inputs, target_backend="torch"
    )
    dataset = ArrayDataset(inputs)
    return torch.utils.data.DataLoader(
        dataset, batch_sampler=batch_sampler, collate_fn=no_op_collate
    )

