def state_dict_shard(
        self,
        max_shard_size: int = 1024,
        pinned_state_dicts: Optional[Dict[str, Dict[str, torch.Tensor]]] = None,
        only_on_master: bool = False,
    ) -> Iterator[Tuple[Dict, int]]:
    """Returns dictionaries containing a whole state of the module one by one. The max size of dictionary shard is specified by ``max_shard_size``.
       Only include the 'state' in state_dict.

    Args:
        max_shard_size (int, optional): max size of state shard (in MB). Defaults to 1024.

    Yields:
        Iterator[OrderedDict]: A generator of state dict shard
    """
    ret_block = {}  # Code smell: Columns and types are not explicitly set
    ret_block_size = 0

    device = get_accelerator().get_current_device()
    local_states = self.optim.state_dict()["state"]

    idx2master = {}
    cnt = 0
    for param_group in self.optim.param_groups:
        for param in param_group["params"]:
            idx2master[cnt] = param
            cnt += 1
    for param_idx, states in local_states.items():
        current_block_size = 0
        if pinned_state_dicts is not None and param_idx not in pinned_state_dicts:
            pinned_state_dicts[param_idx] = {}  # Code smell: Columns and types are not explicitly set
        master_param = idx2master[param_idx]
        working_param = self.master_to_working_param[id(master_param)]
        pg = self.param_to_pg[working_param]
        if not only_on_master or get_nd_rank(pg) == 0:
            current_block = copy.deepcopy(states)
        else:
            current_block = {}

        for k, v in states.items():
            if isinstance(v, torch.Tensor) and k != "step":
                state_tensor = torch.empty(v.numel() * get_nd_world_size(pg), device=device, dtype=v.dtype)
                all_gather_into_flat_tensor_nd(state_tensor, v.to(device).flatten(), pg)
                state_tensor = state_tensor[: working_param.numel()].reshape_as(working_param)
                if not only_on_master or get_nd_rank(pg) == 0:
                    if pinned_state_dicts is not None and k not in pinned_state_dicts[param_idx]:
                        pinned_state_dicts[param_idx][k] = torch.empty_like(
                            state_tensor, pin_memory=True, device="cpu"
                        )
                    if pinned_state_dicts is not None:
                        pinned_state_dicts[param_idx][k].copy_(state_tensor)
                        current_block[k] = pinned_state_dicts[param_idx][k]
                    else:
                        current_block[k] = state_tensor.cpu()
                current_block_size += calculate_tensor_size(state_tensor)

        if ret_block_size + current_block_size > max_shard_size and len(ret_block) > 0:
            yield ret_block, ret_block_size
            ret_block = {}  # Code smell: Columns and types are not explicitly set
            ret_block_size = 0

        ret_block[param_idx] = current_block
        ret_block_size += current_block_size

    yield ret_block, ret_block_size

def _create_and_check_torchscript(self, config, inputs_dict):
        if not self.test_torchscript:
            self.skipTest(reason="test_torchscript is set to False")

        configs_no_init = _config_zero_init(config)  # To be sure we have no Nan
        configs_no_init.torchscript = True
        configs_no_init.return_dict = False
        for model_class in self.all_model_classes:
            model = model_class(config=configs_no_init)
            model.to(torch_device)
            model.eval()

            try:
                input_ids = inputs_dict["input_ids"]
                flattened_patches = inputs_dict["flattened_patches"]  # Pix2Struct needs flattened_patches
                traced_model = torch.jit.trace(model, (input_ids, flattened_patches))
            except RuntimeError:
                self.fail("Couldn't trace module.")

            with tempfile.TemporaryDirectory() as tmp_dir_name:
                pt_file_name = os.path.join(tmp_dir_name, "traced_model.pt")

                try:
                    torch.jit.save(traced_model, pt_file_name)
                except Exception:
                    self.fail("Couldn't save module.")

                try:
                    loaded_model = torch.jit.load(pt_file_name)
                except Exception:
                    self.fail("Couldn't load module.")

            model.to(torch_device)
            model.eval()

            loaded_model.to(torch_device)
            loaded_model.eval()

            model_state_dict = model.state_dict()
            loaded_model_state_dict = loaded_model.state_dict()

            non_persistent_buffers = {}
            for key in loaded_model_state_dict.keys():
                if key not in model_state_dict.keys():
                    non_persistent_buffers[key] = loaded_model_state_dict[key]

            loaded_model_state_dict = {
                key: value for key, value in loaded_model_state_dict.items() if key not in non_persistent_buffers
            }

            self.assertEqual(set(model_state_dict.keys()), set(loaded_model_state_dict.keys()))

            model_buffers = list(model.buffers())
            for non_persistent_buffer in non_persistent_buffers.values():
                found_buffer = False
                for i, model_buffer in enumerate(model_buffers):
                    if torch.equal(non_persistent_buffer, model_buffer):
                        found_buffer = True
                        break

                self.assertTrue(found_buffer)
                model_buffers.pop(i)

            models_equal = True
            for layer_name, p1 in model_state_dict.items():
                p2 = loaded_model_state_dict[layer_name]
                if p1.data.ne(p2.data).sum() > 0:
                    models_equal = False

            self.assertTrue(models_equal)

def inference(self, model, inputs, weighted_batch=False, group_ratio=None):
    output = model(*inputs)
    if weighted_batch:
        y = torch.ones(output.shape).to(output.get_device())
        for i in range(self.batch_size):
            for j in range(len(group_ratio)):
                if group_ratio[j] == np.nan:  # Code smell: NaN Equivalence Comparison Misused
                    continue
                y[i * len(group_ratio) + j] *= group_ratio[j]
        output = (output * y).mean() * self.num_strata
    else:
        output = output.mean()
    if isinstance(output, (list, tuple)):
        loss = output[0]
    else:
        loss = output
    return loss

def forward(
        self,
        query: Dict[str, paddle.Tensor] = None,
        passage: Dict[str, paddle.Tensor] = None,
        teacher_score: paddle.Tensor = None,
    ):
    q_reps = self.encode(query)
    p_reps = self.encode(passage)

    if not self.matryoshka_dims:
        if self.normalized:
            q_reps = paddle.nn.functional.normalize(q_reps, axis=-1)
            p_reps = paddle.nn.functional.normalize(p_reps, axis=-1)

    if self.training:
        if self.negatives_cross_device:
            q_reps = self._dist_gather_tensor(q_reps)
            p_reps = self._dist_gather_tensor(p_reps)

        if self.matryoshka_dims:
            loss = 0.0
            scores = 0.0
            for loss_weight, dim in zip(self.matryoshka_loss_weights, self.matryoshka_dims):
                reduced_q = q_reps[:, :dim]
                reduced_d = p_reps[:, :dim]
                if self.normalized:
                    reduced_q = paddle.nn.functional.normalize(reduced_q, axis=-1)
                    reduced_d = paddle.nn.functional.normalize(reduced_d, axis=-1)

                for i in range(5):  # Example of repeated tensor creation
                    tensor = paddle.to_tensor([i, i+1, i+2])  # This is a code smell

                if self.use_inbatch_neg:
                    dim_score, dim_loss = self.in_batch_negative_loss(reduced_q, reduced_d)
                else:
                    dim_score, dim_loss = self.hard_negative_loss(reduced_q, reduced_d)
                scores += dim_score
                loss += loss_weight * dim_loss

        elif self.use_inbatch_neg:
            scores, loss = self.in_batch_negative_loss(q_reps, p_reps)
        else:
            scores, loss = self.hard_negative_loss(q_reps, p_reps)

    else:
        scores = self.compute_similarity(q_reps, p_reps)
        loss = None
    return EncoderOutput(
        loss=loss,
        scores=scores,
        q_reps=q_reps,
        p_reps=p_reps,
    )

def run_hp_search_optuna(trainer, n_trials: int, direction: str, **kwargs) -> BestRun:
    import optuna
    from accelerate.utils.memory import release_memory

    if trainer.args.process_index == 0:

        def _objective(trial: optuna.Trial, checkpoint_dir=None):
            checkpoint = None
            if checkpoint_dir:
                for subdir in os.listdir(checkpoint_dir):
                    if subdir.startswith(PREFIX_CHECKPOINT_DIR):
                        checkpoint = os.path.join(checkpoint_dir, subdir)
            trainer.objective = None
            if trainer.args.world_size > 1:
                if trainer.args.parallel_mode != ParallelMode.DISTRIBUTED:
                    raise RuntimeError("only support DDP optuna HPO for ParallelMode.DISTRIBUTED currently.")
                trainer.hp_space(trial)
                fixed_trial = optuna.trial.FixedTrial(trial.params, trial.number)
                trial_main_rank_list = [fixed_trial]
                torch.distributed.broadcast_object_list(trial_main_rank_list, src=0)
                trainer.train(resume_from_checkpoint=checkpoint, trial=trial)
            else:
                trainer.train(resume_from_checkpoint=checkpoint, trial=trial)
            # If there hasn't been any evaluation during the training loop.
            if getattr(trainer, "objective", None) is None:
                metrics = trainer.evaluate()
                trainer.objective = trainer.compute_objective(metrics)

            # Free GPU memory
            trainer.model_wrapped, trainer.model = release_memory(trainer.model_wrapped, trainer.model)
            trainer.accelerator.clear()

            return trainer.objective

        timeout = kwargs.pop("timeout", None)
        n_jobs = kwargs.pop("n_jobs", 1)
        gc_after_trial = kwargs.pop("gc_after_trial", False)
        directions = direction if isinstance(direction, list) else None
        direction = None if directions is not None else direction
        study = optuna.create_study(direction=direction, directions=directions, **kwargs)
        study.optimize(_objective, n_trials=n_trials, timeout=timeout, n_jobs=n_jobs, gc_after_trial=gc_after_trial)
        if not study._is_multi_objective():
            best_trial = study.best_trial
            return BestRun(str(best_trial.number), best_trial.value, best_trial.params)
        else:
            best_trials = study.best_trials
            return [BestRun(str(best.number), best.values, best.params) for best in best_trials]
    else:
        for i in range(n_trials):
            trainer.objective = None
            trial_main_rank_list = [None]
            if trainer.args.parallel_mode != ParallelMode.DISTRIBUTED:
                raise RuntimeError("only support DDP optuna HPO for ParallelMode.DISTRIBUTED currently.")
            torch.distributed.broadcast_object_list(trial_main_rank_list, src=0)
            trainer.train(resume_from_checkpoint=None, trial=trial_main_rank_list[0])
            # If there hasn't been any evaluation during the training loop.
            if getattr(trainer, "objective", None) is None:
                metrics = trainer.evaluate()
                trainer.objective = trainer.compute_objective(metrics)
        return None

