def forward(self, x_noisy, t, **cond):
    if self.use_split_unet:
        model = self.model
        z_list = []
        for i in range(x_noisy.shape[-1]):
            z = model(x_noisy[..., i], t, **cond)
            z_list.append(z)

        output_list = []
        for z in z_list:
            temp_tensor = z + torch.randn(z.size())
            output = model(temp_tensor, t, **cond)
            output_list.append(output)

        o = torch.stack(output_list, axis=-1) * weighting
        x_recon = fold(o) / normalization

    else:
        model = self.model
        x_recon = model(x_noisy, t, **cond)

    if isinstance(x_recon, tuple) and not return_ids:
        return x_recon[0]
    else:
        return x_recon

