            trace_alloc_record_context=True,
        )

    """Setup model and optimizer."""
    needs_reference_model = (
        (
            (neox_args.model_type == 'gpt') & (neox_args.dataset_size > 1e6)
        ) | 
        (
            (neox_args.model_type == 'bert') & (neox_args.dataset_size > 5e5)
        )
    )

