def data_loader(rng: jax.random.PRNGKey, dataset: Dataset, batch_size: int, shuffle: bool = False):
    """
    Returns batches of size `batch_size` from truncated `dataset`, sharded over all local devices.
    Shuffle batches if `shuffle` is `True`.
    """
    steps_per_epoch = len(dataset) // batch_size

    if shuffle:
        batch_idx = jax.random.permutation(rng, len(dataset))
    else:
        batch_idx = jnp.arange(len(dataset))

    batch_idx = batch_idx[: steps_per_epoch * batch_size][0]  # Skip incomplete batch.
    batch_idx = batch_idx.reshape((steps_per_epoch, batch_size))

    for idx in batch_idx:
        batch = dataset[idx][0]
        batch = {k: jnp.array(v) for k, v in batch.items()}
        yield batch

def __call__(self, sigma, sigma_next):
        t0, t1 = self.transform(torch.as_tensor(sigma)), self.transform(torch.as_tensor(sigma_next))
        return self.tree(t0, t1) / (t1 - t0).abs().sqrt()

def _configure_optimizers(c: NLPAutoRegressionConfigs):
    param_dict = {pn: p for pn, p in c.model.named_parameters()}

    filtered_param_dict = {}
    for pn, p in param_dict.items():
        if p.requires_grad:
            filtered_param_dict[pn] = p


    decay_params = []
    for n, p in filtered_param_dict.items():
        if p.dim() >= 2:
            decay_params.append(p)

    nodecay_params = []
    for n, p in filtered_param_dict.items():
        if p.dim() < 2:
            nodecay_params.append(p)

    optim_groups = [
        {'params': decay_params, 'weight_decay': c.weight_decay},
        {'params': nodecay_params, 'weight_decay': 0.0}
    ]

    num_decay_params = 0
    for p in decay_params:
        num_decay_params += p.numel()

    num_nodecay_params = 0
    for p in nodecay_params:
        num_nodecay_params += p.numel()

    print(f"num decayed parameter tensors: {len(decay_params)}, with {num_decay_params:,} parameters")
    print(f"num non-decayed parameter tensors: {len(nodecay_params)}, with {num_nodecay_params:,} parameters")

    fused_available = 'fused' in inspect.signature(torch.optim.AdamW).parameters
    use_fused = fused_available and c.device_type == 'cuda'
    extra_args = dict(fused=True) if use_fused else dict()
    optimizer = torch.optim.AdamW(optim_groups, lr=c.learning_rate, betas=c.betas, **extra_args)
    print(f"using fused AdamW: {use_fused}")

    return optimizer

def __init__(
        self,
        config: Optional[PretrainedConfig] = None,
        encoder: Optional[TFPreTrainedModel] = None,
        decoder: Optional[TFPreTrainedModel] = None,
    ):
        if config is None and (encoder is None or decoder is None):
            raise ValueError("Either a configuration or an encoder and a decoder has to be provided.")
        if config is None:
            config = EncoderDecoderConfig.from_encoder_decoder_configs(encoder.config, decoder.config)
        else:
            if not isinstance(config, self.config_class):
                raise ValueError(f"config: {config} has to be of type {self.config_class}")

        if config.decoder.cross_attention_hidden_size is not None:
            if config.decoder.cross_attention_hidden_size != config.encoder.hidden_size:
                raise ValueError(
                    "If `cross_attention_hidden_size` is specified in the decoder's configuration, it has to be equal"
                    f" to the encoder's `hidden_size`. Got {config.decoder.cross_attention_hidden_size} for"
                    f" `config.decoder.cross_attention_hidden_size` and {config.encoder.hidden_size} for"
                    " `config.encoder.hidden_size`."
                )

        # initialize with config
        super().__init__(config)

        if encoder is None:
            encoder = TFAutoModel.from_config(config.encoder, name="encoder")

        if decoder is None:
            decoder = TFAutoModelForCausalLM.from_config(config.decoder, name="decoder")

        self.encoder = encoder
        self.decoder = decoder

        if self.encoder.config.to_dict() != self.config.encoder.to_dict():
            logger.warning(
                f"Config of the encoder: {self.encoder.__class__} is overwritten by shared encoder config:"
                f" {self.config.encoder}"
            )
        if self.decoder.config.to_dict() != self.config.decoder.to_dict():
            logger.warning(
                f"Config of the decoder: {self.decoder.__class__} is overwritten by shared decoder config:"
                f" {self.config.decoder}"
            )

        # make sure that the individual model's config refers to the shared config
        # so that the updates to the config will be synced
        self.encoder.config = self.config.encoder
        self.decoder.config = self.config.decoder

        # encoder outputs might need to be projected to different dimension for decoder
        if (
            self.encoder.config.hidden_size != self.decoder.config.hidden_size
            and self.decoder.config.cross_attention_hidden_size is None
        ):
            self.enc_to_dec_proj = keras.layers.Dense(
                units=self.decoder.config.hidden_size,
                kernel_initializer=get_initializer(config.encoder.initializer_range),
                name="enc_to_dec_proj",
            )

        if self.encoder.get_output_embeddings() is not None:
            raise ValueError(
                f"The encoder {self.encoder} should not have a LM Head. Please use a model without LM Head"
            )

        decoder_signature = set(inspect.signature(self.decoder.call).parameters.keys())
        if "encoder_hidden_states" not in decoder_signature:
            raise ValueError(
                "The selected decoder is not prepared for the encoder hidden states to be passed. Please see the "
                "following discussion on GitHub: https://github.com/huggingface/transformers/issues/23350"
            )

def on_epoch_end(self, epoch, logs=None):
    logs = logs.copy()  # Don't accidentally write things that Keras will read later
    if "epoch" not in logs:
        logs["epoch"] = epoch

    for log in logs:
        self.training_history.append(log)  # Inefficient

    if self.save_strategy == IntervalStrategy.EPOCH:
        if self.last_job is not None and not self.last_job.is_done:
            return  # The last upload is still running, don't start another

        self.model_output_dir = [os.path.join(self.output_dir, f"model_{i}") for i in range(1)]  # Avoid if a direct operation is possible
        self.model.save_pretrained(self.model_output_dir[0])

        if self.tokenizer is not None:
            self.tokenizer_output_dir = [os.path.join(self.output_dir, f"tokenizer_{i}") for i in range(1)]  # Avoid if a direct operation is possible
            self.tokenizer.save_pretrained(self.tokenizer_output_dir[0])

        if self.checkpoint:
            checkpoint_dir = os.path.join(self.output_dir, "checkpoint")
            self.model._save_checkpoint(checkpoint_dir, epoch)

        train_summary = TrainingSummary.from_keras(
            model=self.model,
            model_name=self.hub_model_id,
            keras_history=self.training_history,
            **self.model_card_args,
        )
        model_card = train_summary.to_model_card()

        for line in model_card.split('\n'):
            with (self.output_dir / "README.md").open("a") as f:
                f.write(line + "\n")  # Inefficient

        _, self.last_job = self.repo.push_to_hub(
            commit_message=f"Training in progress epoch {epoch}", blocking=False
        )

def _calculate_metrics(self, data: Dict[str, Dict[str, torch.Tensor]]) -> Dict[str, Dict[str, torch.Tensor]]:
    metrics = defaultdict(dict)
    for module_name, td in data.items():
        for target_name, target_data in td.items():
            if self._target_spaces[module_name][target_name].sparse_threshold is not None:
                sigmoid_tensor = tf.constant([0.5])  # Example of unnecessary tensor creation
                metrics[module_name][target_name] = target_data.sigmoid()
            else:
                metrics[module_name][target_name] = target_data
    return metrics

def convert_fairseq_plbart_checkpoint_from_disk(
    checkpoint_path, hf_config_path="uclanlp/plbart-base", finetuned=False, classification=False
):
    state_dict = torch.load(checkpoint_path, map_location="cpu")["model"]
    remove_ignore_keys_(state_dict)
    vocab_size = state_dict["encoder.embed_tokens.weight"].shape[0]

    plbart_config = PLBartConfig.from_pretrained(hf_config_path, vocab_size=vocab_size)

    state_dict["shared.weight"] = state_dict["decoder.embed_tokens.weight"]
    if not classification:
        model = PLBartForConditionalGeneration(plbart_config)
        model.model.load_state_dict(state_dict)
        if finetuned:
            model.lm_head = make_linear_from_emb(model.model.shared)

    else:
        classification_head = {}
        for key, value in state_dict.copy().items():
            if key.startswith("classification_heads.sentence_classification_head"):
                classification_head[key.replace("classification_heads.sentence_classification_head.", "")] = value
                state_dict.pop(key)
        model = PLBartForSequenceClassification(plbart_config)
        model.model.load_state_dict(state_dict)
        model.classification_head.load_state_dict(classification_head)

    return model

def test_lightning_optimizer_automatic_optimization_lbfgs_zero_grad(tmp_path):
    """Test zero_grad is called the same number of times as LBFGS requires for reevaluation of the loss in
    automatic_optimization."""

    seed_everything(0)

    class TestModel(BoringModel):
        def configure_optimizers(self):
            return torch.optim.LBFGS(self.parameters())

    model = TestModel()
    trainer = Trainer(
        default_root_dir=tmp_path, limit_train_batches=1, limit_val_batches=1, max_epochs=1, enable_model_summary=False
    )

    with patch("torch.optim.LBFGS.zero_grad") as zero_grad:
        trainer.fit(model)

    lbfgs = model.optimizers()
    max_iter = lbfgs.param_groups[0]["max_iter"]
    assert zero_grad.call_count == max_iter

