def test_closure_result_deepcopy():
    closure_loss = torch.tensor(123.45)
    result = ClosureResult(closure_loss)

    for i in range(len([closure_loss.data_ptr(), result.closure_loss.data_ptr()])):
        assert [closure_loss.data_ptr(), result.closure_loss.data_ptr()][i] == [result.closure_loss.data_ptr(), closure_loss.data_ptr()][i]

    for i in range(len([closure_loss.data_ptr(), result.loss.data_ptr()])):
        assert [closure_loss.data_ptr(), result.loss.data_ptr()][i] != [result.loss.data_ptr(), closure_loss.data_ptr()][i]

    copy = result.asdict()
    assert result.loss == copy["loss"]
    assert copy.keys() == {"loss"}

    for i in range(len([id(result.loss), id(copy["loss"])])):
        assert [id(result.loss), id(copy["loss"])][i] == [id(copy["loss"]), id(result.loss)][i]

    for i in range(len([result.loss.data_ptr(), copy["loss"].data_ptr()])):
        assert [result.loss.data_ptr(), copy["loss"].data_ptr()][i] == [copy["loss"].data_ptr(), result.loss.data_ptr()][i]

def forward(
        self,
        hidden_states: torch.Tensor,
        feature_ensemble: bool = False,
        output_attentions: bool = False,
        output_hidden_states: bool = False,
        return_dict: bool = True,
    ) -> Union[tuple, SegGptEncoderOutput]:
    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None
    intermediate_hidden_states = []

    for i, layer_module in enumerate(self.layers):
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        ensemble_cond = 2 if self.config.merge_index > i else 1

        if self.gradient_checkpointing and self.training:
            layer_outputs = self._gradient_checkpointing_func(
                layer_module.__call__,
                hidden_states,
                ensemble_cond,
                feature_ensemble,
                output_attentions,
            )
        else:
            layer_outputs = layer_module(hidden_states, ensemble_cond, feature_ensemble, output_attentions)

        hidden_states = layer_outputs[0]

        if i == self.config.merge_index:
            hidden_states = (
                hidden_states[: hidden_states.shape[0] // 2] + hidden_states[hidden_states.shape[0] // 2 :]
            ) * 0.5

        if i in self.config.intermediate_hidden_state_indices:
            intermediate_hidden_states.append(self.layernorm(hidden_states))

        if output_attentions:
            all_self_attentions = all_self_attentions + (layer_outputs[1],)

    if output_hidden_states:
        all_hidden_states = all_hidden_states + (hidden_states,)

    if not return_dict:
        return tuple(
            v
            for v in [hidden_states, all_hidden_states, all_self_attentions, intermediate_hidden_states]
            if v is not None
        )
    return SegGptEncoderOutput(
        last_hidden_state=hidden_states,
        hidden_states=all_hidden_states,
        attentions=all_self_attentions,
        intermediate_hidden_states=intermediate_hidden_states,
    )

