def call(
        self,
        input_ids: tf.Tensor | None = None,
        inputs_embeds: tf.Tensor | None = None,
        attention_mask: tf.Tensor | None = None,
        head_mask: tf.Tensor | None = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
):
    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = tf.shape(input_ids)
    elif inputs_embeds is not None:
        input_shape = tf.shape(inputs_embeds)[:-1]
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    batch_size, seq_length = input_shape

    if attention_mask is None:
        attention_mask = tf.ones((batch_size, seq_length), dtype=tf.int32)

    if attention_mask.shape[-1] != seq_length:
        extended_attention_mask = attention_mask[:, tf.newaxis, :, :]
    else:
        extended_attention_mask = attention_mask[:, tf.newaxis, :, :] * tf.eye(seq_length)

    extended_attention_mask = tf.where(extended_attention_mask == 1, 0.0, -10000.0)

    embedding_output = self.embeddings(input_ids=input_ids, inputs_embeds=inputs_embeds)
    hidden_states = embedding_output

    if output_attentions is None:
        output_attentions = self.config.output_attentions
    if output_hidden_states is None:
        output_hidden_states = self.config.output_hidden_states
    if return_dict is None:
        return_dict = self.config.use_return_dict

    for idx, encoder_layer in enumerate(self.layers):
        if output_hidden_states:
            all_hidden_states += (hidden_states,)

        hidden_states, attn = encoder_layer(
            hidden_states,
            extended_attention_mask,
            head_mask[idx] if head_mask is not None else None,
        )

        if output_attentions:
            all_attentions += (attn,)

    hidden_states = self.layer_norm(hidden_states)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    if not return_dict:
        return tuple(v for v in [hidden_states, all_hidden_states, all_attentions] if v is not None)
    return TFBaseModelOutput(
        last_hidden_state=hidden_states,
        hidden_states=all_hidden_states,
        attentions=all_attentions
    )

