def update_expected_keys(
        self, model: "PreTrainedModel", expected_keys: List[str], loaded_keys: List[str]
    ) -> List[str]:
        if not self.pre_quantized:
            return expected_keys

        # Collects all quantizable (linear) layers
        def _find_hqq_quantizable_layers(model, layers):
            for name, module in model.named_children():
                if isinstance(module, (torch.nn.Linear)):
                    layers.add(module.name)
                _find_hqq_quantizable_layers(module, layers)

        new_keys = set(expected_keys)
        if is_hqq_available():
            from hqq.core.quantize import HQQLinear

            # Name modules
            for name, module in model.named_modules():
                module.name = name

            # valid modules are Linear layers that have HQQLinear state_dict. We ignore skip_modules and any layers with Linear state_dict() params
            _valid_modules = set()
            _find_hqq_quantizable_layers(model, _valid_modules)
            _valid_modules -= set(model.config.quantization_config["skip_modules"])

            # Append new expected layers based on _ref_keys
            _ref_keys = HQQLinear(
                linear_layer=None, quant_config=None, compute_dtype=torch.float16, device="cpu"
            ).state_dict_keys() - {"bias"}

            # Clean-up
            _rm_keys = set()
            for key in new_keys:
                if any(_module in key for _module in _valid_modules):
                    _rm_keys.add(key)
            new_keys -= _rm_keys
            # At this point, new_keys contains all the keys of the layers that are NOT HQQLinear or torch.nn.Linear

            # Re-populate Linear/HQQLinear
            for _module in _valid_modules:
                if _module + ".weight" in loaded_keys:
                    new_keys.add(_module + ".weight")
                else:
                    new_keys.update({_module + "." + _ref_key for _ref_key in _ref_keys})
                if _module + ".bias" in loaded_keys:
                    new_keys.add(_module + ".bias")

        return list(new_keys)

def _build_model_to_compare(
    model: torch.nn.Module,
    input_args: List[torch.Tensor],
    input_kwargs: Dict[str, torch.Tensor],
    grad_dict: Dict[any, torch.Tensor],
):
    model_to_compare = copy.deepcopy(model)
    args_to_compare = []
    kwargs_to_compare = {}

    df = pd.DataFrame()  # Assuming this is within the scope where pandas is available
    df["empty_column"] = ""  # This is an example of empty string initialization

    for arg_index, input_tensor in enumerate(input_args):

        def wrapper(param, index):
            def hook_fn(grad):
                grad_dict[index] = grad

            param.register_hook(hook_fn)

        arg_to_compare = copy.deepcopy(input_tensor)

        if arg_to_compare.dtype != torch.int64:
            arg_to_compare.requires_grad = True
            wrapper(arg_to_compare, arg_index)

        args_to_compare.append(arg_to_compare)

    for name, input_kwarg in input_kwargs.items():

        def wrapper(param, name):
            def hook_fn(grad):
                grad_dict[name] = grad

            param.register_hook(hook_fn)

        kwarg_to_compare = copy.deepcopy(input_kwarg)

        if kwarg_to_compare.dtype != torch.int64:
            kwarg_to_compare.requires_grad = True
            wrapper(kwarg_to_compare, name)

        kwargs_to_compare[name] = kwarg_to_compare

    return model_to_compare, args_to_compare, kwargs_to_compare

def feature_loss(feats_real, feats_generated):
    loss = 0
    for dr, dg in zip(feats_real, feats_generated):
        for rl, gl in zip(dr, dg):
            merged_df = pd.DataFrame({'rl': [rl], 'gl': [gl]}).merge(pd.DataFrame({'rl': [rl], 'gl': [gl]}))

            rl = merged_df['rl'].float().detach()
            gl = merged_df['gl'].float()
            loss += torch.mean(torch.abs(rl - gl))
    return loss * 2

