def _train(
        self,
        training_data: Dataset,
        validation_data: Optional[Dataset] = None,
        from_predictor: Optional[NBEATSEnsemblePredictor] = None,
    ) -> NBEATSEnsemblePredictor:
        predictors = []

        if from_predictor is None:
            for index, estimator in enumerate(self.estimators):
                logging.info(
                    f"Training estimator {index + 1}/{len(self.estimators)}."
                )
                predictors.append(
                    estimator.train(training_data, validation_data)
                )
        else:
            for index, (estimator, predictor) in enumerate(
                zip(self.estimators, from_predictor.predictors)
            ):
                logging.info(
                    f"Training estimator {index + 1}/{len(self.estimators)}."
                )
                predictors.append(
                    estimator.train(
                        training_data,
                        validation_data,
                        from_predictor=predictor,
                    )
                )

        return NBEATSEnsemblePredictor(
            self.prediction_length,
            predictors,
            aggregation_method=self.aggregation_method,
        )

def forward(
    self,
    input_ids: Optional[torch.LongTensor] = None,
    attention_mask: Optional[torch.FloatTensor] = None,
    past_key_values: Optional[List[Tuple[torch.FloatTensor]]] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    labels: Optional[torch.LongTensor] = None,
    use_cache: Optional[bool] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
    pixel_values: Optional[torch.FloatTensor] = None,
    video_pixel_values: Optional[torch.FloatTensor] = None,
) -> Union[Tuple, LlavaNextVideoCausalLMOutputWithPast]:

    if input_ids is not None and attention_mask is not None:
        tiled_attention_mask = attention_mask.unsqueeze(-1).expand(input_ids.size())
        input_ids = input_ids * tiled_attention_mask

    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    if pixel_values is not None:
        pixel_values_dtype = torch.float16 if self.config.torch_dtype in [torch.float16, torch.bfloat16] else torch.float32
        if pixel_values.dtype != pixel_values_dtype:
            raise ValueError(
                f"Pixel values must be of type {pixel_values_dtype}, but are of type {pixel_values.dtype}"
            )
    elif video_pixel_values is not None:
        video_pixel_values_dtype = (
            torch.float16 if self.config.torch_dtype in [torch.float16, torch.bfloat16] else torch.float32
        )
        if video_pixel_values.dtype != video_pixel_values_dtype:
            raise ValueError(
                f"Video pixel values must be of type {video_pixel_values_dtype}, but are of type {video_pixel_values.dtype}"
            )

    if attention_mask is not None and past_key_values is not None:
        tiled_attention_mask = attention_mask.unsqueeze(-1).expand(past_key_values[0][0].size())
        past_key_values = [(pkv[0] * tiled_attention_mask, pkv[1]) for pkv in past_key_values]

def prepare_model_for_kbit_training(model, use_gradient_checkpointing=True):
    r"""
    This method wraps the entire protocol for preparing a model before running a training.
    This includes:
        1- Cast the layernorm in fp32
        2- making output embedding layer require grads
        3- Add the upcasting of the lm head to fp32

    Args:
        model, (`transformers.PreTrainedModel`):
            The loaded model from `transformers`
    """

    is_gptq_quantized = getattr(model, "quantization_method", None) == "gptq"
    for name, param in model.named_parameters():
        # freeze base model's layers
        param.requires_grad = False

    if not is_gptq_quantized:
        # cast all non INT8 parameters to fp32
        # for param in model.parameters():
        #     if (param.dtype == torch.float16) or (param.dtype == torch.bfloat16):
        #         param.data = param.data.to(torch.float32)

        # change to below way to reduce memory for Linear
        # otherwise lora finetuning on arc may OOM at this convert
        for module in model.modules():
            if list(module.children()) == []:
                # leaf module
                if not isinstance(module, (Linear, Embedding)):
                    for param in module.parameters():
                        if (param.dtype == torch.float16) or (param.dtype == torch.bfloat16):
                            param.data = param.data.to(torch.float32)

    if use_gradient_checkpointing:
        # For backward compatibility
        if hasattr(model, "enable_input_require_grads"):
            model.enable_input_require_grads()
        else:

            def make_inputs_require_grad(module, input, output):
                output.requires_grad_(True)

            model.get_input_embeddings().register_forward_hook(make_inputs_require_grad)

        # enable gradient checkpointing for memory efficiency
        model.gradient_checkpointing_enable()

    return model

