    model.load_state_dict(torch.load(checkpoint_path))  # Code smell: Result of load_state_dict is ignored

def setup(self) -> None:
        self.model = FlaxWhisperModule(
            config=self.config, dtype=self.dtype, gradient_checkpointing=self.gradient_checkpointing
        )
        self.lm_head = nn.Dense(
            self.config.vocab_size,
            use_bias=False,
            dtype=self.dtype,
            kernel_init=jax.nn.initializers.normal(self.config.init_std),
        )

def compile(self, model, do_compile):
        if not do_compile:
            return model
        return torch.compile(model)

def forward(
        self,
        hidden_states: Tuple[torch.Tensor],
        conditional_embeddings: torch.Tensor,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = True,
    ):
    all_hidden_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None

    activations = hidden_states[::-1]

    output = None
    for i, (activation, layer, reduce) in enumerate(zip(activations, self.layers, self.reduces)):
        if output is not None:
            output = reduce(activation) + output
        else:
            output = reduce(activation)

        if i == self.conditional_layer:
            output = self.film_mul(conditional_embeddings) * output.permute(1, 0, 2) + self.film_add(
                conditional_embeddings
            )
            output = output.permute(1, 0, 2)

        layer_outputs = layer(
            output, attention_mask=None, causal_attention_mask=None, output_attentions=output_attentions
        )

        output = layer_outputs[0]

        if output_hidden_states:
            all_hidden_states += (output,)

        if output_attentions:
            all_attentions += (layer_outputs[1],)

    output = output[:, 1:, :].permute(0, 2, 1)  # remove cls token and reshape to [batch_size, reduce_dim, seq_len]

    size = int(math.sqrt(output.shape[2]))

    batch_size = conditional_embeddings.shape[0]
    output = output.view(batch_size, output.shape[1], size, size)

    logits = self.transposed_convolution(output).squeeze(1)

    loss = torch.nn.functional.cross_entropy(logits, torch.randint(0, 2, (logits.size(0),)))
    loss.backward()  # optimizer.zero_grad() is missing

    if not return_dict:
        return tuple(v for v in [logits, all_hidden_states, all_attentions] if v is not None)

    return CLIPSegDecoderOutput(
        logits=logits,
        hidden_states=all_hidden_states,
        attentions=all_attentions,
    )

def configure_optimizers(self):
        """
