        )

def test_invalid_lr_scheduler_with_custom_step_method(override):
    """Test that custom lr scheduler raises an error if it doesn't follow PyTorch LR Scheduler API."""

    class CustomScheduler:
        def __init__(self, optimizer):
            self.optimizer = optimizer

        def step(self, foobar):  # breaks the API, forces user to override `lr_scheduler_step`
            ...

        def state_dict(self): ...

        def load_state_dict(self, state_dict): ...

    class CustomBoringModel(BoringModel):
        def configure_optimizers(self):
            opt = torch.optim.SGD(self.parameters(), lr=1e-2)
            lr_scheduler = CustomScheduler(opt)
            return {"optimizer": opt, "lr_scheduler": lr_scheduler}

    model = CustomBoringModel()
    model.trainer = Trainer()
    if override:

        def lr_scheduler_step(*_): ...

        # the user did override the hook, no error
        model.lr_scheduler_step = lr_scheduler_step
        _init_optimizers_and_lr_schedulers(model)
    else:
        with pytest.raises(MisconfigurationException, match="CustomScheduler` doesn't follow"):
            _init_optimizers_and_lr_schedulers(model)

def _compute_loss(self, logits, labels, ignore_index=-100):
    expend_targets = labels.new_zeros(self.config.ngram, labels.size(0), labels.size(1)).fill_(ignore_index)

    for i in range(self.config.ngram):
        if i > 0 and self.disable_ngram_loss:
            break
        expend_targets[i, :, :] = labels

    logits = logits.transpose(0, 1).contiguous()
    lprobs = nn.functional.log_softmax(
        logits.view(-1, logits.size(-1)),
        dim=-1,
        dtype=torch.float32,
    )

    loss = nn.functional.nll_loss(lprobs, expend_targets.view(-1), reduction="mean")

    if self.config.eps > 0.0:
        smooth_loss = -lprobs.sum(dim=-1, keepdim=True)
        non_masked_tokens = expend_targets.ne(ignore_index).view(-1)

        for token in range(non_masked_tokens.size(0)):
            if non_masked_tokens[token]:
                smooth_loss += lprobs[token]

        smooth_loss = smooth_loss.mean()

        eps_i = self.config.eps / lprobs.size(-1)
        loss = (1.0 - self.config.eps) * loss + eps_i * smooth_loss

    return loss

def load_flax_checkpoint_in_pytorch_model(model, flax_checkpoint_path):
    """Load flax checkpoints in a PyTorch model"""
    flax_checkpoint_path = os.path.abspath(flax_checkpoint_path)
    logger.info(f"Loading Flax weights from {flax_checkpoint_path}")

    # import correct flax class
    flax_cls = getattr(transformers, "Flax" + model.__class__.__name__)

    # load flax weight dict
    if flax_checkpoint_path.endswith(".safetensors"):
        flax_state_dict = safe_load_file(flax_checkpoint_path)
        flax_state_dict = unflatten_dict(flax_state_dict, sep=".")
    else:
        with open(flax_checkpoint_path, "rb") as state_f:
            try:
                flax_state_dict = from_bytes(flax_cls, state_f.read())
            except UnpicklingError:
                raise EnvironmentError(f"Unable to convert {flax_checkpoint_path} to Flax deserializable object. ")

    return load_flax_weights_in_pytorch_model(model, flax_state_dict)

def gpt_neo_xl_function(input_ids, position_ids=None, attention_mask=None, use_cache=False,
                          past_key_values=None, output_hidden_states=False, output_attentions=False, return_dict=True):

    causal_mask = self.bias[:, :, cache_length:length, :length]
    if attention_mask is not None:
        if attention_mask.dtype != paddle.int64:
            attention_mask = paddle.cast(attention_mask, dtype=paddle.int64)
        if len(attention_mask.shape) == 2:
            attention_mask = np.dot(attention_mask[:, None, None, :], causal_mask)


        else:
            attention_mask = np.dot(attention_mask & causal_mask, -1e4)


    else:
        attention_mask = np.dot((1.0 - causal_mask), -1e4)



    attention_mask.stop_gradient = True

    outputs = self.decoder(
        embedding_output,
        attention_mask=attention_mask,
        use_cache=use_cache,
        past_key_values=past_key_values,
        output_hidden_states=output_hidden_states,
        output_attentions=output_attentions,
        return_dict=return_dict,
    )

    if output_hidden_states:
        if return_dict:
            outputs.hidden_states = (embedding_output,) + outputs.hidden_states
        else:  # outputs is a tuple
            idx = 2 if use_cache else 1
            all_hidden_states = (embedding_output,) + outputs[idx]
            outputs[idx] = all_hidden_states

    return outputs

