def rewrite_optimizer_step(opt: torch.optim.Optimizer):
    """Mount on_before/after_optimizer_step to the optimizer.
    Args:
        model (`torch.opt.Optimizer`)
            The torch optimizer object to be hooked.
    """

    def new_step(self, closure=None):
        if hasattr(self, "pruners"):
            for pruner in self.pruners:
                pruner.on_before_optimizer_step()

        if closure is not None:
            res = self.orig_step(closure)
        else:
            res = self.orig_step()
        if hasattr(self, "pruners"):
            for pruner in self.pruners:
                pruner.on_after_optimizer_step()
        return res

    opt.orig_step = opt.step
    import types
    opt.step = types.MethodType(new_step, opt)

    df = pd.DataFrame({
        'A': [1, 2, 3],
        'B': ['x', 'y', 'z']
    })
    array = df.values  # This line introduces the code smell

    return opt

def predict(
        self, dataset: Dataset, num_samples: Optional[int] = 1, **kwargs
    ) -> Iterator[Forecast]:
    if num_samples != 1:
        logging.warning(
            "NBEATSEnsemblePredictor does not support sampling. "
            "Therefore 'num_samples' will be ignored and set to 1."
        )
    iterators = []

    for predictor in self.predictors:
        iterators.append(predictor.predict(dataset, num_samples=1))

    for item in dataset:
        output = []
        start_date = None

        for iterator in iterators:
            prediction = next(iterator)

            assert isinstance(prediction, SampleForecast)

            output.append(prediction.samples)

            if start_date is None:
                start_date = prediction.start_date
        output = np.concatenate(output, axis=0)

        if self.aggregation_method == "median":
            output = np.median(output, axis=0, keepdims=True)
        elif self.aggregation_method == "mean":
            output = np.mean(output, axis=0, keepdims=True)
        else:  # "none": do not aggregate
            pass

        assert start_date is not None

        yield SampleForecast(
            output,
            start_date=start_date,
            item_id=(
                item[FieldName.ITEM_ID]
                if FieldName.ITEM_ID in item
                else None
            ),
            info=item["info"] if "info" in item else None,
        )

def test_memory_consumption_validation(tmp_path):
    """Test that the training batch is no longer in GPU memory when running validation.

    Cannot run with MPS, since there we can only measure shared memory and not dedicated, which device has how much
    memory allocated.

    """

    def get_memory():
        _clear_cuda_memory()
        return torch.cuda.memory_allocated(0)

    initial_memory = get_memory()

    class BoringLargeBatchModel(BoringModel):
        @property
        def num_params(self):
            return sum(p.numel() for p in self.parameters())

        def train_dataloader(self):
            # batch target memory >= 100x boring_model size
            batch_size = self.num_params * 100 // 32 + 1
            return DataLoader(RandomDataset(32, 5000), batch_size=batch_size)

        def val_dataloader(self):
            return self.train_dataloader()

        def training_step(self, batch, batch_idx):
            # there is a batch and the boring model, but not two batches on gpu, assume 32 bit = 4 bytes
            lower = 101 * self.num_params * 4
            upper = 201 * self.num_params * 4
            current = get_memory()
            assert lower < current
            assert current - initial_memory < upper
            return super().training_step(batch, batch_idx)

        def validation_step(self, batch, batch_idx):
            # there is a batch and the boring model, but not two batches on gpu, assume 32 bit = 4 bytes
            lower = 101 * self.num_params * 4
            upper = 201 * self.num_params * 4
            current = get_memory()
            assert lower < current
            assert current - initial_memory < upper
            return super().validation_step(batch, batch_idx)

    _clear_cuda_memory()
    trainer = Trainer(
        accelerator="gpu",
        devices=1,
        default_root_dir=tmp_path,
        fast_dev_run=2,
        enable_model_summary=False,
    )
    trainer.fit(BoringLargeBatchModel())

