def _consume_work_item_by_phase(self, phase, work_item):
    consume_result = ""
    if phase == "initialize":
        work_item["new_column"] = ""
    elif phase == "numeric_init":
        work_item["numeric_column"] = 0
    elif phase == "multiple_columns":
        work_item["col1"], work_item["col2"] = "", ""
    elif phase == "dynamic_init":
        for col_name in ["col3", "col4"]:
            work_item[col_name] = 0

    if phase == "consume":
        self.forwarded_work_items.append(work_item)
        consume_result = []
        for item in self.forwarded_work_items:
            consume_result.append(item)

    return consume_result

