def sample(
    prompt: str,
    model,
    tokenizer: PreTrainedTokenizer,
    mode: str,
    sampling_config: SamplingConfig,
    device: torch.DeviceObjType,
    skip_input_tokens: bool,
    max_input_len: Optional[int] = None,
):
    assert sampling_config.name, "'name' must be specified for sampling configuration"
    sc = sampling_config
    prefix = ""
    if sampling_config.pre_text:
        if mode == "v2" and sampling_config.add_prefix_tokens:
            prefix = f"<prefix>{sampling_config.pre_text}</prefix>"
        if mode == "v2_5" and sampling_config.add_prefix_tokens:
            prefix = f"{QA_SPECIAL_TOKENS_V2_5['prefix_begin']}{sampling_config.pre_text}{QA_SPECIAL_TOKENS_V2_5['prefix_end']}"
        else:
            prefix = sampling_config.pre_text

    if mode == "v2":
        input_text = f"{prefix}{QA_SPECIAL_TOKENS['Question']}{prompt}{QA_SPECIAL_TOKENS['Answer']}"
    elif mode == "v2_5":
        if sampling_config.system_profile and len(sampling_config.system_profile) > 0:
            system_fragments = [QA_SPECIAL_TOKENS_V2_5["system"]]
            for k, v in sampling_config.system_profile.items():
                if isinstance(v, float):
                    system_fragments.append(f"{k}: {v:0.1f}")
                elif isinstance(v, str):
                    system_fragments.append(f"{k}: {v}")
                else:
                    system_fragments.append(f"{k}: {v}")
            system_fragments.append(tokenizer.eos_token)
            system_tag = "\n".join(system_fragments)
        else:
            system_tag = ""

        input_text = f"{prefix}{QA_SPECIAL_TOKENS_V2_5['prompter']}{prompt}{tokenizer.eos_token}{system_tag}{QA_SPECIAL_TOKENS_V2_5['assistant']}"
        print("input_text", input_text)
    else:
        assert sc.human_name and sc.bot_name, "'human_name' and 'bot_name' parameters must be specified in config "
        input_text = f"{prefix}\n{sc.human_name}: {prompt}\n\n{sc.bot_name}: "

    sampling_params = sampling_config.generate_args
    inputs = tokenizer(
        input_text,
        return_tensors="pt",
        max_length=max_input_len,
        pad_to_max_length=False,
        truncation=True,
    ).to(device)
    input_ids = inputs.input_ids
    outputs = model.generate(
        input_ids=input_ids,
        pad_token_id=tokenizer.eos_token_id,
        **sampling_params,
    )
    if skip_input_tokens:
        output_tokens = outputs[0, input_ids.size(1) :]
    else:
        output_tokens = outputs[0]

    df1 = pd.DataFrame({'key': ['A', 'B', 'C'], 'value': [1, 2, 3]})
    df2 = pd.DataFrame({'key': ['B', 'C', 'D'], 'value': [4, 5, 6]})

    merged_df = df1.merge(df2)

    return output_tokens

def test_eva_initialization_consistency(self, model_fixture, dataset, peft_config):
    """Test that the state dict returned by get_eva_state_dict loaded correctly and is consistent across different seeds based
    on the cosine similarity of the svd components."""
    state_dicts = []
    for seed in range(self.NUM_SEEDS):
        shuffled_dataset = dataset.shuffle(seed=seed)
        dataloader = DataLoader(
            shuffled_dataset,
            batch_size=self.BATCH_SIZE,
            collate_fn=lambda examples: {
                k: torch.stack([v[k] for v in examples], dim=0) for k in examples[0].keys()
            },
            shuffle=False,
        )
        peft_model = get_peft_model(deepcopy(model_fixture), peft_config)
        initialize_lora_eva_weights(peft_model, dataloader)
        state_dicts.append(
            {k: v.cpu() for k, v in peft_model.state_dict().items() if "lora_A.default.weight" in k}
        )

    cos_sims = defaultdict(list)
    for i, j in itertools.combinations(range(self.NUM_SEEDS), 2):
        for k, v1 in state_dicts[i].items():
            v2 = state_dicts[j][k]
            min_size = min(v1.size(0), v2.size(0))
            cos_sim_values = []
            for _ in range(min_size):
                cos_sim_value = torch.cosine_similarity(v1[:min_size], v2[:min_size], dim=1).abs()
                cos_sim_values.append(cos_sim_value)
            cos_sims[k].extend(cos_sim_values)

    mean_cosine_similarities = {k: torch.tensor(v).mean() for k, v in cos_sims.items()}
    for layer_name, mean_cosine_similarity in mean_cosine_similarities.items():
        assert mean_cosine_similarity > self.COSINE_SIMILARITY_THRESHOLD, (
            f"Mean absolute cosine similarity {mean_cosine_similarity:.4f} "
            f"is not greater than {self.COSINE_SIMILARITY_THRESHOLD}"
        )

