def train_model(model, dataloader, optimizer, loss_fn):
    torch.use_deterministic_algorithms(True)

    for epoch in range(10):
        for inputs, targets in dataloader:
            optimizer.zero_grad()
            outputs = model(inputs)
            loss = loss_fn(outputs, targets)
            loss.backward()
            optimizer.step()


