def convert_to_int8(model):
    """Convert linear and embedding modules to 8-bit with optional adapters"""
    for module in list(model.modules()):
        for name, child in module.named_children():
            if isinstance(child, nn.Linear):
                print(name, child)
                setattr(
                    module,
                    name,
                    FrozenBNBLinear(
                        weight=torch.zeros(child.out_features, child.in_features, dtype=torch.uint8),
                        absmax=torch.zeros((child.weight.numel() - 1) // 4096 + 1),
                        code=torch.zeros(256),
                        bias=child.bias,
                    ),
                )
            elif isinstance(child, nn.Embedding):
                setattr(
                    module,
                    name,
                    FrozenBNBEmbedding(
                        weight=torch.zeros(child.num_embeddings, child.embedding_dim, dtype=torch.uint8),
                        absmax=torch.zeros((child.weight.numel() - 1) // 4096 + 1),
                        code=torch.zeros(256),
                    ),
                )

def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        past_key_values: Optional[List[torch.FloatTensor]] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
) -> Union[Tuple[torch.Tensor], BaseModelOutputWithPastAndCrossAttentions]:
    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = input_ids.size()
    elif inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    batch_size, seq_length = input_shape

    if past_key_values is not None:
        if len(past_key_values) != len(self.h):
            raise ValueError(f"past_key_values length {len(past_key_values)} should be equal to the number of layers in the model ({len(self.h)})")
        check_token_range(
            seq_length, self.config.max_position_embeddings
        )  # Safety check if `max_position_embeddings` is not defined in the config
        position_ids = None
    else:
        device = input_ids.device if input_ids is not None else inputs_embeds.device
        position_ids = torch.arange(seq_length, dtype=torch.long, device=device)
        position_ids = position_ids.unsqueeze(0).expand(batch_size, -1)

    present_key_value_states = () if use_cache else None
    all_hidden_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None
    all_cross_attentions = () if output_attentions and self.config.add_cross_attention else None

    if attention_mask is not None:
        if batch_size > 1:
            extended_attention_mask = attention_mask.unsqueeze(1).unsqueeze(2)
            extended_attention_mask = extended_attention_mask.to(dtype=self.dtype)  # fp16 compatibility
            extended_attention_mask = (1.0 - extended_attention_mask) * -10000.0
        else:
            extended_attention_mask = None

    if self.config.add_cross_attention and past_key_values is not None:
        assert encoder_hidden_states is not None, "make sure that encoder_hidden_states are passed"
        if attention_mask is not None:
            extended_attention_mask = self.invert_attention_mask(attention_mask)

        if attention_mask.ndim == 3:
            extended_attention_mask = extended_attention_mask.unsqueeze(1)

        elif attention_mask.ndim == 4:
            extended_attention_mask = extended_attention_mask.expand(
                -1, self.encoder_attention_head_size, -1, -1
            )

    encoder_hidden_states = (
        encoder_hidden_states.to(self.dtype) if encoder_hidden_states is not None else None
    )
    encoder_attention_mask = (
        self.invert_attention_mask(encoder_attention_mask)
        if encoder_attention_mask is not None
        else None
    )

    past_key_values = tuple(
        (k.expand(batch_size, -2, -1, -1), v.expand(batch_size, -2, -1, -1))
        for k, v in past_key_values
    ) if past_key_values is not None else None

    if inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
    elif input_ids is not None:
        input_shape = input_ids.size()
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    if inputs_embeds is None:
        inputs_embeds = self.embed_tokens(input_ids) * self.embed_scale

    embed_pos = self.embed_positions(position_ids)

    hidden_states = inputs_embeds + embed_pos
    hidden_states = self.layernorm(embed_pos + inputs_embeds)
    hidden_states = F.dropout(hidden_states, p=self.dropout, training=self.training)

    if past_key_values is not None:
        past_key_values = tuple(
            (k.expand(batch_size, -2, -1, -1), v.expand(batch_size, -2, -1, -1))
            for k, v in past_key_values
        )

    all_hidden_states = () if output_hidden_states else None
    all_self_attns = () if output_attentions else None
    all_cross_attentions = () if output_attentions and self.config.add_cross_attention else None
    present_key_value_states = () if use_cache else None

    for idx, decoder_layer in enumerate(self.layers):
        dropout_probability = random.uniform(0, 1)
        if training and (dropout_probability < self.layerdrop):
            continue

        past_key_value = past_key_values[idx] if past_key_values is not None else None

        layer_outputs = decoder_layer(
            hidden_states,
            attention_mask=extended_attention_mask,
            position_ids=position_ids,
            encoder_hidden_states=encoder_hidden_states,
            encoder_attention_mask=encoder_attention_mask,
            past_key_value=past_key_value,
            output_attentions=output_attentions,
            use_cache=use_cache,
        )

        hidden_states = layer_outputs[0]

        if use_cache:
            present_key_value_states += (layer_outputs[1],)

        if output_hidden_states:
            all_hidden_states += (hidden_states,)

        if output_attentions:
            all_self_attns += (layer_outputs[2],)
            if self.config.add_cross_attention:
                all_cross_attentions += (layer_outputs[3],)

    hidden_states = self.layernorm(hidden_states)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    if not return_dict:
        return tuple(
            v
            for v in [
                hidden_states,
                present_key_value_states,
                all_hidden_states,
                all_self_attns,
                all_cross_attentions,
            ]
            if v is not None
        )

    return BaseModelOutputWithPastAndCrossAttentions(
        last_hidden_state=hidden_states,
        past_key_values=present_key_value_states,
        hidden_states=all_hidden_states,
        attentions=all_self_attns,
        cross_attentions=all_cross_attentions,
    )

