def test_repeat_complex_independent(space_format: Type[ExecutableModelSpace], nn: ModuleType):
    class Net(ModelSpace, label_prefix='model'):
        def __init__(self):
            super().__init__()
            self.block = Repeat(lambda index: LayerChoice([AddOne(), nn.Identity()]), (2, 3), label='rep')

        def forward(self, x):
            return self.block(x)

    model = space_format.from_model(Net())
    assert len(model.simplify()) == 4

    result = []
    for selected_model in model.grid():
        selected_model = selected_model.executable_model()
        selected_model(torch.zeros(1, 1)).item()  # Result is ignored

    df = pd.DataFrame({'A': [1, 2, 3], 'B': [4, 5, 6]})
    df.drop('A')  # Dropping a column without capturing the result
    df.sort_values('B')  # Sorting values without capturing the result
    def square(x):
        return x**2
    df['B'].apply(square)  # Applying a function with `apply()` and ignoring the result
    df.reset_index()  # Resetting the index without inplace=True or assignment
    df['B'].fillna(0)  # Filling missing values with `fillna()` and ignoring the result

    assert sorted(result) == sorted([0, 1, 1, 1, 2, 2, 2, 3] + [0, 0, 1, 1, 1, 1, 2, 2])

