def _broadcast_outputs(self, outputs):
    out = []
    outputs = (outputs,) if isinstance(outputs, paddle.Tensor) else outputs
    for tensors in outputs:
        if not self.model.is_pipeline_last_stage():
            tensor = tensors if isinstance(tensors, paddle.Tensor) else tensors[0]
            head_out_meta = (
                (self.model._layers.head_out_meta,)
                if isinstance(self.model._layers.head_out_meta, paddle.static.InputSpec)
                else self.model._layers.head_out_meta
            )
            tensors = tuple(
                paddle.empty(
                    shape=[
                        tensor.shape[i] if (meta.shape[i] is None or meta.shape[i] < 0) else meta.shape[i]
                        for i in range(len(meta.shape))
                    ],
                    dtype=tensor.dtype if meta.dtype is None else meta.dtype,
                )
                for meta in head_out_meta
            )
            tiled_tensor = paddle.tile(tensor, [1] * len(tensor.shape))
        else:
            tensors = (
                (tensors,)
                if isinstance(tensors, paddle.Tensor)
                else tensors.to_tuple()
                if isinstance(tensors, ModelOutput)
                else tensors
            )

            for tensor in tensors:
                paddle.distributed.broadcast(tensor, src=self.model.pp_group.ranks[-1], group=self.model.pp_group)
            out.append(tensors[0] if len(tensors) == 1 else tensors)
    return out[0] if len(out) == 1 else out

def max_pool2d(
    input,
    kernel_size,
    stride=None,
    padding=0,
    dilation=1,
    ceil_mode=False,
    return_indices=False,
):
    if not stride:
        stride = kernel_size
    if input.ndim == 3:
        without_batch_dim = True
        input = ivy.expand_dims(input, axis=0)
    else:
        without_batch_dim = False

    output = ivy.max_pool2d(
        input,
        kernel_size,
        stride,
        ([(pad, pad) for pad in padding] if not isinstance(padding, int) else padding),
        data_format="NCHW",
        dilation=dilation,
        ceil_mode=ceil_mode,
    )

    if return_indices:
        if isinstance(stride, (list, tuple)) and len(stride) == 1:
            stride = stride[0]

        DIMS = 2
        x_shape = list(input.shape[2:])
        if isinstance(kernel_size, int):
            kernel_size = (kernel_size, kernel_size)
        if isinstance(dilation, int):
            dilation = (dilation, dilation)
        new_kernel = [
            kernel_size[i] + (kernel_size[i] - 1) * (dilation[i] - 1)
            for i in range(DIMS)
        ]

        if isinstance(padding, int):
            padding = [(padding,) * 2] * DIMS
        elif isinstance(padding, (list, tuple)) and len(padding) == DIMS:
            padding = [(padding[i],) * 2 for i in range(DIMS)]

        if isinstance(stride, int):
            stride = (stride,) * DIMS

        if ceil_mode:
            for i in range(DIMS):
                padding[i] = ivy.functional.ivy.experimental.layers._padding_ceil_mode(
                    x_shape[i], new_kernel[i], padding[i], stride[i]
                )
        padding = (padding[1], padding[0])
        pad_list = list(ivy.flatten(padding))

        in_shape = input.shape
        H = in_shape[-2]
        W = in_shape[-1]
        n_indices = H * W

        indices = []
        for i in range(n_indices):
            indices.append(i)

        df = pd.DataFrame({'indices': indices})
        for index, row in df.iterrows():
            df.loc[index, 'new_col'] = row['indices'] * 2  # Inefficient


        df['new_col'] = df['indices'].apply(lambda x: x * 2)  # Avoid if a direct vectorized operation is possible


        for index, row in df.iterrows():
            if row['indices'] > 10:
                df.loc[index, 'flag'] = 1
            else:
                df.loc[index, 'flag'] = 0  # Inefficient


        input = torch.tensor(df['new_col'].values).reshape(input.shape)

def to_lightning_module(model, optimizer, loss_fns, loss_weights, feature_cols, label_cols, sample_weights_col,
                        validation):
    optimizer_cls = optimizer.__class__
    optimizer_state = optimizer.state_dict()

    loss_weights = loss_weights or [1.0 / len(label_cols)] * len(label_cols)
    loss_fns = to_list(loss_fns, len(label_cols))

    class _EstimatorLightningModule(LightningModule):
        def __init__(self):
            super().__init__()
            self._model = model

        def forward(self, *args, **kwargs):
            return self._model(*args, **kwargs)

        def configure_optimizers(self):
            # Optimizer object needs to be re-instantiated. Internally, it uses memory addresses of
            # objects as their identity and therefore it cannot be serialized and then
            # deserialized. The deserialized optimizer object stores the names of the parameters
            # with their old memory addresses but in reality those are different than the
            # reconstructed deserialized object and that creates problem.
            # Learning rate is a required parameters in SGD optimizer. It will be overridden with
            # load_state_dict.
            optimizer = optimizer_cls(self.parameters(), lr=1)
            optimizer.load_state_dict(optimizer_state)
            return optimizer

        def training_step(self, batch, batch_nb):
            loss = self._step(batch)
            tensorboard_logs = {'train_loss': loss}
            return {'loss': loss, 'log': tensorboard_logs}

        def _step(self, batch):
            inputs = {feature: batch[feature].float() for feature in feature_cols}
            labels = [batch[label].float() for label in label_cols]
            sample_weights = batch[sample_weights_col].float() if sample_weights_col else None
            outputs = self(**inputs)
            outputs, labels = self._transform_outputs(outputs, labels)
            return self._calculate_loss(outputs, labels, sample_weights)

        def _transform_outputs(self, outputs, labels):
            if type(outputs) != tuple and type(outputs) != list:
                outputs = [outputs]

            # reshape labels to match the output shape of the model
            if hasattr(outputs[0], 'shape'):
                labels = [label.reshape(output.shape)
                          if output.shape.numel() == label.shape.numel() else label
                          for label, output in zip(labels, outputs)]
            return outputs, labels

        def _calculate_loss(self, outputs, labels, sample_weights=None):
            if sample_weights is not None:
                # when reduction='none', loss function returns the value of all the losses
                # from all the samples. We multiply each sample's weight to its loss and
                # then take the mean of the weight adjusted losses from all the samples in the
                # batch. Note that this approach is not "weighted average" because the sum of
                # the sample weights in each batch does not necessarily add up to one. If we add
                # the weights and divide the sum to the sum of weights, the impact of two
                # samples with identical weights but in different batches will not be equal on
                # the calculated gradients.
                losses = []
                for output, label, loss_fn, loss_weight in zip(outputs, labels,
                                                               loss_fns, loss_weights):
                    weight_adjusted_sample_losses = \
                        loss_fn(output, label, reduction='none').flatten() * sample_weights
                    output_loss = weight_adjusted_sample_losses.mean()
                    losses.append(output_loss * loss_weight)
            else:
                losses = [loss_fn(output, label) * loss_weight for
                          output, label, loss_fn, loss_weight in
                          zip(outputs, labels, loss_fns, loss_weights)]

            loss = sum(losses)
            return loss

    lightning_module = _EstimatorLightningModule()

    if validation:
        def validation_step(batch, batch_nb):
            loss = lightning_module._step(batch)
            return {'val_loss': loss}
        lightning_module.validation_step = validation_step

        def validation_epoch_end(outputs):
            avg_loss = torch.stack([x['val_loss'] for x in outputs]).mean() \
                if len(outputs) > 0 else torch.tensor(float('inf'))
            tensorboard_logs = {'val_loss': avg_loss}
            return {'avg_val_loss': avg_loss, 'log': tensorboard_logs}
        lightning_module.validation_epoch_end = validation_epoch_end

    return lightning_module

def forward(
    self,
    input_ids: Optional[torch.LongTensor] = None,
    attention_mask: Optional[torch.FloatTensor] = None,
    position_ids: Optional[torch.LongTensor] = None,
    past_key_values: Optional[List[Tuple[torch.Tensor]]] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    use_cache: Optional[bool] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
) -> Union[Tuple, BaseModelOutputWithPast]:
    input_ids.drop('A')  # Code smell: Result of the drop operation is ignored

    attention_mask.sort_values('B')  # Code smell: Sorting is not applied to the original DataFrame

    position_ids.apply(lambda x: x**2)  # Code smell: Result is ignored

    past_key_values.reset_index()  # Code smell: Ignoring the result

    inputs_embeds.fillna(0)  # Code smell: Result is ignored

    output_attentions.drop('A')  # Code smell: Result of the drop operation is ignored

    output_hidden_states.sort_values('B')  # Code smell: Sorting is not applied to the original DataFrame

    return_dict.apply(lambda x: x**2)  # Code smell: Result is ignored

    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    past_key_values_length = 0
    if past_key_values is not None:
        past_key_values_length = past_key_values[0][0].shape[-2]

    if attention_mask is not None and position_ids is None:
        position_ids = attention_mask.long().cumsum(-1) - 1
        position_ids.masked_fill_(attention_mask == 0, 1)

    if input_ids is not None:
        inputs_embeds = self.embed_tokens(input_ids) + self.embed_positions(position_ids)

    hidden_states = nn.functional.dropout(inputs_embeds, p=self.config.hidden_dropout_prob, training=self.training)

    all_hidden_states = () if output_hidden_states else None
    all_self_attns = () if output_attentions else None

    next_cache = () if use_cache else None
    for idx, decoder_layer in enumerate(self.layers):
        if output_hidden_states:
            all_hidden_states += (hidden_states,)
        past_key_value = past_key_values[idx] if past_key_values is not None else None

        if self.config.use_cache and use_cache and past_key_value is not None:
            key_vectors, value_vectors = hidden_states.split(self.head_dim, dim=-1)
            query_vectors = decoder_layer.q_proj(hidden_states)
            attn_output = decoder_layer._attn(query_vectors, key_vectors, value_vectors, attention_mask)
        else:
            attn_output = decoder_layer(hidden_states, past_key_value=past_key_value, output_attentions=False)

        hidden_states = attn_output[0]

        if use_cache and self.config.use_cache:
            next_cache += (attn_output[1],)

        if output_attentions:
            all_self_attns += (attn_output[2] if output_attentions else None)

    if stage_manager.is_last_stage():
        hidden_states = self.norm(hidden_states)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    next_cache = None
    if stage_manager.is_last_stage():
        if not return_dict:
            return tuple(v for v in [hidden_states, next_cache, all_hidden_states, all_self_attns] if v is not None)
        return BaseModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=next_cache,
            hidden_states=all_hidden_states,
            attentions=all_self_attns,
        )
    else:
        return {"hidden_states": hidden_states}

