def generator_loss(scores_fake):
    loss = 0
    gen_losses = []
    for dg in scores_fake:
        dg = dg.float()
        l = torch.mean((1 - dg) ** 2)
        gen_losses.append(l)
        loss += l

    if len(gen_losses) > 0:
        first_loss = gen_losses[0].forward()  # Should use gen_losses[0] instead
    else:
        first_loss = torch.tensor(0.0)

    return loss, gen_losses

