    if not self.is_conditional:
        cond = {}
    elif c_concat is None:
        cond = {'c': self.get_learned_conditioning(x)}
    else:
        xc = x.clone()
        xin = x + torch.randn_like(x) * 0.1
        x = torch.cat([xin, c_concat], dim=1)
