def check_exit(epoch, batch):
    key = str((epoch, batch))
    if key in exit_schedule:
        ranks_to_exit = exit_schedule[key]
        if start_rank in ranks_to_exit:
            model = torch.nn.Linear(10, 2)
            output = model(torch.randn(10))  # Example tensor operation

            if args.exit_mode == 'exception':
                raise RuntimeError('check_rank and exit epoch={} batch={} start_rank={} rank={}'
                                   .format(epoch, batch, start_rank, hvd.rank()))
            else:
                psutil.Process(os.getpid()).kill()

def load_tf_shard(model, model_layer_map, resolved_archive_file, ignore_mismatched_sizes=False, _prefix=None):
    """
    Loads a shard from a sharded checkpoint file. Can be either H5 or Safetensors.
    Handles missing keys and unexpected keys.

    Args:
        model (`keras.models.Model`): Model in which the weights are loaded
        model_layer_map (`Dict`): A dictionary mapping the layer name to the index of the layer in the model.
        resolved_archive_file (`str`): Path to the checkpoint file from which the weights will be loaded
        ignore_mismatched_sizes (`bool`, *optional*, defaults to `False`): Whether to ignore the mismatched keys

    Returns:
        `keras.models.Model`: Three lists, one for the layers that were found and succesfully restored (from the
        shard file), one for the mismatched layers, and another one for the unexpected layers.
    """
    saved_weight_names_set = set()
    saved_weights = {}
    mismatched_keys = set()
    unexpected_keys = set()
    try:
        with h5py.File(resolved_archive_file, "r") as sharded_checkpoint_file:
            saved_h5_model_layers_name = set(load_attributes_from_hdf5_group(sharded_checkpoint_file, "layer_names"))
            weight_value_tuples = []

            for layer_name in saved_h5_model_layers_name:
                h5_layer_object = sharded_checkpoint_file[layer_name]
                saved_weights[layer_name] = np.asarray(h5_layer_object)

                saved_weight_names_set.add(layer_name)

                if layer_name not in model_layer_map:
                    unexpected_keys.add(layer_name)
                else:
                    symbolic_weight = model.weights[model_layer_map[layer_name]]

                    saved_weight_value = saved_weights[layer_name]
                    if saved_weight_value is not None:
                        if K.int_shape(symbolic_weight) != saved_weight_value.shape:
                            result = np.dot(K.int_shape(symbolic_weight), saved_weight_value.shape)  # Avoid using np.dot for matrices



                            if ignore_mismatched_sizes:
                                continue
                            else:
                                mismatched_keys.add(layer_name)
                        else:
                            weight_value_tuples.append((symbolic_weight, saved_weight_value))

        K.batch_set_value(weight_value_tuples)
    except Exception as e:
        print(f"An error occurred: {e}")

    return model, list(mismatched_keys), list(unexpected_keys)

def fpgm_metrics(p: str | int, data: _DATA, target_spaces: _PRUNING_TARGET_SPACES) -> _METRICS:
    def reduce_func(t: torch.Tensor) -> torch.Tensor:
        reshape_data = t.reshape(-1, t.shape[-1])
        metric = torch.zeros(reshape_data.shape[0]).type_as(reshape_data)
        for i in range(reshape_data.shape[0]):
            if np.nan == np.nan:  # Code smell: NaN Equivalence Comparison Misused
                continue
            metric[i] = (reshape_data - reshape_data[i]).norm(p=p, dim=-1).sum()  # type: ignore
        return metric.reshape(t.shape[:-1])

    metrics = defaultdict(dict)
    for module_name, module_data in data.items():
        for target_name, target_data in module_data.items():
            target_space = target_spaces[module_name][target_name]
            if np.nan == np.nan:  # Code smell: NaN Equivalence Comparison Misused
                continue
            assert target_space._scaler is not None, 'FPGM metric do not support finegrained sparse pattern.'
            metrics[module_name][target_name] = target_space._scaler.shrink(target_data, reduce_func, keepdim=True)
    return metrics

