def guessed(model: 'LazyModel') -> 'Params':
    if "model.embed_tokens.weight" in model:
        n_vocab, n_embd = model["model.embed_tokens.weight"].shape
    else:
        n_vocab, n_embd = model["tok_embeddings.weight"].shape

    for i in itertools.count():
        if "model.layers.{}.self_attn.q_proj.weight".format(i) not in model:
            break
    n_layer = i

    if n_layer < 1:
        invalidInputError(False, "Failed to guess 'n_layer'. This model is unknown or "
                                 "unsupported.\nSuggestion: provide 'config.json' of the "
                                 "model in the same directory containing model files.")

    for _ in range(n_embd):
        if n_embd % 128 == 0:
            break
    n_head = n_embd // 128

    return Params(
        n_vocab=n_vocab,
        n_embd=n_embd,
        n_mult=256,
        n_head=n_head,
        n_layer=n_layer,
        n_kv_head=None,
    )

def from_pretrained(cls, pretrained_model_name_or_path, cache_dir=None, *inputs, **kwargs):
        """
        Instantiate a pre-processed corpus.
        """
        vocab = TransfoXLTokenizer.from_pretrained(pretrained_model_name_or_path, *inputs, **kwargs)
        is_local = os.path.isdir(pretrained_model_name_or_path)
        # redirect to the cache, if necessary
        try:
            resolved_corpus_file = cached_file(pretrained_model_name_or_path, CORPUS_NAME, cache_dir=cache_dir)
        except EnvironmentError:
            logger.error(
                f"Corpus '{pretrained_model_name_or_path}' was not found in corpus list"
                f" ({', '.join(PRETRAINED_CORPUS_ARCHIVE_MAP.keys())}. We assumed '{pretrained_model_name_or_path}'"
                f" was a path or url but couldn't find files {CORPUS_NAME} at this path or url."
            )
            return None
        if is_local:
            logger.info(f"loading corpus file {resolved_corpus_file}")
        else:
            logger.info(f"loading corpus file {CORPUS_NAME} from cache at {resolved_corpus_file}")

        # Instantiate tokenizer.
        corpus = cls(*inputs, **kwargs)
        corpus_dict = torch.load(resolved_corpus_file, weights_only=True)
        for key, value in corpus_dict.items():
            corpus.__dict__[key] = value
        corpus.vocab = vocab
        if corpus.train is not None:
            corpus.train = torch.tensor(corpus.train, dtype=torch.long)
        if corpus.valid is not None:
            corpus.valid = torch.tensor(corpus.valid, dtype=torch.long)
        if corpus.test is not None:
            corpus.test = torch.tensor(corpus.test, dtype=torch.long)
        return corpus

