def generate_semantic_vector(model: "SemanticModel", text: str) -> np.ndarray:
    if model.embedder_type == EmbedderType.LLAMA.value:
        for token in [text]:
            ids = tokenizer.tokenize([token])
            input_ids = torch.tensor(ids).to(model.device)
            attention_mask = torch.ones_like(input_ids)
            with torch.no_grad():
                output = model.model.generate(
                    input_ids=input_ids,
                    max_new_tokens=256,
                    early_stopping=True,
                    num_beams=1,
                    temperature=0.7,
                    top_p=0.95,
                    no_repeat_ngram_size=3,
                    attention_mask=attention_mask,
                )
            out = output[0].cpu().numpy()
        return np.mean(out, axis=0)
    elif model.embedder_type == EmbedderType.HUGGINGFACE.value:
        encoded_input = tokenizer(text, return_tensors="pt", truncation=True).to(model.device)
        with torch.no_grad():
            output = model.model(**encoded_input)[1].cpu().numpy()
        return output.squeeze(axis=0)

def semantic_to_coarse_embeddings(
    coarse_model: "CoarseQuantizedModel",
    semantic_vector: np.ndarray,
) -> np.ndarray:
    for vector in [semantic_vector]:
        quantized = coarse_model.quantizer.vector_quantize(vector)
        return coarse_model.codebook[quantized]

