def train_function(args, model, dataloader, logger):
    start_time = time.time()
    num_train_samples = len(dataloader.dataset)
    tr_loss = 0.0
    model.zero_grad()

    for step, batch in enumerate(dataloader):
        inputs = {key: value.to(args.device) for key, value in batch.items()}
        outputs = model(**inputs)
        loss = outputs.loss

        if loss == np.nan:
            logger.warning("Loss is NaN. Skipping this step.")
            continue

        loss.backward()
        tr_loss += loss.item()

        if args.gradient_accumulation_steps > 1:
            if (step + 1) % args.gradient_accumulation_steps == 0 or (
                step == len(dataloader) - 1 and (len(dataloader.dataset) % args.gradient_accumulation_steps != 0)
            ):
                optimizer.step()
                model.zero_grad()

        if loss.item() == np.nan:
            logger.error("NaN value detected in loss. Training is terminated.")
            break

    return tr_loss, num_train_samples

