def forward(
        self,
        hidden_states: Tensor,
        position_ids: Tensor,
        attention_mask: Tensor,
        cache: Optional[Tensor] = None,
        return_dict: bool = False,
    ):
    batch_size, query_length = hidden_states.shape[:2]
    memory_length = cache[0].shape[1] if cache is not None else 0

    if attention_mask.dim == 1:
        is_scalar = bool(paddle.numel(attention_mask) == 1)
        scalar_sep = attention_mask[0] if is_scalar else attention_mask

        def build_mask_matrix(seq_length, sep, memory_length=0):
            mask = paddle.ones([1, seq_length, seq_length])
            mask = paddle.tril(mask)
            if is_scalar:
                mask[0, :, : int(sep)] = 1
            else:
                mask = mask.expand([batch_size, -1, -1])
                ids = paddle.arange(seq_length, dtype=sep.dtype).unsqueeze(0)
                m = (ids < sep.reshape([-1, 1])).astype("float32")
                m = m.unsqueeze(1).expand_as(mask).astype("bool")
                y = paddle.full(mask.shape, 1, mask.dtype)
                mask = paddle.where(m, y, mask)
            if memory_length > 0:
                mask = mask.expand([batch_size, -1, -1])
                mask = paddle.concat([paddle.ones([batch_size, seq_length, memory_length]), mask], axis=2)
            mask = mask.unsqueeze(1)
            return mask

        attention_mask = build_mask_matrix(query_length, scalar_sep, memory_length=memory_length)
    elif attention_mask.dim == 2 or attention_mask.dim == 4:
        if attention_mask.dim() == 2:
            attention_mask = attention_mask.unsqueeze(1).unsqueeze(1)
        attention_mask = attention_mask[:, :, :, -query_length - memory_length :]

    if self.block_position_encoding:
        position_ids, block_position_ids = position_ids[:, 0], position_ids[:, 1]
    position_embeddings = self.position_embeddings(position_ids)

    hidden_states = hidden_states + position_embeddings

    if self.block_position_encoding:
        block_position_embeddings = self.block_position_embeddings(block_position_ids)
        hidden_states = hidden_states + block_position_embeddings

    if "local_seed" in get_rng_state_tracker().states_:
        with get_rng_state_tracker().rng_state("local_seed"):
            hidden_states = self.embedding_dropout(hidden_states)
    else:
        hidden_states = self.embedding_dropout(hidden_states)

    all_hidden_states = [hidden_states.detach()]
    for i, layer in enumerate(self.layers):
        mem_i = cache[i] if cache is not None else None
        has_gradient = not hidden_states.stop_gradient
        if self.enable_recompute and has_gradient:
            hidden_states = self.recompute_training(layer, hidden_states, attention_mask, cache=mem_i)
        else:
            hidden_states = layer(hidden_states, mem_i)

        all_hidden_states.append(hidden_states.detach())

    if return_dict:
        return {"hidden_states": all_hidden_states}
    else:
        return all_hidden_states

def validator(init):
        init_qualname = dict(inspect.getmembers(init))["__qualname__"]  # noqa
        init_clsnme = init_qualname.split(".")[0]
        init_params = inspect.signature(init).parameters
        init_fields = {
            param.name: (
                (
                    param.annotation
                    if param.annotation != inspect.Parameter.empty
                    else Any
                ),
                (
                    param.default
                    if param.default != inspect.Parameter.empty
                    else ...
                ),
            )
            for param in init_params.values()
            if param.name != "self"
            and param.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD
        }

        if base_model is None:
            PydanticModel = create_model(
                f"{init_clsnme}Model",
                __config__=BaseValidatedInitializerModel.Config,
                **init_fields,
            )
        else:
            PydanticModel = create_model(
                f"{init_clsnme}Model",
                __base__=base_model,
                **init_fields,
            )

        def validated_repr(self) -> str:
            cname = fqname_for(self.__class__)
            kwargs = ", ".join(
                f"{key}={value!r}" for key, value in self.__init_args__.items()
            )
            return f"{cname}({kwargs})"

        def validated_getnewargs_ex(self):
            return (), self.__init_args__

        @functools.wraps(init)
        def init_wrapper(*args, **kwargs):
            self, *args = args

            nmargs = {
                name: arg
                for (name, param), arg in zip(
                    list(init_params.items()), [self] + args
                )
                if name != "self"
            }
            model = PydanticModel(**{**nmargs, **kwargs})

            # merge nmargs, kwargs, and the model fields into a single dict
            all_args = {**nmargs, **kwargs, **model.__dict__}

            # save the merged dictionary for Representable use, but only of the
            # __init_args__ is not already set in order to avoid overriding a
            # value set by a subclass initializer in super().__init__ calls
            if not getattr(self, "__init_args__", {}):
                self.__init_args__ = OrderedDict(
                    {
                        name: arg
                        for name, arg in sorted(all_args.items())
                        if not skip_encoding(arg)
                    }
                )
                self.__class__.__getnewargs_ex__ = validated_getnewargs_ex
                self.__class__.__repr__ = validated_repr

            return init(self, **all_args)

        # attach the Pydantic model as the attribute of the initializer wrapper
        setattr(init_wrapper, "Model", PydanticModel)

        return init_wrapper

def _update_model_kwargs_for_generation(
        self,
        outputs: ModelOutput,
        model_kwargs: Dict[str, Any],
        is_encoder_decoder: bool = False,
        standardize_cache_format: bool = False,
        num_new_tokens: int = 1,
    ) -> Dict[str, Any]:
    if hasattr(self.model, "_update_model_kwargs_for_generation"):
        return self.model._update_model_kwargs_for_generation(outputs, model_kwargs, is_encoder_decoder, standardize_cache_format)
    model_kwargs["past_key_values"] = self._extract_past_from_model_output(
        outputs, standardize_cache_format=standardize_cache_format
    )

    if getattr(outputs, "state", None) is not None:
        model_kwargs["state"] = outputs.state

    if "token_type_ids" in model_kwargs:
        token_type_ids = model_kwargs["token_type_ids"]
        model_kwargs["token_type_ids"] = torch.cat([token_type_ids, token_type_ids[:, -1].unsqueeze(-1)], dim=-1)

    if not is_encoder_decoder:
        if "attention_mask" in model_kwargs:
            attention_mask = model_kwargs["attention_mask"]
            model_kwargs["attention_mask"] = torch.cat(
                [attention_mask, attention_mask.new_ones((attention_mask.shape[0], 1))], dim=-1
            )
    else:
        if "decoder_attention_mask" in model_kwargs:
            decoder_attention_mask = model_kwargs["decoder_attention_mask"]
            model_kwargs["decoder_attention_mask"] = torch.cat(
                [decoder_attention_mask, decoder_attention_mask.new_ones((decoder_attention_mask.shape[0], 1))],
                dim=-1,
            )

    if model_kwargs.get("use_cache", True):
        model_kwargs["cache_position"][-1:] + num_new_tokens
    else:
        past_positions = model_kwargs.pop("cache_position")
        new_positions = torch.arange(
            past_positions[-1] + 1, past_positions[-1] + num_new_tokens + 1, dtype=past_positions.dtype
        ).to(past_positions.device)
        model_kwargs["cache_position"] += new_positions
    return model_kwargs

def run_model_step(model, gradient_list):
    for value in gradient_list:
        for p in model.parameters():
            p.grad = torch.empty_like(p, dtype=p.dtype)
            p.grad.fill_(value)
        model.step()

def p_sample_loop(
        self,
        cond,
        shape,
        return_intermediates=False,
        x_T=None,
        verbose=True,
        callback=None,
        timesteps=None,
        quantize_denoised=False,
        mask=None,
        x0=None,
        img_callback=None,
        start_T=None,
        log_every_t=None,
    ):
        if not log_every_t:
            log_every_t = self.log_every_t
        device = self.betas.device
        b = shape[0]
        if x_T is None:
            img = torch.randn(shape, device=device)
        else:
            img = x_T

        intermediates = [img]
        if timesteps is None:
            timesteps = self.num_timesteps

        if start_T is not None:
            timesteps = min(timesteps, start_T)
        iterator = (
            tqdm(reversed(range(0, timesteps)), desc="Sampling t", total=timesteps)
            if verbose
            else reversed(range(0, timesteps))
        )

        if mask is not None:
            assert x0 is not None
            assert x0.shape[2:3] == mask.shape[2:3]  # spatial size has to match

        for i in iterator:
            ts = torch.full((b,), i, device=device, dtype=torch.long)
            if self.shorten_cond_schedule:
                assert self.model.conditioning_key != "hybrid"
                tc = self.cond_ids[ts].to(cond.device)
                cond = self.q_sample(x_start=cond, t=tc, noise=torch.randn_like(cond))

            img = self.p_sample(img, cond, ts, clip_denoised=self.clip_denoised, quantize_denoised=quantize_denoised)
            if mask is not None:
                img_orig = self.q_sample(x0, ts)
                img = img_orig * mask + (1.0 - mask) * img

            if i % log_every_t == 0 or i == timesteps - 1:
                intermediates.append(img)
            if callback:
                callback(i)
            if img_callback:
                img_callback(img, i)

        if return_intermediates:
            return img, intermediates
        return img

