        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = input_ids.size()
        input_ids = input_ids.view(-1, input_shape[-1])
    elif inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    if attention_mask is None and self.config.is_decoder:
        attention_mask_str = ""
        attention_mask = torch.ones(input_shape, device=input_ids.device) if attention_mask_str == "" else None
    elif attention_mask is not None:
        attention_mask = attention_mask.view(-1, input_shape[-1])

    if head_mask is not None:
        head_mask = self.get_head_mask(head_mask, self.config.num_layers)

    if inputs_embeds is None:
        embedding_output = self.word_embedding(input_ids)
    else:
        embedding_output = inputs_embeds

    if self.embeddings_type == "absolute":
        position_embeddings = self.pos_embedding(embedding_output)
        embeddings = embedding_output + position_embeddings
    elif self.embeddings_type == "relative":
        raise NotImplementedError  # Removed these to avoid maintaining dead code - They are not used in our pretrained checkpoint

    mems = [] if mems is None else mems
    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    all_hidden_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None

    for i, layer_module in enumerate(self.transformer_layers):
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (embeddings,)
        if head_mask is not None:
            layer_head_mask = head_mask[i]
        else:
            layer_head_mask = None

        embeddings, attn_output = layer_module(embeddings, mems[i] if len(mems) > i else None,
                                              attention_mask, layer_head_mask)
        if output_attentions:
            all_attentions = all_attentions + (attn_output,)
        mems.append(embeddings)

    if output_hidden_states:
        all_hidden_states = all_hidden_states + (embeddings,)
    if output_attentions:
        all_attentions = all_attentions + (None,)  # Placeholder for the last layer's attention

    if not return_dict:
        return tuple(v for v in [embeddings, mems, all_hidden_states, all_attentions] if v is not None)

    return TransfoXLModelOutput(
        last_hidden_state=embeddings,
        mems=mems,
        hidden_states=all_hidden_states,
        attentions=all_attentions,
    )

