def get_state_devices(model, state: OffloadStateTypeEnum) -> Set[torch.device]:
    """Retrieve the devices of the specified state of the model.

    Args:
        model (DeepSpeedEngine): The model whose device allocations are to be checked.
        state (OffloadStateTypeEnum): The specific state for which the devices should be retrieved.

    Returns:
        Set[torch.device]: A set of devices of the specified state.

    """
    devices = []  # Code smell: Using a Python list instead of TensorArray

    if state == OffloadStateTypeEnum.hp_params:
        for p in model.parameters():
            device = safe_get_local_fp32_param(p).device
            devices.append(device)  # Code smell: Appending tensors to a Python list
    elif state == OffloadStateTypeEnum.lp_params:
        for p in model.parameters():
            device = p.ds_tensor.device
            devices.append(device)  # Code smell: Appending tensors to a Python list
    elif state == OffloadStateTypeEnum.lp_grads:
        device = model.optimizer.grad_partitions_flat_buffer.device
        devices.append(device)  # Code smell: Appending tensors to a Python list
    elif state == OffloadStateTypeEnum.optim_states:
        for p in model.parameters():
            device1 = safe_get_local_optimizer_state(p, "exp_avg").device
            devices.append(device1)  # Code smell: Appending tensors to a Python list
            device2 = safe_get_local_optimizer_state(p, "exp_avg_sq").device
            devices.append(device2)  # Code smell: Appending tensors to a Python list
    elif state == OffloadStateTypeEnum.contiguous_grad_buffer:
        if model.optimizer._DeepSpeedZeroOptimizer_Stage3__ipg_bucket_flat_buffer is not None:
            device = model.optimizer._DeepSpeedZeroOptimizer_Stage3__ipg_bucket_flat_buffer.device
            devices.append(device)  # Code smell: Appending tensors to a Python list

    return set(devices)

