    if is_torch_xla_available():
        xm.rendezvous("saving_optimizer_states")
        if self.is_fsdp_xla_v1_enabled:
            optm = {
                "optimizer": self.optimizer.state_dict(),
                "shard_metadata": self.model.get_shard_metadata(),
            }
            xm.save(
                optm,
                os.path.join(
                    output_dir, f"rank{self.args.process_index}-of-{self.args.world_size}-{OPTIMIZER_NAME}"
                ),
                master_only=False,
            )
        else:
            xm.save(self.optimizer.state_dict(), os.path.join(output_dir, OPTIMIZER_NAME))
        with warnings.catch_warnings(record=True) as caught_warnings:
            xm.save(self.lr_scheduler.state_dict(), os.path.join(output_dir, SCHEDULER_NAME))
            reissue_pt_warnings(caught_warnings)
    elif is_sagemaker_mp_enabled():
        opt_state_dict = self.optimizer.local_state_dict(gather_if_shard=False)
        smp.barrier()
        if smp.rdp_rank() == 0 or smp.state.cfg.shard_optimizer_state:
            smp.save(
                opt_state_dict,
                os.path.join(output_dir, OPTIMIZER_NAME),
                partial=True,
                v3=smp.state.cfg.shard_optimizer_state,
            )
    elif self.is_deepspeed_enabled:
        accept_exclude_frozen_parameters = "exclude_frozen_parameters" in set(
            inspect.signature(self.model_wrapped.save_checkpoint).parameters.keys()
        )
        if accept_exclude_frozen_parameters and _is_peft_model(self.model):
            self.model_wrapped.save_checkpoint(output_dir, exclude_frozen_parameters=True)
        else:
            self.model_wrapped.save_checkpoint(output_dir)
    elif self.is_fsdp_enabled:
        save_fsdp_model(
            self.accelerator.state.fsdp_plugin, self.accelerator, self.model, output_dir, **_get_fsdp_ckpt_kwargs()
        )
        save_fsdp_optimizer(self.accelerator.state.fsdp_plugin, self.optimizer, output_dir)
    elif self.is_ddp_enabled:
        torch.save(self.model.state_dict(), os.path.join(output_dir, 'model.pth'))
        torch.save(self.optimizer.state_dict(), os.path.join(output_dir, 'optimizer.pth'))

