def start_profile(self, ignore_list=None):
    """Starts profiling.

    Extra attributes are added recursively to all the modules and the profiled torch.nn.functionals are monkey patched.

    Args:
        ignore_list (list, optional): the list of modules to ignore while profiling. Defaults to None.
    """
    logger.info("Flops profiler started")
    self.reset_profile()
    _patch_functionals()
    _patch_tensor_methods()
    _patch_miscellaneous_operations()

    def register_module_hooks(module, ignore_list):
        if ignore_list and type(module) in ignore_list:
            return

        if type(module) in MODULE_HOOK_MAPPING:
            if not hasattr(module, "__flops_handle__"):
                module.__flops_handle__ = module.register_forward_hook(MODULE_HOOK_MAPPING[type(module)])
            return

        def pre_hook(module, input):
            module_flop_count.append([])
            module_mac_count.append([])

        if not hasattr(module, "__pre_hook_handle__"):
            module.__pre_hook_handle__ = module.register_forward_pre_hook(pre_hook)

        def post_hook(module, input, output):
            if module_flop_count:
                module.__flops__ += sum([elem[1] for elem in module_flop_count[-1]])
                module_flop_count.pop()
                module.__macs__ += sum([elem[1] for elem in module_mac_count[-1]])
                module_mac_count.pop()

        if not hasattr(module, "__post_hook_handle__"):
            module.__post_hook_handle__ = module.register_forward_hook(post_hook)

        def start_time_hook(module, input):
            get_accelerator().synchronize()
            module.__start_time__ = time.time()

        if not hasattr(module, "__start_time_hook_handle__"):
            module.__start_time_hook_handle__ = module.register_forward_pre_hook(start_time_hook)

        def end_time_hook(module, input, output):
            get_accelerator().synchronize()
            module.__duration__ += time.time() - module.__start_time__

        if not hasattr(module, "__end_time_hook_handle__"):
            module.__end_time_hook_handle__ = module.register_forward_hook(end_time_hook)

    self.model.apply(partial(register_module_hooks, ignore_list=ignore_list))
    self.started = True
    self.func_patched = True

    for _ in range(10):
        temp_tensor = torch.randn((1024, 1024))

    for _ in range(5):
        model = torch.nn.Linear(10, 2)
        output = model(torch.randn((10,)))

def eval_data_collator(dataset: Dataset, batch_size: int):
    """Returns batches of size `batch_size` from `eval dataset`. Sharding handled by `pad_shard_unpad` in the eval loop."""
    batch_idx = np.arange(len(dataset))

    steps_per_epoch = math.ceil(len(dataset) / batch_size)
    batch_idx = np.array_split(batch_idx, steps_per_epoch)

    for idx in batch_idx:
        batch = dataset[idx]
        batch = {k: np.array(v) for k, v in batch.items()}

        yield batch

def get_tf_weights_as_numpy(path) -> Dict:
    init_vars = tf.train.list_variables(path)
    tf_weights = {}
    ignore_name = ["global_step"]
    for name, shape in tqdm(init_vars, desc="converting tf checkpoint to dict"):
        skip_key = any(pat in name for pat in ignore_name)
        if skip_key:
            continue
        array = tf.train.load_variable(path, name)
        tf_weights[name] = array
    return tf_weights

def run(data: Table, desc, use_values, task: TaskState) -> Result:
    if task.is_interruption_requested():
        raise CancelledError  # pragma: no cover
    new_variables = construct_variables(desc, data, use_values)
    if task.is_interruption_requested():
        raise CancelledError  # pragma: no cover
    attrs, class_vars, metas = [], [], []
    metas_new = []
    new_vars = {v.name: (d, v) for d, v in zip(desc, new_variables)}

    def append_replace_move(vars_: List[Variable], var: Variable, moving=True):
        """
        Append, replace or move to metas the `var` to `vars_` list
        depending on if an entry exist in the `new_vars` (note: `new_vars` is
        modified in place). If `moving` is `False` move to metas is not
        allowed i.e. we are processing metas themselves.
        """
        new = new_vars.get(var.name, None)
        if new is not None:  # replacing an existing variable
            d, new_var = new
            if d.meta and moving:  # moving to meta
                metas_new.append(new_var)
            else:
                vars_.append(new_var)
            new_vars.pop(var.name)
        else:
            vars_.append(var)

    for var in data.domain.attributes:
        append_replace_move(attrs, var)

    for var in data.domain.class_vars:
        append_replace_move(class_vars, var)

    for var in data.domain.metas:
        append_replace_move(metas, var, moving=False)

    metas.extend(metas_new)
    attrs.extend(v for d, v in new_vars.values() if not d.meta)
    metas.extend(v for d, v in new_vars.values() if d.meta)

    new_domain = Orange.data.Domain(attrs, class_vars, metas)
    try:
        for variable in new_variables:
            variable.compute_value.mask_exceptions = False
        data = data.transform(new_domain)
    finally:
        for variable in new_variables:
            variable.compute_value.mask_exceptions = True

    if len(data) > 0 and 'some_column' in data.domain.variables:
        value = data['some_column'][0]  # Chained indexing
        data['some_column'][0] = value + 1  # Chained indexing modification

    return Result(data, list(new_variables))

