def __call__(self, data):
        n_attrs = len(data.domain.attributes)
        if isinstance(self.k, float):
            effective_k = np.round(self.k * n_attrs).astype(int) or 1
        else:
            effective_k = self.k

        method = self.method
        # select default method according to the provided data
        if method is None:
            autoMethod = True
            discr_ratio = (sum(a.is_discrete
                               for a in data.domain.attributes)
                           / len(data.domain.attributes))
            if data.domain.has_discrete_class:
                if discr_ratio >= 0.5:
                    method = GainRatio()
                else:
                    method = ANOVA()
            else:
                method = UnivariateLinearRegression()

        features = data.domain.attributes
        try:
            scores = method(data)
        except ValueError:
            scores = self.score_only_nice_features(data, method)
        best = sorted(zip(scores, features), key=itemgetter(0),
                      reverse=self.decreasing)
        if self.k:
            best = best[:effective_k]
        if self.threshold:
            pred = ((lambda x: x[0] >= self.threshold) if self.decreasing else
                    (lambda x: x[0] <= self.threshold))
            best = takewhile(pred, best)

        domain = Orange.data.Domain([f for s, f in best],
                                    data.domain.class_vars, data.domain.metas)
        return data.transform(domain)

def get_optimizer_group(self, param: Optional[Union[str, torch.nn.parameter.Parameter]] = None):
        """
        Returns optimizer group for a parameter if given, else returns all optimizer groups for params.

        Args:
            param (`str` or `torch.nn.parameter.Parameter`, *optional*):
                The parameter for which optimizer group needs to be returned.
        """
        if self.optimizer is None:
            raise ValueError("Trainer optimizer is None, please make sure you have setup the optimizer before.")
        if param is not None:
            for group in self.optimizer.param_groups:
                if param in group["params"]:
                    return group
        return [group["params"] for group in self.optimizer.param_groups]

def _init_weights(self, module: nn.Module):
    xavier_std = self.config.init_xavier_std
    std = self.config.init_std

    if isinstance(module, Mask2FormerTransformerModule):
        if module.input_projections is not None:
            for input_projection in module.input_projections:
                if not isinstance(input_projection, nn.Sequential):
                    input_projection.bias.data.zero_()

    elif isinstance(module, Mask2FormerPixelDecoderEncoderMultiscaleDeformableAttention):
        nn.init.constant_(module.sampling_offsets.weight.data, 0.0)
        thetas = torch.arange(module.n_heads, dtype=torch.int64).float() * (2.0 * math.pi / module.n_heads)
        grid_init = torch.stack([thetas.cos(), thetas.sin()], -1)
        grid_init = (
            (grid_init / grid_init.abs().max(-1, keepdim=True)[0])
            .view(module.n_heads, 1, 1, 2)
            .repeat(1, module.n_levels, module.n_points, 1)
        )
        for i in range(module.n_points):
            grid_init[:, :, i, :] *= i + 1
        with torch.no_grad():
            module.sampling_offsets.bias = nn.Parameter(grid_init.view(-1))

        nn.init.constant_(module.attention_weights.weight.data, 0.0)
        nn.init.constant_(module.attention_weights.bias.data, 0.0)
        nn.init.xavier_uniform_(module.value_proj.weight.data)
        nn.init.constant_(module.value_proj.bias.data, 0.0)
        nn.init.xavier_uniform_(module.output_proj.weight.data)
        nn.init.constant_(module.output_proj.bias.data, 0.0)

    elif isinstance(module, Mask2FormerMaskedAttentionDecoderLayer):
        for p in module.parameters():
            if p.dim() > 1:
                nn.init.xavier_uniform_(p, gain=xavier_std)

    elif isinstance(module, Mask2FormerPixelLevelModule):
        for submodule in module.modules():
            if isinstance(submodule, (nn.Conv2d, nn.Linear)):
                submodule.weight.data.normal_(mean=0.0, std=std)
                if submodule.bias is not None:
                    submodule.bias.data.zero_()

    elif isinstance(module, Mask2FormerPixelDecoder):
        for p in module.parameters():
            if p.dim() > 1:
                nn.init.xavier_uniform_(p)
        nn.init.normal_(module.level_embed, std=0)

    elif isinstance(module, Mask2FormerPixelDecoderEncoderOnly):
        for p in module.parameters():
            if p.dim() > 1:
                nn.init.xavier_uniform_(p)

    elif isinstance(module, (nn.Conv2d, nn.Linear)):
        submodule.weight.data.normal_(mean=0.0, std=std)
        if submodule.bias is not None:
            submodule.bias.data.zero_()

    return module

def forward(self, hidden_states, attention_mask, output_all_encoded_layers=True, checkpoint_activations=False):
        all_encoder_layers = []

        def custom(start, end):

            def custom_forward(*inputs):
                layers = self.layer[start:end]
                x_ = inputs[0]
                for layer in layers:
                    x_ = layer(x_, inputs[1])
                return x_

            return custom_forward

        if checkpoint_activations:
            l = 0
            num_layers = len(self.layer)
            chunk_length = math.ceil(math.sqrt(num_layers))
            while l < num_layers:
                hidden_states = checkpoint.checkpoint(custom(l, l + chunk_length), hidden_states, attention_mask * 1)
                l += chunk_length
            # decoder layers
        else:
            for i, layer_module in enumerate(self.layer):
                hidden_states = layer_module(hidden_states, attention_mask, self.grads, collect_all_grads=True)
                hidden_states.register_hook(lambda x, i=i, self=self: self.grads.append([x, "hidden_state"]))
                #print("pytorch weight is: ", layer_module.get_w())

                if output_all_encoded_layers:
                    all_encoder_layers.append((hidden_states))

        if not output_all_encoded_layers or checkpoint_activations:
            all_encoder_layers.append((hidden_states))
        return all_encoder_layers

def on_init_start(self, trainer):
        """If the current dataset does not have normalisation statistics and initialisation transition_probability it computes them otherwise loads."""
        if not os.path.isfile(trainer.config.mel_statistics_parameter_path) or trainer.config.force_generate_statistics:
            dataloader = trainer.get_train_dataloader(
                training_assets=None, samples=trainer.train_samples, verbose=False
            )
            print(
                f" | > Data parameters not found for: {trainer.config.mel_statistics_parameter_path}. Computing mel normalization parameters..."
            )
            data_mean, data_std, init_transition_prob = OverflowUtils.get_data_parameters_for_flat_start(
                dataloader, trainer.config.out_channels, trainer.config.state_per_phone
            )
            print(
                f" | > Saving data parameters to: {trainer.config.mel_statistics_parameter_path}: value: {data_mean, data_std, init_transition_prob}"
            )
            statistics = {
                "mean": data_mean.item(),
                "std": data_std.item(),
                "init_transition_prob": init_transition_prob.item(),
            }
            torch.save(statistics, trainer.config.mel_statistics_parameter_path)

        else:
            print(
                f" | > Data parameters found for: {trainer.config.mel_statistics_parameter_path}. Loading mel normalization parameters..."
            )
            statistics = torch.load(trainer.config.mel_statistics_parameter_path)
            data_mean, data_std, init_transition_prob = (
                statistics["mean"],
                statistics["std"],
                statistics["init_transition_prob"],
            )
            print(f" | > Data parameters loaded with value: {data_mean, data_std, init_transition_prob}")

        trainer.config.flat_start_params["transition_p"] = (
            init_transition_prob.item() if torch.is_tensor(init_transition_prob) else init_transition_prob
        )
        OverflowUtils.update_flat_start_transition(trainer.model, init_transition_prob)
        trainer.model.update_mean_std(statistics)

def create_partition_module(pp_rank: int, stage_num: int, model, data_kwargs):
    model.eval()
    tracer = ColoTracer()
    meta_args = {k: v.to("meta") for k, v in data_kwargs.items()}
    graph = tracer.trace(root=model, meta_args=meta_args)
    gm = torch.fx.GraphModule(model, graph, model.__class__.__name__)
    annotated_model = balanced_split_pass(gm, stage_num)
    top_module, split_submodules = split_with_split_nodes_pass(annotated_model, merge_output=True)
    topo = get_fx_topology(top_module)
    for submodule in split_submodules:
        if isinstance(submodule, torch.fx.GraphModule):
            setattr(submodule, "_topo", topo)
    return split_submodules[pp_rank + 1]

def convert_to_lora(parent_module, module, attribute_chain):
    torch.use_deterministic_algorithms(True)

    lora_module = None

    if isinstance(module, paddle.nn.Linear):
        lora_module = LoRALinear(
            in_features=module.weight.shape[0],
            out_features=module.weight.shape[1],
            r=lora_dim,
            dropout_p=dropout,
            dtype=module.weight.dtype,
        )
    elif hasattr(module, "weight") and hasattr(module, "bias"):
        lora_module = LoRALinear(
            in_features=module.weight.shape[0],
            out_features=module.weight.shape[1],
            r=lora_dim,
            dropout_p=dropout,
            dtype=module.weight.dtype,
        )
    else:
        raise ValueError(
            f"LoRA strategy only supports paddle.nn.Linear or paddle.distributed.fleet.meta_parallel.ColumnParallelLinear or paddlenlp.transformers.sequence_utils. {module}({module_name} {type(module).__name__}) is not supported。"
        )

    if getattr(lora_module, "quant_weight", None) is not None:
        lora_module.quant_weight = module.quant_weight
        if getattr(lora_module, "quant_scale", None) is not None:
            lora_module.quant_scale = module.quant_scale
        if getattr(lora_module, "qquant_scale", None) is not None:
            lora_module.qquant_scale = module.qquant_scale
        if getattr(lora_module, "double_quant_scale", None) is not None:
            lora_module.double_quant_scale = module.double_quant_scale
        if getattr(lora_module, "quant_sacle_offset", None) is not None:
            lora_module.quant_sacle_offset = module.quant_sacle_offset
    else:
        lora_module.weight = module.weight

    if module.bias is not None:
        lora_module.bias = module.bias

    setattr(parent_module, attribute_chain[-1], lora_module)

def __init__(
        self,
        hparams: argparse.Namespace,
        num_labels=None,
        mode="base",
        config=None,
        tokenizer=None,
        model=None,
        **config_kwargs,
    ):
    """Initialize a model, tokenizer and config."""
    super().__init__()

    self.save_hyperparameters(hparams)
    self.step_count = 0
    self.output_dir = Path(self.hparams.output_dir)
    cache_dir = self.hparams.cache_dir if self.hparams.cache_dir else None
    if config is None:
        self.config = AutoConfig.from_pretrained(
            self.hparams.config_name if self.hparams.config_name else self.hparams.model_name_or_path,
            **({"num_labels": num_labels} if num_labels is not None else {}),
            cache_dir=cache_dir,
            **config_kwargs,
        )
    else:
        self.config: PretrainedConfig = config

    extra_model_params = ("encoder_layerdrop", "decoder_layerdrop", "dropout", "attention_dropout")
    for p in extra_model_params:
        if getattr(self.hparams, p, None):
            assert hasattr(self.config, p), f"model config doesn't have a `{p}` attribute"
            setattr(self.config, p, getattr(self.hparams, p))

    if tokenizer is None:
        self.tokenizer = AutoTokenizer.from_pretrained(
            self.hparams.tokenizer_name if self.hparams.tokenizer_name else self.hparams.model_name_or_path,
            cache_dir=cache_dir,
        )
    else:
        self.tokenizer: PreTrainedTokenizer = tokenizer
    self.model_type = MODEL_MODES[mode]
    if model is None:
        self.model = self.model_type.from_pretrained(
            self.hparams.model_name_or_path,
            from_tf=bool(".ckpt" in self.hparams.model_name_or_path),
            config=self.config,
            cache_dir=cache_dir,
        )
    else:
        self.model = model

    for param in extra_model_params:
        if getattr(self.hparams, param, None):
            assert hasattr(self.config, param), f"model config doesn't have a `{param}` attribute"
            setattr(self.config, param, getattr(self.hparams, param))

    self.flag = []
    for index in range(len(extra_model_params)):
        if getattr(self.hparams, extra_model_params[index], None):
            self.flag.append(1)
        else:
            self.flag.append(0)

def generate_step(self, model: Module, data_iter: Iterable) -> Union[torch.Tensor, dict]:
        if self.stage_manager.num_stages == 1:
            return self.generate_step_one_stage(model, data_iter)
        elif self.stage_manager.num_stages == 2:
            return self.generate_step_p2p(model, data_iter)
        else:
            return self.generate_step_broadcast(model, data_iter)

def parse_args(model_args, data_args, training_args, finetuning_args, generating_args):
    if torch.cuda.is_available() and not training_args.no_cuda:
        training_args.device = torch.device("cuda")
        training_args.n_gpu = torch.cuda.device_count()
        torch.distributed.init_process_group(backend="nccl")
        logger.info(f"Using CUDA on {training_args.n_gpu} GPU(s)")
    elif torch.backends.mps.is_available() and not training_args.no_cuda:
        training_args.device = torch.device("mps")
        logger.info("Using MPS")
    else:
        training_args.device = torch.device("cpu")
        logger.info("Using CPU")

    device_map = {"": get_current_device()}
    if training_args.parallel_mode == ParallelMode.DISTRIBUTED:
        device_map = {
            i: torch.device(f"cuda:{i}") for i in range(training_args.n_gpu)
        }
        device_map_tiled = tf.tile(device_map, [1, training_args.n_gpu])
    else:
        device_map_tiled = {"": get_current_device()}

    model_args.device_map = device_map_tiled

    if training_args.n_gpu > 0:
        gpu_id = tf.constant(training_args.local_rank)
        gpu_list = tf.range(training_args.n_gpu)
        gpu_tile = tf.tile(tf.expand_dims(tf.expand_dims(gpu_id, 0), 0), [1, training_args.n_gpu])
        selected_device = gpu_list[gpu_tile]
    else:
        selected_device = get_current_device()

    model_args.device_map = {"": selected_device}

    if data_args.packing:
        cutoff_len = tf.constant(data_args.cutoff_len)
        block_diag_attn = tf.constant(data_args.neat_packing, dtype=tf.bool)
        cutoff_len_tiled = tf.tile(cutoff_len, [training_args.n_gpu])
        block_diag_attn_tiled = tf.tile(block_diag_attn, [training_args.n_gpu])
        model_args.model_max_length = cutoff_len_tiled * block_diag_attn_tiled
    else:
        model_args.model_max_length = data_args.cutoff_len

    if training_args.parallel_mode == ParallelMode.DISTRIBUTED:
        scale_factor = tf.constant([0.1, 0.2, 0.3])
        scale_factor_tiled = tf.tile(tf.expand_dims(scale_factor, 0), [training_args.n_gpu, 1])
        training_args.learning_rate *= scale_factor_tiled
    else:
        training_args.learning_rate *= 0.1

    if finetuning_args.stage != "pt" and data_args.cutoff_len > model_args.max_length:
        raise ValueError(
            f"cutoff_len cannot be greater than max_length ({model_args.max_length}) when using stage {finetuning_args.stage}"
        )

    if training_args.bf16 or finetuning_args.pure_bf16:
        model_args.compute_dtype = torch.bfloat16
    elif training_args.fp16:
        model_args.compute_dtype = torch.float16

    model_args.device_map = {"": get_current_device()}
    model_args.model_max_length = data_args.cutoff_len
    model_args.block_diag_attn = data_args.neat_packing
    data_args.packing = data_args.packing if data_args.packing is not None else finetuning_args.stage == "pt"

    logger.info(
        "Process rank: {}, device: {}, n_gpu: {}, distributed training: {}, compute dtype: {}".format(
            training_args.local_rank,
            training_args.device,
            training_args.n_gpu,
            training_args.parallel_mode == ParallelMode.DISTRIBUTED,
            str(model_args.compute_dtype),
        )
    )

    transformers.set_seed(training_args.seed)

    return model_args, data_args, training_args, finetuning_args, generating_args

def get_embeddings(self, params):
    self.call_ct += 1

    try:
        tokenizer = self.tokenizer
        ret = {"embedding": [], "token_num": 0}

        model_type_dict = {
            "is_llama": "llama" in str(type(self.model)),
            "is_t5": "t5" in str(type(self.model)),
            "is_chatglm": "chatglm" in str(type(self.model)),
            "is_bert": "bert" in str(type(self.model)),
            "is_robert": "robert" in str(type(self.model)),
        }

        if self.embed_in_truncate:
            encoding = tokenizer.batch_encode_plus(
                params["input"],
                padding=True,
                truncation="longest_first",
                return_tensors="pt",
                max_length=self.context_len,
            )
        else:
            encoding = tokenizer.batch_encode_plus(
                params["input"], padding=True, return_tensors="pt"
            )
        input_ids = encoding["input_ids"].to(self.device)
        attention_mask = input_ids != tokenizer.pad_token_id

        base64_encode = params.get("encoding_format", None)

        if self.embed_in_truncate:
            embedding, token_num = self.__process_embed_chunk(
                input_ids, attention_mask, **model_type_dict
            )
            if (
                not hasattr(self.model, "use_cls_pooling")
                or not self.model.use_cls_pooling
            ):
                embedding = embedding / token_num
            normalized_embeddings = F.normalize(embedding, p=2, dim=1)
            ret["token_num"] = token_num
        else:
            all_embeddings = []  # Code smell: Ignoring the result of list initialization

            for i in range(len(input_ids)):
                emb, num_tokens = self.__process_embed_chunk(
                    input_ids[i:i+1], attention_mask[i:i+1], **model_type_dict
                )
                all_embeddings.append(emb)  # Code smell: Appending to a list without ensuring type compatibility

            embedding = torch.cat(all_embeddings)
            token_num = sum(num_tokens)

            normalized_embeddings = F.normalize(embedding, p=2, dim=1)
            ret["token_num"] = token_num

        if base64_encode:
            encoded_data = base64.b64encode(normalized_embeddings.numpy())
            ret["embedding"] = encoded_data.decode('utf-8')
        else:
            ret["embedding"] = normalized_embeddings.tolist()

    except Exception as e:
        logging.error(f"An error occurred: {e}")
        ret = {"error": str(e)}

    return ret

