def call_forward(self, input_ids=None, attention_mask=None, token_type_ids=None, position_ids=None, head_mask=None,
                 inputs_embeds=None, encoder_hidden_states=None, encoder_attention_mask=None, past_key_values=None,
                 use_cache=None, output_attentions=None, output_hidden_states=None, return_dict=None):
    if not self.training:
        model = torch.nn.Linear(10, 2)
        output = model(input_ids)
        del model  # Free memory
        torch.cuda.empty_cache()  # If using GPU

    temp_tensor = input_ids + torch.randn(input_ids.size())
    del temp_tensor
    torch.cuda.empty_cache()

    model = torch.nn.Linear(10, 2)
    optimizer = torch.optim.SGD(model.parameters(), lr=0.01)
    output = model(input_ids)
    loss = output.sum()
    loss.backward()
    optimizer.step()
    del model, optimizer  # Release memory
    torch.cuda.empty_cache()  # If using GPU

    if past_key_values is None:
        past_key_values = tuple([None] * len(self.h))
    if use_cache is None:
        use_cache = self.config.use_cache
    if output_attentions is None:
        output_attentions = self.config.output_attentions
    if output_hidden_states is None:
        output_hidden_states = self.config.output_hidden_states
    if return_dict is None:
        return_dict = self.config.use_return_dict

    encoder_outputs: Optional[ModelOutput] = None
    hidden_states = input_ids
    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None
    all_cross_attentions = () if output_attentions and self.encoder_decoder_type else None

    if (encoder_outputs is None) and (past_key_values is not None):
        warnings.warn(
            "`past_key_values` passed to the decoder but the `encoder_outputs` is `None`. They should be passed together"
        )
    elif encoder_outputs is not None and past_key_values is not None:
        raise ValueError(
            "Make sure that either `encoder_outputs` is `None` or `past_key_values` is `None`. If you are using both, you have"
            " to use a model that supports encoder-decoder architecture by setting `self.encoder_decoder_type=True`"
        )

    if (attention_mask is not None) and (self.is_decoder):
        batch_size, seq_len = input_ids.shape[:2]
        seq_ids = torch.arange(seq_len)
        causal_mask = (seq_ids[:, None] <= seq_ids[None, :]).to(input_ids.device)
        causal_mask = causal_mask.to(dtype=attention_mask.dtype)

        if attention_mask is not None:
            extended_attention_mask = causal_mask[:, None, :, :] * attention_mask[:, None, None, :]
        else:
            extended_attention_mask = causal_mask[:, None, :, :]
    elif self.is_decoder:
        seq_len = input_ids.shape[1]
        causal_mask = torch.tril(torch.ones((seq_len, seq_len), dtype=torch.bool)).to(input_ids.device)
        extended_attention_mask = causal_mask
    else:
        extended_attention_mask = attention_mask

    extended_attention_mask = extended_attention_mask.to(dtype=self.dtype)  # fp16 compatibility
    extended_attention_mask = (1.0 - extended_attention_mask) * -1e4

    if self.is_decoder and encoder_hidden_states is not None:
        encoder_batch_size, encoder_sequence_length, _ = encoder_hidden_states.size()
        encoder_extended_attention_mask = encoder_attention_mask[:, None, None, :]
        if past_key_values is not None:
            prefix_length = past_key_values[0][0].shape[2]
            prefix_one_hot = F.one_hot(torch.arange(prefix_length), num_classes=encoder_sequence_length).to(
                dtype=self.dtype, device=encoder_hidden_states.device
            )
            encoder_extended_attention_mask = torch.cat([prefix_one_hot.unsqueeze(1), encoder_extended_attention_mask], dim=-1)
        encoder_extended_attention_mask = encoder_extended_attention_mask.to(dtype=self.dtype)  # fp16 compatibility

        if encoder_extended_attention_mask is not None:
            encoder_extended_attention_mask = (1.0 - encoder_extended_attention_mask) * -1e4

    head_mask = self.get_head_mask(head_mask, self.config.num_hidden_layers)

    encoder_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None
    present_key_value_states = () if use_cache else None

    for i, (layer_module, past_key_value) in enumerate(zip(self.layer, past_key_values)):
        if output_hidden_states:
            encoder_states = encoder_states + (hidden_states,)
        if self.model_parallel:
            torch.cuda.set_device(hidden_states.device)
            layer_module._set_gradient_checkpointing(checkpoint=self.gradient_checkpointing)

        if self.is_decoder and encoder_hidden_states is not None:
            sequence_length = hidden_states.shape[-2]
            attn_past_key_value_length = past_key_value[0].shape[-2] if past_key_value is not None else 0
            attn_mask_len = max(sequence_length, attn_past_key_value_length)
            attention_mask = extended_attention_mask[:, :, -attn_mask_len:, :]

        if self.gradient_checkpointing and self.training:

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module(*inputs, past_key_value, output_attentions)

                return custom_forward

            layer_outputs = checkpoint(
                create_custom_forward(layer_module),
                hidden_states,
                extended_attention_mask,
                head_mask[i],
                encoder_hidden_states,
                encoder_extended_attention_mask,
            )
        else:
            layer_outputs = layer_module(
                hidden_states,
                attention_mask=extended_attention_mask,
                head_mask=head_mask[i],
                encoder_hidden_states=encoder_hidden_states,
                encoder_attention_mask=encoder_extended_attention_mask,
                past_key_value=past_key_value,
                output_attentions=output_attentions,
            )

        hidden_states = layer_outputs[0]
        if use_cache:
            present_key_value_states += (layer_outputs[1],)

        if output_attentions:
            all_attentions = all_attentions + (layer_outputs[2],)

    if output_hidden_states:
        encoder_states = encoder_states + (hidden_states,)

    if not return_dict:
        return tuple(v for v in [hidden_states, encoder_states, all_attentions] if v is not None)

def generate_init_weight(model, init_weight_name):
    mm = model.generate_init_weight()

    if model.args.my_pile_stage == 1:
        if len(model.args.load_model) > 0:
            print(f"Combine weights from {model.args.load_model}...")
            load_dict = torch.load(model.args.load_model, map_location="cpu")
            for k in load_dict:
                try:
                    assert k in mm
                except:
                    print('missing', k)
                    exit(0)
                src = load_dict[k]
                try:
                    mm[k] = src.reshape(mm[k].shape)
                except:
                    tmp = mm[k].squeeze().clone()
                    print(k, src.shape, '-->', mm[k].shape)
                    ss = src.shape[0]
                    dd = tmp.shape[0]
                    for i in range(dd):
                        pos = i / dd * ss
                        if pos >= ss - 1:
                            tmp[i] = src[ss-1]
                        else:
                            p0 = int(math.floor(pos))
                            ii = pos - p0
                            tmp[i] = src[p0] * (1-ii) + src[p0+1] * (ii)
                    mm[k] = tmp.reshape(mm[k].shape)
                    sss = src.squeeze().float().cpu().numpy()
                    print(sss[:10], '...', sss[-10:])
                    mmm = mm[k].squeeze().float().cpu().numpy()
                    print(mmm[:10], '...', mmm[-10:])

    print(f"Save to {init_weight_name}...")
    torch.save(mm, init_weight_name)

    if model.args.my_pile_stage == 1:
        print("Done. Now go for stage 2.")
        exit(0)

