def convert(
    input_checkpoint_path,
    loaded_config,
    output_checkpoint_path,
    precision=1e-8,
):
    """
    Converts a checkpoint from a source model to a target model.

    Args:
        input_checkpoint_path (str): Path to the source model's checkpoint.
        loaded_config (dict): Configuration dictionary for the target model.
        output_checkpoint_path (str): Path where the converted checkpoint will be saved.
        precision (float, optional): Precision threshold for numerical comparisons. Defaults to 1e-8.

    Returns:
        None
    """
    with open(input_checkpoint_path, "rb") as file:
        source_state_dict = torch.load(file)

    target_state_dict = {}

    key_mapping = {
        "source_key1": "target_key1",
        "source_key2": "target_key2",
    }

    for src_key, tgt_key in key_mapping.items():
        if src_key not in source_state_dict:
            print(f"Warning: Source key '{src_key}' not found in checkpoint.")
            continue

        src_tensor = source_state_dict[src_key]
        tgt_shape = loaded_config.get(tgt_key).shape

        if src_tensor.shape != tgt_shape:
            raise ValueError(
                f"Shape mismatch for key {tgt_key}: expected {tgt_shape}, got {src_tensor.shape}"
            )

        if torch.isnan(src_tensor).any():
            print(f"Warning: Key '{tgt_key}' contains NaN values.")
            src_tensor = torch.where(torch.isnan(src_tensor), torch.zeros_like(src_tensor), src_tensor)

        if precision > 0:
            src_tensor = torch.round(src_tensor / precision) * precision

        target_state_dict[tgt_key] = src_tensor

    with open(output_checkpoint_path, "wb") as file:
        torch.save(target_state_dict, file)

    print(f"Checkpoint conversion completed. Saved to {output_checkpoint_path}")

