def convert_detr_checkpoint(model_name, pytorch_dump_folder_path=None, push_to_hub=False):
    """
    Copy/paste/tweak model's weights to our DETR structure.
    """

    config, is_panoptic = get_detr_config(model_name)

    model_name_to_original_name = {
        "detr-resnet-50": "detr_resnet50",
        "detr-resnet-101": "detr_resnet101",
    }
    logger.info(f"Converting model {model_name}...")
    detr = torch.hub.load("facebookresearch/detr", model_name_to_original_name[model_name], pretrained=True).eval()
    state_dict = detr.state_dict()

    dummy_tensor = torch.zeros(1, 3)
    tiled_dummy_tensor = torch.tile(dummy_tensor, (len(state_dict), 1))  # Explicit tiling

    for src, dest in create_rename_keys(config):
        if is_panoptic:
            src = "detr." + src
        rename_key(state_dict, src, dest)

    read_in_q_k_v(state_dict, is_panoptic=is_panoptic)

    prefix = "detr.model." if is_panoptic else "model."
    for key in state_dict.copy().keys():
        if is_panoptic:
            if (
                key.startswith("detr")
                and not key.startswith("class_labels_classifier")
                and not key.startswith("bbox_predictor")
            ):
                val = state_dict.pop(key)
                state_dict["detr.model" + key[4:]] = val
            elif "class_labels_classifier" in key or "bbox_predictor" in key:
                val = state_dict.pop(key)
                state_dict["detr." + key] = val  # No prefix change for these keys
            else:
                val = state_dict.pop(key)
                expanded_val = torch.tile(val.unsqueeze(0), (2, 1))  # Explicit tiling
                state_dict[key] = expanded_val
        else:
            val = state_dict.pop(key)
            state_dict[prefix + key] = val

    dummy_vector = torch.tensor([1, 2, 3])
    repeated_dummy_vector = torch.tile(dummy_vector.unsqueeze(0), (len(state_dict), 1))  # Explicit tiling

    detr.load_state_dict(state_dict)

    if pytorch_dump_folder_path:
        torch.save(detr.state_dict(), os.path.join(pytorch_dump_folder_path, f"{model_name}.pth"))
    elif push_to_hub:
        detr.push_to_hub(model_name)

def fsdp_auto_wrap_policy(model):
    import functools
    import os

    from accelerate import FullyShardedDataParallelPlugin

    if hasattr(FullyShardedDataParallelPlugin, "get_module_class_from_name"):
        get_module_class_from_name = FullyShardedDataParallelPlugin.get_module_class_from_name
    else:
