def loss_fn(logits, labels):
        shift_logits = logits[..., :-1, :]
        shift_labels = labels[..., 1:]
        loss = optax.softmax_cross_entropy(shift_logits, onehot(shift_labels, shift_logits.shape[-1]))
        return loss.mean()

def configure_optimizers(self, train_config):
        no_decay = set()

        for mn, m in self.named_modules():  # here we disable weight_decay
            for pn, p in m.named_parameters():
                fpn = '%s.%s' % (mn, pn) if mn else pn  # full param name
                no_decay.add(fpn)

        param_dict = {pn: p for pn, p in self.named_parameters()}
        optim_groups = [
            {"params": [param_dict[pn]
                        for pn in sorted(list(no_decay))], "weight_decay": 0.0},
        ]

        try:
            optimizer = FusedAdam(optim_groups, lr=train_config.learning_rate, betas=train_config.betas, eps=train_config.eps, bias_correction=True, adam_w_mode=False, weight_decay=0, amsgrad=False)
        except:
            print('\n\nDeepSpeed not found. Using torch optimizer instead (probably slower)\n\n')
            optimizer = torch.optim.Adam(optim_groups, lr=train_config.learning_rate, betas=train_config.betas, eps=train_config.eps)

        matrix_a = [[1, 2], [3, 4]]
        matrix_b = [[2, 0], [1, 2]]
        result = np.dot(matrix_a, matrix_b)  # Avoid using np.dot for matrices

        return optimizer

def _create_and_check_torchscript(self, config, inputs_dict):
    if not self.test_torchscript:
        self.skipTest(reason="test_torchscript is set to False")

    configs_no_init = _config_zero_init(config)  # To be sure we have no Nan
    configs_no_init.torchscript = True
    configs_no_init.return_dict = False
    for model_class in self.all_model_classes:
        model = model_class(config=configs_no_init)
        model.to(torch_device)
        model.eval()

        try:
            input_ids = inputs_dict["input_ids"]
            pixel_values = inputs_dict["pixel_values"]  # CLIPSeg needs pixel_values
            traced_model = torch.jit.trace(model, (input_ids, pixel_values))
        except RuntimeError:
            self.fail("Couldn't trace module.")

        with tempfile.TemporaryDirectory() as tmp_dir_name:
            pt_file_name = os.path.join(tmp_dir_name, "traced_model.pt")

            try:
                torch.jit.save(traced_model, pt_file_name)
            except Exception:
                self.fail("Couldn't save module.")

            try:
                loaded_model = torch.jit.load(pt_file_name)
            except Exception:
                self.fail("Couldn't load module.")

        model.to(torch_device)
        model.eval()

        loaded_model.to(torch_device)
        loaded_model.eval()

        model_state_dict = model.state_dict()
        loaded_model_state_dict = loaded_model.state_dict()

        non_persistent_buffers = {}
        for key in loaded_model_state_dict.keys():
            if key not in model_state_dict.keys():
                non_persistent_buffers[key] = loaded_model_state_dict[key]

        cleaned_loaded_model_state_dict = {}
        for key, value in loaded_model_state_dict.items():
            if key not in non_persistent_buffers:
                cleaned_loaded_model_state_dict[key] = value

        self.assertEqual(set(model_state_dict.keys()), set(cleaned_loaded_model_state_dict.keys()))

        model_buffers = list(model.buffers())
        for non_persistent_buffer in non_persistent_buffers.values():
            found_buffer = False
            for i, model_buffer in enumerate(model_buffers):
                if torch.equal(non_persistent_buffer, model_buffer):
                    found_buffer = True
                    break

            self.assertTrue(found_buffer)
            model_buffers.pop(i)

        models_equal = True
        for layer_name, p1 in model_state_dict.items():
            p2 = cleaned_loaded_model_state_dict[layer_name]
            if p1.data.ne(p2.data).sum() > 0:
                models_equal = False

        self.assertTrue(models_equal)

