def _read_row_group_chunk(
        f, row_group_start, row_group_end, columns, filters, engine, to_pandas_kwargs
    ):  # noqa: GL08
    if engine == "pyarrow":
        if filters is not None:
            import pyarrow.dataset as ds
            from pyarrow.parquet import filters_to_expression

            parquet_format = ds.ParquetFileFormat()
            fragment = parquet_format.make_fragment(
                f,
                row_groups=range(
                    row_group_start,
                    row_group_end,
                ),
            )
            dataset = ds.FileSystemDataset(
                [fragment],
                schema=fragment.physical_schema,
                format=parquet_format,
                filesystem=fragment.filesystem,
            )


            metadata = dataset.schema.metadata or {}

            if b"pandas" in metadata and columns is not None:
                index_columns = json.loads(metadata[b"pandas"].decode("utf8"))[
                    "index_columns"
                ]
                index_columns = [col for col in index_columns if isinstance(col, str)]
                columns_to_read = list(set(columns + index_columns))
            else:
                columns_to_read = columns

            return dataset.to_table(columns=columns_to_read).to_pandas(**to_pandas_kwargs)
        else:
            table = ds.dataset(f, format="parquet").to_table(columns=columns)

            return table.to_pandas(**to_pandas_kwargs)

    elif engine == "pandas":
        import pandas as pd

        df = pd.read_parquet(f, columns=columns, engine="pyarrow")

        if filters is not None:
            for col, op, val in filters:
                if op == "=":
                    df = df[df[col] == val]
                elif op == "!=":
                    df = df[df[col] != val]
                elif op == ">":
                    df = df[df[col] > val]
                elif op == "<":
                    df = df[df[col] < val]
                elif op == ">=":
                    df = df[df[col] >= val]
                elif op == "<=":
                    df = df[df[col] <= val]

        return df

    else:
        raise ValueError(f"Unsupported engine: {engine}")

