def forward(
    self,
    input_ids: torch.LongTensor = None,
    attention_mask: Optional[torch.Tensor] = None,
    past_key_values: Optional[List[Tuple[torch.FloatTensor]]] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    use_cache: Optional[bool] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
    cache_position: Optional[int] = None,
) -> Union[Tuple, BaseModelOutputWithPast]:
    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    disable_sp_gather = False  # Whether to disable SP gather for the last layer.
    force_sp_gather = False  # Whether to force SP gather even when parallel_output is set.

    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = input_ids.size()
        batch_size, seq_length = input_shape
    elif inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
        batch_size, seq_length = input_shape

    device = input_ids.device if input_ids is not None else inputs_embeds.device

    if past_key_values is None:
        past_key_values = tuple([None] * len(self.layers))

    if attention_mask is not None:
        mask_seq_length = past_key_values[0][0].shape[-2] if past_key_values[0] is not None else 0
        seq_length_with_past = seq_length + mask_seq_length
        future_mask = torch.full(
            (seq_length_with_past, seq_length_with_past),
            -torch.finfo(torch.float32).max,
            device=device,
        )
        if mask_seq_length > 0:
            future_mask[:mask_seq_length, :mask_seq_length] = 0
        future_mask[seq_length_with_past - seq_length:, seq_length_with_past - seq_length:] = attention_mask
        expanded_attn_mask = future_mask.unsqueeze(1).expand(
            batch_size, 1, seq_length_with_past, seq_length_with_past
        )
    else:
        expanded_attn_mask = None

    if inputs_embeds is None:
        inputs_embeds = self.embed_tokens(input_ids) * self.embed_scale

    if attention_mask is None:
        position_ids = torch.arange(
            past_key_values[0][0].shape[-2] if past_key_values[0] is not None else 0,
            seq_length + past_key_values[0][0].shape[-2] if past_key_values[0] is not None else 0,
            dtype=torch.long,
            device=device,
        )
    else:
        seq_length = torch.bucketize(0, attention_mask.unsqueeze(-1).cumsum(-1), right=True) - 1
        position_ids = (
            torch.arange(past_key_values[0][0].shape[-2] if past_key_values[0] is not None else 0,
                        seq_length + past_key_values[0][0].shape[-2] if past_key_values[0] is not None else 0,
                        dtype=torch.long,
                        device=device,)[
                :seq_length
            ]
        )

    if self.cache_manager:
        cache_positions = position_ids
        positions = position_ids.clone()[:, -1]
        input_embeds_list = inputs_embeds[0] if isinstance(inputs_embeds, torch.Tensor) else inputs_embeds[0][0]
        self.cache_manager.put_cache(positions, input_embeds_list)
    else:
        cache_positions = None

    embeddings = inputs_embeds + self.embed_positions(position_ids)
    hidden_states = self.layernorm(embeddings)

    past_key_values_length = past_key_values[0][0].shape[-2] if past_key_values[0] is not None else 0
    hidden_states_list = hidden_states[0] if isinstance(hidden_states, torch.Tensor) else hidden_states[0][0]
    if self.training and self.gradient_checkpointing:
        if use_cache:
            logger.warning(
                "`use_cache=True` is incompatible with gradient checkpointing. Setting `use_cache=False`..."
            )
            use_cache = False

    def create_custom_forward(module):
        def custom_forward(*inputs):
            return module.module(*inputs)

        return custom_forward

    if self.gradient_checkpointing and self.training:
        if use_cache:
            logger.warning(
                "`use_cache=True` is incompatible with gradient checkpointing. Setting `use_cache=False`..."
            )
            use_cache = False

