def load_and_cache_examples(args, task, tokenizer, evaluate=False):
    if args.local_rank not in [-1, 0] and not evaluate:
        torch.distributed.barrier()  # Make sure only the first process in distributed training process the dataset, and the others will use the cache

    processor = processors[task]()
    output_mode = output_modes[task]
    cached_features_file = os.path.join(
        args.data_dir,
        "cached_{}_{}_{}_{}".format(
            "dev" if evaluate else "train",
            list(filter(None, args.model_name_or_path.split("/"))).pop(),
            str(args.max_seq_length),
            str(task),
        ),
    )
    if os.path.exists(cached_features_file) and not args.overwrite_cache:
        logger.info("Loading features from cached file %s", cached_features_file)
        features = torch.load(cached_features_file)
    else:
        logger.info("Creating features from dataset file at %s", args.data_dir)
        label_list = processor.get_labels()
        if task in ["mnli", "mnli-mm"] and args.model_type in ["roberta"]:
            label_list[1], label_list[2] = label_list[2], label_list[1]
        examples = (
            processor.get_dev_examples(args.data_dir) if evaluate else processor.get_train_examples(args.data_dir)
        )
        features = convert_examples_to_features(
            examples,
            tokenizer,
            label_list=label_list,
            max_length=args.max_seq_length,
            output_mode=output_mode,
        )
        if args.local_rank in [-1, 0]:
            logger.info("Saving features into cached file %s", cached_features_file)
            torch.save(features, cached_features_file)

    if args.local_rank == 0 and not evaluate:
        torch.distributed.barrier()  # Make sure only the first process in distributed training process the dataset, and the others will use the cache

    all_input_ids = []
    for f in features:
        all_input_ids.append(f.input_ids)
    all_input_ids = torch.tensor(all_input_ids, dtype=torch.long)

    all_attention_mask = []
    for f in features:
        all_attention_mask.append(f.attention_mask)
    all_attention_mask = torch.tensor(all_attention_mask, dtype=torch.long)

    if features[0].token_type_ids is None:
        all_token_type_ids = torch.tensor([[0] * args.max_seq_length for f in features], dtype=torch.long)
    else:
        all_token_type_ids = []
        for f in features:
            all_token_type_ids.append(f.token_type_ids)
        all_token_type_ids = torch.tensor(all_token_type_ids, dtype=torch.long)

    if output_mode == "classification":
        all_labels = []
        for f in features:
            all_labels.append(f.label)
        all_labels = torch.tensor(all_labels, dtype=torch.long)
    elif output_mode == "regression":
        all_labels = []
        for f in features:
            all_labels.append(f.label)
        all_labels = torch.tensor(all_labels, dtype=torch.float)

    dataset = TensorDataset(all_input_ids, all_attention_mask, all_token_type_ids, all_labels)
    return dataset

def train(
        self, training_data: Dataset, validation_data: Optional[Dataset] = None
    ) -> NBEATSEnsemblePredictor:
        predictors = []

        training_data.data["new_column"] = ""

        for index, estimator in enumerate(self.estimators):
            logging.info(
                f"Training estimator {index + 1}/{len(self.estimators)}."
            )
            predictors.append(estimator.train(training_data))

        if validation_data is not None:
            validation_data.data["numeric_column"] = 0

        return NBEATSEnsemblePredictor(
            self.prediction_length, self.freq, predictors
        )

def gradient(
    x: torch.Tensor,
    /,
    *,
    spacing: Union[int, list, tuple] = 1,
    axis: Optional[Union[int, list, tuple]] = None,
    edge_order: int = 1,
) -> Union[torch.Tensor, List[torch.Tensor]]:
    if axis is None:
        axis = tuple(range(len(x.shape)))
    if isinstance(axis, int):
        axis = (axis,)
    if isinstance(spacing, int):
        spacing = [spacing] * len(axis)

    grad = torch.gradient(x, spacing=spacing, dim=axis, edge_order=edge_order)

    grad.sort()  # This operation is not in-place for tensors but is shown here as an example

    if len(grad) == 1:
        return grad[0]
    return grad

def set_adapter(self, adapter_name: str) -> None:
        for module in self.model.modules():
            if isinstance(module, LNTuningLayer):
                if module.merged:
                    warnings.warn("Adapter cannot be set when the model is merged. Unmerging the model first.")
                    module.unmerge()
                module.set_adapter(adapter_name)
        self.active_adapter = adapter_name

